private void removeUnreferencedFunctionArgs(Scope fnScope) {
  // Notice that removing unreferenced function args breaks
  // Function.prototype.length. In advanced mode, we don't really care
  // about this: we consider "length" the equivalent of reflecting on
  // the function's lexical source.
  //
  // Rather than create a new option for this, we assume that if the user
  // is removing globals, then it's OK to remove unused function args.
  //
  // See http://code.google.com/p/closure-compiler/issues/detail?id=253

  Node function = fnScope.getRootNode();

  Preconditions.checkState(function.isFunction());
  if (NodeUtil.isGetOrSetKey(function.getParent())) {
    // The parameters object literal setters can not be removed.
    return;
  }

  Node argList = getFunctionArgList(function);
  boolean modifyCallers = modifyCallSites
      && callSiteOptimizer.canModifyCallers(function);
  if (!modifyCallers) {
    // Strip unreferenced args off the end of the function declaration.
    Node lastArg;
    while ((lastArg = argList.getLastChild()) != null) {
      Var var = fnScope.getVar(lastArg.getString());
      if (!referenced.contains(var)) {
        argList.removeChild(lastArg);
        compiler.reportCodeChange();
      } else {
        break;
      }
    }
  } else {
    callSiteOptimizer.optimize(fnScope, referenced);
  }
}

public void enterScope(NodeTraversal t) {

  if (t.inGlobalScope()) {
    return; // Don't even bother. All global variables are likely escaped.
  }

  if (LiveVariablesAnalysis.MAX_VARIABLES_TO_ANALYZE <
      t.getScope().getVarCount()) {
    return;
  }

  // Compute the forward reaching definition.
  ControlFlowAnalysis cfa = new ControlFlowAnalysis(compiler, false, true);
  // Process the body of the function.
  Preconditions.checkState(t.getScopeRoot().isFunction());
  cfa.process(null, t.getScopeRoot().getLastChild());
  cfg = cfa.getCfg();
  reachingDef = new MustBeReachingVariableDef(cfg, t.getScope(), compiler);
  reachingDef.analyze();
  candidates = Lists.newLinkedList();

  // Using the forward reaching definition search to find all the inline
  // candidates
  new NodeTraversal(compiler, new GatherCandiates()).traverse(
      t.getScopeRoot().getLastChild());

  // Compute the backward reaching use. The CFG can be reused.
  reachingUses = new MaybeReachingVariableUse(cfg, t.getScope(), compiler);
  reachingUses.analyze();
  for (Candidate c : candidates) {
    if (c.canInline()) {
      c.inlineVariable();

      // If definition c has dependencies, then inlining it may have
      // introduced new dependencies for our other inlining candidates.
      //
      // MustBeReachingVariableDef uses this dependency graph in its
      // analysis, so some of these candidates may no longer be valid.
      // We keep track of when the variable dependency graph changed
      // so that we can back off appropriately.
      if (!c.defMetadata.depends.isEmpty()) {
        inlinedNewDependencies.add(t.getScope().getVar(c.varName));
      }
    }
  }
}

private boolean canInline() {
  // Cannot inline a parameter.
  if (getDefCfgNode().isFunction()) {
    return false;
  }

  // If one of our dependencies has been inlined, then our dependency
  // graph is wrong. Re-computing it would take another CFG computation,
  // so we just back off for now.
  for (Var dependency : defMetadata.depends) {
    if (inlinedNewDependencies.contains(dependency)) {
      return false;
    }
  }

  getDefinition(getDefCfgNode(), null);
  getNumUseInUseCfgNode(useCfgNode, null);

  // Definition was not found.
  if (def == null) {
    return false;
  }

  // Check that the assignment isn't used as a R-Value.
  // TODO(user): Certain cases we can still inline.
  if (def.isAssign() && !NodeUtil.isExprAssign(def.getParent())) {
    return false;
  }

  // The right of the definition has side effect:
  // Example, for x:
  // x = readProp(b), modifyProp(b); print(x);
  if (checkRightOf(def, getDefCfgNode(), SIDE_EFFECT_PREDICATE)) {
    return false;
  }

  // Similar check as the above but this time, all the sub-expressions
  // left of the use of the variable.
  // x = readProp(b); modifyProp(b), print(x);
  if (checkLeftOf(use, useCfgNode, SIDE_EFFECT_PREDICATE)) {
    return false;
  }

  // TODO(user): Side-effect is OK sometimes. As long as there are no
  // side-effect function down all paths to the use. Once we have all the
  // side-effect analysis tool.
  if (NodeUtil.mayHaveSideEffects(def.getLastChild(), compiler)) {
    return false;
  }

  // TODO(user): We could inline all the uses if the expression is short.

  // Finally we have to make sure that there are no more than one use
  // in the program and in the CFG node. Even when it is semantically
  // correctly inlining twice increases code size.
  if (numUseWithinUseCfgNode != 1) {
    return false;
  }

  // Make sure that the name is not within a loop
  if (NodeUtil.isWithinLoop(use)) {
    return false;
  }

  Collection<Node> uses = reachingUses.getUses(varName, getDefCfgNode());

  if (uses.size() != 1) {
    return false;
  }

  // We give up inlining stuff with R-Value that has:
  // 1) GETPROP, GETELEM,
  // 2) anything that creates a new object.
  // 3) a direct reference to a catch expression.
  // Example:
  // var x = a.b.c; j.c = 1; print(x);
  // Inlining print(a.b.c) is not safe consider j and be alias to a.b.
  // TODO(user): We could get more accuracy by looking more in-detail
  // what j is and what x is trying to into to.
  // TODO(johnlenz): rework catch expression handling when we
  // have lexical scope support so catch expressions don't
  // need to be special cased.
  if (NodeUtil.has(def.getLastChild(),
      new Predicate<Node>() {
          @Override
          public boolean apply(Node input) {
            switch (input.getType()) {
              case Token.GETELEM:
              case Token.GETPROP:
              case Token.ARRAYLIT:
              case Token.OBJECTLIT:
              case Token.REGEXP:
              case Token.NEW:
                return true;
            }
            return false;
          }
      },

public boolean apply(Node input) {
  switch (input.getType()) {
    case Token.GETELEM:
    case Token.GETPROP:
    case Token.ARRAYLIT:
    case Token.OBJECTLIT:
    case Token.REGEXP:
    case Token.NEW:
      return true;
  }
  return false;
}

JSType resolveInternal(ErrorReporter t, StaticScope<JSType> enclosing) {
  // TODO(user): Investigate whether it is really necessary to keep two
  // different mechanisms for resolving named types, and if so, which order
  // makes more sense. Now, resolution via registry is first in order to
  // avoid triggering the warnings built into the resolution via properties.
  boolean resolved = resolveViaRegistry(t, enclosing);
  if (detectImplicitPrototypeCycle()) {
    handleTypeCycle(t);
  }

  if (resolved) {
    super.resolveInternal(t, enclosing);
    finishPropertyContinuations();
    return registry.isLastGeneration() ?
        getReferencedType() : this;
  }

  resolveViaProperties(t, enclosing);
  if (detectImplicitPrototypeCycle()) {
    handleTypeCycle(t);
  }

  super.resolveInternal(t, enclosing);
  if (isResolved()) {
    finishPropertyContinuations();
  }
  return registry.isLastGeneration() ?
      getReferencedType() : this;
}

private boolean isInlinableObject(List<Reference> refs) {
  boolean ret = false;
  Set<String> validProperties = Sets.newHashSet();
  for (Reference ref : refs) {
    Node name = ref.getNode();
    Node parent = ref.getParent();
    Node gramps = ref.getGrandparent();

    // Ignore most indirect references, like x.y (but not x.y(),
    // since the function referenced by y might reference 'this').
    //
    if (parent.isGetProp()) {
      Preconditions.checkState(parent.getFirstChild() == name);
      // A call target may be using the object as a 'this' value.
      if (gramps.isCall()
          && gramps.getFirstChild() == parent) {
        return false;
      }

      // Deleting a property has different semantics from deleting
      // a variable, so deleted properties should not be inlined.

      // NOTE(nicksantos): This pass's object-splitting algorithm has
      // a blind spot. It assumes that if a property isn't defined on an
      // object, then the value is undefined. This is not true, because
      // Object.prototype can have arbitrary properties on it.
      //
      // We short-circuit this problem by bailing out if we see a reference
      // to a property that isn't defined on the object literal. This
      // isn't a perfect algorithm, but it should catch most cases.
      String propName = parent.getLastChild().getString();
      if (!validProperties.contains(propName)) {
        if (NodeUtil.isVarOrSimpleAssignLhs(parent, gramps)) {
          validProperties.add(propName);
        } else {
          return false;
        }
      }
      continue;
    }

    // Only rewrite VAR declarations or simple assignment statements
    if (!isVarOrAssignExprLhs(name)) {
       return false;
    }

    Node val = ref.getAssignedValue();
    if (val == null) {
      // A var with no assignment.
      continue;
    }

    // We're looking for object literal assignments only.
    if (!val.isObjectLit()) {
      return false;
    }

    // Make sure that the value is not self-referential. IOW,
    // disallow things like x = {b: x.a}.
    //
    // TODO: Only exclude unorderable self-referential
    // assignments. i.e. x = {a: x.b, b: x.a} is not orderable,
    // but x = {a: 1, b: x.a} is.
    //
    // Also, ES5 getters/setters aren't handled by this pass.
    for (Node child = val.getFirstChild(); child != null;
         child = child.getNext()) {
      if (child.isGetterDef() ||
          child.isSetterDef()) {
        // ES5 get/set not supported.
        return false;
      }

      validProperties.add(child.getString());

      Node childVal = child.getFirstChild();
      // Check if childVal is the parent of any of the passed in
      // references, as that is how self-referential assignments
      // will happen.
      for (Reference t : refs) {
        Node refNode = t.getParent();
        while (!NodeUtil.isStatementBlock(refNode)) {
          if (refNode == childVal) {
            // There's a self-referential assignment
            return false;
          }
          refNode = refNode.getParent();
        }
      }
    }


    // We have found an acceptable object literal assignment. As
    // long as there are no other assignments that mess things up,
    // we can inline.
    ret = true;
  }
  return ret;
}

void expectNotNullOrUndefined(
    NodeTraversal t, Node n, JSType type, String msg, JSType expectedType) {
  if (!type.isNoType() && !type.isUnknownType() &&
      type.isSubtype(nullOrUndefined) &&
      !containsForwardDeclaredUnresolvedName(type)) {

    // There's one edge case right now that we don't handle well, and
    // that we don't want to warn about.
    // if (this.x == null) {
    //   this.initializeX();
    //   this.x.foo();
    // }
    // In this case, we incorrectly type x because of how we
    // infer properties locally. See issue 109.
    // http://code.google.com/p/closure-compiler/issues/detail?id=109
    //
    // We do not do this inference globally.
    if (n.isGetProp() &&
        !t.inGlobalScope() && type.isNullType()) {
      return;
    }

    mismatch(t, n, msg, type, expectedType);
    return;
  }
  return true;
}

private boolean containsForwardDeclaredUnresolvedName(JSType type) {
  if (type.isUnionType()) {
    for (JSType alt : type.toMaybeUnionType().getAlternates()) {
      if (containsForwardDeclaredUnresolvedName(alt)) {
        return true;
      }
    }
  }
  return type.isNoResolvedType();
}

/**
 * Expect that the first type is the direct superclass of the second type.
 *
 * @param t The node traversal.
 * @param n The node where warnings should point to.
 * @param superObject The expected super instance type.
 * @param subObject The sub instance type.
 */
void expectSuperType(NodeTraversal t, Node n, ObjectType superObject,
    ObjectType subObject) {
  FunctionType subCtor = subObject.getConstructor();
  ObjectType implicitProto = subObject.getImplicitPrototype();
  ObjectType declaredSuper =
      implicitProto == null ? null : implicitProto.getImplicitPrototype();
  if (declaredSuper != null &&
      !(superObject instanceof UnknownType) &&
      !declaredSuper.isEquivalentTo(superObject)) {
    if (declaredSuper.isEquivalentTo(getNativeType(OBJECT_TYPE))) {
      registerMismatch(superObject, declaredSuper, report(
          t.makeError(n, MISSING_EXTENDS_TAG_WARNING, subObject.toString())));
    } else {
      mismatch(t.getSourceName(), n,
          "mismatch in declaration of superclass type",
          superObject, declaredSuper);
    }

    // Correct the super type.
    if (!subCtor.hasCachedValues()) {
      subCtor.setPrototypeBasedOn(superObject);
    }
  }
}

/**
 * Expect that the first type can be cast to the second type. The first type
 * should be either a subtype or supertype of the second.
 *
 * @param t The node traversal.
 * @param n The node where warnings should point.
 * @param type The type being cast from.
 * @param castType The type being cast to.
 */
void expectCanCast(NodeTraversal t, Node n, JSType type, JSType castType) {
  castType = castType.restrictByNotNullOrUndefined();
  type = type.restrictByNotNullOrUndefined();

  if (!type.canAssignTo(castType) && !castType.canAssignTo(type)) {
    registerMismatch(type, castType, report(t.makeError(n, INVALID_CAST,
        castType.toString(), type.toString())));
  }
}

/**
 * Expect that the given variable has not been declared with a type.
 *
 * @param sourceName The name of the source file we're in.
 * @param n The node where warnings should point to.
 * @param parent The parent of {@code n}.
 * @param var The variable that we're checking.
 * @param variableName The name of the variable.
 * @param newType The type being applied to the variable. Mostly just here
 *     for the benefit of the warning.
 * @return The variable we end up with. Most of the time, this will just
 *     be {@code var}, but in some rare cases we will need to declare
 *     a new var with new source info.
 */
Var expectUndeclaredVariable(String sourceName, CompilerInput input,
    Node n, Node parent, Var var, String variableName, JSType newType) {
  Var newVar = var;
  boolean allowDupe = false;
  if (n.isGetProp() ||
      NodeUtil.isObjectLitKey(n, parent)) {
    JSDocInfo info = n.getJSDocInfo();
    if (info == null) {
      info = parent.getJSDocInfo();
    }
    allowDupe =
        info != null && info.getSuppressions().contains("duplicate");
  }

  JSType varType = var.getType();

  // Only report duplicate declarations that have types. Other duplicates
  // will be reported by the syntactic scope creator later in the
  // compilation process.
  if (varType != null &&
      varType != typeRegistry.getNativeType(UNKNOWN_TYPE) &&
      newType != null &&
      newType != typeRegistry.getNativeType(UNKNOWN_TYPE)) {
    // If there are two typed declarations of the same variable, that
    // is an error and the second declaration is ignored, except in the
    // case of native types. A null input type means that the declaration
    // was made in TypedScopeCreator#createInitialScope and is a
    // native type. We should redeclare it at the new input site.
    if (var.input == null) {
      Scope s = var.getScope();
      s.undeclare(var);
      newVar = s.declare(variableName, n, varType, input, false);

      n.setJSType(varType);
      if (parent.isVar()) {
        if (n.getFirstChild() != null) {
          n.getFirstChild().setJSType(varType);
        }
      } else {
        Preconditions.checkState(parent.isFunction());
        parent.setJSType(varType);
      }
    } else {
      // Always warn about duplicates if the overridden type does not
      // match the original type.
      //
      // If the types match, suppress the warning iff there was a @suppress
      // tag, or if the original declaration was a stub.
      if (!(allowDupe ||
            var.getParentNode().isExprResult()) ||
          !newType.isEquivalentTo(varType)) {
        report(JSError.make(sourceName, n, DUP_VAR_DECLARATION,
            variableName, newType.toString(), var.getInputName(),
            String.valueOf(var.nameNode.getLineno()),
            varType.toString()));
      }
    }
  }

  return newVar;
}

public JSType caseObjectType(ObjectType type) {
  if (value.equals("function")) {
    JSType ctorType = getNativeType(U2U_CONSTRUCTOR_TYPE);
    return resultEqualsValue && ctorType.isSubtype(type) ? ctorType : null;
      // Objects are restricted to "Function", subtypes are left
      // Only filter out subtypes of "function"
  }
  return matchesExpectation("object") ? type : null;
}

private boolean canBeRedeclared(Node n, Scope s) {
  if (!NodeUtil.isExprAssign(n)) {
    return false;
  }
  Node assign = n.getFirstChild();
  Node lhs = assign.getFirstChild();

  if (!lhs.isName()) {
    return false;
  }

  Var var = s.getVar(lhs.getString());
  return var != null
      && var.getScope() == s
      && !blacklistedVars.contains(var)
      && var.isReassignable();
}

private String normalizeSourceName(String filename) {
  // The DOS command shell will normalize "/" to "\", so we have to
  // wrestle it back.

  if (filename.indexOf(filenamePrefix) == 0) {
    filename = filename.substring(filenamePrefix.length());
  }

  return filename.replace("\\", "/");
}

private void visitScript(NodeTraversal t, Node script) {
  Preconditions.checkArgument(scriptNodeCount == 1,
      "ProcessCommonJSModules supports only one invocation per " +
      "CompilerInput / script node");
  String moduleName = guessCJSModuleName(normalizeSourceName(script.getSourceFileName()));
  script.addChildToFront(IR.var(IR.name(moduleName), IR.objectlit())
      .copyInformationFromForTree(script));
  if (reportDependencies) {
    CompilerInput ci = t.getInput();
    ci.addProvide(moduleName);
    JSModule m = new JSModule(moduleName);
    m.addAndOverrideModule(ci);
    module = m;
  }
  script.addChildToFront(IR.exprResult(
      IR.call(IR.getprop(IR.name("goog"), IR.string("provide")),
          IR.string(moduleName))).copyInformationFromForTree(script));

  emitOptionalModuleExportsOverride(script, moduleName);

  // Rename vars to not conflict in global scope.
  NodeTraversal.traverse(compiler, script, new SuffixVarsCallback(
      moduleName));

  compiler.reportCodeChange();
}

static boolean mayBeString(Node n, boolean recurse) {
  if (recurse) {
    return allResultsMatch(n, MAY_BE_STRING_PREDICATE);
  } else {
    return mayBeStringHelper(n);
  }
}

private void visitGetProp(NodeTraversal t, Node n, Node parent) {
  // obj.prop or obj.method()
  // Lots of types can appear on the left, a call to a void function can
  // never be on the left. getPropertyType will decide what is acceptable
  // and what isn't.
  Node property = n.getLastChild();
  Node objNode = n.getFirstChild();
  JSType childType = getJSType(objNode);

  if (childType.isDict()) {
    report(t, property, TypeValidator.ILLEGAL_PROPERTY_ACCESS, "'.'", "dict");
  } else if (n.getJSType() != null && parent.isAssign()) {
    return;
  } else if (validator.expectNotNullOrUndefined(t, n, childType,
      "No properties on this expression", getNativeType(OBJECT_TYPE))) {
    checkPropertyAccess(childType, property.getString(), t, n);
  }
  ensureTyped(t, n);
}

private void traverse(Node node) {
  // The goal here is to avoid retraversing
  // the entire AST to catch newly created opportunities.
  // So we track whether a "unit of code" has changed,
  // and revisit immediately.
  if (!shouldVisit(node)) {
    return;
  }

  int visits = 0;
  do {
    Node c = node.getFirstChild();
    while(c != null) {
      traverse(c);
      Node next = c.getNext();
      c = next;
    }

    visit(node);
    visits++;

    Preconditions.checkState(visits < 10000, "too many interations");
  } while (shouldRetraverse(node));

  exitNode(node);
}

private static Node computeFollowNode(Node fromNode, Node node, ControlFlowAnalysis cfa) {
    Node parent = node.getParent();
    if (parent == null || parent.isFunction() ||
        (cfa != null && node == cfa.root)) {
        return null;
    }

    switch (parent.getType()) {
        case Token.IF:
            return computeFollowNode(fromNode, parent, cfa);
        case Token.CASE:
        case Token.DEFAULT_CASE:
            if (parent.getNext() != null) {
                if (parent.getNext().isCase()) {
                    return parent.getNext().getFirstChild().getNext();
                } else if (parent.getNext().isDefaultCase()) {
                    return parent.getNext().getFirstChild();
                } else {
                    Preconditions.checkState(false, "Not reachable");
                }
            } else {
                return computeFollowNode(fromNode, parent, cfa);
            }
            break;
        case Token.FOR:
            if (NodeUtil.isForIn(parent)) {
                return parent;
            } else {
                return parent.getFirstChild().getNext().getNext();
            }
        case Token.WHILE:
        case Token.DO:
            return parent;
        case Token.TRY:
            if (parent.getFirstChild() == node) {
                if (NodeUtil.hasFinally(parent)) {
                    return computeFallThrough(parent.getLastChild());
                } else {
                    return computeFollowNode(fromNode, parent, cfa);
                }
            } else if (NodeUtil.getCatchBlock(parent) == node){
                if (NodeUtil.hasFinally(parent)) {
                    return computeFallThrough(node.getNext());
                } else {
                    return computeFollowNode(fromNode, parent, cfa);
                }
            } else if (parent.getLastChild() == node){
                if (cfa != null) {
                    for (Node finallyNode : cfa.finallyMap.get(parent)) {
                        cfa.createEdge(fromNode, Branch.UNCOND, finallyNode);
                    }
                }
                return computeFollowNode(fromNode, parent, cfa);
            }
    }

    Node nextSibling = node.getNext();
    while (nextSibling != null && nextSibling.isFunction()) {
        nextSibling = nextSibling.getNext();
    }

    if (nextSibling != null) {
        return computeFallThrough(nextSibling);
    } else {
        return computeFollowNode(fromNode, parent, cfa);
    }
}

private static Node computeFallThrough(Node n) {
    switch (n.getType()) {
        case Token.DO:
            return computeFallThrough(n.getFirstChild());
        case Token.FOR:
            if (NodeUtil.isForIn(n)) {
                return n.getFirstChild().getNext();
            }
            return computeFallThrough(n.getFirstChild());
        case Token.LABEL:
            return computeFallThrough(n.getLastChild());
        default:
            return n;
    }
}

private void handleBreak(Node node) {
    String label = null;
    if (node.hasChildren()) {
        label = node.getFirstChild().getString();
    }
    Node cur;
    Node previous = null;
    Node lastJump;
    Node parent = node.getParent();
    for (cur = node, lastJump = node;
        !isBreakTarget(cur, label);
        cur = parent, parent = parent.getParent()) {
        if (cur.isTry() && NodeUtil.hasFinally(cur)
            && cur.getLastChild() != previous) {
            if (lastJump == node) {
                createEdge(lastJump, Branch.UNCOND, computeFallThrough(
                    cur.getLastChild()));
            } else {
                finallyMap.put(lastJump, computeFallThrough(cur.getLastChild()));
            }
            lastJump = cur;
        }
        if (parent == null) {
            if (compiler.isIdeMode()) {
                return;
            } else {
                throw new IllegalStateException("Cannot find break target.");
            }
        }
        previous = cur;
    }
    if (lastJump == node) {
        createEdge(lastJump, Branch.UNCOND, computeFollowNode(cur, this));
    } else {
        finallyMap.put(lastJump, computeFollowNode(cur, this));
    }
}

private void handleContinue(Node node) {
    String label = null;
    if (node.hasChildren()) {
        label = node.getFirstChild().getString();
    }
    Node cur;
    Node previous = null;
    Node lastJump;
    Node parent = node.getParent();
    for (cur = node, lastJump = node;
        !isContinueTarget(cur, parent, label);
        cur = parent, parent = parent.getParent()) {
        if (cur.isTry() && NodeUtil.hasFinally(cur)
            && cur.getLastChild() != previous) {
            if (lastJump == node) {
                createEdge(lastJump, Branch.UNCOND, cur.getLastChild());
            } else {
                finallyMap.put(lastJump, computeFallThrough(cur.getLastChild()));
            }
            lastJump = cur;
        }
        Preconditions.checkState(parent != null, "Cannot find continue target.");
        previous = cur;
    }
    Node iter = cur;
    if (cur.getChildCount() == 4) {
        iter = cur.getFirstChild().getNext().getNext();
    }

    if (lastJump == node) {
        createEdge(node, Branch.UNCOND, iter);
    } else {
        finallyMap.put(lastJump, iter);
    }
}

private void handleReturn(Node node) {
    Node lastJump = null;
    for (Iterator<Node> iter = exceptionHandler.iterator(); iter.hasNext();) {
        Node curHandler = iter.next();
        if (curHandler.isFunction()) {
            break;
        }
        if (NodeUtil.hasFinally(curHandler)) {
            if (lastJump == null) {
                createEdge(node, Branch.UNCOND, curHandler.getLastChild());
            } else {
                finallyMap.put(lastJump,
                    computeFallThrough(curHandler.getLastChild()));
            }
            lastJump = curHandler;
        }
    }

    if (node.hasChildren()) {
        connectToPossibleExceptionHandler(node, node.getFirstChild());
    }

    if (lastJump == null) {
        createEdge(node, Branch.UNCOND, null);
    } else {
        finallyMap.put(lastJump, null);
    }
}

private void handleStmt(Node node) {
    createEdge(node, Branch.UNCOND, computeFollowNode(node, this));
    connectToPossibleExceptionHandler(node, node);
}

public boolean apply(Node n) {
  // When the node is null it means, we reached the implicit return
  // where the function returns (possibly without an return statement)
  if (n == null) {
    return false;
  }

  // TODO(user): We only care about calls to functions that
  // passes one of the dependent variable to a non-side-effect free
  // function.
  if (n.isCall() && NodeUtil.functionCallHasSideEffects(n)) {
    return true;
  }

  if (n.isNew() && NodeUtil.constructorCallHasSideEffects(n)) {
    return true;
  }

  for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
    if (!ControlFlowGraph.isEnteringNewCfgNode(c) && apply(c)) {
      return true;
    }
  }
  return false;
}

private class AliasedTypeNode implements AliasUsage {
  private final Node typeReference;
  private final String aliasName;

  AliasedTypeNode(Node typeReference,
      String aliasName) {
    this.typeReference = typeReference;
    this.aliasName = aliasName;
  }

  @Override
  public void applyAlias() {
    typeReference.setString(aliasName);
  }

private void fixTypeNode(Node typeNode) {
  if (typeNode.isString()) {
    String name = typeNode.getString();
    int endIndex = name.indexOf('.');
    if (endIndex == -1) {
      endIndex = name.length();
    }
    String baseName = name.substring(0, endIndex);
    Var aliasVar = aliases.get(baseName);
    if (aliasVar != null) {
      Node aliasedNode = aliasVar.getInitialValue();
      aliasUsages.add(new AliasedTypeNode(typeNode, aliasedNode.getQualifiedName() + name.substring(endIndex)));
    }
  }

  for (Node child = typeNode.getFirstChild(); child != null;
       child = child.getNext()) {
    fixTypeNode(child);
  }
}

private JSType getDeclaredType(String sourceName, JSDocInfo info,
    Node lValue, @Nullable Node rValue) {
  if (info != null && info.hasType()) {
    return getDeclaredTypeInAnnotation(sourceName, lValue, info);
  } else if (rValue != null && rValue.isFunction() &&
      shouldUseFunctionLiteralType(
          JSType.toMaybeFunctionType(rValue.getJSType()), info, lValue)) {
    return rValue.getJSType();
  } else if (info != null) {
    if (info.hasEnumParameterType()) {
      if (rValue != null && rValue.isObjectLit()) {
        return rValue.getJSType();
      } else {
        return createEnumTypeFromNodes(
            rValue, lValue.getQualifiedName(), info, lValue);
      }
    } else if (info.isConstructor() || info.isInterface()) {
      return createFunctionTypeFromNodes(
          rValue, lValue.getQualifiedName(), info, lValue);
    } else {
      // Check if this is constant, and if it has a known type.
      if (info.isConstant()) {
        JSType knownType = null;
        if (rValue != null) {
          if (rValue.getJSType() != null && !rValue.getJSType().isUnknownType()) {
            // If rValue has a type-cast, we use the type in the type-cast.
            // If rValue's type was already computed during scope creation,
            // then we can safely use that.
            return rValue.getJSType();
          } else if (rValue.isOr()) {
            // Check for a very specific JS idiom:
            // var x = x || TYPE;
            // This is used by Closure's base namespace for esoteric
            // reasons.
            Node firstClause = rValue.getFirstChild();
            Node secondClause = firstClause.getNext();
            boolean namesMatch = firstClause.isName()
                && lValue.isName()
                && firstClause.getString().equals(lValue.getString());
            if (namesMatch && secondClause.getJSType() != null
                && !secondClause.getJSType().isUnknownType()) {
              return secondClause.getJSType();
            }
          }
        }
      }
    }
  }

  return getDeclaredTypeInAnnotation(sourceName, lValue, info);
}

private void applyDelegateRelationship(
    DelegateRelationship delegateRelationship) {
  ObjectType delegatorObject = ObjectType.cast(
      typeRegistry.getType(delegateRelationship.delegator));
  ObjectType delegateBaseObject = ObjectType.cast(
      typeRegistry.getType(delegateRelationship.delegateBase));
  ObjectType delegateSuperObject = ObjectType.cast(
      typeRegistry.getType(codingConvention.getDelegateSuperclassName()));
  if (delegatorObject != null &&
      delegateBaseObject != null &&
      delegateSuperObject != null) {
    FunctionType delegatorCtor = delegatorObject.getConstructor();
    FunctionType delegateBaseCtor = delegateBaseObject.getConstructor();
    FunctionType delegateSuperCtor = delegateSuperObject.getConstructor();

    if (delegatorCtor != null && delegateBaseCtor != null &&
        delegateSuperCtor != null) {
      FunctionParamBuilder functionParamBuilder =
          new FunctionParamBuilder(typeRegistry);
      functionParamBuilder.addRequiredParams(
          getNativeType(U2U_CONSTRUCTOR_TYPE));
      FunctionType findDelegate = typeRegistry.createFunctionType(
          typeRegistry.createDefaultObjectUnion(delegateBaseObject),
          functionParamBuilder.build());

      FunctionType delegateProxy = typeRegistry.createConstructorType(
          delegateBaseObject.getReferenceName() + DELEGATE_PROXY_SUFFIX,
          null, null, null);
      delegateProxy.setPrototypeBasedOn(delegateBaseObject);

      codingConvention.applyDelegateRelationship(
          delegateSuperObject, delegateBaseObject, delegatorObject,
          delegateProxy, findDelegate);
      delegateProxyPrototypes.add(delegateProxy.getPrototype());
    }
  }
}

Node parseInputs() {
  boolean devMode = options.devMode != DevMode.OFF;

  // If old roots exist (we are parsing a second time), detach each of the
  // individual file parse trees.
  if (externsRoot != null) {
    externsRoot.detachChildren();
  }
  if (jsRoot != null) {
    jsRoot.detachChildren();
  }

  // Parse main JS sources.
  jsRoot = IR.block();
  jsRoot.setIsSyntheticBlock(true);

  externsRoot = IR.block();
  externsRoot.setIsSyntheticBlock(true);

  externAndJsRoot = IR.block(externsRoot, jsRoot);
  externAndJsRoot.setIsSyntheticBlock(true);

  if (options.tracer.isOn()) {
    tracker = new PerformanceTracker(jsRoot, options.tracer);
    addChangeHandler(tracker.getCodeChangeHandler());
  }

  Tracer tracer = newTracer("parseInputs");

  try {
    // Parse externs sources.
    for (CompilerInput input : externs) {
      Node n = input.getAstRoot(this);
      if (hasErrors()) {
        return null;
      }
      externsRoot.addChildToBack(n);
    }

    // Modules inferred in ProcessCommonJS pass.
    if (options.transformAMDToCJSModules || options.processCommonJSModules) {
      processAMDAndCommonJSModules();
    }

    hoistExterns(externsRoot);

    // Check if the sources need to be re-ordered.
    boolean staleInputs = false;
    if (options.dependencyOptions.needsManagement() && options.closurePass) {
      for (CompilerInput input : inputs) {
        // Forward-declare all the provided types, so that they
        // are not flagged even if they are dropped from the process.
        for (String provide : input.getProvides()) {
          getTypeRegistry().forwardDeclareType(provide);
        }
      }

      try {
        inputs =
            (moduleGraph == null ? new JSModuleGraph(modules) : moduleGraph)
            .manageDependencies(options.dependencyOptions, inputs);
        staleInputs = true;
      } catch (CircularDependencyException e) {
        report(JSError.make(
            JSModule.CIRCULAR_DEPENDENCY_ERROR, e.getMessage()));

        // If in IDE mode, we ignore the error and keep going.
        if (hasErrors()) {
          return null;
        }
      } catch (MissingProvideException e) {
        report(JSError.make(
            MISSING_ENTRY_ERROR, e.getMessage()));

        // If in IDE mode, we ignore the error and keep going.
        if (hasErrors()) {
          return null;
        }
      }
    }

    hoistNoCompileFiles();

    if (staleInputs) {
      repartitionInputs();
    }

    // Build the AST.
    for (CompilerInput input : inputs) {
      Node n = input.getAstRoot(this);
      if (n == null) {
        continue;
      }

      if (devMode) {
        runSanityCheck();
        if (hasErrors()) {
          return null;
        }
      }

      if (options.sourceMapOutputPath != null ||
          options.nameReferenceReportPath != null) {

        // Annotate the nodes in the tree with information from the
        // input file. This information is used to construct the SourceMap.
        SourceInformationAnnotator sia =
            new SourceInformationAnnotator(
                input.getName(), options.devMode != DevMode.OFF);
        NodeTraversal.traverse(this, n, sia);
      }

      jsRoot.addChildToBack(n);
    }

    if (hasErrors()) {
      return null;
    }
    return externAndJsRoot;
  } finally {
    stopTracer(tracer, "parseInputs");
  }
}

protected void declareNameInScope(FlowScope scope, Node node, JSType type) {
  switch (node.getType()) {
    case Token.NAME:
      scope.inferSlotType(node.getString(), type);
      break;

    case Token.GETPROP:
      String qualifiedName = node.getQualifiedName();
      Preconditions.checkNotNull(qualifiedName);

      JSType origType = node.getJSType();
      origType = origType == null ? getNativeType(UNKNOWN_TYPE) : origType;
      scope.inferQualifiedSlot(node, qualifiedName, origType, type);
      break;

      // "this" references aren't currently modeled in the CFG.

    default:
      throw new IllegalArgumentException("Node cannot be refined. \n" +
          node.toStringTree());
  }
}

private Node tryFoldSimpleFunctionCall(Node n) {
  Preconditions.checkState(n.isCall());
  Node callTarget = n.getFirstChild();
  if (callTarget != null && callTarget.isName() &&
        callTarget.getString().equals("String")) {
    // Fold String(a) to '' + (a) on immutable literals,
    // which allows further optimizations
    //
    // We can't do this in the general case, because String(a) has
    // slightly different semantics than '' + (a). See
    // http://code.google.com/p/closure-compiler/issues/detail?id=759
    Node value = callTarget.getNext();
    if (value != null) {
      Node addition = IR.add(
          IR.string("").srcref(callTarget),
          value.detachFromParent());
      n.getParent().replaceChild(n, addition);
      reportCodeChange();
      return addition;
    }
  }
  return n;
}

public void visit(NodeTraversal t, Node n, Node parent) {
  // VOID nodes appear when there are extra semicolons at the BLOCK level.
  // I've been unable to think of any cases where this indicates a bug,
  // and apparently some people like keeping these semicolons around,
  // so we'll allow it.
  if (n.isEmpty() ||
      n.isComma()) {
    return;
  }

  if (parent == null) {
    return;
  }

  // Do not try to remove a block or an expr result. We already handle
  // these cases when we visit the child, and the peephole passes will
  // fix up the tree in more clever ways when these are removed.
  if (n.isExprResult()) {
    return;
  }

  // This no-op statement was there so that JSDoc information could
  // be attached to the name. This check should not complain about it.
  if (n.isQualifiedName() && n.getJSDocInfo() != null) {
    return;
  }

  boolean isResultUsed = NodeUtil.isExpressionResultUsed(n);
  boolean isSimpleOp = NodeUtil.isSimpleOperatorType(n.getType());
  if (parent.getType() == Token.COMMA) {
    if (isResultUsed) {
      return;
    }
    if (n == parent.getLastChild()) {
      for (Node an : parent.getAncestors()) {
        int ancestorType = an.getType();
        if (ancestorType == Token.COMMA) continue;
        if (ancestorType != Token.EXPR_RESULT && ancestorType != Token.BLOCK) return;
        else break;
      }
    }
  } else if (parent.getType() != Token.EXPR_RESULT && parent.getType() != Token.BLOCK) {
    if (! (parent.getType() == Token.FOR && parent.getChildCount() == 4 && (n == parent.getFirstChild() || n == parent.getFirstChild().getNext().getNext()))) {
      return;
    }
  }
  if (
      (isSimpleOp || !NodeUtil.mayHaveSideEffects(n, t.getCompiler()))) {
    String msg = "This code lacks side-effects. Is there a bug?";
    if (n.isString()) {
      msg = "Is there a missing '+' on the previous line?";
    } else if (isSimpleOp) {
      msg = "The result of the '" + Token.name(n.getType()).toLowerCase() +
          "' operator is not being used.";
    }

    t.getCompiler().report(
        t.makeError(n, level, USELESS_CODE_ERROR, msg));
    // TODO(johnlenz): determine if it is necessary to
    // try to protect side-effect free statements as well.
    if (!NodeUtil.isStatement(n)) {
      problemNodes.add(n);
    }
  }
}

public void visit(NodeTraversal t, Node n, Node parent) {
  // VOID nodes appear when there are extra semicolons at the BLOCK level.
  // I've been unable to think of any cases where this indicates a bug,
  // and apparently some people like keeping these semicolons around,
  // so we'll allow it.
  if (n.isEmpty() ||
      n.isComma()) {
    return;
  }

  if (parent == null) {
    return;
  }

  // Do not try to remove a block or an expr result. We already handle
  // these cases when we visit the child, and the peephole passes will
  // fix up the tree in more clever ways when these are removed.
  if (parent.getType() == Token.COMMA) {
    Node gramps = parent.getParent();
    if (gramps.isCall() && parent == gramps.getFirstChild()) {
      if (n == parent.getFirstChild() && parent.getChildCount() == 2 && n.getNext().isName() && "eval".equals(n.getNext().getString())) {
    return;
      }
  }

  // This no-op statement was there so that JSDoc information could
  // be attached to the name. This check should not complain about it.
    if (n == parent.getLastChild()) {
      for (Node an : parent.getAncestors()) {
        int ancestorType = an.getType();
        if (ancestorType == Token.COMMA)
          continue;
        if (ancestorType != Token.EXPR_RESULT && ancestorType != Token.BLOCK)
          return;
        else
          break;
      }
    }
  } else if (parent.getType() != Token.EXPR_RESULT && parent.getType() != Token.BLOCK) {
    if (parent.getType() == Token.FOR && parent.getChildCount() == 4 && (n == parent.getFirstChild() ||
         n == parent.getFirstChild().getNext().getNext())) {
    } else {
    return;
    }
  }

  boolean isResultUsed = NodeUtil.isExpressionResultUsed(n);
  boolean isSimpleOp = NodeUtil.isSimpleOperatorType(n.getType());
  if (!isResultUsed &&
      (isSimpleOp || !NodeUtil.mayHaveSideEffects(n, t.getCompiler()))) {
    if (n.isQualifiedName() && n.getJSDocInfo() != null) {
      return;
    } else if (n.isExprResult()) {
      return;
    }
    String msg = "This code lacks side-effects. Is there a bug?";
    if (n.isString()) {
      msg = "Is there a missing '+' on the previous line?";
    } else if (isSimpleOp) {
      msg = "The result of the '" + Token.name(n.getType()).toLowerCase() +
          "' operator is not being used.";
    }

    t.getCompiler().report(
        t.makeError(n, level, USELESS_CODE_ERROR, msg));
    // TODO(johnlenz): determine if it is necessary to
    // try to protect side-effect free statements as well.
    if (!NodeUtil.isStatement(n)) {
      problemNodes.add(n);
    }
  }
}

private Node tryFoldArrayAccess(Node n, Node left, Node right) {
  Node parent = n.getParent();
  // If GETPROP/GETELEM is used as assignment target the array literal is
  // acting as a temporary we can't fold it here:
  //    "[][0] += 1"
  if (isAssignmentTarget(n)) {
    return n;
  }

  if (!right.isNumber()) {
    // Sometimes people like to use complex expressions to index into
    // arrays, or strings to index into array methods.
    return n;
  }

  double index = right.getDouble();
  int intIndex = (int) index;
  if (intIndex != index) {
    error(INVALID_GETELEM_INDEX_ERROR, right);
    return n;
  }

  if (intIndex < 0) {
    error(INDEX_OUT_OF_BOUNDS_ERROR, right);
    return n;
  }

  Node current = left.getFirstChild();
  Node elem = null;
  for (int i = 0; current != null && i < intIndex; i++) {
    elem = current;
    current = current.getNext();
  }

  if (elem == null) {
    error(INDEX_OUT_OF_BOUNDS_ERROR, right);
    return n;
  }

  if (elem.isEmpty()) {
    elem = NodeUtil.newUndefinedNode(elem);
  } else {
    left.removeChild(elem);
  }

  // Replace the entire GETELEM with the value
  n.getParent().replaceChild(n, elem);
  reportCodeChange();
  return elem;
}

private void findAliases(NodeTraversal t) {
  Scope scope = t.getScope();
  for (Var v : scope.getVarIterable()) {
    Node n = v.getNode();
    int type = n.getType();
    Node parent = n.getParent();
    if (parent.isVar()) {
      if (n.hasChildren() && n.getFirstChild().isQualifiedName()) {
        String name = n.getString();
        Var aliasVar = scope.getVar(name);
        if (aliasVar != null) {
          aliases.put(name, aliasVar);

          String qualifiedName =
              aliasVar.getInitialValue().getQualifiedName();
          transformation.addAlias(name, qualifiedName);
          // Bleeding functions already get a BAD_PARAMETERS error, so just
          // do nothing.
          // Parameters of the scope function also get a BAD_PARAMETERS
          // error.
        }
      } else {
        // TODO(robbyw): Support using locals for private variables.
        report(t, n, GOOG_SCOPE_NON_ALIAS_LOCAL, n.getString());
      }
    }
  }
}

private FlowScope traverseNew(Node n, FlowScope scope) {

  Node constructor = n.getFirstChild();
  scope = traverse(constructor, scope);
  JSType constructorType = constructor.getJSType();
  JSType type = null;
  if (constructorType != null) {
    constructorType = constructorType.restrictByNotNullOrUndefined();
    if (constructorType.isUnknownType()) {
      type = getNativeType(UNKNOWN_TYPE);
    } else {
      FunctionType ct = constructorType.toMaybeFunctionType();
      if (ct == null && constructorType instanceof FunctionType) {
        // If constructorType is a NoObjectType, then toMaybeFunctionType will
        // return null. But NoObjectType implements the FunctionType
        // interface, precisely because it can validly construct objects.
        ct = (FunctionType) constructorType;
      }
      if (ct != null && ct.isConstructor()) {
        type = ct.getInstanceType();
      }
    }
  }
  n.setJSType(type);
  for (Node arg = constructor.getNext(); arg != null; arg = arg.getNext()) {
    scope = traverse(arg, scope);
  }
  return scope;
}

private class ProcessCommonJsModulesCallback extends
    AbstractPostOrderCallback {

  private int scriptNodeCount = 0;

  @Override
  public void visit(NodeTraversal t, Node n, Node parent) {
    if (n.isCall() && n.getChildCount() == 2 &&
        "require".equals(n.getFirstChild().getQualifiedName()) &&
        n.getChildAtIndex(1).isString()) {
      visitRequireCall(t, n, parent);
    }

    if (n.isScript()) {
      scriptNodeCount++;
      visitScript(t, n);
    }

    if (n.isGetProp() &&
        "module.exports".equals(n.getQualifiedName())) {
      visitModuleExports(n);
    }
  }

private void visitModuleExports(Node prop) {
  String moduleName = guessCJSModuleName(prop.getSourceFileName());
  Node module = prop.getChildAtIndex(0);
  module.putProp(Node.ORIGINALNAME_PROP, "module");
  module.setString(moduleName);
  Node exports = prop.getChildAtIndex(1);
  exports.putProp(Node.ORIGINALNAME_PROP, "exports");
  exports.setString("module$exports");
}

public static Node tryFinally(Node tryBody, Node finallyBody) {
  Preconditions.checkState(tryBody.isTry());
  Preconditions.checkState(finallyBody.isBlock());
  Node catchBody = block().copyInformationFrom(tryBody);
  return new Node(Token.TRY, tryBody, catchBody, finallyBody);
}

public static Node tryCatch(Node tryBody, Node catchNode) {
  Preconditions.checkState(tryBody.isBlock());
  Preconditions.checkState(catchNode.isCatch());
  Node catchBody = block(catchNode).copyInformationFrom(catchNode);
  return new Node(Token.TRY, tryBody, catchBody);
}

private boolean isInlinableObject(List<Reference> refs) {
  boolean ret = false;
  for (Reference ref : refs) {
    Node name = ref.getNode();
    Node parent = ref.getParent();
    Node gramps = ref.getGrandparent();

    // Ignore indirect references, like x.y (except x.y(), since
    // the function referenced by y might reference 'this').
    //
    if (parent.isGetProp()) {
      Preconditions.checkState(parent.getFirstChild() == name);
      // A call target maybe using the object as a 'this' value.
      if (gramps.isCall()
          && gramps.getFirstChild() == parent) {
        return false;
      }

      // NOTE(nicksantos): This pass's object-splitting algorithm has
      // a blind spot. It assumes that if a property isn't defined on an
      // object, then the value is undefined. This is not true, because
      // Object.prototype can have arbitrary properties on it.
      //
      // We short-circuit this problem by bailing out if we see a reference
      // to a property that isn't defined on the object literal. This
      // isn't a perfect algorithm, but it should catch most cases.
      continue;
    }

    // Only rewrite VAR declarations or simple assignment statements
    if (!isVarOrAssignExprLhs(name)) {
       return false;
    }

    Node val = ref.getAssignedValue();
    if (val == null) {
      // A var with no assignment.
      continue;
    }

    // We're looking for object literal assignments only.
    if (!val.isObjectLit()) {
      return false;
    }

    // Make sure that the value is not self-refential. IOW,
    // disallow things like x = {b: x.a}.
    //
    // TODO: Only exclude unorderable self-referential
    // assignments. i.e. x = {a: x.b, b: x.a} is not orderable,
    // but x = {a: 1, b: x.a} is.
    //
    // Also, ES5 getters/setters aren't handled by this pass.
    for (Node child = val.getFirstChild(); child != null;
         child = child.getNext()) {
      if (child.isGetterDef() ||
          child.isSetterDef()) {
        // ES5 get/set not supported.
        return false;
      }


      Node childVal = child.getFirstChild();
      // Check if childVal is the parent of any of the passed in
      // references, as that is how self-referential assignments
      // will happen.
      for (Reference t : refs) {
        Node refNode = t.getParent();
        while (!NodeUtil.isStatementBlock(refNode)) {
          if (refNode == childVal) {
            // There's a self-referential assignment
            return false;
          }
          refNode = refNode.getParent();
        }
      }
    }


    // We have found an acceptable object literal assignment. As
    // long as there are no other assignments that mess things up,
    // we can inline.
    ret = true;
  }
  return ret;
}

public void process(Node externs, Node root) {
  (new NodeTraversal(compiler, this)).traverseRoots(externs, root);
}

public void visit(NodeTraversal t, Node n, Node parent) {
  if (n.isName() && jsScope.isDeclared(n.getString(), true)) {
    Var dep = jsScope.getVar(n.getString());
    if (dep != null) {
      def.depends.add(dep);
    }
  }
}

boolean dependsOnOuterScopeVars(String name, Node useNode) {
  Preconditions.checkArgument(getCfg().hasNode(useNode));
  GraphNode<Node, Branch> n = getCfg().getNode(useNode);
  FlowState<MustDef> state = n.getAnnotation();
  Definition def = state.getIn().reachingDef.get(jsScope.getVar(name));

  if (def != null) {
    for (Var s : def.depends) {
      if (s.scope != jsScope) {
        return true;
      }
    }
  }
  return false;
}

Node parseInputs() {
  boolean devMode = options.devMode != DevMode.OFF;

  // If old roots exist (we are parsing a second time), detach each of the
  // individual file parse trees.
  if (externsRoot != null) {
    externsRoot.detachChildren();
  }
  if (jsRoot != null) {
    jsRoot.detachChildren();
  }

  // Parse main js sources.
  jsRoot = IR.block();
  jsRoot.setIsSyntheticBlock(true);

  externsRoot = IR.block();
  externsRoot.setIsSyntheticBlock(true);

  externAndJsRoot = IR.block(externsRoot, jsRoot);
  externAndJsRoot.setIsSyntheticBlock(true);

  if (options.tracer.isOn()) {
    tracker = new PerformanceTracker(jsRoot, options.tracer);
    addChangeHandler(tracker.getCodeChangeHandler());
  }

  Tracer tracer = newTracer("parseInputs");

  try {
    // Parse externs sources.
    for (CompilerInput input : externs) {
      Node n = input.getAstRoot(this);
      if (hasErrors()) {
        return null;
      }
      externsRoot.addChildToBack(n);
    }

    // Modules inferred in ProcessCommonJS pass.
    if (options.transformAMDToCJSModules || options.processCommonJSModules) {
      processAMDAndCommonJSModules();
    }

    // Check if inputs need to be rebuilt from modules.
    boolean staleInputs = false;

    // Check if the sources need to be re-ordered.
    if (options.dependencyOptions.needsManagement() &&
        !options.skipAllPasses &&
        options.closurePass) {
      for (CompilerInput input : inputs) {
        // Forward-declare all the provided types, so that they
        // are not flagged even if they are dropped from the process.
        for (String provide : input.getProvides()) {
          getTypeRegistry().forwardDeclareType(provide);
        }
      }

      try {
        inputs =
            (moduleGraph == null ? new JSModuleGraph(modules) : moduleGraph)
            .manageDependencies(options.dependencyOptions, inputs);
        staleInputs = true;
      } catch (CircularDependencyException e) {
        report(JSError.make(
            JSModule.CIRCULAR_DEPENDENCY_ERROR, e.getMessage()));

        // If in IDE mode, we ignore the error and keep going.
        if (hasErrors()) {
          return null;
        }
      } catch (MissingProvideException e) {
        report(JSError.make(
            MISSING_ENTRY_ERROR, e.getMessage()));

        // If in IDE mode, we ignore the error and keep going.
        if (hasErrors()) {
          return null;
        }
      }
    }

    for (CompilerInput input : inputs) {
      Node n = input.getAstRoot(this);

      // Inputs can have a null AST during initial parse.
      if (n == null) {
        continue;
      }

      if (n.getJSDocInfo() != null) {
        JSDocInfo info = n.getJSDocInfo();
        if (info.isExterns()) {
          // If the input file is explicitly marked as an externs file, then
          // assume the programmer made a mistake and throw it into
          // the externs pile anyways.
          externsRoot.addChildToBack(n);
          input.setIsExtern(true);

          input.getModule().remove(input);

          externs.add(input);
          staleInputs = true;
        } else if (info.isNoCompile()) {
          input.getModule().remove(input);
          staleInputs = true;
        }
      }
    }

    if (staleInputs) {
      fillEmptyModules(modules);
      rebuildInputsFromModules();
    }

    // Build the AST.
    for (CompilerInput input : inputs) {
      Node n = input.getAstRoot(this);
      if (n == null) {
        continue;
      }

      if (devMode) {
        runSanityCheck();
        if (hasErrors()) {
          return null;
        }
      }

      if (options.sourceMapOutputPath != null ||
          options.nameReferenceReportPath != null) {

        // Annotate the nodes in the tree with information from the
        // input file. This information is used to construct the SourceMap.
        SourceInformationAnnotator sia =
            new SourceInformationAnnotator(
                input.getName(), options.devMode != DevMode.OFF);
        NodeTraversal.traverse(this, n, sia);
      }

      jsRoot.addChildToBack(n);
    }

    if (hasErrors()) {
      return null;
    }
    return externAndJsRoot;
  } finally {
    stopTracer(tracer, "parseInputs");
  }
}

if (token == JsDocToken.EOL) {
  if (state == State.SEARCHING_NEWLINE) {
    state = State.SEARCHING_ANNOTATION;
  }
  token = next();
  continue retry;
} else {
  state = State.SEARCHING_NEWLINE;
  token = eatTokensUntilEOL();
  continue retry;
}

case EOF:
  // discard any accumulated information
  jsdocBuilder.build(null);
  parser.addParserWarning("msg.unexpected.eof",
      stream.getLineno(), stream.getCharno());
  checkExtendedTypes(extendedTypes);
  return false;

case MODIFIES:
  token = parseModifiesTag(next());
  continue retry;

case SEE:
  if (jsdocBuilder.shouldParseDocumentation()) {
    ExtractionInfo referenceInfo = extractSingleLineBlock();
    String reference = referenceInfo.string;

    if (reference.length() == 0) {
      parser.addParserWarning("msg.jsdoc.seemissing",
          stream.getLineno(), stream.getCharno());
    } else {
      jsdocBuilder.addReference(reference);
    }

    token = referenceInfo.token;
  } else {
    token = eatTokensUntilEOL(token);
  }
  continue retry;

case SUPPRESS:
  token = parseSuppressTag(next());
  continue retry;

case TEMPLATE:
  ExtractionInfo templateInfo = extractSingleLineBlock();
  String templateTypeName = templateInfo.string;

  if (templateTypeName.length() == 0) {
    parser.addTypeWarning("msg.jsdoc.templatemissing",
          stream.getLineno(), stream.getCharno());
  } else if (!jsdocBuilder.recordTemplateTypeName(
      templateTypeName)) {
    parser.addTypeWarning("msg.jsdoc.template.at.most.once",
          stream.getLineno(), stream.getCharno());
  }

  token = templateInfo.token;
  continue retry;

case IDGENERATOR:
  if (!jsdocBuilder.recordIdGenerator()) {
    parser.addParserWarning("msg.jsdoc.idgen",
      stream.getLineno(), stream.getCharno());
  }
  token = eatTokensUntilEOL();
  continue retry;

case VERSION:
  ExtractionInfo versionInfo = extractSingleLineBlock();
  String version = versionInfo.string;

  if (version.length() == 0) {
    parser.addParserWarning("msg.jsdoc.versionmissing",
          stream.getLineno(), stream.getCharno());
  } else {
    if (!jsdocBuilder.recordVersion(version)) {
       parser.addParserWarning("msg.jsdoc.extraversion",
          stream.getLineno(), stream.getCharno());
    }
  }

  token = versionInfo.token;
  continue retry;

case DEFINE:
case RETURN:
case THIS:
case TYPE:
case TYPEDEF:
  lineno = stream.getLineno();
  charno = stream.getCharno();

  Node typeNode = null;
  if (!lookAheadForTypeAnnotation() &&
      annotation == Annotation.RETURN) {
    // If RETURN doesn't have a type annotation, record
    // it as the unknown type.
    typeNode = newNode(Token.QMARK);
  } else {
    skipEOLs();
    token = next();
    typeNode = parseAndRecordTypeNode(token);
  }

  if (annotation == Annotation.THIS) {
    typeNode = wrapNode(Token.BANG, typeNode);
    if (typeNode != null && token != JsDocToken.LC) {
      typeNode.putBooleanProp(Node.BRACELESS_TYPE, true);
    }
  }
  type = createJSTypeExpression(typeNode);

  if (type == null) {
    // error reported during recursive descent
    // recovering parsing
  } else {
    switch (annotation) {
      case DEFINE:
        if (!jsdocBuilder.recordDefineType(type)) {
          parser.addParserWarning("msg.jsdoc.define",
              lineno, charno);
        }
        break;

      case RETURN:
        if (!jsdocBuilder.recordReturnType(type)) {
          parser.addTypeWarning(
              "msg.jsdoc.incompat.type", lineno, charno);
          break;
        }

        // Find the return's description (if applicable).
        if (jsdocBuilder.shouldParseDocumentation()) {
          ExtractionInfo returnDescriptionInfo =
              extractMultilineTextualBlock(token);

          String returnDescription =
              returnDescriptionInfo.string;

          if (returnDescription.length() > 0) {
            jsdocBuilder.recordReturnDescription(
                returnDescription);
          }

          token = returnDescriptionInfo.token;
        } else {
          token = eatTokensUntilEOL(token);
        }
        continue retry;

      case THIS:
        if (!jsdocBuilder.recordThisType(type)) {
          parser.addTypeWarning(
              "msg.jsdoc.incompat.type", lineno, charno);
        }
        break;

      case TYPE:
        if (!jsdocBuilder.recordType(type)) {
          parser.addTypeWarning(
              "msg.jsdoc.incompat.type", lineno, charno);
        }
        break;

      case TYPEDEF:
        if (!jsdocBuilder.recordTypedef(type)) {
          parser.addTypeWarning(
              "msg.jsdoc.incompat.type", lineno, charno);
        }
        break;
    }
  }

  token = eatTokensUntilEOL();
  continue retry;

case THROWS:
  skipEOLs();
  token = next();
  lineno = stream.getLineno();
  charno = stream.getCharno();
  type = null;

  if (token == JsDocToken.LC) {
    type = createJSTypeExpression(
        parseAndRecordTypeNode(token));

    if (type == null) {
      // parsing error reported during recursive descent
      // recovering parsing
      token = eatTokensUntilEOL();
      continue retry;
    }
  }

  // *Update* the token to that after the type annotation.
  token = current();

  // Save the throw type.
  jsdocBuilder.recordThrowType(type);

  // Find the throw's description (if applicable).
  if (jsdocBuilder.shouldParseDocumentation()) {
    ExtractionInfo descriptionInfo =
        extractMultilineTextualBlock(token);

    String description = descriptionInfo.string;

    if (description.length() > 0) {
      jsdocBuilder.recordThrowDescription(type, description);
    }

    token = descriptionInfo.token;
  } else {
    token = eatTokensUntilEOL(token);
  }
  continue retry;

public void matchConstraint(ObjectType constraintObj) {
  // We only want to match contraints on anonymous types.

  // Handle the case where the constraint object is a record type.
  //
  // param constraintObj {{prop: (number|undefined)}}
  // function f(constraintObj) {}
  // f({});
  //
  // We want to modify the object literal to match the constraint, by
  // taking any each property on the record and trying to match
  // properties on this object.
  if (constraintObj.isRecordType()) {
    for (String prop : constraintObj.getOwnPropertyNames()) {
      JSType propType = constraintObj.getPropertyType(prop);
      if (!isPropertyTypeDeclared(prop)) {
        JSType typeToInfer = propType;
        if (!hasProperty(prop)) {
          typeToInfer = getNativeType(JSTypeNative.VOID_TYPE)
              .getLeastSupertype(propType);
        }
        defineInferredProperty(prop, typeToInfer, null);
      }
    }
  }
}

if (input == bottomScope) {
  return input;
}

FlowScope output = input.createChildFlowScope();
output = traverse(n, output);
return output;

List<FlowScope> result = Lists.newArrayListWithCapacity(branchEdges.size());
for (DiGraphEdge<Node, Branch> branchEdge : branchEdges) {
  Branch branch = branchEdge.getValue();
  FlowScope newScope = output;

  switch (branch) {
    case ON_TRUE:
      if (NodeUtil.isForIn(source)) {
        Node item = source.getFirstChild();
        Node obj = item.getNext();

        FlowScope informed = traverse(obj, output.createChildFlowScope());

        if (item.isVar()) {
          item = item.getFirstChild();
        }
        if (item.isName()) {
          JSType iterKeyType = getNativeType(STRING_TYPE);
          ObjectType objType = getJSType(obj).dereference();
          JSType objIndexType = objType == null ?
              null : objType.getIndexType();
          if (objIndexType != null && !objIndexType.isUnknownType()) {
            JSType narrowedKeyType =
                iterKeyType.getGreatestSubtype(objIndexType);
            if (!narrowedKeyType.isEmptyType()) {
              iterKeyType = narrowedKeyType;
            }
          }
          redeclareSimpleVar(informed, item, iterKeyType);
        }
        newScope = informed;
        break;
      }

      // FALL THROUGH

    case ON_FALSE:
      if (condition == null) {
        condition = NodeUtil.getConditionExpression(source);
        if (condition == null && source.isCase()) {
          condition = source;

          // conditionFlowScope is cached from previous iterations
          // of the loop.
          if (conditionFlowScope == null) {
            conditionFlowScope = traverse(
                condition.getFirstChild(), output.createChildFlowScope());
          }
        }
      }

      if (condition != null) {
        if (condition.isAnd() ||
            condition.isOr()) {
          BooleanOutcomePair conditionOutcomes =
              traverseWithinShortCircuitingBinOp(condition, output.createChildFlowScope());
          newScope =
              reverseInterpreter.getPreciserScopeKnowingConditionOutcome(
                  condition,
                  conditionOutcomes.getOutcomeFlowScope(
                      condition.getType(), branch == Branch.ON_TRUE),
                  branch == Branch.ON_TRUE);
        } else {
          // conditionFlowScope is cached from previous iterations
          // of the loop.
          if (conditionFlowScope == null) {
            conditionFlowScope =
                traverse(condition, output.createChildFlowScope());
          }
          newScope =
              reverseInterpreter.getPreciserScopeKnowingConditionOutcome(
                  condition, conditionFlowScope, branch == Branch.ON_TRUE);
        }
      }
      break;
  }

  result.add(newScope.optimize());
}
return result;

/**
 * Filters variables declared as "constant", and declares them in the outer
 * declaredConstants map.
 *
 * In Google coding conventions, this means anything declared with @const
 * or named in all caps, and initialized to an immutable value.
 * CheckConsts has already verified that these are truly constants.
 */
private class IdentifyConstants implements Predicate<Var> {
  @Override
  public boolean apply(Var var) {
    return var.isConst();
  }
}

/**
 * Filters non-global variables.
 */
private class IdentifyLocals implements Predicate<Var> {
  @Override
  public boolean apply(Var var) {
    return var.scope.isLocal();
  }
}

private void traverseFunction(Node n, Node parent) {
  Preconditions.checkState(n.getChildCount() == 3);
  Preconditions.checkState(n.isFunction());

  final Node fnName = n.getFirstChild();

  boolean isFunctionExpression = (parent != null)
      && NodeUtil.isFunctionExpression(n);

  if (!isFunctionExpression) {
    // Functions declarations are in the scope containing the declaration.
    traverseBranch(fnName, n);
  }

  curNode = n;
  pushScope(n);

  if (isFunctionExpression) {
    // Function expression names are only accessible within the function
    // scope.
    traverseBranch(fnName, n);
  }

  final Node args = fnName.getNext();
  final Node body = args.getNext();

  // Args
  traverseBranch(args, n);

  // Body
  Preconditions.checkState(body.getNext() == null &&
          body.isBlock());
  traverseBranch(body, n);

  popScope();
}

Node processFunctionNode(FunctionNode functionNode) {
  Name name = functionNode.getFunctionName();
  Boolean isUnnamedFunction = false;
  if (name == null) {
    int functionType = functionNode.getFunctionType();
    if (functionType != FunctionNode.FUNCTION_EXPRESSION) {
      errorReporter.error(
        "unnamed function statement",
        sourceName,
        functionNode.getLineno(), "", 0);

      // Return the bare minimum to put the AST in a valid state.
      return newNode(Token.EXPR_RESULT, Node.newNumber(0));
    }
    name = new Name();
    name.setIdentifier("");
    isUnnamedFunction = true;
  }
  Node node = newNode(Token.FUNCTION);
  Node newName = transform(name);
  if (isUnnamedFunction) {
    // Old Rhino tagged the empty name node with the line number of the
    // declaration.
    newName.setLineno(functionNode.getLineno());
    // TODO(bowdidge) Mark line number of paren correctly.
    // Same problem as below - the left paren might not be on the
    // same line as the function keyword.
    int lpColumn = functionNode.getAbsolutePosition() +
        functionNode.getLp();
    newName.setCharno(position2charno(lpColumn));
    maybeSetLengthFrom(newName, name);
  }

  node.addChildToBack(newName);
  Node lp = newNode(Token.PARAM_LIST);
  // The left paren's complicated because it's not represented by an
  // AstNode, so there's nothing that has the actual line number that it
  // appeared on.  We know the paren has to appear on the same line as the
  // function name (or else a semicolon will be inserted.)  If there's no
  // function name, assume the paren was on the same line as the function.
  // TODO(bowdidge): Mark line number of paren correctly.
  Name fnName = functionNode.getFunctionName();
  if (fnName != null) {
    lp.setLineno(fnName.getLineno());
  } else {
    lp.setLineno(functionNode.getLineno());
  }
  int lparenCharno = functionNode.getLp() +
      functionNode.getAbsolutePosition();

  lp.setCharno(position2charno(lparenCharno));
  for (AstNode param : functionNode.getParams()) {
    lp.addChildToBack(transform(param));
  }
  node.addChildToBack(lp);

  Node bodyNode = transform(functionNode.getBody());
    // When in ideMode Rhino tries to parse some constructs the compiler
    // doesn't support, repair it here. see Rhino's
    // Parser#parseFunctionBodyExpr.
  parseDirectives(bodyNode);
  node.addChildToBack(bodyNode);
 return node;
}

void addNumber(double x) {
  // This is not pretty printing. This is to prevent misparsing of x- -4 as
  // x--4 (which is a syntax error).
  char prev = getLastChar();
  boolean negativeZero = isNegativeZero(x);
  if (x < 0 && prev == '-') {
    add(" ");
  }

  if ((long) x == x && !negativeZero) {
    long value = (long) x;
    long mantissa = value;
    int exp = 0;
    if (Math.abs(x) >= 100) {
      while (mantissa / 10 * Math.pow(10, exp + 1) == value) {
        mantissa /= 10;
        exp++;
      }
    }
    if (exp > 2) {
      add(Long.toString(mantissa) + "E" + Integer.toString(exp));
    } else {
      add(Long.toString(value));
    }
  } else {
    add(String.valueOf(x));
  }
}

String toStringHelper(boolean forAnnotations) {
  if (hasReferenceName()) {
    return getReferenceName();
  } else if (prettyPrint) {
    // Don't pretty print recursively.
    prettyPrint = false;

    // Use a tree set so that the properties are sorted.
    Set<String> propertyNames = Sets.newTreeSet();
    for (ObjectType current = this;
         current != null && !current.isNativeObjectType() &&
             propertyNames.size() <= MAX_PRETTY_PRINTED_PROPERTIES;
         current = current.getImplicitPrototype()) {
      propertyNames.addAll(current.getOwnPropertyNames());
    }

    StringBuilder sb = new StringBuilder();
    sb.append("{");

    int i = 0;
    for (String property : propertyNames) {
      if (i > 0) {
        sb.append(", ");
      }

      sb.append(property);
      sb.append(": ");
      sb.append(getPropertyType(property).toString());

      ++i;
      if (i == MAX_PRETTY_PRINTED_PROPERTIES) {
        sb.append(", ...");
        break;
      }
    }

    sb.append("}");

    prettyPrint = true;
    return sb.toString();
  } else {
    return "{...}";
  }
}

public void visit(NodeTraversal t, Node n, Node parent) {

  // Record global variable and function declarations
  if (t.inGlobalScope()) {
    if (NodeUtil.isVarDeclaration(n)) {
      NameInformation ns = createNameInformation(t, n, parent);
      Preconditions.checkNotNull(ns);
      recordSet(ns.name, n);
    } else if (NodeUtil.isFunctionDeclaration(n)) {
      Node nameNode = n.getFirstChild();
      NameInformation ns = createNameInformation(t, nameNode, n);
      if (ns != null) {
        JsName nameInfo = getName(nameNode.getString(), true);
        recordSet(nameInfo.name, nameNode);
      }
    } else if (NodeUtil.isObjectLitKey(n, parent)) {
      NameInformation ns = createNameInformation(t, n, parent);
      if (ns != null) {
        recordSet(ns.name, n);
      }
    }
  }

  // Record assignments and call sites
  if (n.isAssign()) {
    Node nameNode = n.getFirstChild();

    NameInformation ns = createNameInformation(t, nameNode, n);
    if (ns != null) {
      if (ns.isPrototype) {
        recordPrototypeSet(ns.prototypeClass, ns.prototypeProperty, n);
      } else {
        recordSet(ns.name, nameNode);
      }
    }
  } else if (n.isCall()) {
    Node nameNode = n.getFirstChild();
    NameInformation ns = createNameInformation(t, nameNode, n);
    if (ns != null && ns.onlyAffectsClassDef) {
      JsName name = getName(ns.name, false);
      if (name != null) {
      refNodes.add(new ClassDefiningFunctionNode(
          name, n, parent, parent.getParent()));
      }
    }
  }
}

Node processForInLoop(ForInLoop loopNode) {

    // Return the bare minimum to put the AST in a valid state.
    Node iterator = transform(loopNode.getIterator());
    Node iteratedObject = transform(loopNode.getIteratedObject());
    Node body = transformBlock(loopNode.getBody());
    return newNode(Token.FOR, iterator, iteratedObject, body);
}

public void visit(NodeTraversal t, Node n, Node parent) {
  inputId = t.getInputId();
  attachLiteralTypes(t, n);

  switch (n.getType()) {
    case Token.CALL:
      checkForClassDefiningCalls(t, n, parent);
      checkForCallingConventionDefiningCalls(n, delegateCallingConventions);
      break;

    case Token.FUNCTION:
      if (t.getInput() == null || !t.getInput().isExtern()) {
        nonExternFunctions.add(n);
      }

      // Hoisted functions are handled during pre-traversal.
      if (!NodeUtil.isHoistedFunctionDeclaration(n)) {
        defineFunctionLiteral(n, parent);
      }
      break;

    case Token.ASSIGN:
      // Handle initialization of properties.
      Node firstChild = n.getFirstChild();
      if (firstChild.isGetProp() &&
          firstChild.isQualifiedName()) {
        maybeDeclareQualifiedName(t, n.getJSDocInfo(),
            firstChild, n, firstChild.getNext());
      }
      break;

    case Token.CATCH:
      defineCatch(n, parent);
      break;

    case Token.VAR:
      defineVar(n, parent);
      break;

    case Token.GETPROP:
      // Handle stubbed properties.
      if (parent.isExprResult() &&
          n.isQualifiedName()) {
        maybeDeclareQualifiedName(t, n.getJSDocInfo(), n, parent, null);
      }
      break;
  }

  // Analyze any @lends object literals in this statement.
}

private void attachLiteralTypes(NodeTraversal t, Node n) {
  switch (n.getType()) {
    case Token.NULL:
      n.setJSType(getNativeType(NULL_TYPE));
      break;

    case Token.VOID:
      n.setJSType(getNativeType(VOID_TYPE));
      break;

    case Token.STRING:
      // Defer keys to the Token.OBJECTLIT case
      if (!NodeUtil.isObjectLitKey(n, n.getParent())) {
        n.setJSType(getNativeType(STRING_TYPE));
      }
      break;

    case Token.NUMBER:
      n.setJSType(getNativeType(NUMBER_TYPE));
      break;

    case Token.TRUE:
    case Token.FALSE:
      n.setJSType(getNativeType(BOOLEAN_TYPE));
      break;

    case Token.REGEXP:
      n.setJSType(getNativeType(REGEXP_TYPE));
      break;

    case Token.OBJECTLIT:
        defineObjectLiteral(n);
      break;

      // NOTE(nicksantos): If we ever support Array tuples,
      // we will need to put ARRAYLIT here as well.
  }
}

