public void enterScope(NodeTraversal t) {
  Node declarationRoot = t.getScopeRoot();
  Renamer renamer;
  if (nameStack.isEmpty()) {
    // If the contextual renamer is being used the starting context can not
    // be a function.
    Preconditions.checkState(
        declarationRoot.getType() != Token.FUNCTION ||
        !(rootRenamer instanceof ContextualRenamer));
    Preconditions.checkState(t.inGlobalScope());
    renamer = rootRenamer;
  } else {
    renamer = nameStack.peek().forChildScope();
  }

  if (declarationRoot.getType() == Token.FUNCTION) {
    for (Node c = declarationRoot.getFirstChild().getNext().getFirstChild(); c != null; c = c.getNext()) {
      String name = c.getString();
      renamer.addDeclaredName(name);
    }
    Node functionBody = declarationRoot.getLastChild();
    findDeclaredNames(functionBody, null, renamer);
  }  else 
  if (declarationRoot.getType() != Token.FUNCTION) {
    // Add the block declarations
    findDeclaredNames(declarationRoot, null, renamer);
  }
  nameStack.push(renamer);
}

public boolean shouldTraverse(NodeTraversal t, Node n, Node parent) {

  switch (n.getType()) {
    case Token.FUNCTION:
      {
        // Add recursive function name, if needed.
        // NOTE: "enterScope" is called after we need to pick up this name.
        Renamer renamer = nameStack.peek().forChildScope();

        // If needed, add the function recursive name.
        String name = n.getFirstChild().getString();
        if (name != null && !name.isEmpty() && parent != null
            && !NodeUtil.isFunctionDeclaration(n)) {
          renamer.addDeclaredName(name);
        }

        // Add the function parameters
        for (Node param = n.getSecondChild(); param != null; param = param.getNext()) {
          if (param.isName()) {
            renamer.addDeclaredName(param.getString());
          }
        }

        // Add the function body declarations
        Node functionBody = n.getLastChild();
        findDeclaredNames(functionBody, null, renamer);

        nameStack.push(renamer);
      }
      break;

    case Token.CATCH:
      {
        Renamer renamer = nameStack.peek().forChildScope();

        String name = n.getFirstChild().getString();
        renamer.addDeclaredName(name);

        nameStack.push(renamer);
      }
      break;
  }

  return true;
}

public void visit(NodeTraversal t, Node n, Node parent) {
  switch (n.getType()) {
    case Token.NAME:
      String newName = getReplacementName(n.getString());
      if (newName != null) {
        Renamer renamer = nameStack.peek();
        if (renamer.stripConstIfReplaced()) {
          // TODO(johnlenz): Do we need to do anything about the javadoc?
          n.removeProp(Node.IS_CONSTANT_NAME);
        }
        n.setString(newName);
        t.getCompiler().reportCodeChange();
      }
      break;

    case Token.FUNCTION:
      // Remove the function body scope
      // Remove function recursive name (if any).
      nameStack.pop();
      break;

    case Token.CATCH:
      // Remove catch except name from the stack of names.
      nameStack.pop();
      break;
  }
}

private Node tryFoldArrayJoin(Node n) {
  Node callTarget = n.getFirstChild();

  if (callTarget == null || !NodeUtil.isGetProp(callTarget)) {
    return n;
  }

  Node right = callTarget.getNext();
  if (right != null) {
    if (!NodeUtil.isImmutableValue(right)) {
      return n;
    }
  }

  Node arrayNode = callTarget.getFirstChild();
  Node functionName = arrayNode.getNext();

  if ((arrayNode.getType() != Token.ARRAYLIT) ||
      !functionName.getString().equals("join")) {
    return n;
  }

  String joinString = (right == null) ? "," : NodeUtil.getStringValue(right);
  List<Node> arrayFoldedChildren = Lists.newLinkedList();
  StringBuilder sb = null;
  int foldedSize = 0;
  Node prev = null;
  Node elem = arrayNode.getFirstChild();
  // Merges adjacent String nodes.
  while (elem != null) {
    if (NodeUtil.isImmutableValue(elem) || elem.getType() == Token.EMPTY) {
      if (sb == null) {
        sb = new StringBuilder();
      } else {
        sb.append(joinString);
      }
      sb.append(NodeUtil.getArrayElementStringValue(elem));
    } else {
      if (sb != null) {
        Preconditions.checkNotNull(prev);
        // + 2 for the quotes.
        foldedSize += sb.length() + 2;
        arrayFoldedChildren.add(
            Node.newString(sb.toString()).copyInformationFrom(prev));
        sb = null;
      }
      foldedSize += InlineCostEstimator.getCost(elem);
      arrayFoldedChildren.add(elem);
    }
    prev = elem;
    elem = elem.getNext();
  }

  if (sb != null) {
    Preconditions.checkNotNull(prev);
    // + 2 for the quotes.
    foldedSize += sb.length() + 2;
    arrayFoldedChildren.add(
        Node.newString(sb.toString()).copyInformationFrom(prev));
  }
  // one for each comma.
  foldedSize += arrayFoldedChildren.size() - 1;

  int originalSize = InlineCostEstimator.getCost(n);
  switch (arrayFoldedChildren.size()) {
    case 0:
      Node emptyStringNode = Node.newString("");
      n.getParent().replaceChild(n, emptyStringNode);
      reportCodeChange();
      return emptyStringNode;
    case 1:
      Node foldedStringNode = arrayFoldedChildren.remove(0);
      if (foldedSize > originalSize) {
        return n;
      }
      arrayNode.detachChildren();
      if (foldedStringNode.getType() != Token.STRING) {
        // If the Node is not a string literal, ensure that
        // it is coerced to a string.
        Node replacement = new Node(Token.ADD,
            Node.newString("").copyInformationFrom(n),
            foldedStringNode);
        foldedStringNode = replacement;
      }
      n.getParent().replaceChild(n, foldedStringNode);
      reportCodeChange();
      return foldedStringNode;
    default:
      // No folding could actually be performed.
      if (arrayFoldedChildren.size() == arrayNode.getChildCount()) {
        return n;
      }
      int kJoinOverhead = "[].join()".length();
      foldedSize += kJoinOverhead;
      foldedSize += (right != null) ? InlineCostEstimator.getCost(right) : 0;
      if (foldedSize > originalSize) {
        return n;
      }
      arrayNode.detachChildren();
      for (Node node : arrayFoldedChildren) {
        arrayNode.addChildToBack(node);
      }
      reportCodeChange();
      break;
  }

  return n;
}

void addNumber(double x) {
  // This is not pretty printing. This is to prevent misparsing of x- -4 as
  // x--4 (which is a syntax error).
  char prev = getLastChar();
  if (x < 0 && prev == '-') {
    add(" ");
  }

  if ((long) x == x) {
    long value = (long) x;
    long mantissa = value;
    int exp = 0;
    if (Math.abs(x) >= 100) {
      while (mantissa / 10 * Math.pow(10, exp + 1) == value) {
        mantissa /= 10;
        exp++;
      }
    }
    if (exp > 2) {
      add(Long.toString(mantissa) + "E" + Integer.toString(exp));
    } else {
      add(Long.toString(value));
    }
  } else {
    add(String.valueOf(x));
  }

}

static boolean isSimpleNumber(String s) {
  int len = s.length();
  if (len == 0) {
    return false;
  }
  for (int index = 0; index < len; index++) {
    char c = s.charAt(index);
    if (c < '0' || c > '9') {
      return false;
    }
  }
  return true;
}

private boolean isInlinableObject(List<Reference> refs) {
    boolean ret = false;
    for (Reference ref : refs) {
        Node name = ref.getNode();
        Node parent = ref.getParent();
        Node gramps = ref.getGrandparent();

        if (parent.getType() == Token.GETPROP) {
            Preconditions.checkState(parent.getFirstChild() == name);
            if (gramps.getType() == Token.CALL && gramps.getFirstChild() == parent) {
                return false;
            }
            continue;
        }

        if (!isVarOrAssignExprLhs(name)) {
            return false;
        }

        Node val = ref.getAssignedValue();
        if (val == null) {
            continue;
        }

        if (val.getType() != Token.OBJECTLIT) {
            return false;
        }

        for (Node child = val.getFirstChild(); child != null; child = child.getNext()) {
            if (child.getType() == Token.GET || child.getType() == Token.SET) {
                return false;
            }
            Node childVal = child.getFirstChild();
            for (Reference t : refs) {
                Node refNode = t.getParent();
                while (!NodeUtil.isStatementBlock(refNode)) {
                    if (refNode == childVal) {
                        return false;
                    }
                    refNode = refNode.getParent();
                }
            }
        }

        ret = true;
    }
    return ret;
}

private void replaceAssignmentExpression(Var v, Reference ref, Map<String, String> varmap) {
    List<Node> nodes = Lists.newArrayList();
    Node val = ref.getAssignedValue();
    blacklistVarReferencesInTree(val, v.scope);
    Preconditions.checkState(val.getType() == Token.OBJECTLIT);
    Set<String> all = Sets.newLinkedHashSet(varmap.keySet());
    for (Node key = val.getFirstChild(); key != null; key = key.getNext()) {
        String var = key.getString();
        Node value = key.removeFirstChild();
        nodes.add(new Node(Token.ASSIGN, Node.newString(Token.NAME, varmap.get(var)), value));
        all.remove(var);
    }

    for (String var : all) {
        nodes.add(new Node(Token.ASSIGN, Node.newString(Token.NAME, varmap.get(var)), NodeUtil.newUndefinedNode(null)));
    }

    Node replacement = new Node(Token.TRUE);
    for (Node node : nodes) {
        replacement.addChildToFront(node);
    }

    Node replace = ref.getParent();
    replacement.copyInformationFromForTree(replace);

    if (replace.getType() == Token.VAR) {
        replace.getParent().replaceChild(replace, NodeUtil.newExpr(replacement));
    } else {
        replace.getParent().replaceChild(replace, replacement);
    }
}

public void visit(NodeTraversal t, Node n, Node parent) {
  inputId = t.getInputId();
  attachLiteralTypes(t, n);

  switch (n.getType()) {
    case Token.CALL:
      checkForClassDefiningCalls(t, n, parent);
      checkForCallingConventionDefiningCalls(n, delegateCallingConventions);
      break;

    case Token.FUNCTION:
      if (t.getInput() == null || !t.getInput().isExtern()) {
        nonExternFunctions.add(n);
      }

      // Hoisted functions are handled during pre-traversal.
      if (!NodeUtil.isHoistedFunctionDeclaration(n)) {
        defineFunctionLiteral(n, parent);
      }
      break;

    case Token.ASSIGN:
      // Handle initialization of properties.
      Node firstChild = n.getFirstChild();
      if (firstChild.getType() == Token.GETPROP &&
          firstChild.isQualifiedName()) {
        maybeDeclareQualifiedName(t, n.getJSDocInfo(),
            firstChild, n, firstChild.getNext());
      }
      break;

    case Token.CATCH:
      defineCatch(n, parent);
      break;

    case Token.VAR:
      defineVar(n, parent);
      break;

    case Token.GETPROP:
      // Handle stubbed properties.
      if (parent.getType() == Token.EXPR_RESULT &&
          n.isQualifiedName()) {
        maybeDeclareQualifiedName(t, n.getJSDocInfo(), n, parent, null);
      }
      break;
  }
}

public boolean setPrototype(PrototypeObjectType prototype) {
  if (prototype == null) {
    return false;
  }
  // getInstanceType fails if the function is not a constructor
  if (isConstructor() && prototype == getInstanceType()) {
    return false;
  }

  boolean replacedPrototype = prototype != null;

  this.prototype = prototype;
  this.prototypeSlot = new SimpleSlot("prototype", prototype, true);
  this.prototype.setOwnerFunction(this);

    // Disassociating the old prototype makes this easier to debug--
    // we don't have to worry about two prototypes running around.

  if (isConstructor() || isInterface()) {
    FunctionType superClass = getSuperClassConstructor();
    if (superClass != null) {
      superClass.addSubType(this);
    }

    if (isInterface()) {
      for (ObjectType interfaceType : getExtendedInterfaces()) {
        if (interfaceType.getConstructor() != null) {
          interfaceType.getConstructor().addSubType(this);
        }
      }
    }
  }

  if (replacedPrototype) {
    clearCachedValues();
  }

  return true;
}

private static boolean isReduceableFunctionExpression(Node n) {
  return NodeUtil.isFunctionExpression(n) && !NodeUtil.isArrowFunction(n);
}

public String getLine(int lineNumber) {
  String js = "";
  try {
    // NOTE(nicksantos): Right now, this is optimized for few warnings.
    // This is probably the right trade-off, but will be slow if there
    // are lots of warnings in one file.
    js = getCode();
  } catch (IOException e) {
    return null;
  }

  int pos = 0;
  int startLine = 1;

  // If we've saved a previous offset and it's for a line less than the
  // one we're searching for, then start at that point.
  if (lineNumber >= lastLine) {
    pos = lastOffset;
    startLine = lastLine;
  }

  for (int n = startLine; n < lineNumber; n++) {
    int nextpos = js.indexOf('\n', pos);
    if (nextpos == -1) {
      return null;
    }
    pos = nextpos + 1;
  }

  // Remember this offset for the next search we do.
  lastOffset = pos;
  lastLine = lineNumber;

  int nextpos = js.indexOf('\n', pos);
  if (nextpos == -1) {
    // If next new line cannot be found, there are two cases
    // 1. pos already reaches the end of file, then null should be returned
    // 2. otherwise, return the contents between pos and the end of file.
    return js.substring(pos);
  } else {
    return js.substring(pos, nextpos);
  }
}

private void computeGenKill(Node n, BitSet gen, BitSet kill,
    boolean conditional) {

  switch (n.getType()) {
    case Token.SCRIPT:
    case Token.BLOCK:
    case Token.FUNCTION:
      return;

    case Token.WHILE:
    case Token.DO:
    case Token.IF:
      computeGenKill(NodeUtil.getConditionExpression(n), gen, kill,
          conditional);
      return;

    case Token.FOR:
      if (!NodeUtil.isForIn(n)) {
        computeGenKill(NodeUtil.getConditionExpression(n), gen, kill,
            conditional);
      } else {
        // for(x in y) {...}
        Node lhs = n.getFirstChild();
        Node rhs = lhs.getNext();
        if (NodeUtil.isVar(lhs)) {
          // for(var x in y) {...}
          lhs = lhs.getLastChild();
        }
          addToSetIfLocal(lhs, kill);
          addToSetIfLocal(lhs, gen);
        computeGenKill(rhs, gen, kill, conditional);
      }
      return;

    case Token.VAR:
      for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
        if (c.hasChildren()) {
          computeGenKill(c.getFirstChild(), gen, kill, conditional);
          if (!conditional) {
            addToSetIfLocal(c, kill);
          }
        }
      }
      return;

    case Token.AND:
    case Token.OR:
      computeGenKill(n.getFirstChild(), gen, kill, conditional);
      // May short circuit.
      computeGenKill(n.getLastChild(), gen, kill, true);
      return;

    case Token.HOOK:
      computeGenKill(n.getFirstChild(), gen, kill, conditional);
      // Assume both sides are conditional.
      computeGenKill(n.getFirstChild().getNext(), gen, kill, true);
      computeGenKill(n.getLastChild(), gen, kill, true);
      return;

    case Token.NAME:
      if (isArgumentsName(n)) {
        markAllParametersEscaped();
      } else {
        addToSetIfLocal(n, gen);
      }
      return;

    default:
      if (NodeUtil.isAssignmentOp(n) && NodeUtil.isName(n.getFirstChild())) {
        Node lhs = n.getFirstChild();
        if (!conditional) {
          addToSetIfLocal(lhs, kill);
        }
        if (!NodeUtil.isAssign(n)) {
          // assignments such as a += 1 reads a.
          addToSetIfLocal(lhs, gen);
        }
        computeGenKill(lhs.getNext(), gen, kill, conditional);
      } else {
        for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
          computeGenKill(c, gen, kill, conditional);
        }
      }
      return;
  }
}

private void addToSetIfLocal(Node node, BitSet set) {
  Preconditions.checkState(NodeUtil.isName(node));
  String name = node.getString();
  if (!jsScope.isDeclared(name, false)) {
    return;
  }
  Var var = jsScope.getVar(name);
  if (!escaped.contains(var)) {
    set.set(var.index);
  }
}

/**
 * Give up computing liveness of formal parameter by putting all the parameter
 * names in the escaped set.
 */
void markAllParametersEscaped() {
  Node lp = jsScope.getRootNode().getFirstChild().getNext();
  for(Node arg = lp.getFirstChild(); arg != null; arg = arg.getNext()) {
    escaped.add(jsScope.getVar(arg.getString()));
  }
}

private boolean isArgumentsName(Node n) {
  if (n.getType() != Token.NAME ||
      !n.getString().equals(ARGUMENT_ARRAY_ALIAS) ||
      jsScope.isDeclared(ARGUMENT_ARRAY_ALIAS, false)) {
    return false;
  } else {
    return true;
  }
}

public void initOptions(CompilerOptions options) {
  this.options = options;
  if (errorManager == null) {
    if (outStream == null) {
      setErrorManager(
          new LoggerErrorManager(createMessageFormatter(), logger));
    } else {
      PrintStreamErrorManager printer =
          new PrintStreamErrorManager(createMessageFormatter(), outStream);
      printer.setSummaryDetailLevel(options.summaryDetailLevel);
      setErrorManager(printer);
    }
  }

  // DiagnosticGroups override the plain checkTypes option.
  if (options.enables(DiagnosticGroups.CHECK_TYPES)) {
    options.checkTypes = true;
  } else if (options.disables(DiagnosticGroups.CHECK_TYPES)) {
    options.checkTypes = false;
  } else if (!options.checkTypes) {
    // If DiagnosticGroups did not override the plain checkTypes
    // option, and checkTypes is enabled, then turn off the
    // parser type warnings.
    options.setWarningLevel(
        DiagnosticGroup.forType(
            RhinoErrorReporter.TYPE_PARSE_ERROR),
        CheckLevel.OFF);
  }

  if (options.checkGlobalThisLevel.isOn()) {
    options.setWarningLevel(
        DiagnosticGroups.GLOBAL_THIS,
        options.checkGlobalThisLevel);
  }

  if (options.getLanguageIn() == LanguageMode.ECMASCRIPT5_STRICT) {
    options.setWarningLevel(
        DiagnosticGroups.ES5_STRICT,
        CheckLevel.ERROR);
  }

  // Initialize the warnings guard.
  List<WarningsGuard> guards = Lists.newArrayList();
  guards.add(
      new SuppressDocWarningsGuard(
          getDiagnosticGroups().getRegisteredGroups()));
  guards.add(options.getWarningsGuard());

  ComposeWarningsGuard composedGuards = new ComposeWarningsGuard(guards);

  // All passes must run the variable check. This synthesizes
  // variables later so that the compiler doesn't crash. It also
  // checks the externs file for validity. If you don't want to warn
  // about missing variable declarations, we shut that specific
  // error off.
  if (!options.checkSymbols &&
      !composedGuards.enables(DiagnosticGroups.CHECK_VARIABLES)) {
    composedGuards.addGuard(new DiagnosticGroupWarningsGuard(
        DiagnosticGroups.CHECK_VARIABLES, CheckLevel.OFF));
  }

  this.warningsGuard = composedGuards;
}

static TernaryValue getImpureBooleanValue(Node n) {
  switch (n.getType()) {
    case Token.ASSIGN:
    case Token.COMMA:
      // For ASSIGN and COMMA the value is the value of the RHS.
      return getImpureBooleanValue(n.getLastChild());
    case Token.NOT:
      TernaryValue value = getImpureBooleanValue(n.getLastChild());
      return value.not();
    case Token.AND: {
      TernaryValue lhs = getImpureBooleanValue(n.getFirstChild());
      TernaryValue rhs = getImpureBooleanValue(n.getLastChild());
      return lhs.and(rhs);
    }
    case Token.OR:  {
      TernaryValue lhs = getImpureBooleanValue(n.getFirstChild());
      TernaryValue rhs = getImpureBooleanValue(n.getLastChild());
      return lhs.or(rhs);
    }
    case Token.HOOK:  {
      TernaryValue trueValue = getImpureBooleanValue(
          n.getFirstChild().getNext());
      TernaryValue falseValue = getImpureBooleanValue(n.getLastChild());
      if (trueValue.equals(falseValue)) {
        return trueValue;
      } else {
        return TernaryValue.UNKNOWN;
      }
    }
    case Token.ARRAYLIT:
    case Token.OBJECTLIT:
      // ignoring side-effects
      return TernaryValue.TRUE;
    default:
      return getPureBooleanValue(n);
  }
}

static TernaryValue getPureBooleanValue(Node n) {
  switch (n.getType()) {
    case Token.STRING:
      return TernaryValue.forBoolean(n.getString().length() > 0);

    case Token.NUMBER:
      return TernaryValue.forBoolean(n.getDouble() != 0);

    case Token.NOT:
      return getPureBooleanValue(n.getLastChild()).not();

    case Token.NULL:
    case Token.FALSE:
      return TernaryValue.FALSE;

    case Token.VOID:
        return TernaryValue.FALSE;

    case Token.NAME:
      String name = n.getString();
      if ("undefined".equals(name)
          || "NaN".equals(name)) {
        // We assume here that programs don't change the value of the keyword
        // undefined to something other than the value undefined.
        return TernaryValue.FALSE;
      } else if ("Infinity".equals(name)) {
        return TernaryValue.TRUE;
      }
      break;

    case Token.TRUE:
    case Token.REGEXP:
      return TernaryValue.TRUE;

    case Token.ARRAYLIT:
    case Token.OBJECTLIT:
      if (!mayHaveSideEffects(n)) {
        return TernaryValue.TRUE;
      }
      break;
  }

  return TernaryValue.UNKNOWN;
}

