private String format(JSError error, boolean warning) {
  // extract source excerpt
  SourceExcerptProvider source = getSource();
  String sourceExcerpt = source == null ? null :
      excerpt.get(
          source, error.sourceName, error.lineNumber, excerptFormatter);

  // formatting the message
  StringBuilder b = new StringBuilder();
  if (error.sourceName != null) {
    b.append(error.sourceName);
    if (error.lineNumber > 0) {
      b.append(':');
      b.append(error.lineNumber);
    }
    b.append(": ");
  }

  b.append(getLevelName(warning ? CheckLevel.WARNING : CheckLevel.ERROR));
  b.append(" - ");

  b.append(error.description);
  b.append('\n');
  if (sourceExcerpt != null) {
    b.append(sourceExcerpt);
    b.append('\n');
    int charno = error.getCharno();

    // padding equal to the excerpt and arrow at the end
    // charno == sourceExpert.length() means something is missing
    // at the end of the line
    if (excerpt.equals(LINE)
        && 0 <= charno && charno < sourceExcerpt.length()) {
      for (int i = 0; i < charno; i++) {
        char c = sourceExcerpt.charAt(i);
        if (Character.isWhitespace(c)) {
          b.append(c);
        } else {
          b.append(' ');
        }
      }
      b.append("^\n");
    }
  }
  return b.toString();
}

runInCompilerThread(new Callable<Void>() {
  public Void call() throws Exception {
    if (options.printInputDelimiter) {
      if ((cb.getLength() > 0) && !cb.endsWith("\n")) {
        cb.append("\n");  // Make sure that the label starts on a new line
      }
      Preconditions.checkState(root.getType() == Token.SCRIPT);

      String delimiter = options.inputDelimiter;

      String sourceName = (String)root.getProp(Node.SOURCENAME_PROP);
      Preconditions.checkState(sourceName != null);
      Preconditions.checkState(!sourceName.isEmpty());

      delimiter = delimiter.replaceAll("%name%", sourceName)
        .replaceAll("%num%", String.valueOf(inputSeqNum));

      cb.append(delimiter)
        .append("\n");
    }
    if (root.getJSDocInfo() != null &&
        root.getJSDocInfo().getLicense() != null) {
      cb.append("/*\n")
        .append(root.getJSDocInfo().getLicense())
        .append("*/\n");
    }

    // If there is a valid source map, then indicate to it that the current
    // root node's mappings are offset by the given string builder buffer.
    if (options.sourceMapOutputPath != null) {
      sourceMap.setStartingPosition(
          cb.getLineIndex(), cb.getColumnIndex());
    }

    // if LanguageMode is ECMASCRIPT5_STRICT, only print 'use strict'
    // for the first input file
    String code = toSource(root, sourceMap);
    if (!code.isEmpty()) {
      cb.append(code);

      // In order to avoid parse ambiguity when files are concatenated
      // together, all files should end in a semi-colon. Do a quick
      // heuristic check if there's an obvious semi-colon already there.
      int length = code.length();
      char lastChar = code.charAt(length - 1);
      char secondLastChar = length >= 2 ?
          code.charAt(length - 2) : '\0';
      boolean hasSemiColon = lastChar == ';' ||
          (lastChar == '\n' && secondLastChar == ';');
      if (!hasSemiColon) {
        cb.append(";");
      }
    }
    return null;
  }
});

String toSource(Node n) {
  initCompilerOptionsIfTesting();
  return toSource(n, null);
}

private String toSource(Node n, SourceMap sourceMap) {
  CodePrinter.Builder builder = new CodePrinter.Builder(n);
  builder.setPrettyPrint(options.prettyPrint);
  builder.setLineBreak(options.lineBreak);
  builder.setSourceMap(sourceMap);
  builder.setSourceMapDetailLevel(options.sourceMapDetailLevel);
  builder.setTagAsStrict(
      options.getLanguageOut() == LanguageMode.ECMASCRIPT5_STRICT);
  builder.setLineLengthThreshold(options.lineLengthThreshold);

  Charset charset = options.outputCharset != null ?
      Charset.forName(options.outputCharset) : null;
  builder.setOutputCharset(charset);

  return builder.build();
}

case Token.FUNCTION:
  if (n.getClass() != Node.class) {
    throw new Error("Unexpected Node subclass.");
  }
  Preconditions.checkState(childCount == 3);
  boolean funcNeedsParens = (context == Context.START_OF_EXPR);
  if (funcNeedsParens) {
    add("(");
  }

  add("function");
  add(first);

  add(first.getNext());
  add(last, Context.PRESERVE_BLOCK);
  cc.endFunction(context == Context.STATEMENT);

  if (funcNeedsParens) {
    add(")");
  }
  break;

case Token.GETPROP: {
  Preconditions.checkState(
      childCount == 2,
      "Bad GETPROP: expected 2 children, but got %s", childCount);
  Preconditions.checkState(
      last.getType() == Token.STRING,
      "Bad GETPROP: RHS should be STRING");
  boolean needsParens = (first.getType() == Token.NUMBER);
  if (needsParens) {
    add("(");
  }
  addLeftExpr(first, NodeUtil.precedence(type), context);
  if (needsParens) {
    add(")");
  }
  add(".");
  addIdentifier(last.getString());
  break;
}

private boolean isPrototypePropertyAssign(Node assign) {
  Node n = assign.getFirstChild();
  if (n != null && NodeUtil.isVarOrSimpleAssignLhs(n, assign)
      && n.getType() == Token.GETPROP
      ) {
    // We want to exclude the assignment itself from the usage list
    boolean isChainedProperty =
        n.getFirstChild().getType() == Token.GETPROP;

    if (isChainedProperty) {
      Node child = n.getFirstChild().getFirstChild().getNext();

      if (child.getType() == Token.STRING &&
          child.getString().equals("prototype")) {
        return true;
      }
    }
  }

  return false;
}

private void visitCall(NodeTraversal t, Node n) {
  Node child = n.getFirstChild();
  JSType childType = getJSType(child).restrictByNotNullOrUndefined();

  if (!childType.canBeCalled()) {
    report(t, n, NOT_CALLABLE, childType.toString());
    ensureTyped(t, n);
    return;
  }

  // A couple of types can be called as if they were functions.
  // If it is a function type, then validate parameters.
  if (childType instanceof FunctionType) {
    FunctionType functionType = (FunctionType) childType;

    boolean isExtern = false;
    JSDocInfo functionJSDocInfo = functionType.getJSDocInfo();
    if(functionJSDocInfo != null) {
      String sourceName = functionJSDocInfo.getSourceName();
      CompilerInput functionSource = compiler.getInput(sourceName);
      isExtern = functionSource.isExtern();
    }

    // Non-native constructors should not be called directly
    // unless they specify a return type and are defined
    // in an extern.
    if (functionType.isConstructor() &&
        !functionType.isNativeObjectType() &&
        (functionType.getReturnType().isUnknownType() ||
         functionType.getReturnType().isVoidType() ||
         !isExtern)) {
      report(t, n, CONSTRUCTOR_NOT_CALLABLE, childType.toString());
    }

    // Functions with explcit 'this' types must be called in a GETPROP
    // or GETELEM.

    visitParameterList(t, n, functionType);
    ensureTyped(t, n, functionType.getReturnType());
  } else {
    ensureTyped(t, n);
  }

  // TODO: Add something to check for calls of RegExp objects, which is not
  // supported by IE.  Either say something about the return type or warn
  // about the non-portability of the call or both.
}

private void declareArguments(Node functionNode) {
  Node astParameters = functionNode.getFirstChild().getNext();
  Node body = astParameters.getNext();
  FunctionType functionType = (FunctionType) functionNode.getJSType();
  if (functionType != null) {
    Node jsDocParameters = functionType.getParametersNode();
    if (jsDocParameters != null) {
      Node jsDocParameter = jsDocParameters.getFirstChild();
      for (Node astParameter : astParameters.children()) {
        if (jsDocParameter != null) {
          defineSlot(astParameter, functionNode,
              jsDocParameter.getJSType(), true);
          jsDocParameter = jsDocParameter.getNext();
        } else {
          defineSlot(astParameter, functionNode, null, true);
        }
      }
    }
  }
} // end declareArguments

private void checkNameVisibility(NodeTraversal t, Node name, Node parent) {
  Var var = t.getScope().getVar(name.getString());
  if (var != null) {
    JSDocInfo docInfo = var.getJSDocInfo();
    if (docInfo != null) {
      // If a name is private, make sure that we're in the same file.
      Visibility visibility = docInfo.getVisibility();
      if (visibility == Visibility.PRIVATE &&
          !t.getInput().getName().equals(docInfo.getSourceName())) {
        if (docInfo.isConstructor() &&
            isValidPrivateConstructorAccess(parent)) {
          return;
        }

        compiler.report(
            t.makeError(name, BAD_PRIVATE_GLOBAL_ACCESS,
                name.getString(), docInfo.getSourceName()));
      }
    }
  }
}

private void checkPropertyVisibility(NodeTraversal t,
    Node getprop, Node parent) {
  ObjectType objectType =
      ObjectType.cast(dereference(getprop.getFirstChild().getJSType()));
  String propertyName = getprop.getLastChild().getString();

  if (objectType != null) {
    // Is this a normal property access, or are we trying to override
    // an existing property?
    boolean isOverride = t.inGlobalScope() &&
        parent.getType() == Token.ASSIGN &&
        parent.getFirstChild() == getprop;

    // Find the lowest property defined on a class with visibility
    // information.
    if (isOverride) {
      objectType = objectType.getImplicitPrototype();
    }
    JSDocInfo docInfo = null;
    for (; objectType != null;
         objectType = objectType.getImplicitPrototype()) {
      docInfo = objectType.getOwnPropertyJSDocInfo(propertyName);
      if (docInfo != null &&
          docInfo.getVisibility() != Visibility.INHERITED) {
        break;
      }
    }

    if (objectType == null) {
      // We couldn't find a visibility modifier; assume it's public.
      return;
    }

    boolean sameInput =
        t.getInput().getName().equals(docInfo.getSourceName());
    Visibility visibility = docInfo.getVisibility();
    JSType ownerType = normalizeClassType(objectType);
    if (isOverride) {
      // Check an ASSIGN statement that's trying to override a property
      // on a superclass.
      JSDocInfo overridingInfo = parent.getJSDocInfo();
      Visibility overridingVisibility = overridingInfo == null ?
          Visibility.INHERITED : overridingInfo.getVisibility();

      // Check that (a) the property *can* be overridden, and
      // (b) that the visibility of the override is the same as the
      // visibility of the original property.
      if (visibility == Visibility.PRIVATE && !sameInput) {
        compiler.report(
            t.makeError(getprop, PRIVATE_OVERRIDE,
                objectType.toString()));
      } else if (overridingVisibility != Visibility.INHERITED &&
          overridingVisibility != visibility) {
        compiler.report(
            t.makeError(getprop, VISIBILITY_MISMATCH,
                visibility.name(), objectType.toString(),
                overridingVisibility.name()));
      }
    } else {
      if (sameInput) {
        // private access is always allowed in the same file.
        return;
      } else if (visibility == Visibility.PRIVATE &&
          (currentClass == null || ownerType.differsFrom(currentClass))) {
        if (docInfo.isConstructor() &&
            isValidPrivateConstructorAccess(parent)) {
          return;
        }

        // private access is not allowed outside the file from a different
        // enclosing class.
        compiler.report(
            t.makeError(getprop,
                BAD_PRIVATE_PROPERTY_ACCESS,
                propertyName,
                validator.getReadableJSTypeName(
                    getprop.getFirstChild(), true)));
      } else if (visibility == Visibility.PROTECTED) {
        // There are 3 types of legal accesses of a protected property:
        // 1) Accesses in the same file
        // 2) Overriding the property in a subclass
        // 3) Accessing the property from inside a subclass
        // The first two have already been checked for.
        if (currentClass == null || !currentClass.isSubtype(ownerType)) {
          compiler.report(
              t.makeError(getprop,  BAD_PROTECTED_PROPERTY_ACCESS,
                  propertyName,
                  validator.getReadableJSTypeName(
                      getprop.getFirstChild(), true)));
        }
      }
    }
  }
}

private void makeLocalNamesUnique(Node fnNode, boolean isCallInLoop) {
  Supplier<String> idSupplier = compiler.getUniqueNameIdSupplier();
  // Make variable names unique to this instance.
  NodeTraversal.traverse(
      compiler, fnNode, new MakeDeclaredNamesUnique(
          new InlineRenamer(
              idSupplier,
              "inline_",
              isCallInLoop)));
  // Make label names unique to this instance.
  NodeTraversal.traverse(
      compiler, fnNode, new RenameLabels(
          compiler,
          idSupplier,
          "label_"));
}

private void visitLabel(Node node, Node parent) {
  Node nameNode = node.getFirstChild();
  Preconditions.checkState(nameNode != null);
  String name = nameNode.getString();
  LabelInfo li = getLabelInfo(name);
  // This is a label...
  if (li.referenced) {
    String newName = getNameForId(li.id);
    if (!name.equals(newName)) {
      // ... and it is used, give it the short name.
      nameNode.setString(newName);
      compiler.reportCodeChange();
    }
  } else {
    // ... and it is not referenced, just remove it.
    Node newChild = node.getLastChild();
    node.removeChild(newChild);
    parent.replaceChild(node, newChild);
    if (newChild.getType() == Token.BLOCK) {
      NodeUtil.tryMergeBlock(newChild);
    }
    compiler.reportCodeChange();
  }

  // Remove the label from the current stack of labels.
  namespaceStack.peek().renameMap.remove(name);
}

private Node tryFoldComparison(Node n, Node left, Node right) {
  if (!NodeUtil.isLiteralValue(left, false) ||
      !NodeUtil.isLiteralValue(right, false)) {
    // We only handle non-literal operands for LT and GT.
    if (n.getType() != Token.GT && n.getType() != Token.LT) {
      return n;
    }
  }

  int op = n.getType();
  boolean result;

  // TODO(johnlenz): Use the JSType to compare nodes of different types.

  boolean rightLiteral = NodeUtil.isLiteralValue(right, false);
  boolean undefinedRight = ((Token.NAME == right.getType()
        && right.getString().equals("undefined"))
        || (Token.VOID == right.getType()
            && NodeUtil.isLiteralValue(right.getFirstChild(), false)));
  int lhType = left.getType();
  int rhType = right.getType();
  switch (lhType) {
    case Token.VOID:
      if (!NodeUtil.isLiteralValue(left.getFirstChild(), false)) {
        return n;
      } else if (!rightLiteral) {
        return n;
      } else {
        result = compareToUndefined(right, op);
      }
      break;

    case Token.NULL:
    case Token.TRUE:
    case Token.FALSE:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }
      if (rhType != Token.TRUE &&
          rhType != Token.FALSE &&
          rhType != Token.NULL) {
        return n;
      }
      switch (op) {
        case Token.SHEQ:
        case Token.EQ:
          result = lhType == rhType;
          break;

        case Token.SHNE:
        case Token.NE:
          result = lhType != rhType;
          break;

        case Token.GE:
        case Token.LE:
        case Token.GT:
        case Token.LT:
          Boolean compareResult = compareAsNumbers(op, left, right);
          if (compareResult != null) {
            result = compareResult;
          } else {
            return n;
          }
          break;

        default:
          return n;  // we only handle == and != here
      }
      break;

    case Token.THIS:
      if (right.getType() != Token.THIS) {
        return n;
      }
      switch (op) {
        case Token.SHEQ:
        case Token.EQ:
          result = true;
          break;

        case Token.SHNE:
        case Token.NE:
          result = false;
          break;

        // We can only handle == and != here.
        // GT, LT, GE, LE depend on the type of "this" and how it will
        // be converted to number.  The results are different depending on
        // whether it is a string, NaN or other number value.
        default:
          return n;
      }
      break;

    case Token.STRING:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }
      if (Token.STRING != right.getType()) {
        return n;  // Only eval if they are the same type
      }
      switch (op) {
        case Token.SHEQ:
        case Token.EQ:
          result = left.getString().equals(right.getString());
          break;

        case Token.SHNE:
        case Token.NE:
          result = !left.getString().equals(right.getString());
          break;

        default:
          return n;  // we only handle == and != here
      }
      break;

    case Token.NUMBER:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }
      if (Token.NUMBER != right.getType()) {
        return n;  // Only eval if they are the same type
      }
      Boolean compareResult = compareAsNumbers(op, left, right);
      if (compareResult != null) {
        result = compareResult;
      } else {
        return n;
      }
      break;

    case Token.NAME:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }

      if (rightLiteral) {
        boolean undefinedLeft = (left.getString().equals("undefined"));
        if (undefinedLeft) {
          result = compareToUndefined(right, op);
          break;
        }
      }

      if (Token.NAME != right.getType()) {
        return n;  // Only eval if they are the same type
      }
      String ln = left.getString();
      String rn = right.getString();
      if (!ln.equals(rn)) {
        return n;  // Not the same value name.
      }

      switch (op) {
        // If we knew the named value wouldn't be NaN, it would be nice
        // to handle EQ,NE,LE,GE,SHEQ, and SHNE.
        case Token.LT:
        case Token.GT:
          result = false;
          break;
        default:
          return n;  // don't handle that op
      }
      break;

    default:
      // assert, this should cover all consts
      return n;
  }

  Node newNode = new Node(result ? Token.TRUE : Token.FALSE);
  n.getParent().replaceChild(n, newNode);
  reportCodeChange();

  return newNode;
}

static Double getStringNumberValue(String rawJsString) {
    // vertical tab is not always whitespace

  String s = trimJsWhiteSpace(rawJsString);
  // return ScriptRuntime.toNumber(s);
  if (s.length() == 0) {
    return 0.0;
  }

  if (s.length() > 2
      && s.charAt(0) == '0'
      && (s.charAt(1) == 'x' || s.charAt(1) == 'X')) {
    // Attempt to convert hex numbers.
    try {
      return Double.valueOf(Integer.parseInt(s.substring(2), 16));
    } catch (NumberFormatException e) {
      return Double.NaN;
    }
  }

  if (s.length() > 3
      && (s.charAt(0) == '-' || s.charAt(0) == '+')
      && s.charAt(1) == '0'
      && (s.charAt(2) == 'x' || s.charAt(2) == 'X')) {
    // hex numbers with explicit signs vary between browsers.
    return Double.NaN;
  }

  // FireFox and IE treat the "Infinity" differently. FireFox is case
  // insensitive, but IE treats "infinity" as NaN.  So leave it alone.
  if (s.equalsIgnoreCase("infinity")) {
    return Double.POSITIVE_INFINITY;
  }

  try {
    return Double.parseDouble(s);
  } catch (NumberFormatException e) {
    return Double.NaN;
  }
}

static TernaryValue isStrWhiteSpaceChar(int c) {
  switch (c) {
    case '\u000B': // <VT>
      return TernaryValue.TRUE;
    case ' ': // <SP>
    case '\n': // <LF>
    case '\r': // <CR>
    case '\t': // <TAB>
    case '\u00A0': // <NBSP>
    case '\u000C': // <FF>
    case '\u2028': // <LS>
    case '\u2029': // <PS>
    case '\uFEFF': // <BOM>
      return TernaryValue.TRUE;
    default:
      return (Character.getType(c) == Character.SPACE_SEPARATOR)
          ? TernaryValue.TRUE : TernaryValue.FALSE;
  }
}

    Node lhs = n.getFirstChild();
    Node rhs = lhs.getNext();

    // Recurse first. Example: dead_x = dead_y = 1; We try to clean up dead_y
    // first.
    if (rhs != null) {
        tryRemoveAssignment(t, rhs, exprRoot, state);
        rhs = lhs.getNext();
    }

    Scope scope = t.getScope();
    if (!NodeUtil.isName(lhs)) {
        return; // Not a local variable assignment.
    }
    String name = lhs.getString();
    if (!scope.isDeclared(name, false)) {
        return;
    }
    Var var = scope.getVar(name);

    if (liveness.getEscapedLocals().contains(var)) {
        return; // Local variable that might be escaped due to closures.
    }

    // If we have an identity assignment such as a=a, always remove it
    // regardless of what the liveness results because it
    // does not change the result afterward.
    if (rhs != null &&
        NodeUtil.isName(rhs) &&
        rhs.getString().equals(var.name) &&
        NodeUtil.isAssign(n)) {
        n.removeChild(rhs);
        n.getParent().replaceChild(n, rhs);
        compiler.reportCodeChange();
        return;
    }

    if (state.getOut().isLive(var)) {
        return; // Variable not dead.
    }

    if (state.getIn().isLive(var) &&
        isVariableStillLiveWithinExpression(n, exprRoot, var.name)) {
        // The variable is killed here but it is also live before it.
        // This is possible if we have say:
        //    if (X = a && a = C) {..} ; .......; a = S;
        // In this case we are safe to remove "a = C" because it is dead.
        // However if we have:
        //    if (a = C && X = a) {..} ; .......; a = S;
        // removing "a = C" is NOT correct, although the live set at the node
        // is exactly the same.
        // TODO(user): We need more fine grain CFA or we need to keep track
        // of GEN sets when we recurse here.
        return;
    }

    if (NodeUtil.isAssign(n)) {
        n.removeChild(rhs);
        n.getParent().replaceChild(n, rhs);
    } else if (NodeUtil.isAssignmentOp(n)) {
        n.removeChild(rhs);
        n.removeChild(lhs);
        Node op = new Node(NodeUtil.getOpFromAssignmentOp(n), lhs, rhs);
        parent.replaceChild(n, op);
    } else if (n.getType() == Token.INC || n.getType() == Token.DEC) {
        if (NodeUtil.isExpressionNode(parent)) {
            parent.replaceChild(n,
                new Node(Token.VOID, Node.newNumber(0).copyInformationFrom(n)));
        } else if(n.getType() == Token.COMMA && n != parent.getLastChild()) {
            parent.removeChild(n);
        } else if (parent.getType() == Token.FOR && !NodeUtil.isForIn(parent) &&
            NodeUtil.getConditionExpression(parent) != n) {
            parent.replaceChild(n, new Node(Token.EMPTY));
        } else {
            // Cannot replace x = a++ with x = a because that's not valid
            // when a is not a number.
            return;
        }
    } else {
        // Not reachable.
        Preconditions.checkState(false, "Unknown statement");
    }

    compiler.reportCodeChange();
    return;

} else {
    for (Node c = n.getFirstChild(); c != null;) {
        Node next = c.getNext();
        if (!ControlFlowGraph.isEnteringNewCfgNode(c)) {
            tryRemoveAssignment(t, c, exprRoot, state);
        }
        c = next;
    }
    return;
}

if (first.getType() == Token.FUNCTION) {
  if (n.getClass() != Node.class) {
    throw new Error("Unexpected Node subclass.");
  }
  Preconditions.checkState(childCount == 3);
  boolean funcNeedsParens = (context == Context.START_OF_EXPR);
  if (funcNeedsParens) {
    add("(");
  }

  add("function");
  add(first);

  add(first.getNext());
  add(last, Context.PRESERVE_BLOCK);
  cc.endFunction(context == Context.STATEMENT);

  if (funcNeedsParens) {
    add(")");
  }
  break;

case Token.GETELEM:
  Preconditions.checkState(
      childCount == 2,
      "Bad GETELEM: expected 2 children but got %s", childCount);
  addLeftExpr(first, NodeUtil.precedence(type), context);
  add("[");
  add(first.getNext());
  add("]");
  break;

private Node performArithmeticOp(int opType, Node left, Node right) {
  // Unlike other operations, ADD operands are not always converted
  // to Number.
  if (opType == Token.ADD
      && (NodeUtil.mayBeString(left, false)
          || NodeUtil.mayBeString(right, false))) {
    return null;
  }

  double result;

  // TODO(johnlenz): Handle NaN with unknown value. BIT ops convert NaN
  // to zero so this is a little akward here.

  Double lValObj = NodeUtil.getNumberValue(left);
  if (lValObj == null) {
    return null;
  }
  Double rValObj = NodeUtil.getNumberValue(right);
  if (rValObj == null) {
    return null;
  }

  double lval = lValObj;
  double rval = rValObj;

  switch (opType) {
    case Token.BITAND:
      result = ScriptRuntime.toInt32(lval) & ScriptRuntime.toInt32(rval);
      break;
    case Token.BITOR:
      result = ScriptRuntime.toInt32(lval) | ScriptRuntime.toInt32(rval);
      break;
    case Token.BITXOR:
      result = ScriptRuntime.toInt32(lval) ^ ScriptRuntime.toInt32(rval);
      break;
    case Token.ADD:
      result = lval + rval;
      break;
    case Token.SUB:
      result = lval - rval;
      break;
    case Token.MUL:
      result = lval * rval;
      break;
    case Token.MOD:
      if (rval == 0) {
        error(DiagnosticType.error("JSC_DIVIDE_BY_0_ERROR", "Divide by 0"), right);
        return null;
      }
      result = lval % rval;
      break;
    case Token.DIV:
      if (rval == 0) {
        error(DiagnosticType.error("JSC_DIVIDE_BY_0_ERROR", "Divide by 0"), right);
        return null;
      }
      result = lval / rval;
      break;
    default:
      throw new Error("Unexpected arithmetic operator");
  }

  // TODO(johnlenz): consider removing the result length check.
  // length of the left and right value plus 1 byte for the operator.
  if (String.valueOf(result).length() <=
      String.valueOf(lval).length() + String.valueOf(rval).length() + 1 &&

      // Do not try to fold arithmetic for numbers > 2^53. After that
      // point, fixed-point math starts to break down and become inaccurate.
      Math.abs(result) <= MAX_FOLD_NUMBER) {
    Node newNumber = Node.newNumber(result);
    return newNumber;
  } else if (Double.isNaN(result)) {
    return Node.newString(Token.NAME, "NaN");
  } else if (result == Double.POSITIVE_INFINITY) {
    return Node.newString(Token.NAME, "Infinity");
  } else if (result == Double.NEGATIVE_INFINITY) {
    return new Node(Token.NEG, Node.newString(Token.NAME, "Infinity"));
  }

  return null;
}

public void process(Node externs, Node root) {
  new NodeTraversal(
      compiler, new NormalizeStatements(compiler, assertOnChange))
      .traverse(root);
  if (MAKE_LOCAL_NAMES_UNIQUE) {
    MakeDeclaredNamesUnique renamer = new MakeDeclaredNamesUnique();
    NodeTraversal t = new NodeTraversal(compiler, renamer);
    t.traverseRoots(externs, root);
  }
  // It is important that removeDuplicateDeclarations runs after
  // MakeDeclaredNamesUnique in order for catch block exception names to be
  // handled properly. Specifically, catch block exception names are
  // only valid within the catch block, but our current Scope logic
  // has no concept of this and includes it in the containing function
  // (or global scope). MakeDeclaredNamesUnique makes the catch exception
  // names unique so that removeDuplicateDeclarations() will properly handle
  // cases where a function scope variable conflicts with an exception name:
  //   function f() {
  //      try {throw 0;} catch(e) {e; /* catch scope 'e'*/}
  //      var e = 1; // f scope 'e'
  //   }
  // otherwise 'var e = 1' would be rewritten as 'e = 1'.
  // TODO(johnlenz): Introduce a separate scope for catch nodes.
  removeDuplicateDeclarations(externs, root);
  new PropagateConstantAnnotationsOverVars(compiler, assertOnChange)
      .process(externs, root);

  if (!compiler.getLifeCycleStage().isNormalized()) {
    compiler.setLifeCycleStage(LifeCycleStage.NORMALIZED);
  }
}

private void createSynthesizedExternVar(String varName) {
  Node nameNode = Node.newString(Token.NAME, varName);

  // Mark the variable as constant if it matches the coding convention
  // for constant vars.
  // NOTE(nicksantos): honestly, I'm not sure how much this matters.
  // AFAIK, all people who use the CONST coding convention also
  // compile with undeclaredVars as errors. We have some test
  // cases for this configuration though, and it makes them happier.
  if (compiler.getCodingConvention().isConstant(varName)) {
    nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
  }

  getSynthesizedExternsRoot().addChildToBack(
      new Node(Token.VAR, nameNode));
  varsToDeclareInExterns.remove(varName);
}

static boolean isBooleanResultHelper(Node n) {
  switch (n.getType()) {
    // Primitives
    case Token.TRUE:
    case Token.FALSE:
    // Comparisons
    case Token.EQ:
    case Token.NE:
    case Token.SHEQ:
    case Token.SHNE:
    case Token.LT:
    case Token.GT:
    case Token.LE:
    case Token.GE:
    // Queryies
    case Token.IN:
    case Token.INSTANCEOF:
    // Inversion
    case Token.NOT:
    // delete operator returns a boolean.
      return true;
    default:
      return false;
  }
}

static boolean evaluatesToLocalValue(Node value, Predicate<Node> locals) {
  switch (value.getType()) {
    case Token.ASSIGN:
      // A result that is aliased by a non-local name, is the effectively the
      // same as returning a non-local name, but this doesn't matter if the
      // value is immutable.
      return NodeUtil.isImmutableValue(value.getLastChild())
          || (locals.apply(value)
              && evaluatesToLocalValue(value.getLastChild(), locals));
    case Token.COMMA:
      return evaluatesToLocalValue(value.getLastChild(), locals);
    case Token.AND:
    case Token.OR:
      return evaluatesToLocalValue(value.getFirstChild(), locals)
         && evaluatesToLocalValue(value.getLastChild(), locals);
    case Token.HOOK:
      return evaluatesToLocalValue(value.getFirstChild().getNext(), locals)
         && evaluatesToLocalValue(value.getLastChild(), locals);
    case Token.INC:
    case Token.DEC:
      if (value.getBooleanProp(Node.INCRDECR_PROP)) {
        return evaluatesToLocalValue(value.getFirstChild(), locals);
      } else {
        return true;
      }
    case Token.THIS:
      return locals.apply(value);
    case Token.NAME:
      return isImmutableValue(value) || locals.apply(value);
    case Token.GETELEM:
    case Token.GETPROP:
      // There is no information about the locality of object properties.
      return locals.apply(value);
    case Token.CALL:
      return callHasLocalResult(value)
          || isToStringMethodCall(value)
          || locals.apply(value);
    case Token.NEW:
      return newHasLocalResult(value)
             || locals.apply(value);
    case Token.FUNCTION:
    case Token.REGEXP:
    case Token.ARRAYLIT:
    case Token.OBJECTLIT:
      // Literals objects with non-literal children are allowed.
      return true;
    case Token.IN:
      // TODO(johnlenz): should IN operator be included in #isSimpleOperator?
      return true;
    default:
      // Other op force a local value:
      //  x = '' + g (x is now an local string)
      //  x -= g (x is now an local number)
      if (isAssignmentOp(value)
          || isSimpleOperator(value)
          || isImmutableValue(value)) {
        return true;
      }

      throw new IllegalStateException(
          "Unexpected expression node" + value +
          "\n parent:" + value.getParent());
  }
}

Node processFunctionNode(FunctionNode functionNode) {
  Name name = functionNode.getFunctionName();
  Boolean isUnnamedFunction = false;
  if (name == null) {
    name = new Name();
    name.setIdentifier("");
    isUnnamedFunction = true;
  }
  Node node = newNode(Token.FUNCTION);
  Node newName = transform(name);
  if (isUnnamedFunction) {
    // Old Rhino tagged the empty name node with the line number of the
    // declaration.
    newName.setLineno(functionNode.getLineno());
    // TODO(bowdidge) Mark line number of paren correctly.
    // Same problem as below - the left paren might not be on the
    // same line as the function keyword.
    int lpColumn = functionNode.getAbsolutePosition() +
        functionNode.getLp();
    newName.setCharno(position2charno(lpColumn));
  }

  node.addChildToBack(newName);
  Node lp = newNode(Token.LP);
  // The left paren's complicated because it's not represented by an
  // AstNode, so there's nothing that has the actual line number that it
  // appeared on.  We know the paren has to appear on the same line as the
  // function name (or else a semicolon will be inserted.)  If there's no
  // function name, assume the paren was on the same line as the function.
  // TODO(bowdidge): Mark line number of paren correctly.
  Name fnName = functionNode.getFunctionName();
  if (fnName != null) {
    lp.setLineno(fnName.getLineno());
  } else {
    lp.setLineno(functionNode.getLineno());
  }
  int lparenCharno = functionNode.getLp() +
      functionNode.getAbsolutePosition();

  lp.setCharno(position2charno(lparenCharno));
  for (AstNode param : functionNode.getParams()) {
    lp.addChildToBack(transform(param));
  }
  node.addChildToBack(lp);

  Node bodyNode = transform(functionNode.getBody());
  parseDirectives(bodyNode);
  node.addChildToBack(bodyNode);
 return node;
}

public final boolean isSubtype(JSType that) {
    if (that.isUnknownType()) {
      return true;
    }
    if (this.isEquivalentTo(that)) {
      return true;
    }
    if (that.isAllType()) {
      return true;
    }
    if (that instanceof UnionType) {
      UnionType union = (UnionType)thatType;
      for (JSType element : union.alternates) {
        if (thisType.isSubtype(element)) {
          return true;
        }
      }
    }
    if (that instanceof NamedType) {
      return thisType.isSubtype(((NamedType)thatType).getReferencedType());
    }
    return false;
}

Node processAssignment(Assignment assignmentNode) {
  Node assign = processInfixExpression(assignmentNode);
  if (assign.getType() == Token.ASSIGN) {
    Node lhs = assign.getFirstChild();
    Node rhs = assign.getLastChild();
    Node result = process(rhs);
    lhs.replaceWith(result);
    return result;
  } else {
    return assign;
  }
}

Node processUnaryExpression(UnaryExpression exprNode) {
  int type = transformTokenType(exprNode.getType());
  Node operand = transform(exprNode.getOperand());
  if (type == Token.NEG && operand.getType() == Token.NUMBER) {
    operand.setDouble(-operand.getDouble());
    return operand;
  } else {

    Node node = newNode(type, operand);
    if (exprNode.isPostfix()) {
      node.putBooleanProp(Node.INCRDECR_PROP, true);
    }
    return node;
  }
}

private Node tryRemoveUnconditionalBranching(Node n) {
  /*
   * For each of the unconditional branching control flow node, check to see
   * if the ControlFlowAnalysis.computeFollowNode of that node is same as
   * the branching target. If it is, the branch node is safe to be removed.
   *
   * This is not as clever as MinimizeExitPoints because it doesn't do any
   * if-else conversion but it handles more complicated switch statements
   * much nicer.
   */

  // If n is null the target is the end of the function, nothing to do.
  if (n == null) {
     return n;
  }

  DiGraphNode<Node, Branch> gNode = curCfg.getDirectedGraphNode(n);

  if (gNode == null) {
    return n;
  }

  if (n.getParent() == null) {
    List<DiGraphEdge<Node,Branch>> outEdges = gNode.getOutEdges();
    if (outEdges.size() == 1) {
      return tryRemoveUnconditionalBranching(outEdges.get(0).getDestination().getValue());
    }
  }
  switch (n.getType()) {
    case Token.BLOCK:
      if (n.hasChildren()) {
        Node first = n.getFirstChild();
        return tryRemoveUnconditionalBranching(first);
      } else {
        return tryRemoveUnconditionalBranching(ControlFlowAnalysis.computeFollowNode(n));
      }
    case Token.RETURN:
      if (n.hasChildren()) {
        break;
      }
    case Token.BREAK:
    case Token.CONTINUE:

      // We are looking for a control flow changing statement that always
      // branches to the same node. If removing it the control flow still
      // branches to that same node. It is safe to remove it.
      List<DiGraphEdge<Node,Branch>> outEdges = gNode.getOutEdges();
      if (outEdges.size() == 1 &&
          // If there is a next node, there is no chance this jump is useless.
          (n.getNext() == null || n.getNext().getType() == Token.FUNCTION)) {

        Preconditions.checkState(outEdges.get(0).getValue() == Branch.UNCOND);
        Node fallThrough = tryRemoveUnconditionalBranching(computeFollowing(n));
        Node nextCfgNode = outEdges.get(0).getDestination().getValue();
        if (nextCfgNode == fallThrough) {
          removeDeadExprStatementSafely(n);
          return fallThrough;
        }
      }
  }
  return n;
}

private Node computeFollowing(Node n) {
  Node next = ControlFlowAnalysis.computeFollowNode(n);
  return next;
}

static boolean evaluatesToLocalValue(Node value, Predicate<Node> locals) {
  switch (value.getType()) {
    case Token.ASSIGN:
      // A result that is aliased by a non-local name, is the effectively the
      // same as returning a non-local name, but this doesn't matter if the
      // value is immutable.
      return NodeUtil.isImmutableValue(value.getLastChild())
          || (locals.apply(value)
              && evaluatesToLocalValue(value.getLastChild(), locals));
    case Token.COMMA:
      return evaluatesToLocalValue(value.getLastChild(), locals);
    case Token.AND:
    case Token.OR:
      return evaluatesToLocalValue(value.getFirstChild(), locals)
         && evaluatesToLocalValue(value.getLastChild(), locals);
    case Token.HOOK:
      return evaluatesToLocalValue(value.getFirstChild().getNext(), locals)
         && evaluatesToLocalValue(value.getLastChild(), locals);
    case Token.INC:
    case Token.DEC:
      if (value.getBooleanProp(Node.INCRDECR_PROP)) {
        return evaluatesToLocalValue(value.getFirstChild(), locals);
      } else {
        return true;
      }
    case Token.THIS:
      return locals.apply(value);
    case Token.NAME:
      return isImmutableValue(value) || locals.apply(value);
    case Token.GETELEM:
    case Token.GETPROP:
      // There is no information about the locality of object properties.
      return locals.apply(value);
    case Token.CALL:
      return callHasLocalResult(value)
          || isToStringMethodCall(value)
          || locals.apply(value);
    case Token.NEW:
      // TODO(nicksantos): This needs to be changed so that it
      // returns true iff we're sure the value was never aliased from inside
      // the constructor (similar to callHasLocalResult)
      return true;
    case Token.FUNCTION:
    case Token.REGEXP:
    case Token.ARRAYLIT:
    case Token.OBJECTLIT:
      // Literals objects with non-literal children are allowed.
      return true;
    case Token.IN:
      // TODO(johnlenz): should IN operator be included in #isSimpleOperator?
      return true;
    default:
      // Other op force a local value:
      //  x = '' + g (x is now an local string)
      //  x -= g (x is now an local number)
      if (isAssignmentOp(value)
          || isSimpleOperator(value)
          || isImmutableValue(value)) {
        return true;
      }

      throw new IllegalStateException(
          "Unexpected expression node" + value +
          "\n parent:" + value.getParent());
  }
}

private boolean isFoldableExpressBlock(Node n) {
  if (n.getType() == Token.BLOCK) {
    if (n.hasOneChild()) {
      Node maybeExpr = n.getFirstChild();
        // IE has a bug where event handlers behave differently when
        // their return value is used vs. when their return value is in
        // an EXPR_RESULT. It's pretty freaking weird. See:
        // http://code.google.com/p/closure-compiler/issues/detail?id=291
        // We try to detect this case, and not fold EXPR_RESULTs
        // into other expressions.

          // We only have to worry about methods with an implicit 'this'
          // param, or this doesn't happen.

        return NodeUtil.isExpressionNode(maybeExpr) && !maybeExpr.isExprResult();
    }
  }

  return false;
}

private void tryRemoveAssignment(NodeTraversal t, Node n,
    FlowState<LiveVariableLattice> state) {
  tryRemoveAssignment(t, n, n, state);
}

private void tryRemoveAssignment(NodeTraversal t, Node n, Node exprRoot,
    FlowState<LiveVariableLattice> state) {
  Node parent = n.getParent();
  if (NodeUtil.isAssignmentOp(n) ||
      n.getType() == Token.INC || n.getType() == Token.DEC) {
    Node lhs = n.getFirstChild();
    Node rhs = lhs.getNext();
    if (rhs != null) {
      tryRemoveAssignment(t, rhs, exprRoot, state);
      rhs = lhs.getNext();
    }
    Scope scope = t.getScope();
    if (!NodeUtil.isName(lhs)) {
      return;
    }
    String name = lhs.getString();
    if (!scope.isDeclared(name, false)) {
      return;
    }
    Var var = scope.getVar(name);
    if (liveness.getEscapedLocals().contains(var)) {
      return;
    }
    if (rhs != null &&
        NodeUtil.isName(rhs) &&
        rhs.getString().equals(var.name) &&
        NodeUtil.isAssign(n)) {
      n.removeChild(rhs);
      n.getParent().replaceChild(n, rhs);
      compiler.reportCodeChange();
      return;
    }
    if (state.getOut().isLive(var)) {
      return;
    }
    if (state.getIn().isLive(var) &&
        isVariableStillLiveWithinExpression(n, exprRoot, var.name)) {
      return;
    }
    if (NodeUtil.isAssign(n)) {
      n.removeChild(rhs);
      n.getParent().replaceChild(n, rhs);
    } else if (NodeUtil.isAssignmentOp(n)) {
      n.removeChild(rhs);
      n.removeChild(lhs);
      Node op = new Node(NodeUtil.getOpFromAssignmentOp(n), lhs, rhs);
      parent.replaceChild(n, op);
    } else if (n.getType() == Token.INC || n.getType() == Token.DEC) {
      if (NodeUtil.isExpressionNode(parent)) {
        parent.replaceChild(n,
            new Node(Token.VOID, Node.newNumber(0).copyInformationFrom(n)));
      } else if(n.getType() == Token.COMMA && n != parent.getLastChild()) {
        parent.removeChild(n);
      } else if (parent.getType() == Token.FOR && !NodeUtil.isForIn(parent) &&
          NodeUtil.getConditionExpression(parent) != n) {
        parent.replaceChild(n, new Node(Token.EMPTY));
      } else {
        return;
      }
    } else {
      Preconditions.checkState(false, "Unknown statement");
    }
    compiler.reportCodeChange();
    return;
  } else {
    for (Node c = n.getFirstChild(); c != null;) {
      Node next = c.getNext();
      if (!ControlFlowGraph.isEnteringNewCfgNode(c)) {
        tryRemoveAssignment(t, c, exprRoot, state);
      }
      c = next;
    }
    return;
  }
}

private boolean isVariableStillLiveWithinExpression(
    Node n, Node exprRoot, String variable) {
  while (n != exprRoot) {
    for(Node sibling = n.getNext(); sibling != null;
        sibling = sibling.getNext()) {
      if (!ControlFlowGraph.isEnteringNewCfgNode(sibling)) {
        VariableLiveness state = isVariableReadBeforeKill(sibling, variable);
        if (state == VariableLiveness.READ) {
          return true;
        } else if (state == VariableLiveness.KILL) {
          return false;
        }
      }
    }
    n = n.getParent();
  }
  return false;
}

private enum VariableLiveness {
  MAYBE_LIVE,
  READ,
  KILL,
}

private VariableLiveness isVariableReadBeforeKill(
    Node n, String variable) {
  if (NodeUtil.isName(n) && variable.equals(n.getString())) {
    if (NodeUtil.isLhs(n, n.getParent())) {
      return VariableLiveness.KILL;
    } else {
      return VariableLiveness.READ;
    }
  }
  for (Node child = n.getFirstChild();
      child != null; child = child.getNext()) {
    if (!ControlFlowGraph.isEnteringNewCfgNode(child)) {
      VariableLiveness state = isVariableReadBeforeKill(child, variable);
      if (state != VariableLiveness.MAYBE_LIVE) {
        return state;
      }
    }
  }
  return VariableLiveness.MAYBE_LIVE;
}

private void updateSimpleDeclaration(String alias, Name refName, Ref ref) {
  Node rvalue = ref.node.getNext();
  Node parent = ref.node.getParent();
  Node gramps = parent.getParent();
  Node greatGramps = gramps.getParent();
  Node greatGreatGramps = greatGramps.getParent();

  // Create the new alias node.
  Node nameNode = NodeUtil.newName(
      compiler.getCodingConvention(), alias, gramps.getFirstChild(),
      refName.fullName());
  NodeUtil.copyNameAnnotations(ref.node.getLastChild(), nameNode);

  if (gramps.getType() == Token.EXPR_RESULT) {
    // BEFORE: a.b.c = ...;
    //   exprstmt
    //     assign
    //       getprop
    //         getprop
    //           name a
    //           string b
    //         string c
    //       NODE
    // AFTER: var a$b$c = ...;
    //   var
    //     name a$b$c
    //       NODE

    // Remove the rvalue (NODE).
    parent.removeChild(rvalue);
    nameNode.addChildToFront(rvalue);

    Node varNode = new Node(Token.VAR, nameNode);
    greatGramps.replaceChild(gramps, varNode);
  } else {
    // This must be a complex assignment.
    Preconditions.checkNotNull(ref.getTwin());

    // BEFORE:
    // ... (x.y = 3);
    //
    // AFTER:
    // var x$y;
    // ... (x$y = 3);

    Node current = gramps;
    Node currentParent = gramps.getParent();
    for (; currentParent.getType() != Token.SCRIPT &&
           currentParent.getType() != Token.BLOCK;
         current = currentParent,
         currentParent = currentParent.getParent()) {}

    // Create a stub variable declaration right
    // before the current statement.
    Node stubVar = new Node(Token.VAR, nameNode.cloneTree())
        .copyInformationFrom(nameNode);
    currentParent.addChildBefore(stubVar, current);

    parent.replaceChild(ref.node, nameNode);
  }

  compiler.reportCodeChange();
}

boolean canCollapseUnannotatedChildNames() {
  if (type == Type.OTHER || globalSets != 1 || localSets != 0) {
    return false;
  }

  // Don't try to collapse if the one global set is a twin reference.
  // We could theoretically handle this case in CollapseProperties, but
  // it's probably not worth the effort.
  Preconditions.checkNotNull(declaration);
  if (declaration.getTwin() != null) {
    return false;
  }

  if (isClassOrEnum) {
    return true;
  }

  // If this is a key of an aliased object literal, then it will be aliased
  // later. So we won't be able to collapse its properties.
  if (parent != null && parent.shouldKeepKeys()) {
    return false;
  }

  // If this is aliased, then its properties can't be collapsed either.
  if (type != Type.FUNCTION && aliasingGets > 0) {
    return false;
  }

  return (parent == null || parent.canCollapseUnannotatedChildNames());
}

public boolean apply(JSType type) {
  // TODO(user): Doing an instanceof check here is too
  // restrictive as (Date,Error) is, for instance, an object type
  // even though its implementation is a UnionType. Would need to
  // create interfaces JSType, ObjectType, FunctionType etc and have
  // separate implementation instead of the class hierarchy, so that
  // union types can also be object types, etc.
  if (!(type.isSubtype(
          typeRegistry.getNativeType(OBJECT_TYPE)) || type.isSubtype(
          typeRegistry.getNativeType(UNION_TYPE)))) {
    reportWarning(THIS_TYPE_NON_OBJECT, type.toString());
    return false;
  }
  return true;
}

JSType resolveInternal(ErrorReporter t, StaticScope<JSType> scope) {
  setResolvedTypeInternal(this);

  call = (ArrowType) safeResolve(call, t, scope);
  prototype = (FunctionPrototypeType) safeResolve(prototype, t, scope);

  // Warning about typeOfThis if it doesn't resolve to an ObjectType
  // is handled further upstream.
  //
  // TODO(nicksantos): Handle this correctly if we have a UnionType.
  //
  // TODO(nicksantos): In ES3, the runtime coerces "null" to the global
  // activation object. In ES5, it leaves it as null. Just punt on this
  // issue for now by coercing out null. This is complicated by the
  // fact that when most people write @this {Foo}, they really don't
  // mean "nullable Foo". For certain tags (like @extends) we de-nullify
  // the name for them.
  JSType maybeTypeOfThis = safeResolve(typeOfThis, t, scope);
  if (maybeTypeOfThis instanceof ObjectType) {
    typeOfThis = (ObjectType) maybeTypeOfThis;
  } else if (maybeTypeOfThis.isSubtype(
            typeRegistry.getNativeType(UNION_TYPE))) {
    typeOfThis = (UnionType) maybeTypeOfThis;
  }

  boolean changed = false;
  ImmutableList.Builder<ObjectType> resolvedInterfaces =
      ImmutableList.builder();
  for (ObjectType iface : implementedInterfaces) {
    ObjectType resolvedIface = (ObjectType) iface.resolve(t, scope);
    resolvedInterfaces.add(resolvedIface);
    changed |= (resolvedIface != iface);
  }
  if (changed) {
    implementedInterfaces = resolvedInterfaces.build();
  }

  if (subTypes != null) {
    for (int i = 0; i < subTypes.size(); i++) {
      subTypes.set(i, (FunctionType) subTypes.get(i).resolve(t, scope));
    }
  }

  return super.resolveInternal(t, scope);
}

public boolean shouldTraverse(NodeTraversal t, Node n, Node parent) {

  if (n.getType() == Token.FUNCTION) {
    // Don't traverse functions that are constructors or have the @this
    // or @override annotation.
    JSDocInfo jsDoc = getFunctionJsDocInfo(n);
    if (jsDoc != null &&
        (jsDoc.isConstructor() ||
         jsDoc.isInterface() ||
         jsDoc.hasThisType() ||
         jsDoc.isOverride())) {
      return false;
    }

    // Don't traverse functions unless they would normally
    // be able to have a @this annotation associated with them. e.g.,
    // var a = function() { }; // or
    // function a() {} // or
    // a.x = function() {}; // or
    // var a = {x: function() {}};
    int pType = parent.getType();
    if (!(pType == Token.BLOCK ||
          pType == Token.SCRIPT ||
          pType == Token.NAME ||
          pType == Token.ASSIGN ||

          // object literal keys
          pType == Token.STRING ||
          pType == Token.NUMBER)) {
      return false;
    }

    // Don't traverse functions that are getting lent to a prototype.
    if (NodeUtil.isGet(parent) && parent.getLastChild().getString().equals("prototype")) {
      return false;
    }
  }

  if (parent != null && parent.getType() == Token.ASSIGN) {
    Node lhs = parent.getFirstChild();
    Node rhs = lhs.getNext();

    if (n == lhs) {
      // Always traverse the left side of the assignment. To handle
      // nested assignments properly (e.g., (a = this).property = c;),
      // assignLhsChild should not be overridden.
      if (assignLhsChild == null) {
        assignLhsChild = lhs;
      }
    } else {
      // Only traverse the right side if it's not an assignment to a prototype
      // property or subproperty.
      if (NodeUtil.isGet(lhs)) {
        if (lhs.getType() == Token.GETPROP &&
            lhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
        Node llhs = lhs.getFirstChild();
        if (llhs.getType() == Token.GETPROP &&
            llhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
      }
    }
  }

  return true;
}

void replace() {
  if (firstNode == null) {
    // Don't touch the base case ('goog').
    replacementNode = candidateDefinition;
    return;
  }

  // Handle the case where there is a duplicate definition for an explicitly
  // provided symbol.
  if (candidateDefinition != null && explicitNode != null) {
    explicitNode.detachFromParent();
    compiler.reportCodeChange();

    // Does this need a VAR keyword?
    replacementNode = candidateDefinition;
    if (NodeUtil.isExpressionNode(candidateDefinition)) {
      candidateDefinition.putBooleanProp(Node.IS_NAMESPACE, true);
      Node assignNode = candidateDefinition.getFirstChild();
      Node nameNode = assignNode.getFirstChild();
      if (nameNode.getType() == Token.NAME) {
        // Need to convert this assign to a var declaration.
        Node valueNode = nameNode.getNext();
        assignNode.removeChild(nameNode);
        assignNode.removeChild(valueNode);
        nameNode.addChildToFront(valueNode);
        Node varNode = new Node(Token.VAR, nameNode);
        varNode.copyInformationFrom(candidateDefinition);
        candidateDefinition.getParent().replaceChild(
            candidateDefinition, varNode);
        nameNode.setJSDocInfo(assignNode.getJSDocInfo());
        compiler.reportCodeChange();
        replacementNode = varNode;
      }
    }
  } else {
    // Handle the case where there's not a duplicate definition.
    replacementNode = createDeclarationNode();
    if (firstModule == minimumModule) {
      firstNode.getParent().addChildBefore(replacementNode, firstNode);
    } else {
      // In this case, the name was implicitly provided by two independent
      // modules. We need to move this code up to a common module.
      int indexOfDot = namespace.indexOf('.');
      if (indexOfDot == -1) {
        // Any old place is fine.
        compiler.getNodeForCodeInsertion(minimumModule)
            .addChildToBack(replacementNode);
      } else {
        // Add it after the parent namespace.
        ProvidedName parentName =
            providedNames.get(namespace.substring(0, indexOfDot));
        Preconditions.checkNotNull(parentName);
        Preconditions.checkNotNull(parentName.replacementNode);
        parentName.replacementNode.getParent().addChildAfter(
            replacementNode, parentName.replacementNode);
      }
    }
    if (explicitNode != null) {
      explicitNode.detachFromParent();
    }
    compiler.reportCodeChange();
  }
}

static boolean isValidDefineValue(Node val, Set<String> defines) {
  switch (val.getType()) {
    case Token.STRING:
    case Token.NUMBER:
    case Token.TRUE:
    case Token.FALSE:
      return true;

    // Binary operators are only valid if both children are valid.
    case Token.BITAND:
    case Token.BITNOT:
    case Token.BITOR:
    case Token.BITXOR:
      return isValidDefineValue(val.getFirstChild(), defines) && isValidDefineValue(val.getSecondChild(), defines);

    // Uniary operators are valid if the child is valid.
    case Token.NOT:
    case Token.NEG:
      return isValidDefineValue(val.getFirstChild(), defines);

    // Names are valid if and only if they are defines themselves.
    case Token.NAME:
    case Token.GETPROP:
      if (val.isQualifiedName()) {
        return defines.contains(val.getQualifiedName());
      }
  }
  return false;
}

void defineSlot(Node n, Node parent, JSType type, boolean inferred) {
  Preconditions.checkArgument(inferred || type != null);

  // Only allow declarations of NAMEs and qualfied names.
  boolean shouldDeclareOnGlobalThis = false;
  if (n.getType() == Token.NAME) {
    Preconditions.checkArgument(
        parent.getType() == Token.FUNCTION ||
        parent.getType() == Token.VAR ||
        parent.getType() == Token.LP ||
        parent.getType() == Token.CATCH);
    shouldDeclareOnGlobalThis = scope.isGlobal() &&
        (parent.getType() == Token.VAR ||
         parent.getType() == Token.FUNCTION);
  } else {
    Preconditions.checkArgument(
        n.getType() == Token.GETPROP &&
        (parent.getType() == Token.ASSIGN ||
         parent.getType() == Token.EXPR_RESULT));
  }
  String variableName = n.getQualifiedName();
  Preconditions.checkArgument(!variableName.isEmpty());

  // If n is a property, then we should really declare it in the
  // scope where the root object appears. This helps out people
  // who declare "global" names in an anonymous namespace.
  Scope scopeToDeclareIn = scope;

    // don't try to declare in the global scope if there's
    // already a symbol there with this name.

  // declared in closest scope?
  if (scopeToDeclareIn.isDeclared(variableName, false)) {
    Var oldVar = scopeToDeclareIn.getVar(variableName);
    validator.expectUndeclaredVariable(
        sourceName, n, parent, oldVar, variableName, type);
  } else {
    if (!inferred) {
      setDeferredType(n, type);
    }
    CompilerInput input = compiler.getInput(sourceName);
    scopeToDeclareIn.declare(variableName, n, type, input, inferred);

    if (shouldDeclareOnGlobalThis) {
      ObjectType globalThis =
          typeRegistry.getNativeObjectType(JSTypeNative.GLOBAL_THIS);
      boolean isExtern = input.isExtern();
      if (inferred) {
        globalThis.defineInferredProperty(variableName,
            type == null ?
                getNativeType(JSTypeNative.NO_TYPE) :
                type,
            isExtern);
      } else {
        globalThis.defineDeclaredProperty(variableName, type, isExtern);
      }
    }

    // If we're in the global scope, also declare var.prototype
    // in the scope chain.
    if (scopeToDeclareIn.isGlobal() && type instanceof FunctionType) {
      FunctionType fnType = (FunctionType) type;
      if (fnType.isConstructor() || fnType.isInterface()) {
        FunctionType superClassCtor = fnType.getSuperClassConstructor();
        scopeToDeclareIn.declare(variableName + ".prototype", n,
            fnType.getPrototype(), compiler.getInput(sourceName),
            /* declared iff there's an explicit supertype */
            superClassCtor == null ||
            superClassCtor.getInstanceType().equals(
                getNativeType(OBJECT_TYPE)));
      }
    }
  }
}

private Node tryFoldShift(Node n, Node left, Node right) {
  if (left.getType() == Token.NUMBER &&
      right.getType() == Token.NUMBER) {

    double result;
    double lval = left.getDouble();
    double rval = right.getDouble();

    // check ranges.  We do not do anything that would clip the double to
    // a 32-bit range, since the user likely does not intend that.
    if (!(lval >= Integer.MIN_VALUE && lval <= Integer.MAX_VALUE)) {
      error(BITWISE_OPERAND_OUT_OF_RANGE, left);
      return n;
    }

    // only the lower 5 bits are used when shifting, so don't do anything
    // if the shift amount is outside [0,32)
    if (!(rval >= 0 && rval < 32)) {
      error(SHIFT_AMOUNT_OUT_OF_BOUNDS, right);
      return n;
    }

    // Convert the numbers to ints
    int lvalInt = (int) lval;
    if (lvalInt != lval) {
      error(FRACTIONAL_BITWISE_OPERAND, left);
      return n;
    }

    int rvalInt = (int) rval;
    if (rvalInt != rval) {
      error(FRACTIONAL_BITWISE_OPERAND, right);
      return n;
    }

    switch (n.getType()) {
      case Token.LSH:
        result = lvalInt << rvalInt;
        break;
      case Token.RSH:
        result = lvalInt >> rvalInt;
        break;
      case Token.URSH:
        // JavaScript handles zero shifts on signed numbers differently than
        // Java as an Java int can not represent the unsigned 32-bit number
        // where JavaScript can so use a long here.
        result = lvalInt >>> rvalInt;
        break;
      default:
        throw new AssertionError("Unknown shift operator: " +
            Node.tokenToName(n.getType()));
    }

    Node newNumber = Node.newNumber(result);
    n.getParent().replaceChild(n, newNumber);
    reportCodeChange();

    return newNumber;
  }

  return n;
}

boolean isAssignedOnceInLifetime() {
  Reference ref = getOneAndOnlyAssignment();
  if (ref == null) {
    return false;
