}

public Node getChildBefore(Node child) {
  if (child == first) {
    return null;
  }
  Node n = first;

  while (n.next != child) {
    n = n.next;
    if (n == null) {
      throw new RuntimeException("node is not a child");
    }
  }
  return n;
}

protected JSType caseTopType(JSType topType) {
  return topType;
}

private BooleanOutcomePair traverseAnd(Node n, FlowScope scope) {
  return traverseShortCircuitingBinOp(n, scope, true);
}

private BooleanOutcomePair traverseOr(Node n, FlowScope scope) {
  return traverseShortCircuitingBinOp(n, scope, false);
}

private BooleanOutcomePair traverseShortCircuitingBinOp(
    Node n, FlowScope scope, boolean condition) {
  Node left = n.getFirstChild();
  Node right = n.getLastChild();

  // type the left node
  BooleanOutcomePair leftLiterals =
      traverseWithinShortCircuitingBinOp(left,
          scope.createChildFlowScope());
  JSType leftType = left.getJSType();

  // reverse abstract interpret the left node to produce the correct
  // scope in which to verify the right node
  FlowScope rightScope = reverseInterpreter.
      getPreciserScopeKnowingConditionOutcome(
          left, leftLiterals.getOutcomeFlowScope(left.getType(), condition),
          condition);

  // type the right node
  BooleanOutcomePair rightLiterals =
      traverseWithinShortCircuitingBinOp(
          right, rightScope.createChildFlowScope());
  JSType rightType = right.getJSType();

  JSType type;
  BooleanOutcomePair literals;
  if (leftType != null && rightType != null) {
    leftType = leftType.getRestrictedTypeGivenToBooleanOutcome(!condition);
    if (leftLiterals.toBooleanOutcomes ==
        BooleanLiteralSet.get(!condition)) {
      // Use the restricted left type, since the right side never gets
      // evaluated.
      type = leftType;
      literals = leftLiterals;
    } else {
      // Use the join of the restricted left type knowing the outcome of the
      // ToBoolean predicate and of the right type.
      type = leftType.getLeastSupertype(rightType);
      literals =
          getBooleanOutcomePair(leftLiterals, rightLiterals, condition);
    }

    // Exclude the boolean type if the literal set is empty because a boolean
    // can never actually be returned.
    if (literals.booleanValues == BooleanLiteralSet.EMPTY &&
        getNativeType(BOOLEAN_TYPE).isSubtype(type)) {
      // Exclusion only make sense for a union type.
      if (type.isUnionType()) {
        type = type.toMaybeUnionType().getRestrictedUnion(
            getNativeType(BOOLEAN_TYPE));
      }
    }
  } else {
    type = null;
    literals = new BooleanOutcomePair(
        BooleanLiteralSet.BOTH, BooleanLiteralSet.BOTH,
        leftLiterals.getJoinedFlowScope(),
        rightLiterals.getJoinedFlowScope());
  }
  n.setJSType(type);

  return literals;
}

private BooleanOutcomePair traverseWithinShortCircuitingBinOp(Node n,
    FlowScope scope) {
  switch (n.getType()) {
    case Token.AND:
      return traverseAnd(n, scope);

    case Token.OR:
      return traverseOr(n, scope);

    default:
      scope = traverse(n, scope);
      return newBooleanOutcomePair(n.getJSType(), scope);
  }
}

/**
 * Infers the boolean outcome pair that can be taken by a
 * short-circuiting binary operation ({@code &&} or {@code ||}).
 * @see #getBooleanOutcomes(BooleanLiteralSet, BooleanLiteralSet, boolean)
 */
BooleanOutcomePair getBooleanOutcomePair(BooleanOutcomePair left,
    BooleanOutcomePair right, boolean condition) {
  return new BooleanOutcomePair(
      getBooleanOutcomes(left.toBooleanOutcomes, right.toBooleanOutcomes,
                         condition),
      getBooleanOutcomes(left.booleanValues, right.booleanValues, condition),
      left.getJoinedFlowScope(), right.getJoinedFlowScope());
}

/**
 * When traversing short-circuiting binary operations, we need to keep track
 * of two sets of boolean literals:
 * 1. {@code toBooleanOutcomes}: boolean literals as converted from any types,
 * 2. {@code booleanValues}: boolean literals from just boolean types.
 */
private final class BooleanOutcomePair {
  final BooleanLiteralSet toBooleanOutcomes;
  final BooleanLiteralSet booleanValues;

  // The scope if only half of the expression executed, when applicable.
  final FlowScope leftScope;

  // The scope when the whole expression executed.
  final FlowScope rightScope;

  // The scope when we don't know how much of the expression is executed.
  FlowScope joinedScope = null;

  BooleanOutcomePair(
      BooleanLiteralSet toBooleanOutcomes, BooleanLiteralSet booleanValues,
      FlowScope leftScope, FlowScope rightScope) {
    this.toBooleanOutcomes = toBooleanOutcomes;
    this.booleanValues = booleanValues;
    this.leftScope = leftScope;
    this.rightScope = rightScope;
  }

  /**
   * Gets the safe estimated scope without knowing if all of the
   * subexpressions will be evaluated.
   */
  FlowScope getJoinedFlowScope() {
    if (joinedScope == null) {
      if (leftScope == rightScope) {
        joinedScope = rightScope;
      } else {
        joinedScope = join(leftScope, rightScope);
      }
    }
    return joinedScope;
  }

  /**
   * Gets the outcome scope if we do know the outcome of the entire
   * expression.
   */
  FlowScope getOutcomeFlowScope(int nodeType, boolean outcome) {
    if (nodeType == Token.AND && outcome ||
        nodeType == Token.OR && !outcome) {
      // We know that the whole expression must have executed.
      return rightScope;
    } else {
      return getJoinedFlowScope();
    }
  }
}

private BooleanOutcomePair newBooleanOutcomePair(
    JSType jsType, FlowScope flowScope) {
  if (jsType == null) {
    return new BooleanOutcomePair(
        BooleanLiteralSet.BOTH, BooleanLiteralSet.BOTH, flowScope, flowScope);
  }
  return new BooleanOutcomePair(jsType.getPossibleToBooleanOutcomes(),
      registry.getNativeType(BOOLEAN_TYPE).isSubtype(jsType) ?
          BooleanLiteralSet.BOTH : BooleanLiteralSet.EMPTY,
      flowScope, flowScope);
}

private void redeclareSimpleVar(
    FlowScope scope, Node nameNode, JSType varType) {
  Preconditions.checkState(nameNode.isName());
  String varName = nameNode.getString();
  if (varType == null) {
    varType = getNativeType(JSTypeNative.UNKNOWN_TYPE);
  }
  if (isUnflowable(syntacticScope.getVar(varName))) {
    return;
  }
  scope.inferSlotType(varName, varType);
}

private boolean isUnflowable(Var v) {
  return v != null && v.isLocal() && v.isMarkedEscaped() &&
      // It's OK to flow a variable in the scope where it's escaped.
      v.getScope() == syntacticScope;
}

/**
 * This method gets the JSType from the Node argument and verifies that it is
 * present.
 */
private JSType getJSType(Node n) {
  JSType jsType = n.getJSType();
  if (jsType == null) {
    // TODO(nicksantos): This branch indicates a compiler bug, not worthy of
    // halting the compilation but we should log this and analyze to track
    // down why it happens. This is not critical and will be resolved over
    // time as the type checker is extended.
    return unknownType;
  } else {
    return jsType;
  }
}

private JSType getNativeType(JSTypeNative typeId) {
  return registry.getNativeType(typeId);
}

private void processRequireCall(NodeTraversal t, Node n, Node parent) {
  Node left = n.getFirstChild();
  Node arg = left.getNext();
  if (verifyLastArgumentIsString(t, left, arg)) {
    String ns = arg.getString();
    ProvidedName provided = providedNames.get(ns);
    if (provided == null || !provided.isExplicitlyProvided()) {
      unrecognizedRequires.add(
          new UnrecognizedRequire(n, ns, t.getSourceName()));
    } else {
      JSModule providedModule = provided.explicitModule;

      // This must be non-null, because there was an explicit provide.
      Preconditions.checkNotNull(providedModule);

      JSModule module = t.getModule();
      if (moduleGraph != null &&
          module != providedModule &&
          !moduleGraph.dependsOn(module, providedModule)) {
        compiler.report(
            t.makeError(n, XMODULE_REQUIRE_ERROR, ns,
                providedModule.getName(),
                module.getName()));
      }
    }

    maybeAddToSymbolTable(left);
    maybeAddStringNodeToSymbolTable(arg);

    // Requires should be removed before further processing.
    // Some clients run closure pass multiple times, first with
    // the checks for broken requires turned off. In these cases, we
    // allow broken requires to be preserved by the first run to
    // let them be caught in the subsequent run.
    if (provided != null) {
      parent.detachFromParent();
      compiler.reportCodeChange();
    }
  }
}

private void recordAssignment(NodeTraversal t, Node n, Node recordNode) {
  Node nameNode = n.getFirstChild();
  Node parent = n.getParent();
  NameInformation ns = createNameInformation(t, nameNode);
  if (ns != null) {
    if (parent.isFor() && !NodeUtil.isForIn(parent)) {
      // Patch for assignments that appear in the init,
      // condition or iteration part of a FOR loop.  Without
      // this change, all 3 of those parts try to claim the for
      // loop as their dependency scope.  The last assignment in
      // those three fields wins, which can result in incorrect
      // reference edges between referenced and assigned variables.
      //
      // TODO(user) revisit the dependency scope calculation
      // logic.
      if (parent.getFirstChild().getNext() != n) {
        recordDepScope(recordNode, ns);
      } else {
        recordDepScope(nameNode, ns);
      }
    } else {
      // The rhs of the assignment is the caller, so it's used by the
      // context. Don't associate it w/ the lhs.
      // FYI: this fixes only the specific case where the assignment is the
      // caller expression, but it could be nested deeper in the caller and
      // we would still get a bug.
      // See testAssignWithCall2 for an example of this.
      recordDepScope(recordNode, ns);
    }
  }
}

/**
 * Checks if the given function matches the criteria for an inlinable
 * function, and if so, adds it to our set of inlinable functions.
 */
boolean isDirectCallNodeReplacementPossible(Node fnNode) {
    // Only inline single-statement functions
    Node block = NodeUtil.getFunctionBody(fnNode);

    // Check if this function is suitable for direct replacement of a CALL node:
    // a function that consists of single return that returns an expression.
    if (!block.hasChildren()) {
        // special case empty functions.
        return true;
    } else if (block.hasOneChild()) {
        // Only inline functions that return something.
        if (block.getFirstChild().isReturn()
                && block.getFirstChild().getFirstChild() != null) {
            return true;
        }
    }

    return false;
}

/**
 * Determines whether a function can be inlined at a particular call site.
 * There are several criteria that the function and reference must hold in
 * order for the functions to be inlined:
 * - It must be a simple call, or assignment, or var initialization.
 * <pre>
 *    f();
 *    a = foo();
 *    var a = foo();
 * </pre>
 */
private CanInlineResult canInlineReferenceAsStatementBlock(
        NodeTraversal t, Node callNode, Node fnNode, Set<String> namesToAlias) {
    CallSiteType callSiteType = classifyCallSite(callNode);
    if (callSiteType == CallSiteType.UNSUPPORTED) {
        return CanInlineResult.NO;
    }

    if (!allowDecomposition
            && (callSiteType == CallSiteType.DECOMPOSABLE_EXPRESSION
                    || callSiteType == CallSiteType.EXPRESSION)) {
        return CanInlineResult.NO;
    }

    if (!callMeetsBlockInliningRequirements(
            t, callNode, fnNode, namesToAlias)) {
        return CanInlineResult.NO;
    }

    if (callSiteType == CallSiteType.DECOMPOSABLE_EXPRESSION
            || callSiteType == CallSiteType.EXPRESSION) {
        return CanInlineResult.AFTER_PREPARATION;
    } else {
        return CanInlineResult.YES;
    }
}

/**
 * Determines whether a function can be inlined at a particular call site.
 * - Don't inline if the calling function contains an inner function and
 * inlining would introduce new globals.
 */
private boolean callMeetsBlockInliningRequirements(
        NodeTraversal t, Node callNode, final Node fnNode,
        Set<String> namesToAlias) {
    final boolean assumeMinimumCapture = this.assumeMinimumCapture;

    // Note: functions that contain function definitions are filtered out
    // in isCandidateFunction.

    // TODO(johnlenz): Determining if the called function contains VARs
    // or if the caller contains inner functions accounts for 20% of the
    // run-time cost of this pass.

    // Don't inline functions with var declarations into a scope with inner
    // functions as the new vars would leak into the inner function and
    // cause memory leaks.
    boolean fnContainsVars = NodeUtil.has(
            NodeUtil.getFunctionBody(fnNode),
            new NodeUtil.MatchDeclaration(),
            new NodeUtil.MatchShallowStatement());
    boolean forbidTemps = false;
    if (!t.inGlobalScope()) {
        Node fnCaller = t.getScopeRoot();
        Node fnCallerBody = fnCaller.getLastChild();

        // Don't allow any new vars into a scope that contains eval or one
        // that contains functions (excluding the function being inlined).
        Predicate<Node> match = new Predicate<Node>() {
            @Override
            public boolean apply(Node n) {
                if (n.isName()) {
                    return n.getString().equals("eval");
                }
                if (!assumeMinimumCapture && n.isFunction()) {
                    return n != fnNode;
                }
                return false;
            }
        };
        forbidTemps = NodeUtil.has(fnCallerBody,
                match, NodeUtil.MATCH_NOT_FUNCTION);
    }

    if (fnContainsVars && forbidTemps) {
        return false;
    }

    // If the caller contains functions or evals, verify we aren't adding any
    // additional VAR declarations because aliasing is needed.
    if (forbidTemps) {
        Map<String, Node> args =
                FunctionArgumentInjector.getFunctionCallParameterMap(
                        fnNode, callNode, this.safeNameIdSupplier);
        boolean hasArgs = !args.isEmpty();
        if (hasArgs) {
            // Limit the inlining
            Set<String> allNamesToAlias = Sets.newHashSet(namesToAlias);
            FunctionArgumentInjector.maybeAddTempsForCallArguments(
                    fnNode, args, allNamesToAlias, compiler.getCodingConvention());
            if (!allNamesToAlias.isEmpty()) {
                return false;
            }
        }
    }

    return true;
}

/**
 * Determines whether a function can be inlined at a particular call site.
 * There are several criteria that the function and reference must hold in
 * order for the functions to be inlined:
 * 1) If a call's arguments have side effects,
 * the corresponding argument in the function must only be referenced once.
 * For instance, this will not be inlined:
 * <pre>
 *     function foo(a) { return a + a }
 *     x = foo(i++);
 * </pre>
 */
private CanInlineResult canInlineReferenceDirectly(
        Node callNode, Node fnNode) {
    if (!isDirectCallNodeReplacementPossible(fnNode)) {
        return CanInlineResult.NO;
    }

    Node block = fnNode.getLastChild();

    boolean hasSideEffects = false;
    if (block.hasChildren()) {
        Preconditions.checkState(block.hasOneChild());
        Node stmt = block.getFirstChild();
        if (stmt.isReturn()) {
            hasSideEffects = NodeUtil.mayHaveSideEffects(stmt.getFirstChild(), compiler);
        }
    }
    // CALL NODE: [ NAME, ARG1, ARG2, ... ]
    Node cArg = callNode.getFirstChild().getNext();

    // Functions called via 'call' and 'apply' have a this-object as
    // the first parameter, but this is not part of the called function's
    // parameter list.
    if (!callNode.getFirstChild().isName()) {
        if (NodeUtil.isFunctionObjectCall(callNode)) {
            // TODO(johnlenz): Support replace this with a value.
            if (cArg == null || !cArg.isThis()) {
                return CanInlineResult.NO;
            }
            cArg = cArg.getNext();
        } else {
            // ".apply" call should be filtered before this.
            Preconditions.checkState(!NodeUtil.isFunctionObjectApply(callNode));
        }
    }

    // FUNCTION NODE -> LP NODE: [ ARG1, ARG2, ... ]
    Node fnParam = NodeUtil.getFunctionParameters(fnNode).getFirstChild();
    while (cArg != null || fnParam != null) {
        // For each named parameter check if a mutable argument use more than one.
        if (fnParam != null) {
            if (cArg != null) {
                if (hasSideEffects && NodeUtil.canBeSideEffected(cArg)) {
                    return CanInlineResult.NO;
                }
                // Check for arguments that are evaluated more than once.
                // Note: Unlike block inlining, there it is not possible that a
                // parameter reference will be in a loop.
                if (NodeUtil.mayEffectMutableState(cArg, compiler)
                        && NodeUtil.getNameReferenceCount(
                                block, fnParam.getString()) > 1) {
                    return CanInlineResult.NO;
                }
            }

            // Move to the next name.
            fnParam = fnParam.getNext();
        }

        // For every call argument check for side-effects, even if there
        // isn't a named parameter to match.
        if (cArg != null) {
            if (NodeUtil.mayHaveSideEffects(cArg, compiler)) {
                return CanInlineResult.NO;
            }
            cArg = cArg.getNext();
        }
    }

    return CanInlineResult.YES;
}

private static final int NAME_COST_ESTIMATE =
    InlineCostEstimator.ESTIMATED_IDENTIFIER_COST;

/** The cost of a argument separator (a comma). */
private static final int COMMA_COST = 1;

/** The cost of the parentheses needed to make a call.*/
private static final int PAREN_COST = 2;

private static final int NAME_COST_ESTIMATE =
    InlineCostEstimator.ESTIMATED_IDENTIFIER_COST;

/** The cost of a argument separator (a comma). */
private static final int COMMA_COST = 1;

/** The cost of the parentheses needed to make a call.*/
private static final int PAREN_COST = 2;

String getReadableJSTypeName(Node n, boolean dereference) {

  // The best type name is the actual type name.

  // If we're analyzing a GETPROP, the property may be inherited by the
  // prototype chain. So climb the prototype chain and find out where
  // the property was originally defined.
  if (n.isGetProp()) {
    ObjectType objectType = getJSType(n.getFirstChild()).dereference();
    if (objectType != null) {
      String propName = n.getLastChild().getString();
      if (objectType.getConstructor() != null &&
          objectType.getConstructor().isInterface()) {
        objectType = FunctionType.getTopDefiningInterface(
            objectType, propName);
      } else {
        // classes
        while (objectType != null && !objectType.hasOwnProperty(propName)) {
          objectType = objectType.getImplicitPrototype();
        }
      }

      // Don't show complex function names or anonymous types.
      // Instead, try to get a human-readable type name.
      if (objectType != null &&
          (objectType.getConstructor() != null ||
           objectType.isFunctionPrototypeType())) {
        return objectType.toString() + "." + propName;
      }
    }
  }

  JSType type = getJSType(n);
  if (dereference) {
    ObjectType dereferenced = type.dereference();
    if (dereferenced != null) {
      type = dereferenced;
    }
  }
  if (type.isFunctionPrototypeType() ||
      (type.toObjectType() != null &&
       type.toObjectType().getConstructor() != null)) {
    return type.toString();
  }
  String qualifiedName = n.getQualifiedName();
  if (qualifiedName != null) {
    return qualifiedName;
  } else if (type.isFunctionType()) {
    // Don't show complex function names.
    return "function";
  } else {
    return type.toString();
  }
}

private void handleObjectLit(NodeTraversal t, Node n) {
  for (Node child = n.getFirstChild();
      child != null;
      child = child.getNext()) {
    // Maybe STRING, GET, SET

    // We should never see a mix of numbers and strings.
    String name = child.getString();
    if (name == null) {
        continue;
    }
    T type = typeSystem.getType(getScope(), n, name);

    Property prop = getProperty(name);
    if (!prop.scheduleRenaming(child,
                               processProperty(t, prop, type, null))) {
      // TODO(user): It doesn't look like the user can do much in this
      // case right now.
      if (propertiesToErrorFor.containsKey(name)) {
        compiler.report(JSError.make(
            t.getSourceName(), child, propertiesToErrorFor.get(name),
            Warnings.INVALIDATION, name,
            (type == null ? "null" : type.toString()), n.toString(), ""));
      }
    }
  }

public void collect(JSModule module, Scope scope, Node n) {
  Node parent = n.getParent();

  String name;
  boolean isSet = false;
  Name.Type type = Name.Type.OTHER;
  boolean isPropAssign = false;

  switch (n.getType()) {
    case Token.GETTER_DEF:
    case Token.SETTER_DEF:
    case Token.STRING_KEY:
      // This may be a key in an object literal declaration.
      name = null;
      if (parent != null && parent.isObjectLit()) {
        name = getNameForObjLitKey(n);
      }
      if (name == null) {
        return;
      }
      isSet = true;
      switch (n.getType()) {
        case Token.STRING_KEY:
          type = getValueType(n.getFirstChild());
          break;
        case Token.GETTER_DEF:
          type = Name.Type.GET;
          break;
        case Token.SETTER_DEF:
          type = Name.Type.SET;
          break;
        default:
          throw new IllegalStateException("unexpected:" + n);
      }
      break;
    case Token.NAME:
      // This may be a variable get or set.
      if (parent != null) {
        switch (parent.getType()) {
          case Token.VAR:
            isSet = true;
            Node rvalue = n.getFirstChild();
            type = rvalue == null ? Name.Type.OTHER : getValueType(rvalue);
            break;
          case Token.ASSIGN:
            if (parent.getFirstChild() == n) {
              isSet = true;
              type = getValueType(n.getNext());
            }
            break;
          case Token.GETPROP:
            return;
          case Token.FUNCTION:
            Node gramps = parent.getParent();
            if (gramps == null || NodeUtil.isFunctionExpression(parent)) {
              return;
            }
            isSet = true;
            type = Name.Type.FUNCTION;
            break;
          case Token.INC:
          case Token.DEC:
            isSet = true;
            type = Name.Type.OTHER;
            break;
          default:
            if (NodeUtil.isAssignmentOp(parent) &&
                parent.getFirstChild() == n) {
              isSet = true;
              type = Name.Type.OTHER;
            }
        }
      }
      name = n.getString();
      break;
    case Token.GETPROP:
      // This may be a namespaced name get or set.
      if (parent != null) {
        switch (parent.getType()) {
          case Token.ASSIGN:
            if (parent.getFirstChild() == n) {
              isSet = true;
              type = getValueType(n.getNext());
              isPropAssign = true;
            }
            break;
          case Token.INC:
          case Token.DEC:
            isSet = true;
            type = Name.Type.OTHER;
            break;
          case Token.GETPROP:
            return;
          default:
            if (NodeUtil.isAssignmentOp(parent) &&
                parent.getFirstChild() == n) {
              isSet = true;
              type = Name.Type.OTHER;
            }
        }
      }
      name = n.getQualifiedName();
      if (name == null) {
        return;
      }
      break;
    default:
      return;
  }

  // We are only interested in global names.
  if (!isGlobalNameReference(name, scope)) {
    return;
  }

  if (isSet) {
    if (isGlobalScope(scope)) {
      handleSetFromGlobal(module, scope, n, parent, name, isPropAssign, type);
    } else {
      handleSetFromLocal(module, scope, n, parent, name);
    }
  } else {
    handleGet(module, scope, n, parent, name);
  }
}

boolean isAssignedOnceInLifetime() {
  Reference ref = getOneAndOnlyAssignment();
  if (ref == null) {
    return false;
  }

  // Make sure this assignment is not in a loop.
  for (BasicBlock block = ref.getBasicBlock();
       block != null; block = block.getParent()) {
    if (block.isFunction) {
      break;
    } else if (block.isLoop) {
      return false;
    }
  }

  return true;
}

private boolean isStringWorthInlining(Var var, List<Reference> refs) {
  if (!inlineAllStrings && !var.isDefine()) {
    int len = var.getInitialValue().getString().length() + "''".length();

    // if not inlined: var xx="value"; .. xx .. xx ..
    // The 4 bytes per reference is just a heuristic:
    // 2 bytes per var name plus maybe 2 bytes if we don't inline, e.g.
    // in the case of "foo " + CONST + " bar"
    int noInlineBytes = "var xx=;".length() + len +
                        4 * (refs.size() - 1);

    // if inlined:
    // I'm going to assume that half of the quotes will be eliminated
    // thanks to constant folding, therefore I subtract 1 (2/2=1) from
    // the string length.
    int inlineBytes = (len - 1) * (refs.size() - 1);

    // Not inlining if doing so uses more bytes, or this constant is being
    // defined.
    return noInlineBytes >= inlineBytes;
  }

  return true;
}

private boolean isStringWorthInlining(Var var, List<Reference> refs) {
  if (!inlineAllStrings && !var.isDefine()) {
    int len = var.getInitialValue().getString().length() + "''".length();

    // if not inlined: var xx="value"; .. xx .. xx ..
    // The 4 bytes per reference is just a heuristic:
    // 2 bytes per var name plus maybe 2 bytes if we don't inline, e.g.
    // in the case of "foo " + CONST + " bar"
    int noInlineBytes = "var xx=;".length() + len +
                        4 * (refs.size() - 1);

    // if inlined:
    // I'm going to assume that half of the quotes will be eliminated
    // thanks to constant folding, therefore I subtract 1 (2/2=1) from
    // the string length.
    int inlineBytes = (len - 1) * (refs.size() - 1);

    // Not inlining if doing so uses more bytes, or this constant is being
    // defined.
    return noInlineBytes >= inlineBytes;
