public void visit(NodeTraversal t, Node n, Node parent) {
  switch (n.getType()) {
    case Token.WHILE:
      if (CONVERT_WHILE_TO_FOR) {
        Node expr = n.getFirstChild();
        Node init = new Node(Token.EMPTY);
        Node test = expr;
        Node update = new Node(Token.EMPTY);
        n.setType(Token.FOR);
        n.addChildToFront(init);
        n.addChildToFront(test);
        n.addChildToFront(update);
        reportCodeChange("WHILE node");
      }
      break;

  }
