FunctionType buildAndRegister() {
  if (returnType == null) {
    returnType = typeRegistry.getNativeType(UNKNOWN_TYPE);
  }

  if (parametersNode == null) {
    throw new IllegalStateException(
        "All Function types must have params and a return type");
  }

  FunctionType fnType;
  if (isConstructor) {
    fnType = getOrCreateConstructor();
  } else if (isInterface) {
    fnType = typeRegistry.createInterfaceType(fnName, sourceNode);
    if (scope.isGlobal() && !fnName.isEmpty()) {
      typeRegistry.declareType(fnName, fnType.getInstanceType());
    }
    maybeSetBaseType(fnType);
  } else {
    fnType = new FunctionBuilder(typeRegistry)
        .withName(fnName)
        .withSourceNode(sourceNode)
        .withParamsNode(parametersNode)
        .withReturnType(returnType)
        .withTypeOfThis(thisType)
        .withTemplateName(templateTypeName)
        .build();
    maybeSetBaseType(fnType);
  }

  if (implementedInterfaces != null) {
    fnType.setImplementedInterfaces(implementedInterfaces);
  }

  typeRegistry.clearTemplateTypeName();

  return fnType;
}

private boolean isOneExactlyFunctionOrDo(Node n) {
      // For labels with block children, we need to ensure that a
      // labeled FUNCTION or DO isn't generated when extraneous BLOCKs 
      // are skipped. 
      // Either a empty statement or an block with more than one child,
      // way it isn't a FUNCTION or DO.
      return (n.getType() == Token.FUNCTION || n.getType() == Token.DO) && n.getChildCount() == 1;
}

public TypePair getTypesUnderInequality(JSType that) {
  // unions types
  if (that instanceof UnionType) {
    TypePair p = that.getTypesUnderInequality(this);
    return new TypePair(p.typeB, p.typeA);
  }

  // other types
  switch (this.testForEquality(that)) {
    case TRUE:
      return new TypePair(null, null);

    case FALSE:
    case UNKNOWN:
      return new TypePair(this, that);
  }

  // switch case is exhaustive
  throw new IllegalStateException();
}

public boolean shouldTraverse(NodeTraversal t, Node n, Node parent) {

  if (n.getType() == Token.FUNCTION) {
    // Don't traverse functions that are constructors or have the @this
    // or @override annotation.
    JSDocInfo jsDoc = getFunctionJsDocInfo(n);
    if (jsDoc != null &&
        (jsDoc.isConstructor() ||
         jsDoc.isInterface() ||
         jsDoc.hasThisType() ||
         jsDoc.isOverride())) {
      return false;
    }

    // Don't traverse functions unless they would normally
    // be able to have a @this annotation associated with them. e.g.,
    // var a = function() { }; // or
    // function a() {} // or
    // a.x = function() {}; // or
    // var a = {x: function() {}};
    int pType = parent.getType();
    if (!(pType == Token.BLOCK ||
          pType == Token.SCRIPT ||
          pType == Token.NAME ||
          pType == Token.ASSIGN)) {
      return false;
    }
  }

  if (parent != null && parent.getType() == Token.ASSIGN) {
    Node lhs = parent.getFirstChild();
    Node rhs = lhs.getNext();

    if (n == lhs) {
      // Always traverse the left side of the assignment. To handle
      // nested assignments properly (e.g., (a = this).property = c;),
      // assignLhsChild should not be overridden.
      if (assignLhsChild == null) {
        assignLhsChild = lhs;
      }
    } else {
      // Only traverse the right side if it's not an assignment to a prototype
      // property or subproperty.
      if (NodeUtil.isGet(lhs)) {
        if (lhs.getType() == Token.GETPROP &&
            lhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
        Node llhs = lhs.getFirstChild();
        if (llhs.getType() == Token.GETPROP &&
            llhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
      }
    }
  }

  return true;
}

private void visitFunction(NodeTraversal t, Node n) {
  FunctionType funType = (FunctionType) n.getJSType();
  Node block = n.getLastChild();
  Node paramName = NodeUtil.getFnParameters(n).getFirstChild();
  Node insertionPoint = null;

  // To satisfy normalization constraints, the type checking must be
  // added after any inner function declarations.

  for (Node paramType : funType.getParameters()) {
    // Can this ever happen?
    if (paramName == null) {
      return;
    }

    Node checkNode = createCheckTypeCallNode(
        paramType.getJSType(), paramName.cloneTree());

    if (checkNode == null) {
      // We don't know how to check this parameter type.
      paramName = paramName.getNext();
      continue;
    }

    checkNode = new Node(Token.EXPR_RESULT, checkNode);
    if (insertionPoint == null) {
      block.addChildToFront(checkNode);
    } else {
      block.addChildAfter(checkNode, insertionPoint);
    }

    compiler.reportCodeChange();
    paramName = paramName.getNext();
    insertionPoint = checkNode;
  }
}

private Node tryFoldTypeof(Node originalTypeofNode) {
  Preconditions.checkArgument(originalTypeofNode.getType() == Token.TYPEOF);

  Node argumentNode = originalTypeofNode.getFirstChild();
  if (argumentNode == null || !NodeUtil.isLiteralValue(argumentNode)) {
    return originalTypeofNode;
  }

  String typeNameString = null;

  switch (argumentNode.getType()) {
    case Token.STRING:
      typeNameString = "string";
      break;
    case Token.NUMBER:
      typeNameString = "number";
      break;
    case Token.TRUE:
    case Token.FALSE:
      typeNameString = "boolean";
      break;
    case Token.NULL:
    case Token.OBJECTLIT:
    case Token.ARRAYLIT:
      typeNameString = "object";
      break;
    case Token.NAME:
      // We assume here that programs don't change the value of the
      // keyword undefined to something other than the value undefined.
      if ("undefined".equals(argumentNode.getString())) {
        typeNameString = "undefined";
      }
      break;
  }

  if (typeNameString != null) {
    Node newNode = Node.newString(typeNameString);
    originalTypeofNode.getParent().replaceChild(originalTypeofNode, newNode);
    reportCodeChange();

    return newNode;
  }

  return originalTypeofNode;
}

public class SourceMap {


  /**
   * A mapping from a given position in an input source file to a given position
   * in the generated code.
   */
  static class Mapping {
    /**
     * A unique ID for this mapping for record keeping purposes.
     */
    int id;

    /**
     * The input source file.
     */
    String sourceFile;

    /**
     * The position of the code in the input source file. Both
     * the line number and the character index are indexed by
     * 1 for legacy reasons via the Rhino Node class.
     */
    Position originalPosition;

    /**
     * The starting position of the code in the generated source
     * file which this mapping represents. Indexed by 0.
     */
    Position startPosition;

    /**
     * The ending position of the code in the generated source
     * file which this mapping represents. Indexed by 0.
     */
    Position endPosition;

    /**
     * The original name of the token found at the position
     * represented by this mapping (if any).
     */
    String originalName;

    /**
     * Whether the mapping is actually used by the source map.
     */

    /**
     * Cache of escaped source file name.
     */

    /**
     * Appends the mapping to the given buffer.
     */
    void appendTo(Appendable out) throws IOException {
      out.append("[");

      out.append(sourceFile);
      // The source file rarely changes, so cache the escaped string.

      out.append(",");


      out.append(String.valueOf(originalPosition.getLineNumber()));

      out.append(",");
      out.append(String.valueOf(originalPosition.getCharacterIndex()));

      if (originalName != null) {
        out.append(",");
        out.append(originalName);
      }

      out.append("]");
    }
    /**
     * Add used mappings to the supplied Appendable.
     */
  }

  /**
   * A pre-order traversal ordered list of mappings stored in this map.
   */
  private List<Mapping> mappings = Lists.newArrayList();

  /**
   * The position that the current source map is offset in the
   * buffer being used to generated the compiled source file.
   */
  private Position offsetPosition = new Position(0, 0);

  /**
   * The position that the current source map is offset in the
   * generated the compiled source file by the addition of a
   * an output wrapper prefix.
   */
  private Position prefixPosition = new Position(0, 0);

  /**
   * Escapes the given string for JSON.
   */
  private static String escapeString(String value) {
    return CodeGenerator.escapeToDoubleQuotedJsString(value);
  }

void addMapping(Node node, Position startPosition, Position endPosition) {
  String sourceFile = (String)node.getProp(Node.SOURCEFILE_PROP);

  // If the node does not have an associated source file or
  // its line number is -1, then the node does not have sufficient
  // information for a mapping to be useful.
  if (sourceFile == null || node.getLineno() < 0) {
    return;
  }

  String escapedSourceFile;
  if (lastSourceFile != sourceFile) {  // yes, "s1 != s2" not "!s1.equals(s2)"
    lastSourceFile = sourceFile;
    lastSourceFileEscaped = escapeString(sourceFile);
  }
  escapedSourceFile = lastSourceFileEscaped;
  // Create the new mapping.
  Mapping mapping = new Mapping();
  mapping.id = mappings.size();
  mapping.sourceFile = escapedSourceFile;
  mapping.originalPosition = new Position(node.getLineno(), node.getCharno());

  String originalName = (String)node.getProp(Node.ORIGINALNAME_PROP);
  if (originalName != null) {
    mapping.originalName = escapeString(originalName);
  }

    // If the mapping is found on the first line, we need to offset
    // its character position by the number of characters found on
    // the *last* line of the source file to which the code is
    // being generated.
    int offsetLine = offsetPosition.getLineNumber();
    int startOffsetPosition = offsetPosition.getCharacterIndex();
    int endOffsetPosition = offsetPosition.getCharacterIndex();

    if (startPosition.getLineNumber() > 0) {
      startOffsetPosition = 0;
    }

    if (endPosition.getLineNumber() > 0) {
      endOffsetPosition = 0;
    }

    mapping.startPosition =
        new Position(startPosition.getLineNumber() + offsetLine,
                     startPosition.getCharacterIndex() + startOffsetPosition);

    mapping.endPosition =
        new Position(endPosition.getLineNumber() + offsetLine,
                     endPosition.getCharacterIndex() + endOffsetPosition);

  mappings.add(mapping);
}

private int findLastLine() {
  int maxLine = 0;
  for (Mapping mapping : mappings) {
    int endPositionLine = mapping.endPosition.getLineNumber();
    maxLine = Math.max(maxLine, endPositionLine);
  }
  return maxLine + prefixPosition.getLineNumber();
}

private class LineMapper {
  // The destination.
  private final Appendable out;
  private int line;
  private int col;
  // Whether the current line has had a value written yet.
  private boolean firstChar = true;

  private final static String UNMAPPED_STRING = "-1";

  private final static int UNMAPPED = -1;

  LineMapper(Appendable out) {
    this.out = out;
  }

protected B createOptions() {
  B options = createOptions();
  CompilerFlagTranslator.setOptionsFromFlags(options);
  addMyCrazyCompilerPassThatOutputsAnExtraFile(options);
  return options;
}

protected B createOptions() {
  B options = new CompilerOptions();
  options.setCodingConvention(new ClosureCodingConvention());
  CompilationLevel level = flags.compilation_level;
  level.setOptionsForCompilationLevel(options);
  if (flags.debug) {
    level.setDebugOptionsForCompilationLevel(options);
  }

  WarningLevel wLevel = flags.warning_level;
  wLevel.setOptionsForWarningLevel(options);
  for (FormattingOption formattingOption : flags.formatting) {
    formattingOption.applyToOptions(options);
  }

  options.closurePass = flags.process_closure_primitives;
  initOptionsFromFlags(options);
  return options;
}

private String toSource(Node n, SourceMap sourceMap) {
  CodePrinter.Builder builder = new CodePrinter.Builder(n);
  builder.setPrettyPrint(options.prettyPrint);
  builder.setLineBreak(options.lineBreak);
  builder.setSourceMap(sourceMap);
  builder.setSourceMapDetailLevel(options.sourceMapDetailLevel);

  Charset charset = options.outputCharset;
  builder.setOutputCharset(charset);

  return builder.build();
}

private FunctionType getFunctionType(String name,
    Node rValue, JSDocInfo info, @Nullable Node lvalueNode) {
  FunctionType functionType = null;

  // Global function aliases should be registered with the type registry.
  if (rValue != null && rValue.isQualifiedName() && scope.isGlobal()) {
    Var var = scope.getVar(rValue.getQualifiedName());
    if (var != null && var.getType() instanceof FunctionType) {
      functionType = (FunctionType) var.getType();
      if (functionType != null && functionType.isConstructor()) {
        typeRegistry.declareType(name, functionType.getInstanceType());
      }
    }
    return functionType;
  }

  Node owner = null;
  if (lvalueNode != null) {
    owner = getPrototypePropertyOwner(lvalueNode);
  }

  Node errorRoot = rValue == null ? lvalueNode : rValue;
  boolean isFnLiteral =
      rValue != null && rValue.getType() == Token.FUNCTION;
  Node fnRoot = isFnLiteral ? rValue : null;
  Node parametersNode = isFnLiteral ?
      rValue.getFirstChild().getNext() : null;
  Node fnBlock = isFnLiteral ? parametersNode.getNext() : null;

  if (functionType == null && info != null && info.hasType()) {
    JSType type = info.getType().evaluate(scope, typeRegistry);

    // Known to be not null since we have the FUNCTION token there.
    type = type.restrictByNotNullOrUndefined();
    if (type.isFunctionType()) {
      functionType = (FunctionType) type;
      functionType.setJSDocInfo(info);
    }
  }

  if (functionType == null) {
    // Find the type of any overridden function.
    FunctionType overriddenPropType = null;
    if (lvalueNode != null && lvalueNode.getType() == Token.GETPROP &&
        lvalueNode.isQualifiedName()) {
      Var var = scope.getVar(
          lvalueNode.getFirstChild().getQualifiedName());
      if (var != null) {
        ObjectType ownerType = ObjectType.cast(var.getType());
        if (ownerType != null) {
          String propName = lvalueNode.getLastChild().getString();
          overriddenPropType = findOverriddenFunction(ownerType, propName);
        }
      }
    }

    functionType =
        new FunctionTypeBuilder(name, compiler, errorRoot, sourceName,
            scope)
        .setSourceNode(fnRoot)
        .inferFromOverriddenFunction(overriddenPropType, parametersNode)
        .inferTemplateTypeName(info)
        .inferReturnType(info)
        .inferInheritance(info)
        .inferThisType(info, owner)
        .inferParameterTypes(parametersNode, info)
        .inferReturnStatementsAsLastResort(fnBlock)
        .buildAndRegister();
  }

  // assigning the function type to the function node
  if (rValue != null) {
    setDeferredType(rValue, functionType);
  }

  // all done
  return functionType;
}

private FunctionType getEnumType(String name, Node parent,
    Node value, JSType elementsType) {
  EnumType enumType = null;

  // no value with @enum
  if (value != null) {
    if (value.getType() == Token.OBJECTLIT) {
      // collect enum elements
      enumType = typeRegistry.createEnumType(name, elementsType);

      // populate the enum type.
      Node key = value.getFirstChild();
      while (key != null) {
        String keyName = NodeUtil.getStringValue(key);

        if (enumType.hasOwnProperty(keyName)) {
          compiler.report(JSError.make(sourceName, key, ENUM_DUP, keyName));
        } else if (!codingConvention.isValidEnumKey(keyName)) {
          compiler.report(
              JSError.make(sourceName, key, ENUM_NOT_CONSTANT, keyName));
        } else {
          enumType.defineElement(keyName);
        }
        key = key.getNext();
        key = (key == null) ? null : key.getNext();
      }
    } else if (value.isQualifiedName()) {
      Var var = scope.getVar(value.getQualifiedName());
      if (var != null && var.getType() instanceof EnumType) {
        enumType = (EnumType) var.getType();
      }
    }
  }

  if (enumType == null) {
    compiler.report(JSError.make(sourceName, parent, ENUM_INITIALIZER));
  } else if (scope.isGlobal()) {
    if (name != null && !name.isEmpty()) {
      typeRegistry.declareType(name, enumType.getElementsType());
    }
  }

  return enumType;
}

JSType resolveInternal(ErrorReporter t, StaticScope<JSType> scope) {
  setResolvedTypeInternal(this);

  call = (ArrowType) safeResolve(call, t, scope);
  prototype = (FunctionPrototypeType) safeResolve(prototype, t, scope);

  // Warning about typeOfThis if it doesn't resolve to an ObjectType
  // is handled further upstream.
  // TODO(nicksantos): Handle this correctly if we have a UnionType.
  typeOfThis = (ObjectType) safeResolve(typeOfThis, t, scope);

  boolean changed = false;
  ImmutableList.Builder<ObjectType> resolvedInterfaces =
      ImmutableList.builder();
  for (ObjectType iface : implementedInterfaces) {
    ObjectType resolvedIface = (ObjectType) iface.resolve(t, scope);
    resolvedInterfaces.add(resolvedIface);
    changed |= (resolvedIface != iface);
  }
  if (changed) {
    implementedInterfaces = resolvedInterfaces.build();
  }

  if (subTypes != null) {
    for (int i = 0; i < subTypes.size(); i++) {
      subTypes.set(i, (FunctionType) subTypes.get(i).resolve(t, scope));
    }
  }

  return super.resolveInternal(t, scope);
}

private void scanRoot(Node n, Scope parent) {
  if (n.getType() == Token.FUNCTION) {
    sourceName = (String) n.getProp(Node.SOURCENAME_PROP);

    final Node fnNameNode = n.getFirstChild();
    final Node args = fnNameNode.getNext();
    final Node body = args.getNext();

    // Bleed the function name into the scope, if it hasn't
    // been declared in the outer scope.
    String fnName = fnNameNode.getString();
    if (!fnName.isEmpty() && NodeUtil.isFunctionExpression(n)) {
      declareVar(fnName, fnNameNode, n, null, null, n);
    }

    // Args: Declare function variables
    Preconditions.checkState(args.getType() == Token.LP);
    for (Node a = args.getFirstChild(); a != null;
         a = a.getNext()) {
      Preconditions.checkState(a.getType() == Token.NAME);
      declareVar(a.getString(), a, args, n, null, n);
    }

    // Body
    scanVars(body, n);
  } else {
    // It's the global block
    Preconditions.checkState(scope.getParent() == null);
    scanVars(n, null);
  }
}

private void scanVars(Node n, Node parent) {
  switch (n.getType()) {
    case Token.VAR:
      // Declare all variables. e.g. var x = 1, y, z;
      for (Node child = n.getFirstChild();
           child != null;) {
        Node next = child.getNext();
        Preconditions.checkState(child.getType() == Token.NAME);
        String name = child.getString();
        declareVar(name, child, n, parent, null, n);
        child = next;
      }
      return;

    case Token.FUNCTION:
      if (NodeUtil.isFunctionExpression(n)) {
        return;
      }

      String fnName = n.getFirstChild().getString();
      if (fnName.isEmpty()) {
        // This is invalid, but allow it so the checks can catch it.
        return;
      }
      declareVar(fnName, n.getFirstChild(), n, parent, null, n);
      return;   // should not examine function's children

    case Token.CATCH:
      Preconditions.checkState(n.getChildCount() == 2);
      Preconditions.checkState(n.getFirstChild().getType() == Token.NAME);
      // the first child is the catch var and the third child
      // is the code block

      final Node var = n.getFirstChild();
      final Node block = var.getNext();

      declareVar(var.getString(), var, n, parent, null, n);
      scanVars(block, n);
      return;  // only one child to scan

    case Token.SCRIPT:
      sourceName = (String) n.getProp(Node.SOURCENAME_PROP);
      break;
  }

  // Variables can only occur in statement-level nodes, so
  // we only need to traverse children in a couple special cases.
  if (NodeUtil.isControlStructure(n) || NodeUtil.isStatementBlock(n)) {
    for (Node child = n.getFirstChild();
         child != null;) {
      Node next = child.getNext();
      scanVars(child, n);
      child = next;
    }
  }
}

private class DefaultRedeclarationHandler implements RedeclarationHandler {
  public void onRedeclaration(
      Scope s, String name,
      Node n, Node parent, Node gramps, Node nodeWithLineNumber) {

    // Don't allow multiple variables to be declared at the top level scope
    if (scope.isGlobal()) {
      Scope.Var origVar = scope.getVar(name);
      Node origParent = origVar.getParentNode();
      if (origParent.getType() == Token.CATCH &&
          parent.getType() == Token.CATCH) {
        // Okay, both are 'catch(x)' variables.
        return;
      }

      boolean allowDupe = false;
      JSDocInfo info = n.getJSDocInfo();
      if (info == null) {
        info = parent.getJSDocInfo();
      }
      allowDupe =
          info != null && info.getSuppressions().contains("duplicate");

      if (!allowDupe) {
        compiler.report(
            JSError.make(sourceName, n,
                         VAR_MULTIPLY_DECLARED_ERROR,
                         name,
                         (origVar.input != null
                          ? origVar.input.getName()
                          : "??")));
      }
    } else if (name.equals(ARGUMENTS) && !NodeUtil.isVarDeclaration(n)) {
      // Disallow shadowing "arguments" as we can't handle with our current
      // scope modeling.
      compiler.report(
          JSError.make(sourceName, n,
              VAR_ARGUMENTS_SHADOWED_ERROR));
    }
  }
}

private class InliningBehavior implements Behavior {

  /**
   * A list of variables that should not be inlined, because their
   * reference information is out of sync with the state of the AST.
   */
  private final Set<Var> staleVars = Sets.newHashSet();

  /**
   * Stored possible aliases of variables that never change, with
   * all the reference info about those variables. Hashed by the NAME
   * node of the variable being aliased.
   */
  final Map<Node, AliasCandidate> aliasCandidates = Maps.newHashMap();

  @Override
  public void afterExitScope(NodeTraversal t,
      Map<Var, ReferenceCollection> referenceMap) {
    collectAliasCandidates(t, referenceMap);
    doInlinesForScope(t, referenceMap);
  }

  /**
   * If any of the variables are well-defined and alias other variables,
   * mark them as aliasing candidates.
   */
  private void collectAliasCandidates(NodeTraversal t,
      Map<Var, ReferenceCollection> referenceMap) {
    if (mode != Mode.CONSTANTS_ONLY) {
      for (Iterator<Var> it = t.getScope().getVars(); it.hasNext();) {
        Var v = it.next();
        ReferenceCollection referenceInfo = referenceMap.get(v);

        // NOTE(nicksantos): Don't handle variables that are never used.
        // The tests are much easier to write if you don't, and there's
        // another pass that handles unused variables much more elegantly.
        if (referenceInfo != null && referenceInfo.references.size() >= 2 &&
            referenceInfo.isWellDefined() &&
            referenceInfo.isAssignedOnceInLifetime()) {
          Reference init = referenceInfo.getInitializingReference();
          Node value = init.getAssignedValue();
          if (value != null && value.getType() == Token.NAME) {
            aliasCandidates.put(value, new AliasCandidate(v, referenceInfo));
          }
        }
      }
    }
  }

  /**
   * For all variables in this scope, see if they are only used once.
   * If it looks safe to do so, inline them.
   */
  private void doInlinesForScope(NodeTraversal t,
      Map<Var, ReferenceCollection> referenceMap) {

    for (Iterator<Var> it = t.getScope().getVars(); it.hasNext();) {
      Var v = it.next();

      ReferenceCollection referenceInfo = referenceMap.get(v);

      // referenceInfo will be null if we're in constants-only mode
      // and the variable is not a constant.
      if (referenceInfo == null || isVarInlineForbidden(v)) {
        // Never try to inline exported variables or variables that
        // were not collected or variables that have already been inlined.
        continue;
      } else if (isInlineableDeclaredConstant(v, referenceInfo)) {
        Reference init = referenceInfo.getInitializingReferenceForConstants();
        Node value = init.getAssignedValue();
        inlineDeclaredConstant(v, value, referenceInfo.references);
        staleVars.add(v);
      } else if (mode == Mode.CONSTANTS_ONLY) {
        // If we're in constants-only mode, don't run more aggressive
        // inlining heuristics. See InlineConstantsTest.
        continue;
      } else {
        inlineNonConstants(v, referenceInfo);
      }
    }
  }

          // Any reference that is not a read of the arguments property
          // consider a escape of the arguments object.


  private void inlineNonConstants(
      Var v, ReferenceCollection referenceInfo) {
    int refCount = referenceInfo.references.size();
    Reference declaration = referenceInfo.references.get(0);
    Reference init = referenceInfo.getInitializingReference();
    int firstRefAfterInit = (declaration == init) ? 2 : 3;

    if (refCount > 1 &&
        isImmutableAndWellDefinedVariable(v, referenceInfo)) {
      // if the variable is referenced more than once, we can only
      // inline it if it's immutable and never defined before referenced.
      Node value;
      if (init != null) {
        value = init.getAssignedValue();
      } else {
        // Create a new node for variable that is never initialized.
        Node srcLocation = declaration.getNameNode();
        value = NodeUtil.newUndefinedNode(srcLocation);
      }
      Preconditions.checkNotNull(value);
      inlineWellDefinedVariable(v, value, referenceInfo.references);
      staleVars.add(v);
    } else if (refCount == firstRefAfterInit) {
      // The variable likely only read once, try some more
      // complex inlining heuristics.
      Reference reference = referenceInfo.references.get(
          firstRefAfterInit - 1);
      if (canInline(declaration, init, reference)) {
        inline(v, declaration, init, reference);
        staleVars.add(v);
      }
    } else if (declaration != init && refCount == 2) {
      if (isValidDeclaration(declaration) && isValidInitialization(init)) {
        // The only reference is the initialization, remove the assignment and
        // the variable declaration.
        Node value = init.getAssignedValue();
        Preconditions.checkNotNull(value);
        inlineWellDefinedVariable(v, value, referenceInfo.references);
        staleVars.add(v);
      }
    }

    // If this variable was not inlined normally, check if we can
    // inline an alias of it. (If the variable was inlined, then the
    // reference data is out of sync. We're better off just waiting for
    // the next pass.)
    if (
        !staleVars.contains(v) && referenceInfo.isWellDefined() &&
        referenceInfo.isAssignedOnceInLifetime()) {
      List<Reference> refs = referenceInfo.references;
      for (int i = 1 /* start from a read */; i < refs.size(); i++) {
        Node nameNode = refs.get(i).getNameNode();
        if (aliasCandidates.containsKey(nameNode)) {
          AliasCandidate candidate = aliasCandidates.get(nameNode);
          if (!staleVars.contains(candidate.alias) &&
              !isVarInlineForbidden(candidate.alias)) {
            Reference aliasInit;
            aliasInit = candidate.refInfo.getInitializingReference();
            Node value = aliasInit.getAssignedValue();
            Preconditions.checkNotNull(value);
            inlineWellDefinedVariable(candidate.alias,
                value,
                candidate.refInfo.references);
            staleVars.add(candidate.alias);
          }
        }
      }
    }
  }

public void visit(NodeTraversal t, Node n, Node parent) {
  if (n.getType() == Token.NAME) {
    Var v = t.getScope().getVar(n.getString());
    if (v != null && varFilter.apply(v)) {
      addReference(t, v,
          new Reference(n, parent, t, blockStack.peek()));
    }
  }

  if (isBlockBoundary(n, parent)) {
    blockStack.pop();
  }
}

public class Scope implements StaticScope<JSType> {
  private final Map<String, Var> vars = new LinkedHashMap<String, Var>();
  private final Scope parent;
  private final int depth;
  private final Node rootNode;

  /** The type of {@code this} in the current scope. */
  private final ObjectType thisType;

  /** Whether this is a bottom scope for the purposes of type inference. */
  private final boolean isBottom;


  /** Stores info about a variable */
  public static class Var implements StaticSlot<JSType> {
    /** name */
    final String name;

    /** Var node */
    final Node nameNode;

    /**
     * The variable's type.
     */
    private JSType type;

    /**
     * The variable's doc info.
     */
    private final JSDocInfo info;

    /**
     * Whether the variable's type has been inferred or is declared. An inferred
     * type may change over time (as more code is discovered), whereas a
     * declared type is a static contract that must be matched.
     */
    private final boolean typeInferred;

    /** Input source */
    final CompilerInput input;

    /** Whether the variable is a define */
    final boolean isDefine;

    /**
     * The index at which the var is declared. e..g if it's 0, it's the first
     * declared variable in that scope
     */
    final int index;

    /** The enclosing scope */
    final Scope scope;

    /**
     * Creates a variable.
     *
     * @param inferred whether its type is inferred (as opposed to declared)
     */
    private Var(boolean inferred, String name, Node nameNode, JSType type,
                Scope scope, int index, CompilerInput input, boolean isDefine,
                JSDocInfo info) {
      this.name = name;
      this.nameNode = nameNode;
      this.type = type;
      this.scope = scope;
      this.index = index;
      this.input = input;
      this.isDefine = isDefine;
      this.info = info;
      this.typeInferred = inferred;
    }

    /**
     * Gets the name of the variable.
     */
    public String getName() {
      return name;
    }

    /**
     * Gets the parent of the name node.
     */
    public Node getParentNode() {
      return nameNode == null ? null : nameNode.getParent();
    }

private void collapseDeclarationOfNameAndDescendants(Name n, String alias) {
  boolean canCollapseChildNames = n.canCollapseUnannotatedChildNames();

  // Handle this name first so that nested object literals get unrolled.
  if (n.canCollapse() && canCollapseChildNames) {
    updateObjLitOrFunctionDeclaration(n, alias);
  }

  if (n.props != null) {
    for (Name p : n.props) {
      // Recurse first so that saved node ancestries are intact when needed.
      collapseDeclarationOfNameAndDescendants(
          p, appendPropForAlias(alias, p.name));

      if (!p.inExterns && canCollapseChildNames && p.declaration != null &&
          p.declaration.node != null &&
          p.declaration.node.getParent() != null &&
          p.declaration.node.getParent().getType() == Token.ASSIGN) {
        updateSimpleDeclaration(
            appendPropForAlias(alias, p.name), p, p.declaration);
      }
    }
  }
}

private void updateObjLitOrFunctionDeclaration(Name n, String alias) {
  if (n.declaration == null) {
    // Some names do not have declarations, because they
    // are only defined in local scopes.
    return;
  }

  if (n.declaration.getTwin() != null) {
    // Twin declarations will get handled when normal references
    // are handled.
    return;
  }

  switch (n.declaration.node.getParent().getType()) {
    case Token.ASSIGN:
      updateObjLitOrFunctionDeclarationAtAssignNode(n, alias);
      break;
    case Token.VAR:
      updateObjLitOrFunctionDeclarationAtVarNode(n);
      break;
    case Token.FUNCTION:
      updateFunctionDeclarationAtFunctionNode(n);
      break;
  }
}

private void updateObjLitOrFunctionDeclarationAtVarNode(Name n) {

  Ref ref = n.declaration;
  String name = ref.node.getString();
  Node rvalue = ref.node.getFirstChild();
  Node varNode = ref.node.getParent();
  Node gramps = varNode.getParent();

  boolean isObjLit = rvalue.getType() == Token.OBJECTLIT;
  int numChanges = 0;

  if (isObjLit) {
    numChanges += declareVarsForObjLitValues(
        n, name, rvalue, varNode, gramps.getChildBefore(varNode),
        gramps);
  }

  numChanges += addStubsForUndeclaredProperties(n, name, gramps, varNode);

  if (isObjLit && n.canEliminate()) {
    varNode.removeChild(ref.node);
    if (!varNode.hasChildren()) {
      gramps.removeChild(varNode);
    }
    numChanges++;

    // Clear out the object reference, since we've eliminated it from the
    // parse tree.
    ref.node = null;
  }

  if (numChanges > 0) {
    compiler.reportCodeChange();
  }
}

private void updateFunctionDeclarationAtFunctionNode(Name n) {

  Ref ref = n.declaration;
  String fnName = ref.node.getString();
  addStubsForUndeclaredProperties(
      n, fnName, ref.node.getAncestor(2), ref.node.getParent());
}

