}

private FlowScope traverseObjectLiteral(Node n, FlowScope scope) {
  JSType type = n.getJSType();
  Preconditions.checkNotNull(type);

  for (Node name = n.getFirstChild(); name != null; name = name.getNext()) {
    scope = traverse(name.getFirstChild(), scope);
  }

  // Object literals can be reflected on other types.
  // See CodingConvention#getObjectLiteralCase and goog.object.reflect.
  // Ignore these types of literals.
  ObjectType objectType = ObjectType.cast(type);
  if (objectType == null) {
    return scope;
  }
  boolean hasLendsName = n.getJSDocInfo() != null &&
      n.getJSDocInfo().getLendsName() != null;
  if (objectType.hasReferenceName() && !hasLendsName) {
    return scope;
  }

  String qObjName = NodeUtil.getBestLValueName(
      NodeUtil.getBestLValue(n));
  for (Node name = n.getFirstChild(); name != null;
       name = name.getNext()) {
    String memberName = NodeUtil.getObjectLitKeyName(name);
    if (memberName != null) {
      JSType rawValueType =  name.getFirstChild().getJSType();
      JSType valueType = NodeUtil.getObjectLitKeyTypeFromValueType(
          name, rawValueType);
      if (valueType == null) {
        valueType = unknownType;
      }
      objectType.defineInferredProperty(memberName, valueType, name);

      // Do normal flow inference if this is a direct property assignment.
      if (qObjName != null && name.isStringKey()) {
        String qKeyName = qObjName + "." + memberName;
        Var var = syntacticScope.getVar(qKeyName);
        JSType oldType = var == null ? null : var.getType();
        if (var != null && var.isTypeInferred()) {
          var.setType(oldType == null ?
              valueType : oldType.getLeastSupertype(oldType));
        }

        scope.inferQualifiedSlot(name, qKeyName,
            oldType == null ? unknownType : oldType,
            valueType);
      }
    } else {
      n.setJSType(unknownType);
    }
  }
  return scope;
}

private JSType getDeclaredType(JSDocInfo info, Node lValue,
    @Nullable Node rValue) {
  if (info != null && info.hasType()) {
    return getDeclaredTypeInAnnotation(lValue, info);
  } else if (rValue != null && rValue.isFunction() &&
      shouldUseFunctionLiteralType(
          JSType.toMaybeFunctionType(rValue.getJSType()), info, lValue)) {
    return rValue.getJSType();
  } else if (info != null) {
    if (info.hasEnumParameterType()) {
      if (rValue != null && rValue.isObjectLit()) {
        return rValue.getJSType();
      } else {
        return createEnumTypeFromNodes(
            rValue, lValue.getQualifiedName(), info, lValue);
      }
    } else if (info.isConstructor() || info.isInterface()) {
      return createFunctionTypeFromNodes(
          rValue, lValue.getQualifiedName(), info, lValue);
    }
  }

  // Check if this is constant, and if it has a known type.
  if (isConstantSymbol(info, lValue)) {
    if (rValue != null) {
      JSDocInfo rValueInfo = rValue.getJSDocInfo();
      if (rValueInfo != null && rValueInfo.hasType()) {
        // If rValue has a type-cast, we use the type in the type-cast.
        return rValueInfo.getType().evaluate(scope, typeRegistry);
      } else if (rValue.getJSType() != null
          && !rValue.getJSType().isUnknownType()) {
        // If rValue's type was already computed during scope creation,
        // then we can safely use that.
        return rValue.getJSType();
      } else if (rValue.isOr()) {
        // Check for a very specific JS idiom:
        // var x = x || TYPE;
        // This is used by Closure's base namespace for esoteric
        // reasons.
        Node firstClause = rValue.getFirstChild();
        Node secondClause = firstClause.getNext();
        boolean namesMatch = firstClause.isName()
            && lValue.isName()
            && firstClause.getString().equals(lValue.getString());
        if (namesMatch && secondClause.getJSType() != null
            && !secondClause.getJSType().isUnknownType()) {
          return secondClause.getJSType();
        }
      }
    }
  }

  return getDeclaredTypeInAnnotation(lValue, info);
}

private boolean shouldUseFunctionLiteralType(
    FunctionType type, JSDocInfo info, Node lValue) {
  if (info != null) {
    return true;
  }
  if (lValue != null &&
      NodeUtil.isObjectLitKey(lValue)) {
    return false;
  }
  return scope.isGlobal() || !type.isReturnTypeInferred();
}

private void parse(AbstractCompiler compiler) {
  try {
    ParserRunner.ParseResult result = ParserRunner.parse(sourceFile, sourceFile.getCode(),
        compiler.getParserConfig(),
        compiler.getDefaultErrorReporter(),
        logger_);
    root = result.ast;
    compiler.setOldParseTree(sourceFile.getName(), result.oldAst);
  } catch (IOException e) {
    compiler.report(
        JSError.make(AbstractCompiler.READ_ERROR, sourceFile.getName()));
  }

  if (root == null || compiler.hasHaltingErrors()) {
      // Most passes try to report as many errors as possible,
      // so there may already be errors. We only care if there were
      // errors in the code we just parsed.
    // There was a parse error or IOException, so use a dummy block.
    root = IR.script();
  } else {
    compiler.prepareAst(root);
  }

  // Set the source name so that the compiler passes can track
  // the source file and module.
  root.setStaticSourceFile(sourceFile);
}

static boolean isUndefined(Node n) {
  switch (n.getType()) {
    case Token.VOID:
      return true;
    case Token.NAME:
      return n.getString().equals("undefined");
  }
  return false;
}

static boolean isNullOrUndefined(Node n) {
  return n.isNull() || isUndefined(n);
}

private void findAliases(NodeTraversal t) {
  Scope scope = t.getScope();
  for (Var v : scope.getVarIterable()) {
    Node n = v.getNode();
    Node parent = n.getParent();
    boolean isVarAssign = parent.isVar() && n.hasChildren();
    if (isVarAssign && n.getFirstChild().isQualifiedName()) {
      recordAlias(v);
    } else if (v.isBleedingFunction()) {
      // Bleeding functions already get a BAD_PARAMETERS error, so just
      // do nothing.
    } else if (parent.getType() == Token.LP) {
      // Parameters of the scope function also get a BAD_PARAMETERS
      // error.
    } else if (isVarAssign) {
      Node value = v.getInitialValue().detachFromParent();
      String name = n.getString();
      int nameCount = scopedAliasNames.count(name);
      scopedAliasNames.add(name);
      String globalName =
          "$jscomp.scope." + name + (nameCount == 0 ? "" : ("$" + nameCount));

      compiler.ensureLibraryInjected("base");

      // Add $jscomp.scope.name = EXPR;
      // Make sure we copy over all the jsdoc and debug info.
        Node newDecl = NodeUtil.newQualifiedNameNodeDeclaration(
            compiler.getCodingConvention(),
            globalName,
            value,
            v.getJSDocInfo())
            .useSourceInfoIfMissingFromForTree(n);
        NodeUtil.setDebugInformation(
            newDecl.getFirstChild().getFirstChild(), n, name);
        parent.getParent().addChildBefore(newDecl, parent);

      // Rewrite "var name = EXPR;" to "var name = $jscomp.scope.name;"
      v.getNameNode().addChildToFront(
          NodeUtil.newQualifiedNameNode(
              compiler.getCodingConvention(), globalName, n, name));

      recordAlias(v);
    } else {
      // Do not allow hoisted functions or other kinds of local symbols.
      report(t, n, GOOG_SCOPE_NON_ALIAS_LOCAL, n.getString());
    }
  }
}

class FunctionInjector {

  private final AbstractCompiler compiler;
  private final boolean allowDecomposition;
  private Set<String> knownConstants = Sets.newHashSet();
  private final boolean assumeStrictThis;
  private final boolean assumeMinimumCapture;
  private final Supplier<String> safeNameIdSupplier;

  /**
   * @param allowDecomposition Whether an effort should be made to break down
   * expressions into simpler expressions to allow functions to be injected
   * where they would otherwise be disallowed.
   */
  public FunctionInjector(
      AbstractCompiler compiler,
      Supplier<String> safeNameIdSupplier,
      boolean allowDecomposition,
      boolean assumeStrictThis,
      boolean assumeMinimumCapture) {
    Preconditions.checkNotNull(compiler);
    Preconditions.checkNotNull(safeNameIdSupplier);
    this.compiler = compiler;
    this.safeNameIdSupplier = safeNameIdSupplier;
    this.allowDecomposition = allowDecomposition;
    this.assumeStrictThis = assumeStrictThis;
    this.assumeMinimumCapture = assumeMinimumCapture;
  }

  /** The type of inlining to perform. */
  enum InliningMode {
    /**
     * Directly replace the call expression. Only functions of meeting
     * strict preconditions can be inlined.
     */
    DIRECT,

    /**
     * Replaces the call expression with a block of statements. Conditions
     * on the function are looser in mode, but stricter on the call site.
     */
    BLOCK
  }

  /** Holds a reference to the call node of a function call */
  static class Reference {
    final Node callNode;
    final JSModule module;
    final InliningMode mode;

    Reference(Node callNode, JSModule module, InliningMode mode){
      this.callNode = callNode;
      this.module = module;
      this.mode = mode;
    }
  }

private BooleanOutcomePair traverseShortCircuitingBinOp(
    Node n, FlowScope scope, boolean condition) {
  Node left = n.getFirstChild();
  Node right = n.getLastChild();

  // type the left node
  BooleanOutcomePair leftLiterals =
      traverseWithinShortCircuitingBinOp(left,
          scope.createChildFlowScope());
  JSType leftType = left.getJSType();

  // reverse abstract interpret the left node to produce the correct
  // scope in which to verify the right node
  FlowScope rightScope = reverseInterpreter.
      getPreciserScopeKnowingConditionOutcome(
          left, leftLiterals.getOutcomeFlowScope(left.getType(), condition),
          condition);

  // type the right node
  BooleanOutcomePair rightLiterals =
      traverseWithinShortCircuitingBinOp(
          right, rightScope.createChildFlowScope());
  JSType rightType = right.getJSType();

  JSType type;
  BooleanOutcomePair literals;
  if (leftType != null && rightType != null) {
    leftType = leftType.getRestrictedTypeGivenToBooleanOutcome(!condition);
    if (leftLiterals.toBooleanOutcomes ==
        BooleanLiteralSet.get(!condition)) {
      // Use the restricted left type, since the right side never gets
      // evaluated.
      type = leftType;
      literals = leftLiterals;
    } else {
      // Use the join of the restricted left type knowing the outcome of the
      // ToBoolean predicate and of the right type.
      type = leftType.getLeastSupertype(rightType);
      literals =
          getBooleanOutcomePair(leftLiterals, rightLiterals, condition);
    }

    // Exclude the boolean type if the literal set is empty because a boolean
    // can never actually be returned.
    if (literals.booleanValues == BooleanLiteralSet.EMPTY &&
        getNativeType(BOOLEAN_TYPE).isSubtype(type)) {
      // Exclusion only make sense for a union type.
      if (type.isUnionType()) {
        type = type.toMaybeUnionType().getRestrictedUnion(
            getNativeType(BOOLEAN_TYPE));
      }
    }
  } else {
    type = null;
    literals = new BooleanOutcomePair(
        BooleanLiteralSet.BOTH, BooleanLiteralSet.BOTH,
        leftLiterals.getJoinedFlowScope(),
        rightLiterals.getJoinedFlowScope());
  }
  n.setJSType(type);

  return literals;
}

private BooleanOutcomePair traverseWithinShortCircuitingBinOp(Node n,
    FlowScope scope) {
  switch (n.getType()) {
    case Token.AND:
      return traverseAnd(n, scope);

    case Token.OR:
      return traverseOr(n, scope);

    default:
      scope = traverse(n, scope);
      return newBooleanOutcomePair(n.getJSType(), scope);
  }
}

public String caverphone(String txt) {
    // NOTE: Version 1.0 of Caverphone is easily derivable from this code 
    // by commenting out the 2.0 lines and adding in the 1.0 lines

    if( txt == null || txt.length() == 0 ) {
        return "1111111111";
    }

    // 1. Convert to lowercase
    txt = txt.toLowerCase();

    // 2. Remove anything not A-Z
    txt = txt.replaceAll("[^a-z]", "");

    // 2.5. Remove final e
    txt = txt.replaceAll("e$", "");             // 2.0 only

    // 3. Handle various start options
    txt = txt.replaceAll("^cough", "cou2f");
    txt = txt.replaceAll("^rough", "rou2f");
    txt = txt.replaceAll("^tough", "tou2f");
    txt = txt.replaceAll("^enough", "enou2f");  // 2.0 only
    txt = txt.replaceAll("^trough", "trou2f");  // 2.0 only - note the spec says ^enough here again, c+p error I assume
    txt = txt.replaceAll("^gn", "2n");
    txt = txt.replaceAll("^mb", "m2");

    // 4. Handle replacements
    txt = txt.replaceAll("cq", "2q");
    txt = txt.replaceAll("ci", "si");
    txt = txt.replaceAll("ce", "se");
    txt = txt.replaceAll("cy", "sy");
    txt = txt.replaceAll("tch", "2ch");
    txt = txt.replaceAll("c", "k");
    txt = txt.replaceAll("q", "k");
    txt = txt.replaceAll("x", "k");
    txt = txt.replaceAll("v", "f");
    txt = txt.replaceAll("dg", "2g");
    txt = txt.replaceAll("tio", "sio");
    txt = txt.replaceAll("tia", "sia");
    txt = txt.replaceAll("d", "t");
    txt = txt.replaceAll("ph", "fh");
    txt = txt.replaceAll("b", "p");
    txt = txt.replaceAll("sh", "s2");
    txt = txt.replaceAll("z", "s");
    txt = txt.replaceAll("^[aeiou]", "A");
    txt = txt.replaceAll("[aeiou]", "3");
    txt = txt.replaceAll("j", "y");        // 2.0 only
    txt = txt.replaceAll("^y3", "Y3");     // 2.0 only
    txt = txt.replaceAll("^y", "A");       // 2.0 only
    txt = txt.replaceAll("y", "3");        // 2.0 only
    txt = txt.replaceAll("3gh3", "3kh3");
    txt = txt.replaceAll("gh", "22");
    txt = txt.replaceAll("g", "k");
    txt = txt.replaceAll("s+", "S");
    txt = txt.replaceAll("t+", "T");
    txt = txt.replaceAll("p+", "P");
    txt = txt.replaceAll("k+", "K");
    txt = txt.replaceAll("f+", "F");
    txt = txt.replaceAll("m+", "M");
    txt = txt.replaceAll("n+", "N");
    txt = txt.replaceAll("w3", "W3");
    //txt = txt.replaceAll("wy", "Wy");    // 1.0 only
    txt = txt.replaceAll("wh3", "Wh3");
    txt = txt.replaceAll("w$", "3");       // 2.0 only
    //txt = txt.replaceAll("why", "Why");  // 1.0 only
    txt = txt.replaceAll("w", "2");
    txt = txt.replaceAll("^h", "A");
    txt = txt.replaceAll("h", "2");
    txt = txt.replaceAll("r3", "R3");
    txt = txt.replaceAll("r$", "3");       // 2.0 only
    //txt = txt.replaceAll("ry", "Ry");    // 1.0 only
    txt = txt.replaceAll("r", "2");
    txt = txt.replaceAll("l3", "L3");
    txt = txt.replaceAll("l$", "3");       // 2.0 only
    //txt = txt.replaceAll("ly", "Ly");    // 1.0 only
    txt = txt.replaceAll("l", "2");
    //txt = txt.replaceAll("j", "y");      // 1.0 only
    //txt = txt.replaceAll("y3", "Y3");    // 1.0 only
    //txt = txt.replaceAll("y", "2");      // 1.0 only

    // 5. Handle removals
    txt = txt.replaceAll("2", "");
    txt = txt.replaceAll("3$", "A");       // 2.0 only
    txt = txt.replaceAll("3", "");

    // 6. put ten 1s on the end
    txt = txt + "111111" + "1111";        // 1.0 only has 6 1s

    // 7. take the first six characters as the code
    return txt.substring(0, 10);          // 1.0 truncates to 6
}

void encode(byte[] in, int inPos, int inAvail) {
    if (eof) {
        return;
    }
    // inAvail < 0 is how we're informed of EOF in the underlying data we're
    // encoding.
    if (inAvail < 0) {
        eof = true;
        if (buf == null || buf.length - pos < encodeSize) {
            resizeBuf();
        }
        switch (modulus) {
            case 1:
                buf[pos++] = encodeTable[(x >> 2) & MASK_6BITS];
                buf[pos++] = encodeTable[(x << 4) & MASK_6BITS];
                // URL-SAFE skips the padding to further reduce size.
                if (encodeTable == STANDARD_ENCODE_TABLE) {
                    buf[pos++] = PAD;
                    buf[pos++] = PAD;
                }
                break;

            case 2:
                buf[pos++] = encodeTable[(x >> 10) & MASK_6BITS];
                buf[pos++] = encodeTable[(x >> 4) & MASK_6BITS];
                buf[pos++] = encodeTable[(x << 2) & MASK_6BITS];
                // URL-SAFE skips the padding to further reduce size.
                if (encodeTable == STANDARD_ENCODE_TABLE) {
                    buf[pos++] = PAD;
                }
                break;
        }
        if (lineLength > 0) {
            System.arraycopy(lineSeparator, 0, buf, pos, lineSeparator.length);
            pos += lineSeparator.length;
        }
    } else {
        for (int i = 0; i < inAvail; i++) {
            if (buf == null || buf.length - pos < encodeSize) {
                resizeBuf();
            }
            modulus = (++modulus) % 3;
            int b = in[inPos++];
            if (b < 0) { b += 256; }
            x = (x << 8) + b;
            if (0 == modulus) {
                buf[pos++] = encodeTable[(x >> 18) & MASK_6BITS];
                buf[pos++] = encodeTable[(x >> 12) & MASK_6BITS];
                buf[pos++] = encodeTable[(x >> 6) & MASK_6BITS];
                buf[pos++] = encodeTable[x & MASK_6BITS];
                currentLinePos += 4;
                if (lineLength > 0 && lineLength <= currentLinePos) {
                    System.arraycopy(lineSeparator, 0, buf, pos, lineSeparator.length);
                    pos += lineSeparator.length;
                    currentLinePos = 0;
                }
            }
        }
    }
}

