/**
 * Create a new {@link Set} with the same type as the provided {@code set}
 * and populate it with all elements of {@code list}.
 * 
 * @param set
 *            the {@link Set} to be used as return type, must not be null
 * @param list
 *            the {@link List} to populate the {@link Set}
 * @return a new {@link Set} populated with all elements of the provided
 *         {@link List}
 */
@SuppressWarnings("unchecked")
protected Set<E> createSetBasedOnList(final Set<E> set, final List<E> list) {
    Set<E> subSet;
    if (set.getClass().equals(HashSet.class)) {
        subSet = new HashSet<E>(list.size());
    } else {
        try {
            subSet = set.getClass().newInstance();
        } catch (final InstantiationException ie) {
            subSet = new HashSet<E>();
        } catch (final IllegalAccessException iae) {
            subSet = new HashSet<E>();
        }
    }
    subSet.addAll(list);
    return subSet;
}

public void putAll(int index, final Map<? extends K, ? extends V> map) {
    for (final Map.Entry<? extends K, ? extends V> entry : map.entrySet()) {
        final V old = put(index, entry.getKey(), entry.getValue());
        if (old == null) {
        // The return value of put is null if the key did not exist OR the value was null
        // so it cannot be used to determine whether the key was added
            // if no key was replaced, increment the index
            index++;
        } else {
            // otherwise put the next item after the currently inserted key
            index = indexOf(entry.getKey()) + 1;
        }
    }
}

