private void skipRemainderOfLastBlock() throws IOException {
    long readFromLastBlock = getBytesRead() % blockSize;
    long remainingBytes = readFromLastBlock == 0 ? 0 : blockSize - readFromLastBlock;
    while (remainingBytes > 0) {
        long skipped = skip(remainingBytes);
        if (skipped <= 0) {
            break;
        }
        remainingBytes -= skipped;
    }
}

@Override
public long skip(long n) throws IOException {
    if (n < 0) {
        throw new IllegalArgumentException("negative skip length");
    }
    ensureOpen();
    long total = 0;
    while (total < n) {
        long len = Math.min(n - total, this.tmpbuf.length);
        len = read(this.tmpbuf, 0, (int) len);
        if (len == -1) {
            this.entryEOF = true;
            break;
        }
        total += len;
    }
    return total;
}

@Override
public CpioArchiveEntry getNextEntry() throws IOException {
    return getNextCPIOEntry();
}

private void skip(int bytes) throws IOException {
    if (bytes > 0) {
        readFully(FOUR_BYTES_BUF, 0, bytes);
    }
}

private void closeEntry() throws IOException {
    ensureOpen();
    while (read(this.tmpbuf, 0, this.tmpbuf.length) != -1) { // NOPMD
        // do nothing
    }
    this.entryEOF = true;
}

private CpioArchiveEntry readNewEntry(final boolean hasCrc) throws IOException {
    CpioArchiveEntry ret;
    if (hasCrc) {
        ret = new CpioArchiveEntry(FORMAT_NEW_CRC);
    } else {
        ret = new CpioArchiveEntry(FORMAT_NEW);
    }
    ret.setInode(readAsciiLong(8, 16));
    ret.setMode(readAsciiLong(8, 16));
    ret.setUID(readAsciiLong(8, 16));
    ret.setGID(readAsciiLong(8, 16));
    ret.setNumberOfLinks(readAsciiLong(8, 16));
    ret.setTime(readAsciiLong(8, 16));
    ret.setSize(readAsciiLong(8, 16));
    ret.setDeviceMaj(readAsciiLong(8, 16));
    ret.setDeviceMin(readAsciiLong(8, 16));
    ret.setRemoteDeviceMaj(readAsciiLong(8, 16));
    ret.setRemoteDeviceMin(readAsciiLong(8, 16));
    long namesize = readAsciiLong(8, 16);
    ret.setChksum(readAsciiLong(8, 16));
    String name = readCString((int) namesize);
    ret.setName(name);
    if (ret.getMode() == 0 && !name.equals(CPIO_TRAILER)){
        throw new IOException("Mode 0 only allowed in the trailer. Found entry name: "+name + " Occured at byte: " + getBytesRead());
    }
    skip(ret.getHeaderPadCount());
    return ret;
}

private CpioArchiveEntry readOldAsciiEntry() throws IOException {
    CpioArchiveEntry ret = new CpioArchiveEntry(FORMAT_OLD_ASCII);
    ret.setDevice(readAsciiLong(6, 8));
    ret.setInode(readAsciiLong(6, 8));
    ret.setMode(readAsciiLong(6, 8));
    ret.setUID(readAsciiLong(6, 8));
    ret.setGID(readAsciiLong(6, 8));
    ret.setNumberOfLinks(readAsciiLong(6, 8));
    ret.setRemoteDevice(readAsciiLong(6, 8));
    ret.setTime(readAsciiLong(11, 8));
    long namesize = readAsciiLong(6, 8);
    ret.setSize(readAsciiLong(11, 8));
    String name = readCString((int) namesize);
    ret.setName(name);
    if (ret.getMode() == 0 && !name.equals(CPIO_TRAILER)){
        throw new IOException("Mode 0 only allowed in the trailer. Found entry: "+ name + " Occured at byte: " + getBytesRead());
    }
    return ret;
}

private CpioArchiveEntry readOldBinaryEntry(final boolean swapHalfWord) throws IOException {
    CpioArchiveEntry ret = new CpioArchiveEntry(FORMAT_OLD_BINARY);
    ret.setDevice(readBinaryLong(2, swapHalfWord));
    ret.setInode(readBinaryLong(2, swapHalfWord));
    ret.setMode(readBinaryLong(2, swapHalfWord));
    ret.setUID(readBinaryLong(2, swapHalfWord));
    ret.setGID(readBinaryLong(2, swapHalfWord));
    ret.setNumberOfLinks(readBinaryLong(2, swapHalfWord));
    ret.setRemoteDevice(readBinaryLong(2, swapHalfWord));
    ret.setTime(readBinaryLong(4, swapHalfWord));
    long namesize = readBinaryLong(2, swapHalfWord);
    ret.setSize(readBinaryLong(4, swapHalfWord));
    String name = readCString((int) namesize);
    ret.setName(name);
    if (ret.getMode() == 0 && !name.equals(CPIO_TRAILER)){
        throw new IOException("Mode 0 only allowed in the trailer. Found entry: "+name + "Occured at byte: " + getBytesRead());
    }
    skip(ret.getHeaderPadCount());
    return ret;
}

