private void skipRemainderOfLastBlock() throws IOException {
    long readFromLastBlock = getBytesRead() % blockSize;
    long remainingBytes = readFromLastBlock == 0 ? 0 : blockSize - readFromLastBlock;
    while (remainingBytes > 0) {
        long skipped = skip(remainingBytes);
        if (skipped <= 0) {
            break;
        }
        remainingBytes -= skipped;
    }
}

/**
 * Sets the compression method to use for entry contents - the
 * default is LZMA2.
 *
 * <p>Currently only {@link SevenZMethod#COPY}, {@link
 * SevenZMethod#LZMA2}, {@link SevenZMethod#BZIP2} and {@link
 * SevenZMethod#DEFLATE} are supported.</p>
 */
public void setContentCompression(SevenZMethod method) {
    this.contentCompression = method;
}

/**
 * Closes the archive, calling {@link #finish} if necessary.
 * 
 * @throws IOException
 */
public void close() throws IOException {
    if (!finished) {
        finish();
    }
    file.close();
}

/**
 * Create an archive entry using the inputFile and entryName provided.
 * 
 * @param inputFile
 * @param entryName 
 * @return the ArchiveEntry set up with details from the file
 * 
 * @throws IOException
 */
public SevenZArchiveEntry createArchiveEntry(final File inputFile,
        final String entryName) throws IOException {
    final SevenZArchiveEntry entry = new SevenZArchiveEntry();
    entry.setDirectory(inputFile.isDirectory());
    entry.setName(entryName);
    entry.setLastModifiedDate(new Date(inputFile.lastModified()));
    return entry;
}

/**
 * Records an archive entry to add.
 *
 * The caller must then write the content to the archive and call
 * {@link #closeArchiveEntry()} to complete the process.
 * 
 * @param archiveEntry describes the entry
 * @throws IOException
 */
public void putArchiveEntry(final ArchiveEntry archiveEntry) throws IOException {
    final SevenZArchiveEntry entry = (SevenZArchiveEntry) archiveEntry;
    files.add(entry);
}

/**
 * Closes the archive entry.
 * @throws IOException
 */
public void closeArchiveEntry() throws IOException {
    if (currentOutputStream != null) {
        currentOutputStream.flush();
        currentOutputStream.close();
    }

    final SevenZArchiveEntry entry = files.get(files.size() - 1);
    if (fileBytesWritten > 0) {
        entry.setHasStream(true);
        ++numNonEmptyStreams;
        entry.setSize(currentOutputStream.getBytesWritten());
        entry.setCompressedSize(fileBytesWritten);
        entry.setCrcValue(crc32.getValue());
        entry.setCompressedCrcValue(compressedCrc32.getValue());
        entry.setHasCrc(true);
    } else {
        entry.setHasStream(false);
        entry.setSize(0);
        entry.setCompressedSize(0);
        entry.setHasCrc(false);
    }
    currentOutputStream = null;
    crc32.reset();
    compressedCrc32.reset();
    fileBytesWritten = 0;
}

/**
 * Writes a byte to the current archive entry.
 * @param b The byte to be written.
 * @throws IOException on error
 */
public void write(final int b) throws IOException {
    getCurrentOutputStream().write(b);
}

/**
 * Writes a byte array to the current archive entry.
 * @param b The byte array to be written.
 * @throws IOException on error
 */
public void write(final byte[] b) throws IOException {
    write(b, 0, b.length);
}

/**
 * Writes part of a byte array to the current archive entry.
 * @param b The byte array to be written.
 * @param off offset into the array to start writing from
 * @param len number of bytes to write
 * @throws IOException on error
 */
public void write(final byte[] b, final int off, final int len) throws IOException {
    if (len > 0) {
        getCurrentOutputStream().write(b, off, len);
    }
}

/**
 * Finishes the addition of entries to this archive, without closing it.
 * 
 * @throws IOException if archive is already closed.
 */
public void finish() throws IOException {
    if (finished) {
        throw new IOException("This archive has already been finished");
    }
    finished = true;

    final long headerPosition = file.getFilePointer();

    final ByteArrayOutputStream headerBaos = new ByteArrayOutputStream();
    final DataOutputStream header = new DataOutputStream(headerBaos);

    writeHeader(header);
    header.flush();
    final byte[] headerBytes = headerBaos.toByteArray();
    file.write(headerBytes);

    final CRC32 crc32 = new CRC32();

    // signature header
    file.seek(0);
    file.write(SevenZFile.sevenZSignature);
    // version
    file.write(0);
    file.write(2);

    // start header
    final ByteArrayOutputStream startHeaderBaos = new ByteArrayOutputStream();
    final DataOutputStream startHeaderStream = new DataOutputStream(startHeaderBaos);
    startHeaderStream.writeLong(Long.reverseBytes(headerPosition - SevenZFile.SIGNATURE_HEADER_SIZE));
    startHeaderStream.writeLong(Long.reverseBytes(0xffffFFFFL & headerBytes.length));
    crc32.reset();
    crc32.update(headerBytes);
    startHeaderStream.writeInt(Integer.reverseBytes((int)crc32.getValue()));
    startHeaderStream.flush();
    final byte[] startHeaderBytes = startHeaderBaos.toByteArray();
    crc32.reset();
    crc32.update(startHeaderBytes);
    file.writeInt(Integer.reverseBytes((int) crc32.getValue()));
    file.write(startHeaderBytes);
}

/*
 * Creation of output stream is deferred until data is actually
 * written as some codecs might write header information even for
 * empty streams and directories otherwise.
 */
private OutputStream getCurrentOutputStream() throws IOException {
    if (currentOutputStream == null) {
        currentOutputStream = setupFileOutputStream();
    }
    return currentOutputStream;
}

private CountingOutputStream setupFileOutputStream() throws IOException {
    OutputStream out = new OutputStreamWrapper();
    return new CountingOutputStream(Coders
                                    .addEncoder(out,
                                                contentCompression,
                                                null)) {
        @Override
        public void write(final int b) throws IOException {
            super.write(b);
            crc32.update(b);
        }

        @Override
        public void write(final byte[] b) throws IOException {
            super.write(b);
            crc32.update(b);
        }

        @Override
        public void write(final byte[] b, final int off, final int len)
            throws IOException {
            super.write(b, off, len);
            crc32.update(b, off, len);
        }
    };
}

private void writeHeader(final DataOutput header) throws IOException {
    header.write(NID.kHeader);

    header.write(NID.kMainStreamsInfo);
    writeStreamsInfo(header);
    writeFilesInfo(header);
    header.write(NID.kEnd);
}

private void writeStreamsInfo(final DataOutput header) throws IOException {
    if (numNonEmptyStreams > 0) {
        writePackInfo(header);
        writeUnpackInfo(header);
    }

    writeSubStreamsInfo(header);

    header.write(NID.kEnd);
}

private void writePackInfo(final DataOutput header) throws IOException {
    header.write(NID.kPackInfo);

    writeUint64(header, 0);
    writeUint64(header, 0xffffFFFFL & numNonEmptyStreams);

    header.write(NID.kSize);
    for (final SevenZArchiveEntry entry : files) {
        if (entry.hasStream()) {
            writeUint64(header, entry.getCompressedSize());
        }
    }

    header.write(NID.kCRC);
    header.write(1);
    for (final SevenZArchiveEntry entry : files) {
        if (entry.hasStream()) {
            header.writeInt(Integer.reverseBytes((int) entry.getCompressedCrcValue()));
        }
    }

    header.write(NID.kEnd);
}

private void writeUnpackInfo(final DataOutput header) throws IOException {
    header.write(NID.kUnpackInfo);

    header.write(NID.kFolder);
    writeUint64(header, numNonEmptyStreams);
    header.write(0);
    for (int i = 0; i < numNonEmptyStreams; i++) {
        writeFolder(header);
    }

    header.write(NID.kCodersUnpackSize);
    for (final SevenZArchiveEntry entry : files) {
        if (entry.hasStream()) {
            writeUint64(header, entry.getSize());
        }
    }

    header.write(NID.kCRC);
    header.write(1);
    for (final SevenZArchiveEntry entry : files) {
        if (entry.hasStream()) {
            header.writeInt(Integer.reverseBytes((int) entry.getCrcValue()));
        }
    }

    header.write(NID.kEnd);
}

public class BZip2CompressorInputStream extends CompressorInputStream implements
                                                                          BZip2Constants {

    /**
     * Index of the last char in the block, so the block size == last + 1.
     */
    private int last;

    /**
     * Index in zptr[] of original string after sorting.
     */
    private int origPtr;

    /**
     * always: in the range 0 .. 9. The current block size is 100000 * this
     * number.
     */
    private int blockSize100k;

    private boolean blockRandomised;

    private int bsBuff;
    private int bsLive;
    private final CRC crc = new CRC();

    private int nInUse;

    private InputStream in;
    private final boolean decompressConcatenated;

    private int currentChar = -1;
    private static final int EOF = 0;
    private static final int START_BLOCK_STATE = 1;
    private static final int RAND_PART_A_STATE = 2;
    private static final int RAND_PART_B_STATE = 3;
    private static final int RAND_PART_C_STATE = 4;
    private static final int NO_RAND_PART_A_STATE = 5;
    private static final int NO_RAND_PART_B_STATE = 6;
    private static final int NO_RAND_PART_C_STATE = 7;

    private int currentState = START_BLOCK_STATE;

    private int storedBlockCRC, storedCombinedCRC;
    private int computedBlockCRC, computedCombinedCRC;

    // Variables used by setup* methods exclusively

    private int su_count;
    private int su_ch2;
    private int su_chPrev;
    private int su_i2;
    private int su_j2;
    private int su_rNToGo;
    private int su_rTPos;
    private int su_tPos;
    private char su_z;

    /**
     * All memory intensive stuff. This field is initialized by initBlock().
     */
    private BZip2CompressorInputStream.Data data;

    /**
     * Constructs a new BZip2CompressorInputStream which decompresses bytes
     * read from the specified stream. This doesn't suppprt decompressing
     * concatenated .bz2 files.
     * 
     * @throws IOException
     *             if the stream content is malformed or an I/O error occurs.
     * @throws NullPointerException
     *             if <tt>in == null</tt>
     */
    public BZip2CompressorInputStream(final InputStream in) throws IOException {
        this(in, false);
    }

    /**
     * Constructs a new BZip2CompressorInputStream which decompresses bytes
     * read from the specified stream.
     *
     * @param in the InputStream from which this object should be created
     * @param decompressConcatenated
     *                     if true, decompress until the end of the input;
     *                     if false, stop after the first .bz2 stream and
     *                     leave the input position to point to the next
     *                     byte after the .bz2 stream
     *
     * @throws IOException
     *             if the stream content is malformed or an I/O error occurs.
     * @throws NullPointerException
     *             if <tt>in == null</tt>
     */
    public BZip2CompressorInputStream(final InputStream in, final boolean decompressConcatenated) throws IOException {
        this.in = in;
        this.decompressConcatenated = decompressConcatenated;

        init(true);
        initBlock();
        setupBlock();
    }

    @Override
    public int read() throws IOException {
        if (this.in != null) {
            int r = read0();
            count(r < 0 ? -1 : 1);
            return r;
        } else {
            throw new IOException("stream closed");
        }
    }

    /*
     * (non-Javadoc)
     * 
     * @see java.io.InputStream#read(byte[], int, int)
     */
    @Override
    public int read(final byte[] dest, final int offs, final int len)
        throws IOException {
        if (offs < 0) {
            throw new IndexOutOfBoundsException("offs(" + offs + ") < 0.");
        }
        if (len < 0) {
            throw new IndexOutOfBoundsException("len(" + len + ") < 0.");
        }
        if (offs + len > dest.length) {
            throw new IndexOutOfBoundsException("offs(" + offs + ") + len("
                                                + len + ") > dest.length(" + dest.length + ").");
        }
        if (this.in == null) {
            throw new IOException("stream closed");
        }

        final int hi = offs + len;
        int destOffs = offs;
        int b;
        while (destOffs < hi && ((b = read0()) >= 0)) {
            dest[destOffs++] = (byte) b;
            count(1);
        }

        int c = (destOffs == offs) ? -1 : (destOffs - offs);
        return c;
    }

    private void makeMaps() {
        final boolean[] inUse = this.data.inUse;
        final byte[] seqToUnseq = this.data.seqToUnseq;

        int nInUseShadow = 0;

        for (int i = 0; i < 256; i++) {
            if (inUse[i]) {
                seqToUnseq[nInUseShadow++] = (byte) i;
            }
        }

        this.nInUse = nInUseShadow;
    }

static InputStream addDecoder(final InputStream is,
        final Coder coder, final byte[] password) throws IOException {
    for (final CoderId coderId : coderTable) {
        if (Arrays.equals(coderId.method.getId(), coder.decompressionMethodId)) {
            return coderId.coder.decode(is, coder, password);
        }
    }
    throw new IOException("Unsupported compression method " +
            Arrays.toString(coder.decompressionMethodId));
}

static OutputStream addEncoder(final OutputStream out, final SevenZMethod method,
                               final byte[] password) throws IOException {
    for (final CoderId coderId : coderTable) {
        if (coderId.method.equals(method)) {
            return coderId.coder.encode(out, password);
        }
    }
    throw new IOException("Unsupported compression method " + method);
}

static CoderId[] coderTable = new CoderId[] {
    new CoderId(SevenZMethod.COPY, new CopyDecoder()),
    new CoderId(SevenZMethod.LZMA, new LZMADecoder()),
    new CoderId(SevenZMethod.LZMA2, new LZMA2Decoder()),
    new CoderId(SevenZMethod.DEFLATE, new DeflateDecoder()),
    new CoderId(SevenZMethod.BZIP2, new BZIP2Decoder()),
    new CoderId(SevenZMethod.AES256SHA256, new AES256SHA256Decoder())
};

static class CoderId {
    CoderId(SevenZMethod method, final CoderBase coder) {
        this.method = method;
        this.coder = coder;
    }

    final SevenZMethod method;
    final CoderBase coder;
}

static abstract class CoderBase {
    abstract InputStream decode(final InputStream in, final Coder coder,
            byte[] password) throws IOException;
    OutputStream encode(final OutputStream out, final byte[] password)
        throws IOException {
        throw new UnsupportedOperationException("method doesn't support writing");
    }
}

static class CopyDecoder extends CoderBase {
    @Override
    InputStream decode(final InputStream in, final Coder coder,
            byte[] password) throws IOException {
        return in; 
    }
    @Override
    OutputStream encode(final OutputStream out, final byte[] password) {
        return out;
    }
}

static class LZMADecoder extends CoderBase {
    @Override
    InputStream decode(final InputStream in, final Coder coder,
            byte[] password) throws IOException {
        byte propsByte = coder.properties[0];
        long dictSize = coder.properties[1];
        for (int i = 1; i < 4; i++) {
            dictSize |= (coder.properties[i + 1] << (8 * i));
        }
        if (dictSize > LZMAInputStream.DICT_SIZE_MAX) {
            throw new IOException("Dictionary larger than 4GiB maximum size");
        }
        return new LZMAInputStream(in, -1, propsByte, (int) dictSize);
    }
}

static class DeflateDecoder extends CoderBase {
    @Override
    InputStream decode(final InputStream in, final Coder coder, final byte[] password)
        throws IOException {
        return new InflaterInputStream(new DummyByteAddingInputStream(in),
                                       new Inflater(true));
    }
    @Override
    OutputStream encode(final OutputStream out, final byte[] password) {
        return new DeflaterOutputStream(out, new Deflater(9, true));
    }
}

static class BZIP2Decoder extends CoderBase {
    @Override
    InputStream decode(final InputStream in, final Coder coder, final byte[] password)
            throws IOException {
        return new BZip2CompressorInputStream(in);
    }
    @Override
    OutputStream encode(final OutputStream out, final byte[] password)
            throws IOException {
        return new BZip2CompressorOutputStream(out);
    }
}

static class AES256SHA256Decoder extends CoderBase {
    @Override
    InputStream decode(final InputStream in, final Coder coder,
            final byte[] passwordBytes) throws IOException {
        return new InputStream() {
            private boolean isInitialized = false;
            private CipherInputStream cipherInputStream = null;

            private CipherInputStream init() throws IOException {
                if (isInitialized) {
                    return cipherInputStream;
                }
                final int byte0 = 0xff & coder.properties[0];
                final int numCyclesPower = byte0 & 0x3f;
                final int byte1 = 0xff & coder.properties[1];
                final int ivSize = ((byte0 >> 6) & 1) + (byte1 & 0x0f);
                final int saltSize = ((byte0 >> 7) & 1) + (byte1 >> 4);
                if (2 + saltSize + ivSize > coder.properties.length) {
                    throw new IOException("Salt size + IV size too long");
                }
                final byte[] salt = new byte[saltSize];
                System.arraycopy(coder.properties, 2, salt, 0, saltSize);
                final byte[] iv = new byte[16];
                System.arraycopy(coder.properties, 2 + saltSize, iv, 0, ivSize);

                if (passwordBytes == null) {
                    throw new IOException("Cannot read encrypted files without a password");
                }
                final byte[] aesKeyBytes;
                if (numCyclesPower == 0x3f) {
                    aesKeyBytes = new byte[32];
                    System.arraycopy(salt, 0, aesKeyBytes, 0, saltSize);
                    System.arraycopy(passwordBytes, 0, aesKeyBytes, saltSize,
                            Math.min(passwordBytes.length, aesKeyBytes.length - saltSize));
                } else {
                    final MessageDigest digest;
                    try {
                        digest = MessageDigest.getInstance("SHA-256");
                    } catch (NoSuchAlgorithmException noSuchAlgorithmException) {
                        IOException ioe = new IOException("SHA-256 is unsupported by your Java implementation");
                        ioe.initCause(noSuchAlgorithmException);
                        throw ioe;
        // TODO: simplify when Compress requires Java 1.6                
//                            throw new IOException("SHA-256 is unsupported by your Java implementation",
//                                    noSuchAlgorithmException);
                    }
                    final byte[] extra = new byte[8];
                    for (long j = 0; j < (1L << numCyclesPower); j++) {
                        digest.update(salt);
                        digest.update(passwordBytes);
                        digest.update(extra);
                        for (int k = 0; k < extra.length; k++) {
                            ++extra[k];
                            if (extra[k] != 0) {
                                break;
                            }
                        }
                    }
                    aesKeyBytes = digest.digest();
                }

                final SecretKey aesKey = new SecretKeySpec(aesKeyBytes, "AES");
                try {
                    final Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
                    cipher.init(Cipher.DECRYPT_MODE, aesKey, new IvParameterSpec(iv));
                    cipherInputStream = new CipherInputStream(in, cipher);
                    isInitialized = true;
                    return cipherInputStream;
                } catch (GeneralSecurityException generalSecurityException) {
                    IOException ioe = new IOException("Decryption error " +
                            "(do you have the JCE Unlimited Strength Jurisdiction Policy Files installed?)");
                    ioe.initCause(generalSecurityException);
                    throw ioe;
        // TODO: simplify when Compress requires Java 1.6                
//                        throw new IOException("Decryption error " +
//                                "(do you have the JCE Unlimited Strength Jurisdiction Policy Files installed?)",
//                                generalSecurityException);
                }
            }

            @Override
            public int read() throws IOException {
                return init().read();
            }

            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                return init().read(b, off, len);
            }

            @Override
            public void close() {
            }
        };
    }
}

/**
 * ZLIB requires an extra dummy byte.
 *
 * @see java.util.zip.Inflater#Inflater(boolean)
 * @see org.apache.commons.compress.archivers.zip.ZipFile.BoundedInputStream
 */
private static class DummyByteAddingInputStream extends FilterInputStream {
    private boolean addDummyByte = true;

    private DummyByteAddingInputStream(InputStream in) {
        super(in);
    }

    @Override
    public int read() throws IOException {
        int result = super.read();
        if (result == -1 && addDummyByte) {
            addDummyByte = false;
            result = 0;
        }
        return result;
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        int result = super.read(b, off, len);
        if (result == -1 && addDummyByte) {
            addDummyByte = false;
            b[off] = 0;
            return 1;
        }
        return result;
    }
}
