public class X7875_NewUnix implements ZipExtraField, Cloneable, Serializable {
    private static final ZipShort HEADER_ID = new ZipShort(0x7875);
    private static final BigInteger ONE_THOUSAND = BigInteger.valueOf(1000);
    private static final long serialVersionUID = 1L;

    private int version = 1; // always '1' according to current info-zip spec.

    // BigInteger helps us with little-endian / big-endian conversions.
    // (thanks to BigInteger.toByteArray() and a reverse() method we created).
    // Also, the spec theoretically allows UID/GID up to 255 bytes long!
    //
    // NOTE:  equals() and hashCode() currently assume these can never be null.
    private BigInteger uid;
    private BigInteger gid;

    /**
     * Constructor for X7875_NewUnix.
     */
    public X7875_NewUnix() {
        reset();
    }

public static boolean verifyCheckSum(byte[] header) {
    long storedSum = 0;
    long unsignedSum = 0;
    long signedSum = 0;

    int digits = 0;
    for (int i = 0; i < header.length; i++) {
        byte b = header[i];
        if (CHKSUM_OFFSET <= i && i < CHKSUM_OFFSET + CHKSUMLEN) {
            if ('0' <= b && b <= '7' && digits++ < 6) {
                storedSum = storedSum * 8 + b - '0';
            } else if (digits > 0) {
                digits = 6;
            }
            b = ' ';
        }
        unsignedSum += 0xff & b;
        signedSum += b;
    }
    return storedSum == unsignedSum || storedSum == signedSum;
}

private Archive readHeaders(final byte[] password) throws IOException {
    final byte[] signature = new byte[6];
    file.readFully(signature);
    if (!Arrays.equals(signature, sevenZSignature)) {
        throw new IOException("Bad 7z signature");
    }
    // 7zFormat.txt has it wrong - it's first major then minor
    final byte archiveVersionMajor = file.readByte();
    final byte archiveVersionMinor = file.readByte();
    if (archiveVersionMajor != 0) {
        throw new IOException(String.format("Unsupported 7z version (%d,%d)",
                archiveVersionMajor, archiveVersionMinor));
    }

    final long startHeaderCrc = 0xffffFFFFL & Integer.reverseBytes(file.readInt());
    final StartHeader startHeader = readStartHeader(startHeaderCrc);

    final int nextHeaderSizeInt = (int) startHeader.nextHeaderSize;
    if (nextHeaderSizeInt != startHeader.nextHeaderSize) {
        throw new IOException("cannot handle nextHeaderSize " + startHeader.nextHeaderSize);
    }
    file.seek(SIGNATURE_HEADER_SIZE + startHeader.nextHeaderOffset);
    final byte[] nextHeader = new byte[nextHeaderSizeInt];
    file.readFully(nextHeader);
    final CRC32 crc = new CRC32();
    crc.update(nextHeader);
    if (startHeader.nextHeaderCrc != crc.getValue()) {
        throw new IOException("NextHeader CRC mismatch");
    }

    final ByteArrayInputStream byteStream = new ByteArrayInputStream(nextHeader);
    DataInputStream nextHeaderInputStream = new DataInputStream(
            byteStream);
    Archive archive = new Archive();
    int nid = nextHeaderInputStream.readUnsignedByte();
    if (nid == NID.kEncodedHeader) {
        nextHeaderInputStream =
            readEncodedHeader(nextHeaderInputStream, archive, password);
        // Archive gets rebuilt with the new header
        archive = new Archive();
        nid = nextHeaderInputStream.readUnsignedByte();
    }
    if (nid == NID.kHeader) {
        readHeader(nextHeaderInputStream, archive);
        nextHeaderInputStream.close();
    } else {
        throw new IOException("Broken or unsupported archive: no Header");
    }
    return archive;
}

/**
 * Skips over and discards <code>n</code> bytes of data from this input
 * stream. The <code>skip</code> method may, for a variety of reasons, end
 * up skipping over some smaller number of bytes, possibly <code>0</code>.
 * This may result from any of a number of conditions; reaching end of file
 * or end of entry before <code>n</code> bytes have been skipped; are only
 * two possibilities. The actual number of bytes skipped is returned. If
 * <code>n</code> is negative, no bytes are skipped.
 * 
 * 
 * @param n
 *            the number of bytes to be skipped.
 * @return the actual number of bytes skipped.
 * @exception IOException
 *                if some other I/O error occurs.
 */
@Override
public long skip(final long n) throws IOException {
    if (n <= 0 || isDirectory()) {
        return 0;
    }

    final long available = entrySize - entryOffset;
    final long skipped = is.skip(Math.min(n, available)); 
    count(skipped);
    entryOffset += skipped;
    return skipped;
}

/**
 * Get the next entry in this tar archive as longname data.
 *
 * @return The next entry in the archive as longname data, or null.
 * @throws IOException on error
 */
protected byte[] getLongNameData() throws IOException {
    // read in the name
    final ByteArrayOutputStream longName = new ByteArrayOutputStream();
    int length = 0;
    while ((length = read(SMALL_BUF)) >= 0) {
        longName.write(SMALL_BUF, 0, length);
    }
    getNextEntry();
    if (currEntry == null) {
        // Bugzilla: 40334
        // Malformed tar file - long entry name not followed by entry
        return null;
    }
    byte[] longNameData = longName.toByteArray();
    // remove trailing null terminator(s)
    length = longNameData.length;
    while (length > 0 && longNameData[length - 1] == 0) {
        --length;
    }
    if (length != longNameData.length) {
        final byte[] l = new byte[length];
        System.arraycopy(longNameData, 0, l, 0, length);
        longNameData = l;
    }
    return longNameData;
}

/**
 * Read a record from the input stream and return the data.
 *
 * @return The record data or null if EOF has been hit.
 * @throws IOException on error
 */
protected byte[] readRecord() throws IOException {

    final byte[] record = new byte[recordSize];

    final int readNow = IOUtils.readFully(is, record);
    count(readNow);
    if (readNow != recordSize) {
        return null;
    }

    return record;
}

public boolean isDirectory() {
    if (file != null) {
        return file.isDirectory();
    }

    if (linkFlag == LF_DIR) {
        return true;
    }

    if (getName().endsWith("/")) {
        return true;
    }

    return false;
}

public class ArchiveUtils {
    // Constructor remains private to prevent instantiation
}

public static String sanitize(String s) {
    final char[] chars = s.toCharArray();
    final int len = chars.length;
    final StringBuilder sb = new StringBuilder();
    for (int i = 0; i < len; i++) {
        final char c = chars[i];
        if (!Character.isISOControl(c)) {
            Character.UnicodeBlock block = Character.UnicodeBlock.of(c);
            if (block != null && block != Character.UnicodeBlock.SPECIALS) {
                sb.append(c);
                continue;
            }
        }
        sb.append('?');
    }
    return sb.toString();
}

public long readBits(final int count) throws IOException {
    if (count < 0 || count > MAXIMUM_CACHE_SIZE) {
        throw new IllegalArgumentException("count must not be negative or greater than " + MAXIMUM_CACHE_SIZE);
    }
    while (bitsCachedSize < count) {
        final int nextByte = in.read();
        if (nextByte < 0) {
            return nextByte;
        }
        if (byteOrder == ByteOrder.LITTLE_ENDIAN) {
            bitsCached |= (nextByte << bitsCachedSize);
        } else {
            bitsCached <<= 8;
            bitsCached |= nextByte;
        }
        bitsCachedSize += 8;
    }
    final long bitsOut;
    if (byteOrder == ByteOrder.LITTLE_ENDIAN) {
        bitsOut = (bitsCached & MASKS[count]);
        bitsCached >>>= count;
    } else {
        bitsOut = (bitsCached >> (bitsCachedSize - count)) & MASKS[count];
    }
    bitsCachedSize -= count;
    return bitsOut;
}

private void readFirstLocalFileHeader(final byte[] lfh) throws IOException {
    readFully(lfh);
    final ZipLong sig = new ZipLong(lfh);
    if (sig.equals(ZipLong.DD_SIG)) {
        throw new UnsupportedZipFeatureException(UnsupportedZipFeatureException.Feature.SPLITTING);
    }

    if (sig.equals(ZipLong.SINGLE_SEGMENT_SPLIT_MARKER)) {
        // The archive is not really split as only one segment was
        // needed in the end.  Just skip over the marker.
        final byte[] missedLfhBytes = new byte[4];
        readFully(missedLfhBytes);
        System.arraycopy(lfh, 4, lfh, 0, LFH_LEN - 4);
        System.arraycopy(missedLfhBytes, 0, lfh, LFH_LEN - 4, 4);
    }

    if (!sig.equals(ZipLong.LFH_SIG)) {
        throw new ZipException("Invalid signature: " + sig);
    }
}

private void readFully(final byte[] b) throws IOException {
    final int count = IOUtils.readFully(in, b);
    count(count);
    if (count < b.length) {
        throw new EOFException("Premature end of archive");
    }
}

private void closeEntry() throws IOException {
    if (closed) {
        throw new IOException("The stream is closed");
    }
    if (current == null) {
        return;
    }

    // Ensure all entry bytes are read
    if (currentEntryHasOutstandingBytes()) {
        drainCurrentEntryData();
    } else {
        skip(Long.MAX_VALUE);

        final long inB = current.entry.getMethod() == ZipArchiveOutputStream.DEFLATED
                ? getBytesInflated() : current.bytesRead;

        // this is at most a single read() operation and can't
        // exceed the range of int
        final int diff = (int) (current.bytesReadFromStream - inB);

        // Pushback any required bytes
        if (diff > 0) {
            pushback(buf.array(), buf.limit() - diff, diff);
            current.bytesReadFromStream -= diff;
        }

        // Drain remainder of entry if not all data bytes were required
        if (currentEntryHasOutstandingBytes()) {
            drainCurrentEntryData();
        }
    }

    if (lastStoredEntry == null && current.hasDataDescriptor) {
        readDataDescriptor();
    }

    inf.reset();
    buf.clear().flip();
    current = null;
    lastStoredEntry = null;
}

private void skipRemainderOfArchive() throws IOException {
    // skip over central directory. One LFH has been read too much
    // already.  The calculation discounts file names and extra
    // data so it will be too short.
    realSkip(entriesRead * CFH_LEN - LFH_LEN);
    findEocdRecord();
    realSkip(ZipFile.MIN_EOCD_SIZE - WORD /* signature */ - SHORT /* comment len */);
    readFully(SHORT_BUF);
    // file comment
    realSkip(ZipShort.getValue(SHORT_BUF));
}

private void findEocdRecord() throws IOException {
    int currentByte = -1;
    boolean skipReadCall = false;
    while (skipReadCall || (currentByte = readOneByte()) > -1) {
        skipReadCall = false;
        if (!isFirstByteOfEocdSig(currentByte)) {
            continue;
        }
        currentByte = readOneByte();
        if (currentByte != ZipArchiveOutputStream.EOCD_SIG[1]) {
            if (currentByte == -1) {
                break;
            }
            skipReadCall = isFirstByteOfEocdSig(currentByte);
            continue;
        }
        currentByte = readOneByte();
        if (currentByte != ZipArchiveOutputStream.EOCD_SIG[2]) {
            if (currentByte == -1) {
                break;
            }
            skipReadCall = isFirstByteOfEocdSig(currentByte);
            continue;
        }
        currentByte = readOneByte();
        if (currentByte == -1
                || currentByte == ZipArchiveOutputStream.EOCD_SIG[3]) {
            break;
        }
        skipReadCall = isFirstByteOfEocdSig(currentByte);
    }
}

private boolean isFirstByteOfEocdSig(final int b) {
    return b == ZipArchiveOutputStream.EOCD_SIG[0];
}

private void readDataDescriptor() throws IOException {
    readFully(WORD_BUF);
    ZipLong val = new ZipLong(WORD_BUF);
    if (ZipLong.DD_SIG.equals(val)) {
        // data descriptor with signature, skip sig
        readFully(WORD_BUF);
        val = new ZipLong(WORD_BUF);
    }
    current.entry.setCrc(val.getValue());

    // if there is a ZIP64 extra field, sizes are eight bytes
    // each, otherwise four bytes each.  Unfortunately some
    // implementations - namely Java7 - use eight bytes without
    // using a ZIP64 extra field -
    // http://bugs.sun.com/bugdatabase/view_bug.do?bug_id=7073588

    // just read 16 bytes and check whether bytes nine to twelve
    // look like one of the signatures of what could follow a data
    // descriptor (ignoring archive decryption headers for now).
    // If so, push back eight bytes and assume sizes are four
    // bytes, otherwise sizes are eight bytes each.
    readFully(TWO_DWORD_BUF);
    final ZipLong potentialSig = new ZipLong(TWO_DWORD_BUF, DWORD);
    if (potentialSig.equals(ZipLong.CFH_SIG) || potentialSig.equals(ZipLong.LFH_SIG)) {
        pushback(TWO_DWORD_BUF, DWORD, DWORD);
        current.entry.setCompressedSize(ZipLong.getValue(TWO_DWORD_BUF));
        current.entry.setSize(ZipLong.getValue(TWO_DWORD_BUF, WORD));
    } else {
        current.entry.setCompressedSize(ZipEightByteInteger.getLongValue(TWO_DWORD_BUF));
        current.entry.setSize(ZipEightByteInteger.getLongValue(TWO_DWORD_BUF, DWORD));
    }
}

private void readStoredEntry() throws IOException {
    final ByteArrayOutputStream bos = new ByteArrayOutputStream();
    int off = 0;
    boolean done = false;

    // length of DD without signature
    final int ddLen = current.usesZip64 ? WORD + 2 * DWORD : 3 * WORD;

    while (!done) {
        final int r = in.read(buf.array(), off, ZipArchiveOutputStream.BUFFER_SIZE - off);
        if (r <= 0) {
            // read the whole archive without ever finding a
            // central directory
            throw new IOException("Truncated ZIP file");
        }
        if (r + off < 4) {
            // buffer too small to check for a signature, loop
            off += r;
            continue;
        }

        done = bufferContainsSignature(bos, off, r, ddLen);
        if (!done) {
            off = cacheBytesRead(bos, off, r, ddLen);
        }
    }

    final byte[] b = bos.toByteArray();
    lastStoredEntry = new ByteArrayInputStream(b);
}

