public static long parseOctal(final byte[] buffer, final int offset, final int length) {
    long    result = 0;
    int     end = offset + length;
    int     start = offset;

    if (length < 2){
        throw new IllegalArgumentException("Length "+length+" must be at least 2");
    }

    if (buffer[start] == 0) {
        return 0L;
    }

    // Skip leading spaces
    while (start < end){
        if (buffer[start] == ' '){
            start++;
        } else {
            break;
        }
    }

    // Trim all trailing NULs and spaces.
    // The ustar and POSIX tar specs require a trailing NUL or
    // space but some implementations use the extra digit for big
    // sizes/uids/gids ...
    byte trailer = buffer[end - 1];
    while (start < end && (trailer == 0 || trailer == ' ')) {
        end--;
        trailer = buffer[end - 1];
    }

    for ( ;start < end; start++) {
        final byte currentByte = buffer[start];
        // CheckStyle:MagicNumber OFF
        if (currentByte < '0' || currentByte > '7'){
            throw new IllegalArgumentException(
                    exceptionMessage(buffer, offset, length, start, currentByte));
        }
        result = (result << 3) + (currentByte - '0'); // convert from ASCII
        // CheckStyle:MagicNumber ON
    }

    return result;
}

public static long parseOctalOrBinary(final byte[] buffer, final int offset,
                                      final int length) {

    if ((buffer[offset] & 0x80) == 0) {
        return parseOctal(buffer, offset, length);
    }
    final boolean negative = buffer[offset] == (byte) 0xff;
    if (length < 9) {
        return parseBinaryLong(buffer, offset, length, negative);
    }
    return parseBinaryBigInteger(buffer, offset, length, negative);
}

private static long parseBinaryLong(final byte[] buffer, final int offset,
                                    final int length,
                                    final boolean negative) {
    if (length >= 9) {
        throw new IllegalArgumentException("At offset " + offset + ", "
                                           + length + " byte binary number"
                                           + " exceeds maximum signed long"
                                           + " value");
    }
    long val = 0;
    for (int i = 1; i < length; i++) {
        val = (val << 8) + (buffer[offset + i] & 0xff);
    }
    if (negative) {
        // 2's complement
        val--;
        val ^= (long) Math.pow(2.0, (length - 1) * 8.0) - 1;
    }
    return negative ? -val : val;
}

private static long parseBinaryBigInteger(final byte[] buffer,
                                          final int offset,
                                          final int length,
                                          final boolean negative) {
    final byte[] remainder = new byte[length - 1];
    System.arraycopy(buffer, offset + 1, remainder, 0, length - 1);
    BigInteger val = new BigInteger(remainder);
    if (negative) {
        // 2's complement
        val = val.add(BigInteger.valueOf(-1)).not();
    }
    if (val.bitLength() > 63) {
        throw new IllegalArgumentException("At offset " + offset + ", "
                                           + length + " byte binary number"
                                           + " exceeds maximum signed long"
                                           + " value");
    }
    return negative ? -val.longValue() : val.longValue();
}

public static boolean parseBoolean(final byte[] buffer, final int offset) {
    return buffer[offset] == 1;
}

public static String parseName(final byte[] buffer, final int offset, final int length) {
    try {
        return parseName(buffer, offset, length, DEFAULT_ENCODING);
    } catch (final IOException ex) {
        try {
            return parseName(buffer, offset, length, FALLBACK_ENCODING);
        } catch (final IOException ex2) {
            // impossible
            throw new RuntimeException(ex2); //NOSONAR
        }
    }
}

public static String parseName(final byte[] buffer, final int offset,
                               final int length,
                               final ZipEncoding encoding)
    throws IOException {

    int len = length;
    for (; len > 0; len--) {
        if (buffer[offset + len - 1] != 0) {
            break;
        }
    }
    if (len > 0) {
        final byte[] b = new byte[len];
        System.arraycopy(buffer, offset, b, 0, len);
        return encoding.decode(b);
    }
    return "";
}

public static int formatNameBytes(final String name, final byte[] buf, final int offset, final int length) {
    try {
        return formatNameBytes(name, buf, offset, length, DEFAULT_ENCODING);
    } catch (final IOException ex) {
        try {
            return formatNameBytes(name, buf, offset, length,
                                   FALLBACK_ENCODING);
        } catch (final IOException ex2) {
            // impossible
            throw new RuntimeException(ex2); //NOSONAR
        }
    }
}

public static int formatNameBytes(final String name, final byte[] buf, final int offset,
                                  final int length,
                                  final ZipEncoding encoding)
    throws IOException {
    int len = name.length();
    ByteBuffer b = encoding.encode(name);
    while (b.limit() > length && len > 0) {
        b = encoding.encode(name.substring(0, --len));
    }
    final int limit = b.limit() - b.position();
    System.arraycopy(b.array(), b.arrayOffset(), buf, offset, limit);

    // Pad any remaining output bytes with NUL
    for (int i = limit; i < length; ++i) {
        buf[offset + i] = 0;
    }

    return offset + length;
}

public static void formatUnsignedOctalString(final long value, final byte[] buffer,
        final int offset, final int length) {
    int remaining = length;
    remaining--;
    if (value == 0) {
        buffer[offset + remaining--] = (byte) '0';
    } else {
        long val = value;
        for (; remaining >= 0 && val != 0; --remaining) {
            // CheckStyle:MagicNumber OFF
            buffer[offset + remaining] = (byte) ((byte) '0' + (byte) (val & 7));
            val = val >>> 3;
            // CheckStyle:MagicNumber ON
        }
        if (val != 0){
            throw new IllegalArgumentException
            (value+"="+Long.toOctalString(value)+ " will not fit in octal number buffer of length "+length);
        }
    }

    for (; remaining >= 0; --remaining) { // leading zeros
        buffer[offset + remaining] = (byte) '0';
    }
}

public static int formatOctalBytes(final long value, final byte[] buf, final int offset, final int length) {

    int idx=length-2; // For space and trailing null
    formatUnsignedOctalString(value, buf, offset, idx);

    buf[offset + idx++] = (byte) ' '; // Trailing space
    buf[offset + idx]   = 0; // Trailing null

    return offset + length;
}

public static int formatLongOctalBytes(final long value, final byte[] buf, final int offset, final int length) {

    final int idx=length-1; // For space

    formatUnsignedOctalString(value, buf, offset, idx);
    buf[offset + idx] = (byte) ' '; // Trailing space

    return offset + length;
}

public static int formatLongOctalOrBinaryBytes(
    final long value, final byte[] buf, final int offset, final int length) {

    // Check whether we are dealing with UID/GID or SIZE field
    final long maxAsOctalChar = length == TarConstants.UIDLEN ? TarConstants.MAXID : TarConstants.MAXSIZE;

    final boolean negative = value < 0;
    if (!negative && value <= maxAsOctalChar) { // OK to store as octal chars
        return formatLongOctalBytes(value, buf, offset, length);
    }

    if (length < 9) {
        formatLongBinary(value, buf, offset, length, negative);
    }
    formatBigIntegerBinary(value, buf, offset, length, negative);

    buf[offset] = (byte) (negative ? 0xff : 0x80);
    return offset + length;
}

private static ZipLong unixTimeToZipLong(long l) {
    final long TWO_TO_32 = 0x100000000L;
    if (l >= TWO_TO_32) {
        throw new IllegalArgumentException("X5455 timestamps must fit in a signed 32 bit integer: " + l);
    }
    return new ZipLong((int) l);
}

public boolean canReadEntryData(final ArchiveEntry ae) {
    if (ae instanceof ZipArchiveEntry) {
        final ZipArchiveEntry ze = (ZipArchiveEntry) ae;
        return ZipUtil.canHandleEntryData(ze)
            && supportsDataDescriptorFor(ze);
    }
    return false;
}

public int read() throws IOException {
    int current = super.read();
    if (current == '\n') {
        lineCounter++;
    }
    lastChar = current;
    return lastChar;
}

public int read(char[] buf, int offset, int length) throws IOException {
    if (length == 0) {
        return 0;
    }

    int len = super.read(buf, offset, length);

    if (len > 0) {
        for (int i = offset; i < offset + len; i++) {
            char ch = buf[i];
            if (ch == '\n') {
                if ('\r' != (i > 0 ? buf[i-1]: lastChar)) {
                    lineCounter++;                        
                }
            } else if (ch == '\r') {
                lineCounter++;
            }
        }

        lastChar = buf[offset + len - 1];

    } else if (len == -1) {
        lastChar = END_OF_STREAM;
    }

    return len;
}

public String readLine() throws IOException {
    String line = super.readLine();

    if (line != null) {
        if (line.length() > 0) {
            lastChar = line.charAt(line.length() - 1);
        }
        lineCounter++;
    } else {
        lastChar = END_OF_STREAM;
    }

    return line;
}

public int lookAhead() throws IOException {
    super.mark(1);
    int c = super.read();
    super.reset();

    return c;
}

public String get(final String name) {
    if (mapping == null) {
        throw new IllegalStateException(
                "No header mapping was specified, the record values can't be accessed by name");
    }
    final Integer index = mapping.get(name);
    if (index == null) {
        throw new IllegalArgumentException("No value for the header: " + name);
    }
    return values[index.intValue()];
}

int readEscape() throws IOException {
    // the escape char has just been read (normally a backslash)
    final int c = in.read();
    switch (c) {
    case 'r':
        return CR;
    case 'n':
        return LF;
    case 't':
        return TAB;
    case 'b':
        return BACKSPACE;
    case 'f':
        return FF;
    case CR:
    case LF:
    case FF: // TODO is this correct?
    case TAB: // TODO is this correct? Do tabs need to be escaped?
    case BACKSPACE: // TODO is this correct?
        return c;
    case END_OF_STREAM:
        throw new IOException("EOF whilst processing escape sequence");
    default:
        // Now check for meta-characters
        return c;
        // indicate unexpected char - available from in.getLastChar()
    }
}

public CSVParser(final Reader reader, final CSVFormat format) throws IOException {
    Assertions.notNull(reader, "reader");
    Assertions.notNull(format, "format");

    format.validate();
    this.format = format;
    this.lexer = new Lexer(format, new ExtendedBufferedReader(reader));
    this.headerMap = this.initializeHeader();
}

private void addRecordValue() {
    final String input = this.reusableToken.content.toString();
    final String nullString = this.format.getNullString();
    if (nullString == null) {
        this.record.add(input);
    } else {
        this.record.add(input.equalsIgnoreCase(nullString) ? null : input);
    }
}

public void close() throws IOException {
    if (this.lexer != null) {
        this.lexer.close();
    }
}

public Map<String, Integer> getHeaderMap() {
    return new LinkedHashMap<String, Integer>(this.headerMap);
}

public List<CSVRecord> getRecords() throws IOException {
    final List<CSVRecord> records = new ArrayList<CSVRecord>();
    CSVRecord rec;
    while ((rec = this.nextRecord()) != null) {
        records.add(rec);
    }
    return records;
}

private Map<String, Integer> initializeHeader() throws IOException {
    Map<String, Integer> hdrMap = null;
    final String[] formatHeader = this.format.getHeader();
    if (formatHeader != null) {
        hdrMap = new LinkedHashMap<String, Integer>();

        String[] header = null;
        if (formatHeader.length == 0) {
            // read the header from the first line of the file
            final CSVRecord record = this.nextRecord();
            if (record != null) {
                header = record.values();
            }
        } else {
            if (this.format.getSkipHeaderRecord()) {
                this.nextRecord();
            }
            header = formatHeader;
        }

        // build the name to index mappings
        if (header != null) {
            for (int i = 0; i < header.length; i++) {
                hdrMap.put(header[i], Integer.valueOf(i));
            }
        }
    }
    return hdrMap;
}

public Iterator<CSVRecord> iterator() {
    return new Iterator<CSVRecord>() {
        private CSVRecord current;

        private CSVRecord getNextRecord() {
            try {
                return CSVParser.this.nextRecord();
            } catch (final IOException e) {
                // TODO: This is not great, throw an ISE instead?
                throw new RuntimeException(e);
            }
        }

        public boolean hasNext() {
            if (CSVParser.this.isClosed()) {
                return false;
            }
            if (this.current == null) {
                this.current = this.getNextRecord();
            }

            return this.current != null;
        }

        public CSVRecord next() {
            if (CSVParser.this.isClosed()) {
                throw new NoSuchElementException("CSVParser has been closed");
            }
            CSVRecord next = this.current;
            this.current = null;

            if (next == null) {
                // hasNext() wasn't called before
                next = this.getNextRecord();
                if (next == null) {
                    throw new NoSuchElementException("No more CSV records available");
                }
            }

            return next;
        }

        public void remove() {
            throw new UnsupportedOperationException();
        }
    };
}

public CSVRecord nextRecord() throws IOException {
    CSVRecord result = null;
    this.record.clear();
    StringBuilder sb = null;
    do {
        this.reusableToken.reset();
        this.lexer.nextToken(this.reusableToken);
        switch (this.reusableToken.type) {
        case TOKEN:
            this.addRecordValue();
            break;
        case EORECORD:
            this.addRecordValue();
            break;
        case EOF:
            if (this.reusableToken.isReady) {
                this.addRecordValue();
            }
            break;
        case INVALID:
            throw new IOException("(line " + this.getCurrentLineNumber() + ") invalid parse sequence");
        case COMMENT: // Ignored currently
            if (sb == null) { // first comment for this record
                sb = new StringBuilder();
            } else {
                sb.append(Constants.LF);
            }
            sb.append(this.reusableToken.content);
            this.reusableToken.type = TOKEN; // Read another token
            break;
        }
    } while (this.reusableToken.type == TOKEN);

    if (!this.record.isEmpty()) {
        this.recordNumber++;
        final String comment = sb == null ? null : sb.toString();
        result = new CSVRecord(this.record.toArray(new String[this.record.size()]), this.headerMap, comment,
                this.recordNumber);
    }
    return result;
}

public void printAndEscape(final CharSequence value, final int offset, final int len) throws IOException {
    int start = offset;
    int pos = offset;
    final int end = offset + len;

    final char delim = format.getDelimiter();
    final char escape = format.getEscape().charValue();

    while (pos < end) {
        char c = value.charAt(pos);
        if (c == CR || c == LF || c == delim || c == escape) {
            if (pos > start) {
                out.append(value, start, pos);
            }
            if (c == LF) {
                c = 'n';
            } else if (c == CR) {
                c = 'r';
            }
            out.append(escape);
            out.append(c);
            start = pos + 1;
        }
        pos++;
    }
    if (pos > start) {
        out.append(value, start, pos);
    }
}

public void printAndQuote(final Object object, final CharSequence value,
        final int offset, final int len) throws IOException {
    boolean quote = false;
    int start = offset;
    int pos = offset;
    final int end = offset + len;

    final char delimChar = format.getDelimiter();
    final char quoteChar = format.getQuoteChar().charValue();

    Quote quotePolicy = format.getQuotePolicy();
    if (quotePolicy == null) {
        quotePolicy = Quote.MINIMAL;
    }
    switch (quotePolicy) {
    case ALL:
        quote = true;
        break;
    case NON_NUMERIC:
        quote = !(object instanceof Number);
        break;
    case NONE:
        printAndEscape(value, offset, len);
        return;
    case MINIMAL:
        if (len <= 0) {
            if (newRecord) {
                quote = true;
            }
        } else {
            char c = value.charAt(pos);
            if (newRecord && (c < '0' || (c > '9' && c < 'A') || (c > 'Z' && c < 'a') || (c > 'z'))) {
                quote = true;
            } else if (c <= COMMENT) {
                quote = true;
            } else {
                while (pos < end) {
                    c = value.charAt(pos);
                    if (c == LF || c == CR || c == quoteChar || c == delimChar) {
                        quote = true;
                        break;
                    }
                    pos++;
                }
                if (!quote) {
                    pos = end - 1;
                    c = value.charAt(pos);
                    if (c <= SP) {
                        quote = true;
                    }
                }
            }
        }
        if (!quote) {
            out.append(value, start, end);
            return;
        }
        break;
    }
    if (!quote) {
        out.append(value, start, end);
        return;
    }
    out.append(quoteChar);
    while (pos < end) {
        final char c = value.charAt(pos);
        if (c == quoteChar) {
            out.append(value, start, pos + 1);
            start = pos;
        }
        pos++;
    }
    out.append(value, start, pos);
    out.append(quoteChar);
}

/**
 * Returns a value by index.
 *
 * @param i
 *            a column index (0-based)
 * @return the String at the given index
 */
public String get(final int i) {
    if (i < 0 || i >= values.length) {
        throw new IndexOutOfBoundsException("Index " + i + " is out of bounds for record with " + values.length + " values");
    }
    return values[i];
}

/**
 * Returns a value by name.
 *
 * @param name
 *            the name of the column to be retrieved.
 * @return the column value, maybe null depending on {@link CSVFormat#getNullString()}.
 * @throws IllegalStateException
 *             if no header mapping was provided
 * @throws IllegalArgumentException
 *             if {@code name} is not mapped or if the record is inconsistent
 * @see #isConsistent()
 * @see CSVFormat#withNullString(String)
 */
public String get(final String name) {
    if (mapping == null) {
        throw new IllegalStateException(
                "No header mapping was specified, the record values can't be accessed by name");
    }
    final Integer index = mapping.get(name);
    if (index == null) {
        throw new IllegalArgumentException(String.format("Mapping for %s not found, expected one of %s", name,
                mapping.keySet()));
    }
    try {
        return values[index.intValue()];
    } catch (final ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException(String.format(
                "Index for header '%s' is %d but CSVRecord only has %d values!", name, index,
                Integer.valueOf(values.length)));
    }
}

private void addRecordValue() {
    final String input = this.reusableToken.content.toString();
    final String nullString = this.format.getNullString();
    if (nullString == null) {
        this.record.add(input);
    } else {
        this.record.add(input.equalsIgnoreCase(nullString) ? null : input);
    }
}

