private void addRecordValue(final boolean lastRecord) {
    final String input = this.reusableToken.content.toString();
    final String inputClean = this.format.getTrim() ? input.trim() : input;
    if (lastRecord && inputClean.isEmpty() && this.format.getTrailingDelimiter()) {
        return;
    }
    final String nullString = this.format.getNullString();
    this.recordList.add(inputClean.equals(nullString) ? null : inputClean);
}

CSVRecord nextRecord() throws IOException {
    CSVRecord result = null;
    this.recordList.clear();
    StringBuilder sb = null;
    final long startCharPosition = lexer.getCharacterPosition() + this.characterOffset;
    do {
        this.reusableToken.reset();
        this.lexer.nextToken(this.reusableToken);
        switch (this.reusableToken.type) {
        case TOKEN:
            this.addRecordValue(false);
            break;
        case EORECORD:
            this.addRecordValue(true);
            break;
        case EOF:
            if (this.reusableToken.isReady) {
                this.addRecordValue(true);
            }
            break;
        case INVALID:
            throw new IOException("(line " + this.getCurrentLineNumber() + ") invalid parse sequence");
        case COMMENT: // Ignored currently
            if (sb == null) { // first comment for this record
                sb = new StringBuilder();
            } else {
                sb.append(Constants.LF);
            }
            sb.append(this.reusableToken.content);
            this.reusableToken.type = TOKEN; // Read another token
            break;
        default:
            throw new IllegalStateException("Unexpected Token type: " + this.reusableToken.type);
        }
    } while (this.reusableToken.type == TOKEN);

    if (!this.recordList.isEmpty()) {
        this.recordNumber++;
        final String comment = sb == null ? null : sb.toString();
        result = new CSVRecord(this.recordList.toArray(new String[this.recordList.size()]), this.headerMap, comment,
                this.recordNumber, startCharPosition);
    }
    return result;
}

public static final TypeAdapter<Calendar> CALENDAR = new TypeAdapter<Calendar>() {
  private static final String YEAR = "year";
  private static final String MONTH = "month";
  private static final String DAY_OF_MONTH = "dayOfMonth";
  private static final String HOUR_OF_DAY = "hourOfDay";
  private static final String MINUTE = "minute";
  private static final String SECOND = "second";

  @Override
  public Calendar read(JsonReader in) throws IOException {
    if (in.peek() == JsonToken.NULL) {
      in.nextNull();
      return null;
    }
    in.beginObject();
    int year = 0;
    int month = 0;
    int dayOfMonth = 0;
    int hourOfDay = 0;
    int minute = 0;
    int second = 0;
    while (in.peek() != JsonToken.END_OBJECT) {
      String name = in.nextName();
      int value = in.nextInt();
      if (YEAR.equals(name)) {
        year = value;
      } else if (MONTH.equals(name)) {
        month = value;
      } else if (DAY_OF_MONTH.equals(name)) {
        dayOfMonth = value;
      } else if (HOUR_OF_DAY.equals(name)) {
        hourOfDay = value;
      } else if (MINUTE.equals(name)) {
        minute = value;
      } else if (SECOND.equals(name)) {
        second = value;
      }
    }
    in.endObject();
    return new GregorianCalendar(year, month, dayOfMonth, hourOfDay, minute, second);
  }

  @Override
  public void write(JsonWriter out, Calendar value) throws IOException {
    if (value == null) {
      out.nullValue();
      return;
    }
    out.beginObject();
    out.name(YEAR);
    out.value(value.get(Calendar.YEAR));
    out.name(MONTH);
    out.value(value.get(Calendar.MONTH));
    out.name(DAY_OF_MONTH);
    out.value(value.get(Calendar.DAY_OF_MONTH));
    out.name(HOUR_OF_DAY);
    out.value(value.get(Calendar.HOUR_OF_DAY));
    out.name(MINUTE);
    out.value(value.get(Calendar.MINUTE));
    out.name(SECOND);
    out.value(value.get(Calendar.SECOND));
    out.endObject();
  }
};

public static final TypeAdapterFactory TIMESTAMP_FACTORY = new TypeAdapterFactory() {
  @SuppressWarnings("unchecked") // we use a runtime check to make sure the 'T's equal
  public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> typeToken) {
    if (typeToken.getRawType() != Timestamp.class) {
      return null;
    }

    final TypeAdapter<Date> dateTypeAdapter = gson.getAdapter(Date.class);
    return (TypeAdapter<T>) new TypeAdapter<Timestamp>() {
      @Override public Timestamp read(JsonReader in) throws IOException {
        Date date = dateTypeAdapter.read(in);
        return date != null ? new Timestamp(date.getTime()) : null;
      }

      @Override public void write(JsonWriter out, Timestamp value) throws IOException {
        dateTypeAdapter.write(out, value);
      }
    };
  }
};

private <T> ObjectConstructor<T> newDefaultConstructor(Class<? super T> rawType) {
  try {
    final Constructor<? super T> constructor = rawType.getDeclaredConstructor();
    if (!constructor.isAccessible()) {
      constructor.setAccessible(true);
    }
    return new ObjectConstructor<T>() {
      @SuppressWarnings("unchecked") // T is the same raw type as is requested
      @Override public T construct() {
        try {
          Object[] args = null;
          return (T) constructor.newInstance(args);
        } catch (InstantiationException e) {
          // TODO: JsonParseException ?
          throw new RuntimeException("Failed to invoke " + constructor + " with no args", e);
        } catch (InvocationTargetException e) {
          // TODO: don't wrap if cause is unchecked!
          // TODO: JsonParseException ?
          throw new RuntimeException("Failed to invoke " + constructor + " with no args",
              e.getTargetException());
        } catch (IllegalAccessException e) {
          throw new AssertionError(e);
        }
      }
    };
  } catch (NoSuchMethodException e) {
    return null;
  }
}

private <T> ObjectConstructor<T> newDefaultImplementationConstructor(
    final Type type, Class<? super T> rawType) {
  if (Collection.class.isAssignableFrom(rawType)) {
    if (SortedSet.class.isAssignableFrom(rawType)) {
      return new ObjectConstructor<T>() {
        @Override public T construct() {
          return (T) new TreeSet<Object>();
        }
      };
    } else if (EnumSet.class.isAssignableFrom(rawType)) {
      return new ObjectConstructor<T>() {
        @SuppressWarnings("rawtypes")
        @Override public T construct() {
          if (type instanceof ParameterizedType) {
            Type elementType = ((ParameterizedType) type).getActualTypeArguments()[0];
            if (elementType instanceof Class) {
              return (T) EnumSet.noneOf((Class)elementType);
            } else {
              throw new JsonIOException("Invalid EnumSet type: " + type.toString());
            }
          } else {
            throw new JsonIOException("Invalid EnumSet type: " + type.toString());
          }
        }
      };
    } else if (Set.class.isAssignableFrom(rawType)) {
      return new ObjectConstructor<T>() {
        @Override public T construct() {
          return (T) new LinkedHashSet<Object>();
        }
      };
    } else if (Queue.class.isAssignableFrom(rawType)) {
      return new ObjectConstructor<T>() {
        @Override public T construct() {
          return (T) new LinkedList<Object>();
        }
      };
    } else {
      return new ObjectConstructor<T>() {
        @Override public T construct() {
          return (T) new ArrayList<Object>();
        }
      };
    }
  }

  if (Map.class.isAssignableFrom(rawType)) {
    if (SortedMap.class.isAssignableFrom(rawType)) {
      return new ObjectConstructor<T>() {
        @Override public T construct() {
          return (T) new TreeMap<Object, Object>();
        }
      };
    } else if (type instanceof ParameterizedType && !(String.class.isAssignableFrom(
        TypeToken.get(((ParameterizedType) type).getActualTypeArguments()[0]).getRawType()))) {
      return new ObjectConstructor<T>() {
        @Override public T construct() {
          return (T) new LinkedHashMap<Object, Object>();
        }
      };
    } else {
      return new ObjectConstructor<T>() {
        @Override public T construct() {
          return (T) new LinkedTreeMap<String, Object>();
        }
      };
    }
  }

  return null;
}

private <T> ObjectConstructor<T> newUnsafeAllocator(
    final Type type, final Class<? super T> rawType) {
  return new ObjectConstructor<T>() {
    private final UnsafeAllocator unsafeAllocator = UnsafeAllocator.create();
    @SuppressWarnings("unchecked")
    @Override public T construct() {
      try {
        Object newInstance = unsafeAllocator.newInstance(rawType);
        return (T) newInstance;
      } catch (Exception e) {
        throw new RuntimeException(("Unable to invoke no-args constructor for " + type + ". "
            + "Register an InstanceCreator with Gson for this type may fix this problem."), e);
      }
    }
  };
}

private void skipQuotedValue(char quote) throws IOException {
  // Like nextNonWhitespace, this uses locals 'p' and 'l' to save inner-loop field access.
  char[] buffer = this.buffer;
  do {
    int p = pos;
    int l = limit;
    /* the index of the first character not yet appended to the builder. */
    while (p < l) {
      int c = buffer[p++];
      if (c == quote) {
        pos = p;
        return;
      } else if (c == '\\') {
        pos = p;
        readEscapeCharacter();
        p = pos;
        l = limit;
      } else if (c == '\n') {
        lineNumber++;
        lineStart = p;
      }
    }
    pos = p;
  } while (fillBuffer(1));
  throw syntaxError("Unterminated string");
}

private void string(String value) throws IOException {
  String[] replacements = htmlSafe ? HTML_SAFE_REPLACEMENT_CHARS : REPLACEMENT_CHARS;
  out.write("\"");
  int last = 0;
  int length = value.length();
  for (int i = 0; i < length; i++) {
    char c = value.charAt(i);
    String replacement;
    if (c < 128) {
      replacement = replacements[c];
      if (replacement == null) {
        continue;
      }
    } else if (c == '\u2028') {
      replacement = "\\u2028";
    } else if (c == '\u2029') {
      replacement = "\\u2029";
    } else {
      continue;
    }
    if (last < i) {
      out.write(value, last, i - last);
    }
    out.write(replacement);
    last = i + 1;
  }
  if (last < length) {
    out.write(value, last, length - last);
  }
  out.write("\"");
}

public static String format(Date date) {
    return format(date, false, TIMEZONE_UTC);
}

public static String format(Date date, boolean millis) {
    return format(date, millis, TIMEZONE_UTC);
}

public static String format(Date date, boolean millis, TimeZone tz) {
    Calendar calendar = new GregorianCalendar(tz, Locale.US);
    calendar.setTime(date);

    int capacity = "yyyy-MM-ddThh:mm:ss".length();
    capacity += millis ? ".sss".length() : 0;
    capacity += tz.getRawOffset() == 0 ? "Z".length() : "+hh:mm".length();
    StringBuilder formatted = new StringBuilder(capacity);

    padInt(formatted, calendar.get(Calendar.YEAR), "yyyy".length());
    formatted.append('-');
    padInt(formatted, calendar.get(Calendar.MONTH) + 1, "MM".length());
    formatted.append('-');
    padInt(formatted, calendar.get(Calendar.DAY_OF_MONTH), "dd".length());
    formatted.append('T');
    padInt(formatted, calendar.get(Calendar.HOUR_OF_DAY), "hh".length());
    formatted.append(':');
    padInt(formatted, calendar.get(Calendar.MINUTE), "mm".length());
    formatted.append(':');
    padInt(formatted, calendar.get(Calendar.SECOND), "ss".length());
    if (millis) {
        formatted.append('.');
        padInt(formatted, calendar.get(Calendar.MILLISECOND), "sss".length());
    }

    int offset = tz.getOffset(calendar.getTimeInMillis());
    if (offset != 0) {
        int hours = Math.abs((offset / (60 * 1000)) / 60);
        int minutes = Math.abs((offset / (60 * 1000)) % 60);
        formatted.append(offset < 0 ? '-' : '+');
        padInt(formatted, hours, "hh".length());
        formatted.append(':');
        padInt(formatted, minutes, "mm".length());
    } else {
        formatted.append('Z');
    }

    return formatted.toString();
}

public static Date parse(String date, ParsePosition pos) throws ParseException {
    Exception fail = null;
    try {
        int offset = pos.getIndex();

        int year = parseInt(date, offset, offset += 4);
        if (checkOffset(date, offset, '-')) {
            offset += 1;
        }

        int month = parseInt(date, offset, offset += 2);
        if (checkOffset(date, offset, '-')) {
            offset += 1;
        }

        int day = parseInt(date, offset, offset += 2);
        int hour = 0;
        int minutes = 0;
        int seconds = 0;
        int milliseconds = 0;

        boolean hasT = checkOffset(date, offset, 'T');

        if (!hasT && (date.length() <= offset)) {
            Calendar calendar = new GregorianCalendar(year, month - 1, day);

            pos.setIndex(offset);
            return calendar.getTime();
        }

        if (hasT) {

            hour = parseInt(date, offset += 1, offset += 2);
            if (checkOffset(date, offset, ':')) {
                offset += 1;
            }

            minutes = parseInt(date, offset, offset += 2);
            if (checkOffset(date, offset, ':')) {
                offset += 1;
            }
            if (date.length() > offset) {
                char c = date.charAt(offset);
                if (c != 'Z' && c != '+' && c != '-') {
                    seconds = parseInt(date, offset, offset += 2);
                    if (seconds > 59 && seconds < 63) seconds = 59;
                    if (checkOffset(date, offset, '.')) {
                        offset += 1;
                        int endOffset = indexOfNonDigit(date, offset + 1);
                        int parseEndOffset = Math.min(endOffset, offset + 3);
                        int fraction = parseInt(date, offset, parseEndOffset);
                        switch (parseEndOffset - offset) {
                        case 2:
                            milliseconds = fraction * 10;
                            break;
                        case 1:
                            milliseconds = fraction * 100;
                            break;
                        default:
                            milliseconds = fraction;
                        }
                        offset = endOffset;
                    }
                }
            }
        }

        if (date.length() <= offset) {
            throw new IllegalArgumentException("No time zone indicator");
        }

        TimeZone timezone = null;
        char timezoneIndicator = date.charAt(offset);

        if (timezoneIndicator == 'Z') {
            timezone = TIMEZONE_UTC;
            offset += 1;
        } else if (timezoneIndicator == '+' || timezoneIndicator == '-') {
            String timezoneOffset = date.substring(offset);

            offset += timezoneOffset.length();
            if ("+0000".equals(timezoneOffset) || "+00:00".equals(timezoneOffset)) {
                timezone = TIMEZONE_UTC;
            } else {
                String timezoneId = "GMT" + timezoneOffset;
                timezone = TimeZone.getTimeZone(timezoneId);

                String act = timezone.getID();
                if (!act.equals(timezoneId)) {
                    String cleaned = act.replace(":", "");
                    if (!cleaned.equals(timezoneId)) {
                        throw new IndexOutOfBoundsException("Mismatching time zone indicator: "+timezoneId+" given, resolves to "
                                +timezone.getID());
                    }
                }
            }
        } else {
            throw new IndexOutOfBoundsException("Invalid time zone indicator '" + timezoneIndicator+"'");
        }

        Calendar calendar = new GregorianCalendar(timezone);
        calendar.setLenient(false);
        calendar.set(Calendar.YEAR, year);
        calendar.set(Calendar.MONTH, month - 1);
        calendar.set(Calendar.DAY_OF_MONTH, day);
        calendar.set(Calendar.HOUR_OF_DAY, hour);
        calendar.set(Calendar.MINUTE, minutes);
        calendar.set(Calendar.SECOND, seconds);
        calendar.set(Calendar.MILLISECOND, milliseconds);

        pos.setIndex(offset);
        return calendar.getTime();
    } catch (IndexOutOfBoundsException e) {
        fail = e;
    } catch (NumberFormatException e) {
        fail = e;
    } catch (IllegalArgumentException e) {
        fail = e;
    }
    String input = (date == null) ? null : ('"' + date + "'");
    String msg = fail.getMessage();
    if (msg == null || msg.isEmpty()) {
        msg = "("+fail.getClass().getName()+")";
    }
    ParseException ex = new ParseException("Failed to parse date [" + input + "]: " + msg, pos.getIndex());
    ex.initCause(fail);
    throw ex;
}

    private static boolean checkOffset(String value, int offset, char expected) {
        return (offset < value.length()) && (value.charAt(offset) == expected);
    }

    private static int parseInt(String value, int beginIndex, int endIndex) throws NumberFormatException {
        if (beginIndex < 0 || endIndex > value.length() || beginIndex > endIndex) {
            throw new NumberFormatException(value);
        }
        int i = beginIndex;
        int result = 0;
        int digit;
        if (i < endIndex) {
            digit = Character.digit(value.charAt(i++), 10);
            if (digit < 0) {
                throw new NumberFormatException("Invalid number: " + value.substring(beginIndex, endIndex));
            }
            result = -digit;
        }
        while (i < endIndex) {
            digit = Character.digit(value.charAt(i++), 10);
            if (digit < 0) {
                throw new NumberFormatException("Invalid number: " + value.substring(beginIndex, endIndex));
            }
            result *= 10;
            result -= digit;
        }
        return -result;
    }

    private static void padInt(StringBuilder buffer, int value, int length) {
        String strValue = Integer.toString(value);
        for (int i = length - strValue.length(); i > 0; i--) {
            buffer.append('0');
        }
        buffer.append(strValue);
    }

    private static int indexOfNonDigit(String string, int offset) {
        for (int i = offset; i < string.length(); i++) {
            char c = string.charAt(i);
            if (c < '0' || c > '9') return i;
        }
        return string.length();
    }
}

private void checkLenient() throws IOException {
  if (!lenient) {
    throw syntaxError("Use JsonReader.setLenient(true) to accept malformed JSON");
  }
}

private void skipToEndOfLine() throws IOException {
  while (pos < limit || fillBuffer(1)) {
    char c = buffer[pos++];
    if (c == '\n') {
      lineNumber++;
      lineStart = pos + 1;
      break;
    } else if (c == '\r') {
      break;
    }
  }
}

private boolean skipTo(String toFind) throws IOException {
  outer:
  for (; pos + toFind.length() <= limit || fillBuffer(toFind.length()); pos++) {
    if (buffer[pos] == '\n') {
      lineNumber++;
      lineStart = pos + 1;
      continue;
    }
    for (int c = 0; c < toFind.length(); c++) {
      if (buffer[pos + c] != toFind.charAt(c)) {
        continue outer;
      }
    }
    return true;
  }
  return false;
}

@Override public String toString() {
  return getClass().getSimpleName()
      + " at line " + getLineNumber() + " column " + getColumnNumber();
}

/**
 * Returns a <a href="http://goessner.net/articles/JsonPath/">JsonPath</a> to
 * the current location in the JSON value.
 */
public String getPath() {
  StringBuilder result = new StringBuilder().append('$');
  for (int i = 0, size = stackSize; i < size; i++) {
    switch (stack[i]) {
      case JsonScope.EMPTY_ARRAY:
      case JsonScope.NONEMPTY_ARRAY:
        result.append('[').append(pathIndices[i]).append(']');
        break;

      case JsonScope.EMPTY_OBJECT:
      case JsonScope.DANGLING_NAME:
      case JsonScope.NONEMPTY_OBJECT:
        result.append('.');
        if (pathNames[i] != null) {
          result.append(pathNames[i]);
        }
        break;

      case JsonScope.NONEMPTY_DOCUMENT:
      case JsonScope.EMPTY_DOCUMENT:
      case JsonScope.CLOSED:
        break;
    }
  }
  return result.toString();
}

/**
 * Unescapes the character identified by the character or characters that
 * immediately follow a backslash. The backslash '\' should have already
 * been read. This supports both unicode escapes "u000A" and two-character
 * escapes "\n".
 *
 * @throws NumberFormatException if any unicode escape sequences are
 *     malformed.
 */
private char readEscapeCharacter() throws IOException {
  if (pos == limit && !fillBuffer(1)) {
    throw syntaxError("Unterminated escape sequence");
  }

  char escaped = buffer[pos++];
  switch (escaped) {
  case 'u':
    if (pos + 4 > limit && !fillBuffer(4)) {
      throw syntaxError("Unterminated escape sequence");
    }
    // Equivalent to Integer.parseInt(stringPool.get(buffer, pos, 4), 16);
    char result = 0;
    for (int i = pos, end = i + 4; i < end; i++) {
      char c = buffer[i];
      result <<= 4;
      if (c >= '0' && c <= '9') {
        result += (c - '0');
      } else if (c >= 'a' && c <= 'f') {
        result += (c - 'a' + 10);
      } else if (c >= 'A' && c <= 'F') {
        result += (c - 'A' + 10);
      } else {
        throw new NumberFormatException("\\u" + new String(buffer, pos, 4));
      }
    }
    pos += 4;
    return result;

  case 't':
    return '\t';

  case 'b':
    return '\b';

  case 'n':
    return '\n';

  case 'r':
    return '\r';

  case 'f':
    return '\f';

  case '\n':
    lineNumber++;
    lineStart = pos + 1;
    // fall-through

  case '\'':
  case '"':
  case '\\':
  default:
    return escaped;
  }
}

/**
 * Throws a new IO exception with the given message and a context snippet
 * with this reader's content.
 */
private IOException syntaxError(String message) throws IOException {
  throw new MalformedJsonException(message
      + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
}

/**
 * Consumes the non-execute prefix if it exists.
 */
private void consumeNonExecutePrefix() throws IOException {
  // fast forward through the leading whitespace
  nextNonWhitespace(true);
  pos--;

  if (pos + NON_EXECUTE_PREFIX.length > limit && !fillBuffer(NON_EXECUTE_PREFIX.length)) {
    return;
  }

  for (int i = 0; i < NON_EXECUTE_PREFIX.length; i++) {
    if (buffer[pos + i] != NON_EXECUTE_PREFIX[i]) {
      return; // not a security token!
    }
  }

  // we consumed a security token!
  pos += NON_EXECUTE_PREFIX.length;
}

static {
  JsonReaderInternalAccess.INSTANCE = new JsonReaderInternalAccess() {
    @Override public void promoteNameToValue(JsonReader reader) throws IOException {
      if (reader instanceof JsonTreeReader) {
        ((JsonTreeReader)reader).promoteNameToValue();
        return;
      }
      int p = reader.peeked;
      if (p == PEEKED_NONE) {
        p = reader.doPeek();
      }
      if (p == PEEKED_DOUBLE_QUOTED_NAME) {
        reader.peeked = PEEKED_DOUBLE_QUOTED;
      } else if (p == PEEKED_SINGLE_QUOTED_NAME) {
        reader.peeked = PEEKED_SINGLE_QUOTED;
      } else if (p == PEEKED_UNQUOTED_NAME) {
        reader.peeked = PEEKED_UNQUOTED;
      } else {
        throw new IllegalStateException("Expected a name but was " + reader.peek() + " "
            + " at line " + reader.getLineNumber() + " column " + reader.getColumnNumber()
            + " path " + reader.getPath());
      }
    }
  };
}

public static UnsafeAllocator create() {
  // try JVM
  try {
    Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
    Field f = unsafeClass.getDeclaredField("theUnsafe");
    f.setAccessible(true);
    final Object unsafe = f.get(null);
    final Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);
    return new UnsafeAllocator() {
      @Override
      @SuppressWarnings("unchecked")
      public <T> T newInstance(Class<T> c) throws Exception {
        return (T) allocateInstance.invoke(unsafe, c);
      }
    };
  } catch (Exception ignored) {
  }

  // try dalvikvm, post-gingerbread
  try {
    Method getConstructorId = ObjectStreamClass.class
        .getDeclaredMethod("getConstructorId", Class.class);
    getConstructorId.setAccessible(true);
    final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);
    final Method newInstance = ObjectStreamClass.class
        .getDeclaredMethod("newInstance", Class.class, int.class);
    newInstance.setAccessible(true);
    return new UnsafeAllocator() {
      @Override
      @SuppressWarnings("unchecked")
      public <T> T newInstance(Class<T> c) throws Exception {
        return (T) newInstance.invoke(null, c, constructorId);
      }
    };
  } catch (Exception ignored) {
  }

  // try dalvikvm, pre-gingerbread
  try {
    final Method newInstance = ObjectInputStream.class
        .getDeclaredMethod("newInstance", Class.class, Class.class);
    newInstance.setAccessible(true);
    return new UnsafeAllocator() {
      @Override
      @SuppressWarnings("unchecked")
      public <T> T newInstance(Class<T> c) throws Exception {
        return (T) newInstance.invoke(null, c, Object.class);
      }
    };
  } catch (Exception ignored) {
  }

  // give up
  return new UnsafeAllocator() {
    @Override
    public <T> T newInstance(Class<T> c) {
      throw new UnsupportedOperationException("Cannot allocate " + c);
    }
  };
}

public JsonElement get() {
    if (!stack.isEmpty()) {
      throw new IllegalStateException("Expected one JSON element but was " + stack);
    }
    return product;
}

private void put(JsonElement value) {
    if (pendingName != null) {
      if (!value.isJsonNull() || getSerializeNulls()) {
        JsonObject object = (JsonObject) peek();
        object.add(pendingName, value);
      }
      pendingName = null;
    } else if (stack.isEmpty()) {
      product = value;
    } else {
      JsonElement element = peek();
      if (element instanceof JsonArray) {
        ((JsonArray) element).add(value);
      } else {
        throw new IllegalStateException();
      }
    }
}

@Override public JsonWriter beginArray() throws IOException {
    JsonArray array = new JsonArray();
    put(array);
    stack.add(array);
    return this;
}

@Override public JsonWriter endArray() throws IOException {
    if (stack.isEmpty() || pendingName != null) {
      throw new IllegalStateException();
    }
    JsonElement element = peek();
    if (element instanceof JsonArray) {
      stack.remove(stack.size() - 1);
      return this;
    }
    throw new IllegalStateException();
}

@Override public JsonWriter beginObject() throws IOException {
    JsonObject object = new JsonObject();
    put(object);
    stack.add(object);
    return this;
}

@Override public JsonWriter endObject() throws IOException {
    if (stack.isEmpty() || pendingName != null) {
      throw new IllegalStateException();
    }
    JsonElement element = peek();
    if (element instanceof JsonObject) {
      stack.remove(stack.size() - 1);
      return this;
    }
    throw new IllegalStateException();
}

@Override public JsonWriter name(String name) throws IOException {
    if (stack.isEmpty() || pendingName != null) {
      throw new IllegalStateException();
    }
    JsonElement element = peek();
    if (element instanceof JsonObject) {
      pendingName = name;
      return this;
    }
    throw new IllegalStateException();
}

@Override public JsonWriter value(String value) throws IOException {
    if (value == null) {
      return nullValue();
    }
    put(new JsonPrimitive(value));
    return this;
}

@Override public JsonWriter nullValue() throws IOException {
    put(JsonNull.INSTANCE);
    return this;
}

@Override public JsonWriter value(boolean value) throws IOException {
    put(new JsonPrimitive(value));
    return this;
}

@Override public JsonWriter value(double value) throws IOException {
    if (!isLenient() && (Double.isNaN(value) || Double.isInfinite(value))) {
      throw new IllegalArgumentException("JSON forbids NaN and infinities: " + value);
    }
    put(new JsonPrimitive(value));
    return this;
}

@Override public JsonWriter value(long value) throws IOException {
    put(new JsonPrimitive(value));
    return this;
}

@Override public JsonWriter value(Number value) throws IOException {
    if (value == null) {
      return nullValue();
    }

    if (!isLenient()) {
      double d = value.doubleValue();
      if (Double.isNaN(d) || Double.isInfinite(d)) {
        throw new IllegalArgumentException("JSON forbids NaN and infinities: " + value);
      }
    }

    put(new JsonPrimitive(value));
    return this;
}

@Override public void close() throws IOException {
    if (!stack.isEmpty()) {
      throw new IOException("Incomplete document");
    }
    stack.add(SENTINEL_CLOSED);
}

public static final TypeAdapter<Class> CLASS = new TypeAdapter<Class>() {
    @Override
    public void write(JsonWriter out, Class value) throws IOException {
      if (value == null) {
        out.nullValue();
      } else {
        throw new UnsupportedOperationException("Attempted to serialize java.lang.Class: "
            + value.getName() + ". Forgot to register a type adapter?");
      }
    }
    @Override
    public Class read(JsonReader in) throws IOException {
      if (in.peek() == JsonToken.NULL) {
        in.nextNull();
        return null;
      } else {
        throw new UnsupportedOperationException(
            "Attempted to deserialize a java.lang.Class. Forgot to register a type adapter?");
      }
    }
  };
  public static final TypeAdapterFactory CLASS_FACTORY = newFactory(Class.class, CLASS);

public static final TypeAdapter<BitSet> BIT_SET = new TypeAdapter<BitSet>() {
    @Override public BitSet read(JsonReader in) throws IOException {
      if (in.peek() == JsonToken.NULL) {
        in.nextNull();
        return null;
      }

      BitSet bitset = new BitSet();
      in.beginArray();
      int i = 0;
      JsonToken tokenType = in.peek();
      while (tokenType != JsonToken.END_ARRAY) {
        boolean set;
        switch (tokenType) {
        case NUMBER:
          set = in.nextInt() != 0;
          break;
        case BOOLEAN:
          set = in.nextBoolean();
          break;
        case STRING:
          String stringValue = in.nextString();
          try {
            set = Integer.parseInt(stringValue) != 0;
          } catch (NumberFormatException e) {
            throw new JsonSyntaxException(
                "Error: Expecting: bitset number value (1, 0), Found: " + stringValue);
          }
          break;
        default:
          throw new JsonSyntaxException("Invalid bitset value type: " + tokenType);
        }
        if (set) {
          bitset.set(i);
        }
        ++i;
        tokenType = in.peek();
      }
      in.endArray();
      return bitset;
    }

    @Override public void write(JsonWriter out, BitSet src) throws IOException {
      if (src == null) {
        out.nullValue();
        return;
      }

      out.beginArray();
      for (int i = 0; i < src.length(); i++) {
        int value = (src.get(i)) ? 1 : 0;
        out.value(value);
      }
      out.endArray();
    }
  };

public static final TypeAdapter<Boolean> BOOLEAN = new TypeAdapter<Boolean>() {
    @Override
    public Boolean read(JsonReader in) throws IOException {
      if (in.peek() == JsonToken.NULL) {
        in.nextNull();
        return null;
      } else if (in.peek() == JsonToken.STRING) {
        // support strings for compatibility with GSON 1.7
        return Boolean.parseBoolean(in.nextString());
      }
      return in.nextBoolean();
    }
    @Override
    public void write(JsonWriter out, Boolean value) throws IOException {
      if (value == null) {
        out.nullValue();
        return;
      }
      out.value(value);
    }
  };

/**
 * Writes a boolean as a string. Useful for map keys, where booleans aren't
 * otherwise permitted.
 */
public static final TypeAdapter<Boolean> BOOLEAN_AS_STRING = new TypeAdapter<Boolean>() {
    @Override public Boolean read(JsonReader in) throws IOException {
      if (in.peek() == JsonToken.NULL) {
        in.nextNull();
        return null;
      }
      return Boolean.valueOf(in.nextString());
    }

    @Override public void write(JsonWriter out, Boolean value) throws IOException {
