public static int parseInt(char[] digitChars, int offset, int len)
{
    int num = digitChars[offset] - '0';
    len += offset;
    // This looks ugly, but appears the fastest way (as per measurements)
    if (++offset < len) {
        num = (num * 10) + (digitChars[offset] - '0');
        if (++offset < len) {
            num = (num * 10) + (digitChars[offset] - '0');
            if (++offset < len) {
                num = (num * 10) + (digitChars[offset] - '0');
                if (++offset < len) {
                    num = (num * 10) + (digitChars[offset] - '0');
                    if (++offset < len) {
                        num = (num * 10) + (digitChars[offset] - '0');
                        if (++offset < len) {
                            num = (num * 10) + (digitChars[offset] - '0');
                            if (++offset < len) {
                                num = (num * 10) + (digitChars[offset] - '0');
                            }
                        }
                    }
                }
            }
        }
    }
    return num;
}

public static int parseInt(String str)
{
    /* Ok: let's keep strategy simple: ignoring optional minus sign,
     * we'll accept 1 - 9 digits and parse things efficiently;
     * otherwise just defer to JDK parse functionality.
     */
    char c = str.charAt(0);
    int length = str.length();
    boolean negative = (c == '-');
    int offset = 1;
    // must have 1 - 9 digits after optional sign:
    // negative?
    if (negative) {
        if (length == 1 || length > 10) {
            return Integer.parseInt(str);
        }
        c = str.charAt(offset++);
    } else {
        if (length > 9) {
            return Integer.parseInt(str);
        }
    }
    if (c > '9' || c < '0') {
        return Integer.parseInt(str);
    }
    int num = c - '0';
    if (offset < length) {
        c = str.charAt(offset++);
        if (c > '9' || c < '0') {
            return Integer.parseInt(str);
        }
        num = (num * 10) + (c - '0');
        if (offset < length) {
            c = str.charAt(offset++);
            if (c > '9' || c < '0') {
                return Integer.parseInt(str);
            }
            num = (num * 10) + (c - '0');
            // Let's just loop if we have more than 3 digits:
            if (offset < length) {
                do {
                    c = str.charAt(offset++);
                    if (c > '9' || c < '0') {
                        return Integer.parseInt(str);
                    }
                    num = (num * 10) + (c - '0');
                } while (offset < length);
            }
        }
    }
    return negative ? -num : num;
}

public void append(char c) {
    // Using shared buffer so far?
    if (_inputStart >= 0) {
        unshare(16);
    }
    _resultString = null;
    _resultArray = null;
    // Room in current segment?
    char[] curr = _currentSegment;
    if (_currentSize >= curr.length) {
        expand(1);
        curr = _currentSegment;
    }
    curr[_currentSize++] = c;
}

public void append(char[] c, int start, int len)
{
    // Can't append to shared buf (sanity check)
    if (_inputStart >= 0) {
        unshare(len);
    }
    _resultString = null;
    _resultArray = null;

    // Room in current segment?
    char[] curr = _currentSegment;
    int max = curr.length - _currentSize;

    if (max >= len) {
        System.arraycopy(c, start, curr, _currentSize, len);
        _currentSize += len;
        return;
    }
    // No room for all, need to copy part(s):
    if (max > 0) {
        System.arraycopy(c, start, curr, _currentSize, max);
        start += max;
        len -= max;
    }
    /* And then allocate new segment; we are guaranteed to now
     * have enough room in segment.
     */
    // Except, as per [Issue-24], not for HUGE appends... so:
    do {
        expand(len);
        int amount = Math.min(_currentSegment.length, len);
        System.arraycopy(c, start, _currentSegment, 0, amount);
        _currentSize += amount;
        start += amount;
        len -= amount;
    } while (len > 0);
}

protected final int _skipWS() throws IOException
{
    final int[] codes = _icWS;
    while (_inputPtr < _inputEnd || loadMore()) {
        final int i = _inputBuffer[_inputPtr++] & 0xFF;
        switch (codes[i]) {
        case 0: // done!
            return i;
        case 1: // skip
            continue;
        case 2: // 2-byte UTF
            _skipUtf8_2(i);
            break;
        case 3: // 3-byte UTF
            _skipUtf8_3(i);
            break;
        case 4: // 4-byte UTF
            _skipUtf8_4(i);
            break;
        case INT_LF:
            ++_currInputRow;
            _currInputRowStart = _inputPtr;
            break;
        case INT_CR:
            _skipCR();
            break;
        case '/':
            _skipComment();
            break;
        case '#':
            if (!_skipYAMLComment()) {
                return i;
            }
            break;
        default: // e.g. -1
            _reportInvalidChar(i);
        }
    }
    throw _constructError("Unexpected end-of-input within/between "+_parsingContext.getTypeDesc()+" entries");
}

protected final int _skipWSOrEnd() throws IOException
{
    final int[] codes = _icWS;
    while ((_inputPtr < _inputEnd) || loadMore()) {
        final int i = _inputBuffer[_inputPtr++] & 0xFF;
        switch (codes[i]) {
        case 0: // done!
            return i;
        case 1: // skip
            continue;
        case 2: // 2-byte UTF
            _skipUtf8_2(i);
            break;
        case 3: // 3-byte UTF
            _skipUtf8_3(i);
            break;
        case 4: // 4-byte UTF
            _skipUtf8_4(i);
            break;
        case INT_LF:
            ++_currInputRow;
            _currInputRowStart = _inputPtr;
            break;
        case INT_CR:
            _skipCR();
            break;
        case '/':
            _skipComment();
            break;
        case '#':
            if (!_skipYAMLComment()) {
                return i;
            }
            break;
