            return (ArrayNode) n;
        }
        throw new UnsupportedOperationException("Property '" + propertyName
            + "' has value that is not of type ArrayNode (but " + n
            .getClass().getName() + ")");
    }
    ArrayNode result = arrayNode();
    _children.put(propertyName, result);
    return result;
}

