@Override
public void serialize(Object bean, JsonGenerator gen, SerializerProvider prov) throws IOException
{
    try {
        Object value = _accessorMethod.getValue(bean);
        if (value == null) {
            prov.defaultSerializeNull(gen);
            return;
        }
        JsonSerializer<Object> ser = _valueSerializer;
        if (ser == null) {
            Class<?> c = value.getClass();
            /* 10-Mar-2010, tatu: Ideally we would actually separate out type
             *   serializer from value serializer; but, alas, there's no access
             *   to serializer factory at this point... 
             */
            // let's cache it, may be needed soon again
            ser = prov.findTypedValueSerializer(c, true, _property);
        }
        ser.serialize(value, gen, prov);
    } catch (IOException ioe) {
        throw ioe;
    } catch (Exception e) {
        Throwable t = e;
        // Need to unwrap this specific type, to see infinite recursion...
        while (t instanceof InvocationTargetException && t.getCause() != null) {
            t = t.getCause();
        }
        // Errors shouldn't be wrapped (and often can't, as well)
        if (t instanceof Error) {
            throw (Error) t;
        }
        // let's try to indicate the path best we can...
        throw JsonMappingException.wrapWithPath(t, bean, _accessorMethod.getName() + "()");
    }
}

    @Override
    public void serializeWithType(Object bean, JsonGenerator gen, SerializerProvider provider,
            TypeSerializer typeSer0) throws IOException
    {
        // Regardless of other parts, first need to find value to serialize:
        Object value = null;
        try {
            value = _accessorMethod.getValue(bean);
            // and if we got null, can also just write it directly
            if (value == null) {
                provider.defaultSerializeNull(gen);
                return;
            }
            JsonSerializer<Object> ser = _valueSerializer;
            if (ser == null) { // no serializer yet? Need to fetch
//                ser = provider.findTypedValueSerializer(value.getClass(), true, _property);
                ser = provider.findValueSerializer(value.getClass(), _property);
            } else {
                /* 09-Dec-2010, tatu: To work around natural type's refusal to add type info, we do
                 *    this (note: type is for the wrapper type, not enclosed value!)
                 */
                if (_forceTypeInformation) {
                    typeSer0.writeTypePrefixForScalar(bean, gen);
                    ser.serialize(value, gen, provider);
                    typeSer0.writeTypeSuffixForScalar(bean, gen);
                    return;
                }
            }
            // 28-Sep-2016, tatu: As per [databind#1385], we do need to do some juggling
            //    to use different Object for type id (logical type) and actual serialization
            //    (delegat type).
            ser.serializeWithType(value, gen, provider, typeSer0);
        } catch (IOException ioe) {
            throw ioe;
        } catch (Exception e) {
            Throwable t = e;
            // Need to unwrap this specific type, to see infinite recursion...
            while (t instanceof InvocationTargetException && t.getCause() != null) {
                t = t.getCause();
            }
            // Errors shouldn't be wrapped (and often can't, as well)
            if (t instanceof Error) {
                throw (Error) t;
            }
            // let's try to indicate the path best we can...
            throw JsonMappingException.wrapWithPath(t, bean, _accessorMethod.getName() + "()");
        }
    }

public Collection<Object> deserialize(JsonParser p, DeserializationContext ctxt)
    throws IOException
{
    if (_delegateDeserializer != null) {
        return (Collection<Object>) _valueInstantiator.createUsingDelegate(ctxt,
                _delegateDeserializer.deserialize(p, ctxt));
    }
    /* Empty String may be ok; bit tricky to check, however, since
     * there is also possibility of "auto-wrapping" of single-element arrays.
     * Hence we only accept empty String here.
     */
    if (p.hasToken(JsonToken.VALUE_STRING)) {
        String str = p.getText();
        if (str.length() == 0) {
            return (Collection<Object>) _valueInstantiator.createFromString(ctxt, str);
        }
    }
    return deserialize(p, ctxt, (Collection<Object>) _valueInstantiator.createUsingDefault(ctxt));
}

public Collection<Object> deserialize(JsonParser p, DeserializationContext ctxt,
        Collection<Object> result)
    throws IOException
{
    // Ok: must point to START_ARRAY (or equivalent)
    if (!p.isExpectedStartArrayToken()) {
        return handleNonArray(p, ctxt, result);
    }
    // [databind#631]: Assign current value, to be accessible by custom serializers
    p.setCurrentValue(result);

    JsonDeserializer<Object> valueDes = _valueDeserializer;
    final TypeDeserializer typeDeser = _valueTypeDeserializer;
    CollectionReferringAccumulator referringAccumulator =
        (valueDes.getObjectIdReader() == null) ? null :
            new CollectionReferringAccumulator(_collectionType.getContentType().getRawClass(), result);

    JsonToken t;
    while ((t = p.nextToken()) != JsonToken.END_ARRAY) {
        try {
            Object value;
            if (t == JsonToken.VALUE_NULL) {
                value = valueDes.getNullValue(ctxt);
            } else if (typeDeser == null) {
                value = valueDes.deserialize(p, ctxt);
            } else {
                value = valueDes.deserializeWithType(p, ctxt, typeDeser);
            }
            if (referringAccumulator != null) {
                referringAccumulator.add(value);
            } else {
                result.add(value);
            }
        } catch (UnresolvedForwardReference reference) {
            if (referringAccumulator == null) {
                throw JsonMappingException
                        .from(p, "Unresolved forward reference but no identity info", reference);
            }
            Referring ref = referringAccumulator.handleUnresolvedReference(reference);
            reference.getRoid().appendReferring(ref);
        } catch (Exception e) {
            boolean wrap = (ctxt == null) || ctxt.isEnabled(DeserializationFeature.WRAP_EXCEPTIONS);
            if (!wrap && e instanceof RuntimeException) {
                throw (RuntimeException)e;
            }
            throw JsonMappingException.wrapWithPath(e, result, result.size());
        }
    }
    return result;
}

public Object deserializeWithType(JsonParser jp, DeserializationContext ctxt,
        TypeDeserializer typeDeserializer)
    throws IOException
{
    // In future could check current token... for now this should be enough:
    return typeDeserializer.deserializeTypedFromArray(jp, ctxt);
}

/**
 * Helper method called when current token is no START_ARRAY. Will either
 * throw an exception, or try to handle value as if member of implicit
 * array, depending on configuration.
 */
protected final Collection<Object> handleNonArray(JsonParser p, DeserializationContext ctxt,
        Collection<Object> result)
    throws IOException
{
    // Implicit arrays from single values?
    boolean canWrap = (_unwrapSingle == Boolean.TRUE) ||
            ((_unwrapSingle == null) &&
                    ctxt.isEnabled(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY));
    if (!canWrap) {
        throw ctxt.mappingException(_collectionType.getRawClass());
    }
    JsonDeserializer<Object> valueDes = _valueDeserializer;
    final TypeDeserializer typeDeser = _valueTypeDeserializer;
    JsonToken t = p.getCurrentToken();

    Object value;

    try {
        if (t == JsonToken.VALUE_NULL) {
            value = valueDes.getNullValue(ctxt);
        } else if (typeDeser == null) {
            value = valueDes.deserialize(p, ctxt);
        } else {
            value = valueDes.deserializeWithType(p, ctxt, typeDeser);
        }
    } catch (Exception e) {
        // note: pass Object.class, not Object[].class, as we need element type for error info
        throw JsonMappingException.wrapWithPath(e, Object.class, result.size());
    }
    result.add(value);
    return result;
}

public final static class CollectionReferringAccumulator {
    private final Class<?> _elementType;
    private final Collection<Object> _result;

    /**
     * A list of {@link CollectionReferring} to maintain ordering.
     */
    private List<CollectionReferring> _accumulator = new ArrayList<CollectionReferring>();

    public CollectionReferringAccumulator(Class<?> elementType, Collection<Object> result) {
        _elementType = elementType;
        _result = result;
    }

    public void add(Object value)
    {
        if (_accumulator.isEmpty()) {
            _result.add(value);
        } else {
            CollectionReferring ref = _accumulator.get(_accumulator.size() - 1);
            ref.next.add(value);
        }
    }

    public Referring handleUnresolvedReference(UnresolvedForwardReference reference)
    {
        CollectionReferring id = new CollectionReferring(this, reference, _elementType);
        _accumulator.add(id);
        return id;
    }

    public void resolveForwardReference(Object id, Object value) throws IOException
    {
        Iterator<CollectionReferring> iterator = _accumulator.iterator();
        // Resolve ordering after resolution of an id. This mean either:
        // 1- adding to the result collection in case of the first unresolved id.
        // 2- merge the content of the resolved id with its previous unresolved id.
        Collection<Object> previous = _result;
        while (iterator.hasNext()) {
            CollectionReferring ref = iterator.next();
            if (ref.hasId(id)) {
                iterator.remove();
                previous.add(value);
                previous.addAll(ref.next);
                return;
            }
            previous = ref.next;
        }

        throw new IllegalArgumentException("Trying to resolve a forward reference with id [" + id
                + "] that wasn't previously seen as unresolved.");
    }
}

    /**
     * Helper class to maintain processing order of value. The resolved
     * object associated with {@link #_id} comes before the values in
     * {@link #next}.
     */
    private final static class CollectionReferring extends Referring {
        private final CollectionReferringAccumulator _parent;
        public final List<Object> next = new ArrayList<Object>();

        CollectionReferring(CollectionReferringAccumulator parent,
                UnresolvedForwardReference reference, Class<?> contentType)
        {
            super(reference, contentType);
            _parent = parent;
        }

        @Override
        public void handleResolvedForwardReference(Object id, Object value) throws IOException {
            _parent.resolveForwardReference(id, value);
        }
    }
}

public String getDescription() {
    if (_desc == null) {
        StringBuilder sb = new StringBuilder();

        if (_from == null) { // can this ever occur?
            sb.append("UNKNOWN");
        } else {
            Class<?> cls = (_from instanceof Class<?>) ? (Class<?>)_from : _from.getClass();
            // Hmmh. Although Class.getName() is mostly ok, it does look
            // butt-ugly for arrays.
            // 06-Oct-2016, tatu: as per [databind#1403], `getSimpleName()` not so good
            //   as it drops enclosing class. So let's try bit different approach
            String pkgName = com.fasterxml.jackson.databind.util.ClassUtil.getPackageName(cls);
            if (pkgName != null) {
                sb.append(pkgName);
                sb.append('.');
            }
            sb.append(cls.getSimpleName());
        }
        sb.append('[');
        if (_fieldName != null) {
            sb.append('"');
            sb.append(_fieldName);
            sb.append('"');
        } else if (_index >= 0) {
            sb.append(_index);
        } else {
            sb.append('?');
        }
        sb.append(']');
        _desc = sb.toString();
    }
    return _desc;
}

protected Object getPropertyDefaultValue(String name, AnnotatedMember member,
        JavaType type)
{
    Object defaultBean = getDefaultBean();
    if (defaultBean == null) {
        return getDefaultValue(type);
    }
    try {
        return member.getValue(defaultBean);
    } catch (Exception e) {
        return _throwWrapped(e, name, defaultBean);
    }
}

protected Object getDefaultValue(JavaType type)
{
    // 06-Nov-2015, tatu: Returning null is fine for Object types; but need special
    //   handling for primitives since they are never passed as nulls.
    Class<?> cls = type.getRawClass();

    Class<?> prim = ClassUtil.primitiveType(cls);
    if (prim != null) {
        return ClassUtil.defaultValue(prim);
    }
    if (type.isContainerType() || type.isReferenceType()) {
        return JsonInclude.Include.NON_EMPTY;
    }
    if (cls == String.class) {
        return "";
    }
    return null;
}

protected Object _parse(String key, DeserializationContext ctxt) throws Exception
{
    switch (_kind) {
    case TYPE_BOOLEAN:
        if ("true".equals(key)) {
            return Boolean.TRUE;
        }
        if ("false".equals(key)) {
            return Boolean.FALSE;
        }
        return ctxt.handleWeirdKey(_keyClass, key, "value not 'true' or 'false'");
    case TYPE_BYTE:
        {
            int value = _parseInt(key);
            // allow range up to 255, inclusive (to support "unsigned" byte)
            if (value < Byte.MIN_VALUE || value > 255) {
                return ctxt.handleWeirdKey(_keyClass, key, "overflow, value can not be represented as 8-bit value");
            }
            return Byte.valueOf((byte) value);
        }
    case TYPE_SHORT:
        {
            int value = _parseInt(key);
            if (value < Short.MIN_VALUE || value > Short.MAX_VALUE) {
                return ctxt.handleWeirdKey(_keyClass, key, "overflow, value can not be represented as 16-bit value");
                // fall-through and truncate if need be
            }
            return Short.valueOf((short) value);
        }
    case TYPE_CHAR:
        if (key.length() == 1) {
            return Character.valueOf(key.charAt(0));
        }
        return ctxt.handleWeirdKey(_keyClass, key, "can only convert 1-character Strings");
    case TYPE_INT:
        return _parseInt(key);

    case TYPE_LONG:
        return _parseLong(key);

    case TYPE_FLOAT:
        // Bounds/range checks would be tricky here, so let's not bother even trying...
        return Float.valueOf((float) _parseDouble(key));
    case TYPE_DOUBLE:
        return _parseDouble(key);
    case TYPE_LOCALE:
        try {
            return _deser._deserialize(key, ctxt);
        } catch (IOException e) {
            return ctxt.handleWeirdKey(_keyClass, key, "unable to parse key as locale");
        }
    case TYPE_CURRENCY:
        try {
            return _deser._deserialize(key, ctxt);
        } catch (IOException e) {
            return ctxt.handleWeirdKey(_keyClass, key, "unable to parse key as currency");
        }
    case TYPE_DATE:
        return ctxt.parseDate(key);
    case TYPE_CALENDAR:
        java.util.Date date = ctxt.parseDate(key);
        return (date == null)  ? null : ctxt.constructCalendar(date);
    case TYPE_UUID:
        try {
            return UUID.fromString(key);
        } catch (Exception e) {
            return ctxt.handleWeirdKey(_keyClass, key, "problem: %s", e.getMessage());
        }
    case TYPE_URI:
        try {
            return URI.create(key);
        } catch (Exception e) {
            return ctxt.handleWeirdKey(_keyClass, key, "problem: %s", e.getMessage());
        }
    case TYPE_URL:
        try {
            return new URL(key);
        } catch (MalformedURLException e) {
            return ctxt.handleWeirdKey(_keyClass, key, "problem: %s", e.getMessage());
        }
    case TYPE_CLASS:
        try {
            return ctxt.findClass(key);
        } catch (Exception e) {
            return ctxt.handleWeirdKey(_keyClass, key, "unable to parse key as Class");
        }
    default:
        throw new IllegalStateException("Internal error: unknown key type "+_keyClass);
    }
}

public ValueInstantiator _valueInstantiatorInstance(DeserializationConfig config,
        Annotated annotated, Object instDef)
    throws JsonMappingException
{
    if (instDef == null) {
        return null;
    }

    ValueInstantiator inst;

    if (instDef instanceof ValueInstantiator) {
        return (ValueInstantiator) instDef;
    }
    if (!(instDef instanceof Class)) {
        throw new IllegalStateException("AnnotationIntrospector returned key deserializer definition of type "
                +instDef.getClass().getName()
                +"; expected type KeyDeserializer or Class<KeyDeserializer> instead");
    }
    Class<?> instClass = (Class<?>)instDef;
    if (ClassUtil.isBogusClass(instClass)) {
        return null;
    }
    if (!ValueInstantiator.class.isAssignableFrom(instClass)) {
        throw new IllegalStateException("AnnotationIntrospector returned Class "+instClass.getName()
                +"; expected Class<ValueInstantiator>");
    }
    HandlerInstantiator hi = config.getHandlerInstantiator();
    if (hi != null) {
        inst = hi.valueInstantiatorInstance(config, annotated, instClass);
        if (inst != null) {
            return inst;
        }
    }
    return (ValueInstantiator) ClassUtil.createInstance(instClass,
            config.canOverrideAccessModifiers());
}

protected void _addDeserializerConstructors
    (DeserializationContext ctxt, BeanDescription beanDesc, VisibilityChecker<?> vchecker,
     AnnotationIntrospector intr, CreatorCollector creators,
     Map<AnnotatedWithParams,BeanPropertyDefinition[]> creatorParams)
    throws JsonMappingException
{
    // First things first: the "default constructor" (zero-arg
    // constructor; whether implicit or explicit) is NOT included
    // in list of constructors, so needs to be handled separately.
    AnnotatedConstructor defaultCtor = beanDesc.findDefaultConstructor();
    if (defaultCtor != null) {
        if (!creators.hasDefaultCreator() || intr.hasCreatorAnnotation(defaultCtor)) {
            creators.setDefaultCreator(defaultCtor);
        }
    }

    // may need to keep track for [#725]
    List<AnnotatedConstructor> implicitCtors = null;
    for (AnnotatedConstructor ctor : beanDesc.getConstructors()) {
        final boolean isCreator = intr.hasCreatorAnnotation(ctor);
        BeanPropertyDefinition[] propDefs = creatorParams.get(ctor);
        final int argCount = ctor.getParameterCount();

        // some single-arg factory methods (String, number) are auto-detected
        if (argCount == 1) {
            BeanPropertyDefinition argDef = (propDefs == null) ? null : propDefs[0];
            boolean useProps = _checkIfCreatorPropertyBased(intr, ctor, argDef);

            if (useProps) {
                SettableBeanProperty[] properties = new SettableBeanProperty[1];
                PropertyName name = (argDef == null) ? null : argDef.getFullName();
                AnnotatedParameter arg = ctor.getParameter(0);
                properties[0] = constructCreatorProperty(ctxt, beanDesc, name, 0, arg,
                        intr.findInjectableValueId(arg));
                creators.addPropertyCreator(ctor, isCreator, properties);
            } else {
                /*boolean added = */ _handleSingleArgumentConstructor(ctxt, beanDesc, vchecker, intr, creators,
                        ctor, isCreator,
                        vchecker.isCreatorVisible(ctor));
                // one more thing: sever link to creator property, to avoid possible later
                // problems with "unresolved" constructor property
                if (argDef != null) {
                    ((POJOPropertyBuilder) argDef).removeConstructors();
                }
            }
            // regardless, fully handled
            continue;
        }

        // 2 or more args; all params must have names or be injectable
        // 14-Mar-2015, tatu (2.6): Or, as per [#725], implicit names will also
        //   do, with some constraints. But that will require bit post processing...

        AnnotatedParameter nonAnnotatedParam = null;
        SettableBeanProperty[] properties = new SettableBeanProperty[argCount];
        int explicitNameCount = 0;
        int implicitWithCreatorCount = 0;
        int injectCount = 0;

        for (int i = 0; i < argCount; ++i) {
            final AnnotatedParameter param = ctor.getParameter(i);
            BeanPropertyDefinition propDef = (propDefs == null) ? null : propDefs[i];
            Object injectId = intr.findInjectableValueId(param);
            final PropertyName name = (propDef == null) ? null : propDef.getFullName();

            if (propDef != null && propDef.isExplicitlyNamed()) {
                ++explicitNameCount;
                properties[i] = constructCreatorProperty(ctxt, beanDesc, name, i, param, injectId);
                continue;
            }
            if (injectId != null) {
                ++injectCount;
                properties[i] = constructCreatorProperty(ctxt, beanDesc, name, i, param, injectId);
                continue;
            }
            NameTransformer unwrapper = intr.findUnwrappingNameTransformer(param);
            if (unwrapper != null) {
                properties[i] = constructCreatorProperty(ctxt, beanDesc, UNWRAPPED_CREATOR_PARAM_NAME, i, param, null);
                ++explicitNameCount;
                continue;
            }
            // One more thing: implicit names are ok iff ctor has creator annotation
            if (isCreator && (name != null && !name.isEmpty())) {
                ++implicitWithCreatorCount;
                properties[i] = constructCreatorProperty(ctxt, beanDesc, name, i, param, injectId);
                continue;
            }
            if (nonAnnotatedParam == null) {
                nonAnnotatedParam = param;
            }
        }

        final int namedCount = explicitNameCount + implicitWithCreatorCount;
        // Ok: if named or injectable, we have more work to do
        if (isCreator || (explicitNameCount > 0) || (injectCount > 0)) {
            // simple case; everything covered:
            if ((namedCount + injectCount) == argCount) {
                creators.addPropertyCreator(ctor, isCreator, properties);
                continue;
            }
            if ((explicitNameCount == 0) && ((injectCount + 1) == argCount)) {
                // Secondary: all but one injectable, one un-annotated (un-named)
                creators.addDelegatingCreator(ctor, isCreator, properties);
                continue;
            }
            // otherwise, epic fail?
            // 16-Mar-2015, tatu: due to [#725], need to be more permissive. For now let's
            //    only report problem if there's no implicit name
            PropertyName impl = _findImplicitParamName(nonAnnotatedParam, intr);
            if (impl == null || impl.isEmpty()) {
                // Let's consider non-static inner class as a special case...
                int ix = nonAnnotatedParam.getIndex();
                if ((ix == 0) && ClassUtil.isNonStaticInnerClass(ctor.getDeclaringClass())) {
                    throw new IllegalArgumentException("Non-static inner classes like "
                            +ctor.getDeclaringClass().getName()+" can not use @JsonCreator for constructors");
                }
                throw new IllegalArgumentException("Argument #"+ix
                        +" of constructor "+ctor+" has no property name annotation; must have name when multiple-parameter constructor annotated as Creator");
            }
        }
        // [#725]: as a fallback, all-implicit names may work as well
        if (!creators.hasDefaultCreator()) {
            if (implicitCtors == null) {
                implicitCtors = new LinkedList<AnnotatedConstructor>();
            }
            implicitCtors.add(ctor);
        }
    }
    // last option, as per [#725]: consider implicit-names-only, visible constructor,
    // if just one found
    if ((implicitCtors != null) && !creators.hasDelegatingCreator()
            && !creators.hasPropertyBasedCreator()) {
        _checkImplicitlyNamedConstructors(ctxt, beanDesc, vchecker, intr,
                creators, implicitCtors);
    }
}

@Override
public Object deserializeWithType(JsonParser p, DeserializationContext ctxt,
        TypeDeserializer typeDeserializer)
    throws IOException
{
    // 16-Feb-2012, tatu: ObjectId may be used as well... need to check that first
    if (_objectIdReader != null) {
        // 05-Aug-2013, tatu: May use native Object Id
        if (p.canReadObjectId()) {
            Object id = p.getObjectId();
            if (id != null) {
                Object ob = typeDeserializer.deserializeTypedFromObject(p, ctxt);
                return _handleTypedObjectId(p, ctxt, ob, id);
            }
        }
        // or, Object Ids Jackson explicitly sets
        JsonToken t = p.getCurrentToken();
        if (t != null) {
            // Most commonly, a scalar (int id, uuid String, ...)
            if (t.isScalarValue()) {
                return deserializeFromObjectId(p, ctxt);
            }
            // but, with 2.5+, a simple Object-wrapped value also legal:
            if (t == JsonToken.START_OBJECT) {
                t = p.nextToken();
            }
            if ((t == JsonToken.FIELD_NAME) && _objectIdReader.maySerializeAsObject()
                    && _objectIdReader.isValidReferencePropertyName(p.getCurrentName(), p)) {
                return deserializeFromObjectId(p, ctxt);
            }
        }
    }
    // In future could check current token... for now this should be enough:
    return typeDeserializer.deserializeTypedFromObject(p, ctxt);
}

protected Object _handleTypedObjectId(JsonParser p, DeserializationContext ctxt,
        Object pojo, Object rawId)
    throws IOException
{
    // One more challenge: type of id may not be type of property we are expecting
    // later on; specifically, numeric ids vs Strings.
    JsonDeserializer<Object> idDeser = _objectIdReader.getDeserializer();
    final Object id;

    // Ok, this is bit ridiculous; let's see if conversion is needed:
    if (idDeser.handledType() == rawId.getClass()) {
        // nope: already same type
        id = rawId;
    } else {
        id = _convertObjectId(p, ctxt, rawId, idDeser);
    }

    ReadableObjectId roid = ctxt.findObjectId(id, _objectIdReader.generator, _objectIdReader.resolver);
    roid.bindItem(pojo);
    // also: may need to set a property value as well
    SettableBeanProperty idProp = _objectIdReader.idProperty;
    if (idProp != null) {
        return idProp.setAndReturn(pojo, id);
    }
    return pojo;
}

@SuppressWarnings("resource") // TokenBuffers don't need close, nor parser thereof
protected Object _convertObjectId(JsonParser p, DeserializationContext ctxt,
        Object rawId, JsonDeserializer<Object> idDeser) throws IOException
{
    TokenBuffer buf = new TokenBuffer(p, ctxt);
    if (rawId instanceof String) {
        buf.writeString((String) rawId);
    } else if (rawId instanceof Long) {
        buf.writeNumber(((Long) rawId).longValue());
    } else if (rawId instanceof Integer) {
        buf.writeNumber(((Integer) rawId).intValue());
    } else {
        // should we worry about UUIDs? They should be fine, right?
        // 07-Aug-2014, tatu: Maybe, but not necessarily; had issues with
        //   Smile format; [dataformat-smile#19], possibly related.
        // 01-Sep-2016, tatu: For non-JSON, might want to consider `writeEmbeddedObject`
        //   but that won't work for default impl (JSON and most dataformats)
        buf.writeObject(rawId);
    }
    JsonParser bufParser = buf.asParser();
    bufParser.nextToken();
    return idDeser.deserialize(bufParser, ctxt);
}

protected Object deserializeWithObjectId(JsonParser p, DeserializationContext ctxt) throws IOException {
    return deserializeFromObject(p, ctxt);
}

protected Object deserializeFromObjectId(JsonParser p, DeserializationContext ctxt) throws IOException
{
    Object id = _objectIdReader.readObjectReference(p, ctxt);
    ReadableObjectId roid = ctxt.findObjectId(id, _objectIdReader.generator, _objectIdReader.resolver);
    // do we have it resolved?
    Object pojo = roid.resolve();
    if (pojo == null) { // not yet; should wait...
        throw new UnresolvedForwardReference(p,
                "Could not resolve Object Id ["+id+"] (for "+_beanType+").",
                p.getCurrentLocation(), roid);
    }
    return pojo;
}

protected Object deserializeFromObjectUsingNonDefault(JsonParser p,
        DeserializationContext ctxt) throws IOException
{
    if (_delegateDeserializer != null) {
        return _valueInstantiator.createUsingDelegate(ctxt,
                _delegateDeserializer.deserialize(p, ctxt));
    }
    if (_propertyBasedCreator != null) {
        return _deserializeUsingPropertyBased(p, ctxt);
    }
    // should only occur for abstract types...
    if (_beanType.isAbstract()) {
        return ctxt.handleMissingInstantiator(handledType(), p,
                "abstract type (need to add/enable type information?)");
    }
    return ctxt.handleMissingInstantiator(_beanType.getRawClass(), p,
            "no suitable constructor found, can not deserialize from Object value (missing default constructor or creator, or perhaps need to add/enable type information?)");
}

protected abstract Object _deserializeUsingPropertyBased(final JsonParser p,
        final DeserializationContext ctxt)
    throws IOException, JsonProcessingException;

@SuppressWarnings("incomplete-switch")
public Object deserializeFromNumber(JsonParser p, DeserializationContext ctxt)
    throws IOException
{
    // First things first: id Object Id is used, most likely that's it
    if (_objectIdReader != null) {
        return deserializeFromObjectId(p, ctxt);
    }
    switch (p.getNumberType()) {
    case INT:
        if (_delegateDeserializer != null) {
            if (!_valueInstantiator.canCreateFromInt()) {
                Object bean = _valueInstantiator.createUsingDelegate(ctxt,
                        _delegateDeserializer.deserialize(p, ctxt));
                if (_injectables != null) {
                    injectValues(ctxt, bean);
                }
                return bean;
            }
        }
        return _valueInstantiator.createFromInt(ctxt, p.getIntValue());
    case LONG:
        if (_delegateDeserializer != null) {
            if (!_valueInstantiator.canCreateFromInt()) {
                Object bean = _valueInstantiator.createUsingDelegate(ctxt,
                        _delegateDeserializer.deserialize(p, ctxt));
                if (_injectables != null) {
                    injectValues(ctxt, bean);
                }
                return bean;
            }
        }
        return _valueInstantiator.createFromLong(ctxt, p.getLongValue());
    }
    // actually, could also be BigInteger, so:
    if (_delegateDeserializer != null) {
        Object bean = _valueInstantiator.createUsingDelegate(ctxt,
                _delegateDeserializer.deserialize(p, ctxt));
        if (_injectables != null) {
            injectValues(ctxt, bean);
        }
        return bean;
    }
    return ctxt.handleMissingInstantiator(handledType(), p,
            "no suitable creator method found to deserialize from Number value (%s)",
            p.getNumberValue());
}

public Object deserializeFromString(JsonParser p, DeserializationContext ctxt) throws IOException
{
    // First things first: id Object Id is used, most likely that's it
    if (_objectIdReader != null) {
        return deserializeFromObjectId(p, ctxt);
    }
    /* Bit complicated if we have delegating creator; may need to use it,
     * or might not...
     */
    if (_delegateDeserializer != null) {
        if (!_valueInstantiator.canCreateFromString()) {
            Object bean = _valueInstantiator.createUsingDelegate(ctxt,
                    _delegateDeserializer.deserialize(p, ctxt));
            if (_injectables != null) {
                injectValues(ctxt, bean);
            }
            return bean;
        }
    }
    return _valueInstantiator.createFromString(ctxt, p.getText());
}

