protected final Object _deserializeUsingPropertyBased(final JsonParser p,
        final DeserializationContext ctxt)
    throws IOException, JsonProcessingException
{
    final PropertyBasedCreator creator = _propertyBasedCreator;
    PropertyValueBuffer buffer = creator.startBuilding(p, ctxt, _objectIdReader);

    // 04-Jan-2010, tatu: May need to collect unknown properties for polymorphic cases
    TokenBuffer unknown = null;

    JsonToken t = p.getCurrentToken();
    for (; t == JsonToken.FIELD_NAME; t = p.nextToken()) {
        String propName = p.getCurrentName();
        p.nextToken(); // to point to value
        // creator property?
        SettableBeanProperty creatorProp = creator.findCreatorProperty(propName);
        if (creatorProp != null) {
            // Last creator property to set?
            if (buffer.assignParameter(creatorProp, creatorProp.deserialize(p, ctxt))) {
                p.nextToken(); // to move to following FIELD_NAME/END_OBJECT
                Object bean;
                try {
                    bean = creator.build(ctxt, buffer);
                } catch (Exception e) {
                    wrapAndThrow(e, _beanType.getRawClass(), propName, ctxt);
                    continue; // never gets here
                }
                //  polymorphic?
                if (bean.getClass() != _beanType.getRawClass()) {
                    return handlePolymorphic(p, ctxt, bean, unknown);
                }
                if (unknown != null) { // nope, just extra unknown stuff...
                    bean = handleUnknownProperties(ctxt, bean, unknown);
                }
                // or just clean?
                return _deserialize(p, ctxt, bean);
            }
            continue;
        }
        // Object Id property?
        if (buffer.readIdProperty(propName)) {
            continue;
        }
        // regular property? needs buffering
        SettableBeanProperty prop = _beanProperties.find(propName);
        if (prop != null) {
            buffer.bufferProperty(prop, prop.deserialize(p, ctxt));
            continue;
        }
        // As per [JACKSON-313], things marked as ignorable should not be
        // passed to any setter
        if (_ignorableProps != null && _ignorableProps.contains(propName)) {
            handleIgnoredProperty(p, ctxt, handledType(), propName);
            continue;
        }
        // "any property"?
        if (_anySetter != null) {
            buffer.bufferAnyProperty(_anySetter, propName, _anySetter.deserialize(p, ctxt));
            continue;
        }
        // Ok then, let's collect the whole field; name and value
        if (unknown == null) {
            unknown = new TokenBuffer(p, ctxt);
        }
        unknown.writeFieldName(propName);
        unknown.copyCurrentStructure(p);
    }

    // We hit END_OBJECT, so:
    Object bean;
    try {
        bean = creator.build(ctxt, buffer);
    } catch (Exception e) {
        bean = wrapInstantiationProblem(e, ctxt);
    }
    if (unknown != null) {
        // polymorphic?
        if (bean.getClass() != _beanType.getRawClass()) {
            return handlePolymorphic(null, ctxt, bean, unknown);
        }
        // no, just some extra unknown properties
        return handleUnknownProperties(ctxt, bean, unknown);
    }
    return bean;
}

protected final Object deserializeWithView(JsonParser p, DeserializationContext ctxt,
        Object bean, Class<?> activeView)
    throws IOException, JsonProcessingException
{
    JsonToken t = p.getCurrentToken();
    for (; t == JsonToken.FIELD_NAME; t = p.nextToken()) {
        String propName = p.getCurrentName();
        // Skip field name:
        p.nextToken();
        SettableBeanProperty prop = _beanProperties.find(propName);
        if (prop != null) {
            if (!prop.visibleInView(activeView)) {
                p.skipChildren();
                continue;
            }
            try {
                bean = prop.deserializeSetAndReturn(p, ctxt, bean);
            } catch (Exception e) {
                wrapAndThrow(e, bean, propName, ctxt);
            }
            continue;
        }
        handleUnknownVanilla(p, ctxt, bean, propName);
    }
    return bean;
}

protected Object deserializeWithExternalTypeId(JsonParser p,
        DeserializationContext ctxt)
    throws IOException, JsonProcessingException
{
    if (_propertyBasedCreator != null) {
        return deserializeUsingPropertyBasedWithExternalTypeId(p, ctxt);
    }
    return deserializeWithExternalTypeId(p, ctxt, _valueInstantiator.createUsingDefault(ctxt));
}

@Override
public JsonDeserializer<Object> createBeanDeserializer(DeserializationContext ctxt,
        JavaType type, BeanDescription beanDesc)
    throws JsonMappingException
{
    final DeserializationConfig config = ctxt.getConfig();
    // We may also have custom overrides:
    JsonDeserializer<Object> custom = _findCustomBeanDeserializer(type, config, beanDesc);
    if (custom != null) {
        return custom;
    }
    /* One more thing to check: do we have an exception type
     * (Throwable or its sub-classes)? If so, need slightly
     * different handling.
     */
    if (type.isThrowable()) {
        return buildThrowableDeserializer(ctxt, type, beanDesc);
    }
    /* Or, for abstract types, may have alternate means for resolution
     * (defaulting, materialization)
     */
    // 29-Nov-2015, tatu: Also, filter out calls to primitive types, they are
    //    not something we could materialize anything for
    if (type.isAbstract() && !type.isPrimitive()) {
        // Let's make it possible to materialize abstract types.
        JavaType concreteType = materializeAbstractType(ctxt, type, beanDesc);
        if (concreteType != null) {
            /* important: introspect actual implementation (abstract class or
             * interface doesn't have constructors, for one)
             */
            beanDesc = config.introspect(concreteType);
            return buildBeanDeserializer(ctxt, concreteType, beanDesc);
        }
    }

    // Otherwise, may want to check handlers for standard types, from superclass:
    @SuppressWarnings("unchecked")
    JsonDeserializer<Object> deser = (JsonDeserializer<Object>) findStdDeserializer(ctxt, type, beanDesc);
    if (deser != null) {
        return deser;
    }

    // Otherwise: could the class be a Bean class? If not, bail out
    if (!isPotentialBeanType(type.getRawClass())) {
        return null;
    }
    // For checks like [databind#1599]
    // Use generic bean introspection to build deserializer
    return buildBeanDeserializer(ctxt, type, beanDesc);
}

protected JsonDeserializer<?> findStdDeserializer(DeserializationContext ctxt,
        JavaType type, BeanDescription beanDesc)
    throws JsonMappingException
{
    // note: we do NOT check for custom deserializers here, caller has already
    // done that
    JsonDeserializer<?> deser = findDefaultDeserializer(ctxt, type, beanDesc);
    // Also: better ensure these are post-processable?
    if (deser != null) {
        if (_factoryConfig.hasDeserializerModifiers()) {
            for (BeanDeserializerModifier mod : _factoryConfig.deserializerModifiers()) {
                deser = mod.modifyDeserializer(ctxt.getConfig(), beanDesc, deser);
            }
        }
    }
    return deser;
}

protected JavaType materializeAbstractType(DeserializationContext ctxt,
        JavaType type, BeanDescription beanDesc)
    throws JsonMappingException
{
    // May have multiple resolvers, call in precedence order until one returns non-null
    for (AbstractTypeResolver r : _factoryConfig.abstractTypeResolvers()) {
        JavaType concrete = r.resolveAbstractType(ctxt.getConfig(), beanDesc);
        if (concrete != null) {
            return concrete;
        }
    }
    return null;
}

/**
 * Set of well-known "nasty classes", deserialization of which is considered dangerous
 * and should (and is) prevented by default.
 *
 * @since 2.8.9
 */
private static final Set<String> DANGEROUS_CLASSES = new HashSet<>(Arrays.asList(
        "java.lang.RuntimeException",
        "java.lang.Error",
        "java.lang.Throwable"
));

/**
 * Set of class names of types that are never to be deserialized.
 *
 * @since 2.8.9
 */
private static final Set<String> BLACKLISTED_CLASSES = new HashSet<>(Arrays.asList(
        "com.example.SensitiveData",
        "com.example.UnsafeClass"
));

@Override
public JsonDeserializer<Object> createBeanDeserializer(DeserializationContext ctxt,
        JavaType type, BeanDescription beanDesc)
    throws JsonMappingException
{
    final DeserializationConfig config = ctxt.getConfig();
    // We may also have custom overrides:
    JsonDeserializer<Object> custom = _findCustomBeanDeserializer(type, config, beanDesc);
    if (custom != null) {
        return custom;
    }
    /* One more thing to check: do we have an exception type
     * (Throwable or its sub-classes)? If so, need slightly
     * different handling.
     */
    if (type.isThrowable()) {
        return buildThrowableDeserializer(ctxt, type, beanDesc);
    }
    // Check if the type is dangerous or blacklisted
    if (DANGEROUS_CLASSES.contains(type.getRawClass().getName()) ||
        BLACKLISTED_CLASSES.contains(type.getRawClass().getName())) {
        throw new JsonMappingException(ctxt, "Deserialization of " + type.getRawClass().getName() + " is not allowed");
    }
    /* Or, for abstract types, may have alternate means for resolution
     * (defaulting, materialization)
     */
    // 29-Nov-2015, tatu: Also, filter out calls to primitive types, they are
    //    not something we could materialize anything for
    if (type.isAbstract() && !type.isPrimitive() && !type.isEnumType()) {
        // Let's make it possible to materialize abstract types.
        JavaType concreteType = materializeAbstractType(ctxt, type, beanDesc);
        if (concreteType != null) {
            /* important: introspect actual implementation (abstract class or
             * interface doesn't have constructors, for one)
             */
            beanDesc = config.introspect(concreteType);
            return buildBeanDeserializer(ctxt, concreteType, beanDesc);
        }
    }
    // Otherwise, may want to check handlers for standard types, from superclass:
    @SuppressWarnings("unchecked")
    JsonDeserializer<Object> deser = (JsonDeserializer<Object>) findStdDeserializer(ctxt, type, beanDesc);
    if (deser != null) {
        return deser;
    }

    // Otherwise: could the class be a Bean class? If not, bail out
    if (!isPotentialBeanType(type.getRawClass())) {
        return null;
    }
    // For checks like [databind#1599]
    // Use generic bean introspection to build deserializer
    return buildBeanDeserializer(ctxt, type, beanDesc);
}

/**
 * Method that will check whether given raw type is marked as always ignorable
 * (for purpose of ignoring properties with type)
 */
protected boolean isIgnorableType(DeserializationConfig config, BeanDescription beanDesc,
        Class<?> type, Map<Class<?>,Boolean> ignoredTypes)
{
    Boolean status = ignoredTypes.get(type);
    if (status != null) {
        return status.booleanValue();
    }
    // 21-Apr-2016, tatu: For 2.8, can specify config overrides
    ConfigOverride override = config.findConfigOverride(type);
    if (override != null) {
        status = override.getIsIgnoredType();
    }
    if (status == null) {
        BeanDescription desc = config.introspectClassAnnotations(type);
        status = config.getAnnotationIntrospector().isIgnorableType(desc.getClassInfo());
        // We default to 'false', i.e. not ignorable
        if (status == null) {
            status = Boolean.FALSE;
        }
    }
    ignoredTypes.put(type, status);
    return status.booleanValue();
}

