    protected final static QName ROOT_NAME_FOR_NULL = new QName("null");

    protected final XmlRootNameLookup _rootNameLookup;

    public XmlSerializerProvider(XmlRootNameLookup rootNames)
    {
        super();
        _rootNameLookup = rootNames;
    }

    public XmlSerializerProvider(XmlSerializerProvider src,
            SerializationConfig config, SerializerFactory f)
    {
        super(src, config, f);
        _rootNameLookup  = src._rootNameLookup;
    }

    /*
    /**********************************************************************
    /* Overridden methods
    /**********************************************************************
     */

    @Override
    public DefaultSerializerProvider createInstance(SerializationConfig config,
            SerializerFactory jsf) {
        return new XmlSerializerProvider(this, config, jsf);
    }

    @SuppressWarnings("resource")
    @Override
    public void serializeValue(JsonGenerator gen, Object value) throws IOException
    {
        if (value == null) {
            _serializeXmlNull(gen);
            return;
        }
        final Class<?> cls = value.getClass();
        final boolean asArray;
        final ToXmlGenerator xgen = _asXmlGenerator(gen);
        if (xgen == null) { // called by convertValue()
            asArray = false;
        } else {
            QName rootName = _rootNameFromConfig();
            if (rootName == null) {
                rootName = _rootNameLookup.findRootName(cls, _config);
            }
            _initWithRootName(xgen, rootName);
            asArray = TypeUtil.isIndexedType(cls);
            if (asArray) {
                _startRootArray(xgen, rootName);
            }
        }

        // From super-class implementation
        final JsonSerializer<Object> ser = findTypedValueSerializer(cls, true, null);
        try {
            ser.serialize(value, gen, this);
        } catch (IOException ioe) { // As per [JACKSON-99], pass IOException and subtypes as-is
            throw ioe;
        } catch (Exception e) { // but wrap RuntimeExceptions, to get path information
            String msg = e.getMessage();
            if (msg == null) {
                msg = "[no message for "+e.getClass().getName()+"]";
            }
            throw JsonMappingException.from(gen, msg, e);
        }
        // end of super-class implementation

        if (asArray) {
            gen.writeEndObject();
        }
    }

    @SuppressWarnings("resource")
    @Override
    public void serializeValue(JsonGenerator gen, Object value, JavaType rootType)
        throws IOException
    {
        if (value == null) {
            _serializeXmlNull(gen);
            return;
        }
        final boolean asArray;
        final ToXmlGenerator xgen = _asXmlGenerator(gen);
        if (xgen == null) { // called by convertValue()
            asArray = false;
        } else {
            QName rootName = _rootNameFromConfig();
            if (rootName == null) {
                rootName = _rootNameLookup.findRootName(rootType, _config);
            }
            _initWithRootName(xgen, rootName);
            asArray = TypeUtil.isIndexedType(rootType);
            if (asArray) {
                _startRootArray(xgen, rootName);
            }
        }

        final JsonSerializer<Object> ser = findTypedValueSerializer(rootType, true, null);
        // From super-class implementation
        try {
            ser.serialize(value, gen, this);
        } catch (IOException ioe) { // no wrapping for IO (and derived)
            throw ioe;
        } catch (Exception e) { // but others do need to be, to get path etc
            String msg = e.getMessage();
            if (msg == null) {
                msg = "[no message for "+e.getClass().getName()+"]";
            }
            throw JsonMappingException.from(gen, msg, e);
        }
        // end of super-class implementation

        if (asArray) {
            gen.writeEndObject();
        }
    }

    // @since 2.1
    @SuppressWarnings("resource")
    @Override
    public void serializeValue(JsonGenerator gen, Object value, JavaType rootType,
            JsonSerializer<Object> ser) throws IOException
    {
        if (value == null) {
            _serializeXmlNull(gen);
            return;
        }
        final boolean asArray;
        final ToXmlGenerator xgen = _asXmlGenerator(gen);
        if (xgen == null) { // called by convertValue()
            asArray = false;
        } else {
            QName rootName = _rootNameFromConfig();
            if (rootName == null) {
                rootName = _rootNameLookup.findRootName(rootType, _config);
            }
            _initWithRootName(xgen, rootName);
            asArray = TypeUtil.isIndexedType(rootType);
            if (asArray) {
                _startRootArray(xgen, rootName);
            }
        }
        if (ser == null) {
            ser = findTypedValueSerializer(rootType, true, null);
        }
        // From super-class implementation
        try {
            ser.serialize(value, gen, this);
        } catch (IOException ioe) { // no wrapping for IO (and derived)
            throw ioe;
        } catch (Exception e) { // but others do need to be, to get path etc
            String msg = e.getMessage();
            if (msg == null) {
                msg = "[no message for "+e.getClass().getName()+"]";
            }
            throw JsonMappingException.from(gen, msg, e);
        }
        // end of super-class implementation
        if (asArray) {
            gen.writeEndObject();
        }
    }

    protected void _serializeXmlNull(JsonGenerator jgen) throws IOException
    {
        // 14-Nov-2016, tatu: As per [dataformat-xml#213], we may have explicitly
        //    configured root name...
        if (jgen instanceof ToXmlGenerator) {
            _initWithRootName((ToXmlGenerator) jgen, ROOT_NAME_FOR_NULL);
        }
        super.serializeValue(jgen, null);
    }

    protected void _startRootArray(ToXmlGenerator xgen, QName rootName) throws IOException
    {
        xgen.writeStartObject();
        // Could repeat root name, but what's the point? How to customize?
        xgen.writeFieldName("item");
    }    

    protected void _initWithRootName(ToXmlGenerator xgen, QName rootName) throws IOException
    {
        /* 28-Nov-2012, tatu: We should only initialize the root
         *  name if no name has been set, as per [dataformat-xml#42],
         *  to allow for custom serializers to work.
         */
        if (!xgen.setNextNameIfMissing(rootName)) {
            // however, if we are root, we... insist
            if (xgen.inRoot()) {
                xgen.setNextName(rootName);
            }
        }
        xgen.initGenerator();
        String ns = rootName.getNamespaceURI();
        /* [dataformat-xml#26] If we just try writing root element with namespace,
         * we will get an explicit prefix. But we'd rather use the default
         * namespace, so let's try to force that.
         */
        if (ns != null && ns.length() > 0) {
            try {
                xgen.getStaxWriter().setDefaultNamespace(ns);
            } catch (XMLStreamException e) {
                StaxUtil.throwXmlAsIOException(e);
            }
        }
    }

    protected QName _rootNameFromConfig()
    {
        PropertyName name = _config.getFullRootName();
        if (name == null) {
            return null;
        }
        String ns = name.getNamespace();
        if (ns == null || ns.isEmpty()) {
            return new QName(name.getSimpleName());
        }
        return new QName(ns, name.getSimpleName());
    }

    protected ToXmlGenerator _asXmlGenerator(JsonGenerator gen)
        throws JsonMappingException
    {
        // [Issue#71]: When converting, we actually get TokenBuffer, which is fine
        if (!(gen instanceof ToXmlGenerator)) {
            // but verify
            if (!(gen instanceof TokenBuffer)) {
                throw JsonMappingException.from(gen,
                        "XmlMapper does not with generators of type other than ToXmlGenerator; got: "+gen.getClass().getName());
            }
            return null;
        }
        return (ToXmlGenerator) gen;
    }    
}

protected XmlSerializerProvider(XmlSerializerProvider src) {
    super(src);
    // 21-May-2018, tatu: As per [dataformat-xml#282], should NOT really copy
    //    root name lookup as that may link back to diff version, configuration
    _rootNameLookup = null; // Reset root name lookup to avoid linking back to different version
}

public void writeStartArray() throws IOException {
    _verifyValueWrite("start an array");
    _writeContext = _writeContext.createChildArrayContext();
    if (_cfgPrettyPrinter != null) {
        _cfgPrettyPrinter.writeStartArray(this);
    } else {
        // nothing to do here; no-operation
    }
}

public void writeEndArray() throws IOException {
    if (!_writeContext.inArray()) {
        _reportError("Current context not Array but "+_writeContext.typeDesc());
    }
    if (_cfgPrettyPrinter != null) {
        _cfgPrettyPrinter.writeEndArray(this, _writeContext.getEntryCount());
    } else {
        // nothing to do here; no-operation
    }
    _writeContext = _writeContext.getParent();
}

public void writeStartObject() throws IOException {
    _verifyValueWrite("start an object");
    _writeContext = _writeContext.createChildObjectContext();
    if (_cfgPrettyPrinter != null) {
        _cfgPrettyPrinter.writeStartObject(this);
    } else {
        _handleStartObject();
    }
}

public void writeEndObject() throws IOException {
    if (!_writeContext.inObject()) {
        _reportError("Current context not Object but "+_writeContext.typeDesc());
    }
    _writeContext = _writeContext.getParent();
    if (_cfgPrettyPrinter != null) {
        // as per [Issue#45], need to suppress indentation if only attributes written:
        int count = _nextIsAttribute ? 0 : _writeContext.getEntryCount();
        _cfgPrettyPrinter.writeEndObject(this, count);
    } else {
        _handleEndObject();
    }
}

public void _handleStartObject() throws IOException {
    if (_nextName == null) {
        handleMissingName();
    }
    // Need to keep track of names to make Lists work correctly
    _elementNameStack.addLast(_nextName);
    try {
        _xmlWriter.writeStartElement(_nextName.getNamespaceURI(), _nextName.getLocalPart());
    } catch (XMLStreamException e) {
        StaxUtil.throwAsGenerationException(e, this);
    }
}

public void _handleEndObject() throws IOException {
    // We may want to repeat same element, so:
    if (_elementNameStack.isEmpty()) {
        throw new JsonGenerationException("Can not write END_ELEMENT without open START_ELEMENT", this);
    }
    _nextName = _elementNameStack.removeLast();
    try {
        // note: since attributes don't nest, can only have one attribute active, so:
        _nextIsAttribute = false;
        _xmlWriter.writeEndElement();
        // [databind-xml#172]: possibly also need indentation
        if (_elementNameStack.isEmpty() && (_xmlPrettyPrinter != null)) {
            // ... but only if it is likely to succeed:
            if (!_stax2Emulation) {
                _xmlPrettyPrinter.writePrologLinefeed(_xmlWriter);
            }
        }
    } catch (XMLStreamException e) {
        StaxUtil.throwAsGenerationException(e, this);
    }
}

public void writeFieldName(SerializableString name) throws IOException {
    writeFieldName(name.getValue());
}

public void writeString(String text) throws IOException {
    _verifyValueWrite("write String value");
    if (_nextName == null) {
        handleMissingName();
    }
    try {
        if (_nextIsAttribute) { // must write attribute name and value with one call
            _xmlWriter.writeAttribute(_nextName.getNamespaceURI(), _nextName.getLocalPart(), text);
        } else if (checkNextIsUnwrapped()) {
            // [Issue#56] Should figure out how to prevent indentation for end element
            //   but for now, let's just make sure structure is correct
            //if (_xmlPrettyPrinter != null) { ... }
            if(_nextIsCData) {
                _xmlWriter.writeCData(text);
            } else {
                _xmlWriter.writeCharacters(text);
            }
        } else if (_xmlPrettyPrinter != null) {
            _xmlPrettyPrinter.writeLeafElement(_xmlWriter,
                    _nextName.getNamespaceURI(), _nextName.getLocalPart(),
                    text, _nextIsCData);
        } else {
            _xmlWriter.writeStartElement(_nextName.getNamespaceURI(), _nextName.getLocalPart());
            if(_nextIsCData) {
                _xmlWriter.writeCData(text);
            } else {
                _xmlWriter.writeCharacters(text);
            }
            _xmlWriter.writeEndElement();
        } 
    } catch (XMLStreamException e) {
        StaxUtil.throwAsGenerationException(e, this);
    }
}

public void writeString(char[] text, int offset, int len) throws IOException {
    _verifyValueWrite("write String value");
    if (_nextName == null) {
        handleMissingName();
    }
    try {
        if (_nextIsAttribute) {
            _xmlWriter.writeAttribute(_nextName.getNamespaceURI(), _nextName.getLocalPart(), new String(text, offset, len));
        } else if (checkNextIsUnwrapped()) {
        	// should we consider pretty-printing or not?
            if(_nextIsCData) {
                _xmlWriter.writeCData(text, offset, len);
            } else {
                _xmlWriter.writeCharacters(text, offset, len);
            }
        } else if (_xmlPrettyPrinter != null) {
            _xmlPrettyPrinter.writeLeafElement(_xmlWriter,
                    _nextName.getNamespaceURI(), _nextName.getLocalPart(),
                    text, offset, len, _nextIsCData);
        } else {
            _xmlWriter.writeStartElement(_nextName.getNamespaceURI(), _nextName.getLocalPart());
