public boolean hasClass(String className) {
    final String classAttr = attributes.get("class");
    if (classAttr == null) {
        return false;
    }

    final int len = classAttr.length();
    final int wantLen = className.length();

    if (len == 0 || len < wantLen) {
        return false;
    }

    // if both lengths are equal, only need compare the className with the attribute
    if (len == wantLen) {
        return className.equalsIgnoreCase(classAttr);
    }

    // otherwise, scan for whitespace and compare regions (with no string or arraylist allocations)
    boolean inClass = false;
    int start = 0;
    for (int i = 0; i < len; i++) {
        if (Character.isWhitespace(classAttr.charAt(i))) {
            if (inClass) {
                // white space ends a class name, compare it with the requested one, ignore case
                if (i - start == wantLen && classAttr.regionMatches(true, start, className, 0, wantLen)) {
                    return true;
                }
                inClass = false;
            }
        } else {
            if (!inClass) {
                // we're in a class name : keep the start of the substring
                inClass = true;
                start = i;
            }
        }
    }

    // check the last entry
    if (inClass && len - start == wantLen) {
        return classAttr.regionMatches(true, start, className, 0, wantLen);
    }

    return false;
}

boolean anyOtherEndTag(Token t, HtmlTreeBuilder tb) {
    String name = t.asEndTag().normalName();
    ArrayList<Element> stack = tb.getStack();
    for (int pos = stack.size() - 1; pos >= 0; pos--) {
        Element node = stack.get(pos);
        if (node.nodeName().equals(name)) {
            tb.generateImpliedEndTags(name);
            if (!name.equals(tb.currentElement().nodeName()))
                tb.error(this);
            tb.popStackToClose(name);
            break;
        } else {
            if (tb.isSpecial(node)) {
                tb.error(this);
                return false;
            }
        }
    }
    return true;
}

Element insertEmpty(Token.StartTag startTag) {
    Tag tag = Tag.valueOf(startTag.name(), settings);
    Element el = new Element(tag, baseUri, startTag.attributes);
    insertNode(el);
    if (startTag.isSelfClosing()) {
        if (tag.isKnownTag()) {
            if (tag.isSelfClosing()) tokeniser.acknowledgeSelfClosingFlag();
        }
        else {
            tag.setSelfClosing();
            tokeniser.acknowledgeSelfClosingFlag();
        }
    }
    return el;
}

Token read() {
    if (!selfClosingFlagAcknowledged) {
        error("Self closing flag not acknowledged");
        selfClosingFlagAcknowledged = true;
    }
    while (!isEmitPending)
        state.read(this, reader);

    // if emit is pending, a non-character token was found: return any chars in buffer, and leave token for next read:
    if (charsBuilder.length() > 0) {
        String str = charsBuilder.toString();
        charsBuilder.delete(0, charsBuilder.length());
        charsString = null;
        return charPending.data(str);
    } else if (charsString != null) {
        Token token = charPending.data(charsString);
        charsString = null;
        return token;
    } else {
        isEmitPending = false;
        return emitPending;
    }
}

void emit(Token token) {
    Validate.isFalse(isEmitPending, "There is an unread token pending!");

    emitPending = token;
    isEmitPending = true;

    if (token.type == Token.TokenType.StartTag) {
        Token.StartTag startTag = (Token.StartTag) token;
        lastStartTag = startTag.tagName;
        if (startTag.selfClosing)
            selfClosingFlagAcknowledged = false;
    } else if (token.type == Token.TokenType.EndTag) {
        Token.EndTag endTag = (Token.EndTag) token;
        if (endTag.attributes != null)
            error("Attributes incorrectly present on end tag");
    }
}

private static void handleRawtext(Token.StartTag startTag, HtmlTreeBuilder tb) {
    tb.insert(startTag);
    tb.tokeniser.transition(TokeniserState.Rawtext);
    tb.markInsertionMode();
    tb.transition(Text);
}

boolean process(Token t, HtmlTreeBuilder tb) {
    switch (t.type) {
        case StartTag:
            Token.StartTag startTag = t.asStartTag();
            String name = startTag.normalName();
            if (name.equals("tr")) {
                tb.clearStackToTableBodyContext();
                tb.insert(startTag);
                tb.transition(InRow);
            } else if (StringUtil.in(name, "th", "td")) {
                tb.error(this);
                tb.processStartTag("tr");
                return tb.process(startTag);
            } else if (StringUtil.in(name, "caption", "col", "colgroup", "tbody", "tfoot", "thead")) {
                return exitTableBody(t, tb);
            } else
                return anythingElse(t, tb);
            break;
        case EndTag:
            Token.EndTag endTag = t.asEndTag();
            name = endTag.normalName();
            if (StringUtil.in(name, "tbody", "tfoot", "thead")) {
                if (!tb.inTableScope(name)) {
                    tb.error(this);
                    return false;
                } else {
                    tb.clearStackToTableBodyContext();
                    tb.pop();
                    tb.transition(InTable);
                }
            } else if (name.equals("table")) {
                return exitTableBody(t, tb);
            } else if (StringUtil.in(name, "body", "caption", "col", "colgroup", "html", "td", "th", "tr")) {
                tb.error(this);
                return false;
            } else
                return anythingElse(t, tb);
            break;
        default:
            return anythingElse(t, tb);
    }
    return true;
}

boolean process(Token t, HtmlTreeBuilder tb) {
    if (t.isStartTag()) {
        Token.StartTag startTag = t.asStartTag();
        String name = startTag.normalName();

        if (StringUtil.in(name, "th", "td")) {
            tb.clearStackToTableRowContext();
            tb.insert(startTag);
            tb.transition(InCell);
            tb.insertMarkerToFormattingElements();
        } else if (StringUtil.in(name, "caption", "col", "colgroup", "tbody", "tfoot", "thead", "tr")) {
            return handleMissingTr(t, tb);
        } else {
            return anythingElse(t, tb);
        }
    } else if (t.isEndTag()) {
        Token.EndTag endTag = t.asEndTag();
        String name = endTag.normalName();

        if (name.equals("tr")) {
            if (!tb.inTableScope(name)) {
                tb.error(this); // frag
                return false;
            }
            tb.clearStackToTableRowContext();
            tb.pop(); // tr
            tb.transition(InTableBody);
        } else if (name.equals("table")) {
            return handleMissingTr(t, tb);
        } else if (StringUtil.in(name, "tbody", "tfoot", "thead")) {
            if (!tb.inTableScope(name)) {
                tb.error(this);
                return false;
            }
            tb.processEndTag("tr");
            return tb.process(t);
        } else if (StringUtil.in(name, "body", "caption", "col", "colgroup", "html", "td", "th")) {
            tb.error(this);
            return false;
        } else {
            return anythingElse(t, tb);
        }
    } else {
        return anythingElse(t, tb);
    }
    return true;
}

protected Element doClone(Node parent) {
