String consumeTagName() {
    // '\t', '\n', '\r', '\f', ' ', '/', '>', nullChar
    // NOTE: out of spec, added '<' to fix common author bugs
    bufferUp();
    final int start = bufPos;
    final int remaining = bufLength;
    final char[] val = charBuf;

    while (bufPos < remaining) {
        final char c = val[bufPos];
        if (c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == ' ' || c == '/' || c == '>' || c == TokeniserState.nullChar)
            break;
        bufPos++;
    }

    return bufPos > start ? cacheString(charBuf, stringCache, start, bufPos - start) : "";
}

void read(Tokeniser t, CharacterReader r) {
    // previous TagOpen state did NOT consume, will have a letter char in current
    //String tagName = r.consumeToAnySorted(tagCharsSorted).toLowerCase();
    String tagName = r.consumeTagName();
    t.tagPending.appendTagName(tagName);

    char c = r.consume();
    switch (c) {
        case '\t':
        case '\n':
        case '\r':
        case '\f':
        case ' ':
            t.transition(BeforeAttributeName);
            break;
        case '/':
            t.transition(SelfClosingStartTag);
            break;
            // intended fall through to next >
        case '>':
            t.emitTagPending();
            t.transition(Data);
            break;
        case nullChar: // replacement
            t.tagPending.appendTagName(replacementStr);
            break;
        case eof: // should emit pending tag?
            t.eofError(this);
            t.transition(Data);
            break;
        default: // buffer underrun
            t.tagPending.appendTagName(c);
    }
}

void read(Tokeniser t, CharacterReader r) {
    char c = r.consume();
    switch (c) {
        case '\t':
        case '\n':
        case '\r':
        case '\f':
        case ' ':
            break; // ignore whitespace
        case '/':
            t.transition(SelfClosingStartTag);
            break;
            // intended fall through as if >
        case '>':
            t.emitTagPending();
            t.transition(Data);
            break;
        case nullChar:
            t.error(this);
            t.tagPending.newAttribute();
            r.unconsume();
            t.transition(AttributeName);
            break;
        case eof:
            t.eofError(this);
            t.transition(Data);
            break;
        case '"':
        case '\'':
        case '<':
        case '=':
            t.error(this);
            t.tagPending.newAttribute();
            t.tagPending.appendAttributeName(c);
            t.transition(AttributeName);
            break;
        default: // A-Z, anything else
            t.tagPending.newAttribute();
            r.unconsume();
            t.transition(AttributeName);
    }
}

public void head(org.jsoup.nodes.Node source, int depth) {
    namespacesStack.push(new HashMap<>(namespacesStack.peek())); // inherit from above on the stack
    if (source instanceof org.jsoup.nodes.Element) {
        org.jsoup.nodes.Element sourceEl = (org.jsoup.nodes.Element) source;

        String prefix = updateNamespaces(sourceEl);
        String namespace = namespacesStack.peek().get(prefix);
        String tagName = sourceEl.tagName();

        Element el = 
            doc.createElementNS(namespace, tagName);
        copyAttributes(sourceEl, el);
        if (dest == null) { // sets up the root
            doc.appendChild(el);
        } else {
            dest.appendChild(el);
        }
        dest = el; // descend
    } else if (source instanceof org.jsoup.nodes.TextNode) {
        org.jsoup.nodes.TextNode sourceText = (org.jsoup.nodes.TextNode) source;
        Text text = doc.createTextNode(sourceText.getWholeText());
        dest.appendChild(text);
    } else if (source instanceof org.jsoup.nodes.Comment) {
        org.jsoup.nodes.Comment sourceComment = (org.jsoup.nodes.Comment) source;
        Comment comment = doc.createComment(sourceComment.getData());
        dest.appendChild(comment);
    } else if (source instanceof org.jsoup.nodes.DataNode) {
        org.jsoup.nodes.DataNode sourceData = (org.jsoup.nodes.DataNode) source;
        Text node = doc.createTextNode(sourceData.getWholeData());
        dest.appendChild(node);
    } else {
        // unhandled
    }
}

