    /**
     * Find the namespace prefix for the specified namespace URI and NodePointer.
     * @param pointer
     * @param namespaceURI
     * @return prefix if found
     * @since JXPath 1.3
     */
    public String findPrefixForNamespaceURI(NodePointer pointer, String namespaceURI) {
        if (namespaceMap.containsKey(namespaceURI)) {
            return namespaceMap.get(namespaceURI);
        }
        if (parent != null) {
            return parent.findPrefixForNamespaceURI(pointer, namespaceURI);
        }
        return null;
    }

    /**
     * Create a new NamespaceResolver.
     */
    public NamespaceResolver() {
        this(null);
    }

public class DOMNodePointer extends NodePointer {

    private static final long serialVersionUID = -8751046933894857319L;

    private Node node;
    private Map<String, String> namespaces;
    private String defaultNamespace;
    private String id;

    public static final String XML_NAMESPACE_URI = 
            "http://www.w3.org/XML/1998/namespace";
    public static final String XMLNS_NAMESPACE_URI = 
            "http://www.w3.org/2000/xmlns/";

    public DOMNodePointer(Node node, Locale locale) {
        super(null, locale);
        this.node = node;
        this.namespaces = new HashMap<>();
    }

public NodePointer createAttribute(JXPathContext context, QName name) {
    if (!(node instanceof Element)) {
        return super.createAttribute(context, name);
    }
    Element element = (Element) node;
    String prefix = name.getPrefix();
    if (prefix != null) {
        String ns = getNamespaceURI(prefix);
        if (ns == null) {
            throw new JXPathException(
                "Unknown namespace prefix: " + prefix);
        }
        element.setAttributeNS(ns, name.toString(), "");
    }
    else {
        if (!element.hasAttribute(name.getName())) {
            element.setAttribute(name.getName(), "");
        }
    }
    NodeIterator it = attributeIterator(name);
    it.setPosition(1);
    return it.getNodePointer();
}

private String getNamespaceURI(String prefix) {
    return namespaces.get(prefix);
}

protected Object functionFloor(EvalContext context) {
    assertArgCount(1);
    double v = InfoSetUtil.doubleValue(getArg1().computeValue(context));
