public boolean setPosition(int position) {
    if (!prepared) {
        prepared = true;
        BasicNodeSet nodeSet = (BasicNodeSet) getNodeSet();
        ArrayList<NodePointer> pointers = new ArrayList<>();
        for (int i = 0; i < contexts.length; i++) {
            EvalContext ctx = (EvalContext) contexts[i];
            while (ctx.nextSet()) {
                while (ctx.nextNode()) {
                    NodePointer ptr = ctx.getCurrentNodePointer();
                    if (!pointers.contains(ptr)) {
                        nodeSet.add(ptr);
                        pointers.add(ptr);
                    }
                }
            }
        }
    }
    return super.setPosition(position);
}

public static boolean testNode(Node node, NodeTest test) {
    if (test == null) {
        return true;
    }
    if (test instanceof NodeNameTest) {
        if (node.getNodeType() != Node.ELEMENT_NODE) {
            return false;
        }

        NodeNameTest nodeNameTest = (NodeNameTest) test;
        QName testName = nodeNameTest.getNodeName();
        String namespaceURI = nodeNameTest.getNamespaceURI();
        boolean wildcard = nodeNameTest.isWildcard();
        String testPrefix = testName.getPrefix();
        if (wildcard && testPrefix == null) {
            return true;
        }
        if (wildcard
            || testName.getName()
                    .equals(DOMNodePointer.getLocalName(node))) {
            String nodeNS = DOMNodePointer.getNamespaceURI(node);
            return equalStrings(namespaceURI, nodeNS) || nodeNS == null
                    && equalStrings(testPrefix, getPrefix(node));
        }
        return false;
    }
    if (test instanceof NodeTypeTest) {
        int nodeType = node.getNodeType();
        switch (((NodeTypeTest) test).getNodeType()) {
            case Compiler.NODE_TYPE_NODE :
                return nodeType == Node.ELEMENT_NODE
                        || nodeType == Node.DOCUMENT_NODE;
            case Compiler.NODE_TYPE_TEXT :
                return nodeType == Node.CDATA_SECTION_NODE
                    || nodeType == Node.TEXT_NODE;
            case Compiler.NODE_TYPE_COMMENT :
                return nodeType == Node.COMMENT_NODE;
            case Compiler.NODE_TYPE_PI :
                return nodeType == Node.PROCESSING_INSTRUCTION_NODE;
        }
        return false;
    }
    if (test instanceof ProcessingInstructionTest) {
        if (node.getNodeType() == Node.PROCESSING_INSTRUCTION_NODE) {
            String testPI = ((ProcessingInstructionTest) test).getTarget();
            String nodePI = ((ProcessingInstruction) node).getTarget();
            return testPI.equals(nodePI);
        }
    }
    return false;
}

private boolean testAttr(Attr attr) {
    String nodePrefix = DOMNodePointer.getPrefix(attr);
    String nodeLocalName = DOMNodePointer.getLocalName(attr);

    if (nodePrefix != null && nodePrefix.equals("xmlns")) {
        return false;
    }

    if (nodePrefix == null && nodeLocalName.equals("xmlns")) {
        return false;
    }

    String testLocalName = name.getName();
    if (testLocalName.equals("*") || testLocalName.equals(nodeLocalName)) {
        String testPrefix = name.getPrefix();

        if (equalStrings(testPrefix, nodePrefix)) {
            return true;
        }
        String testNS = null;
        if (testPrefix != null) {
            testNS = parent.getNamespaceURI(testPrefix);
        }
        String nodeNS = null;
        if (nodePrefix != null) {
            nodeNS = parent.getNamespaceURI(nodePrefix);
        }
        return equalStrings(testNS, nodeNS);
    }
    return false;
}

public JDOMAttributeIterator(NodePointer parent, QName name) {
    this.parent = parent;
    if (parent.getNode() instanceof Element) {
        Element element = (Element) parent.getNode();
        String prefix = name.getPrefix();
        Namespace ns = null;
        if (prefix != null) {
            if (prefix.equals("xml")) {
                ns = Namespace.XML_NAMESPACE;
            }
            else {
                String uri = parent.getNamespaceResolver().getNamespaceURI(prefix);
                if (uri != null) {
                    ns = Namespace.getNamespace(prefix, uri);
                }
                if (ns == null) {
                    // TBD: no attributes
                    attributes = Collections.EMPTY_LIST;
                    return;
                }
            }
        }
        else {
            ns = Namespace.NO_NAMESPACE;
        }

        String lname = name.getName();
        if (!lname.equals("*")) {
            attributes = new ArrayList();
            if (ns != null) {
            Attribute attr = element.getAttribute(lname, ns);
            if (attr != null) {
                attributes.add(attr);
                }
            }
        }
        else {
            attributes = new ArrayList();
            List allAttributes = element.getAttributes();
            for (int i = 0; i < allAttributes.size(); i++) {
                Attribute attr = (Attribute) allAttributes.get(i);
                if (attr.getNamespace().equals(ns)) {
                    attributes.add(attr);
                }
            }
        }
    }
}

public class AttributeContext extends EvalContext {

    private NodeTest nodeTest;
    private boolean setStarted = false;
    private NodeIterator iterator;
    private NodePointer currentNodePointer;

    /**
     * @param parentContext represents the previous step on the path
     * @param nodeTest is the name of the attribute we are looking for
     */
    public AttributeContext(EvalContext parentContext, NodeTest nodeTest) {
        super(parentContext);
        this.nodeTest = nodeTest;
    }

public boolean nextNode() {
    super.setPosition(getCurrentPosition() + 1);
    if (!setStarted) {
        setStarted = true;
        if (!(nodeTest instanceof NodeNameTest)) {
            return false;
        }
        QName name = ((NodeNameTest) nodeTest).getNodeName();
        iterator =
            parentContext.getCurrentNodePointer().attributeIterator(name);
    }
    if (iterator == null) {
        return false;
    }
    if (!iterator.setPosition(iterator.getPosition() + 1)) {
        return false;
    }
    currentNodePointer = iterator.getNodePointer();
    return true;
}

private int getRelativePositionByQName() {
    int count = 0;
    Node n = node.getPreviousSibling();
    while (n != null) {
        if (n.getNodeType() == Node.ELEMENT_NODE) {
            String nm = n.getNodeName();
            if (nm.equals(node.getNodeName())) {
                count++;
            }
        }
        n = n.getPreviousSibling();
    }
    return count + 1;
}

private int getRelativePositionByQName() {
    if (node instanceof Element) {
        Object parent = ((Element) node).getParent();
        if (!(parent instanceof Element)) {
            return 1;
        }

        List children = ((Element) parent).getContent();
        int count = 0;
        String name = ((Element) node).getQualifiedName();
        for (int i = 0; i < children.size(); i++) {
            Object child = children.get(i);
            if ((child instanceof Element)
                && ((Element) child).getQualifiedName().equals(name)) {
                count++;
            }
            if (child == node) {
                break;
            }
        }
        return count + 1;
    }
    return 1;
}

private boolean compute(Object left, Object right) {
    left = reduce(left);
    right = reduce(right);

    if (left instanceof InitialContext) {
        ((InitialContext) left).reset();
    }
    if (right instanceof InitialContext) {
        ((InitialContext) right).reset();
    }
    if (left instanceof Iterator && right instanceof Iterator) {
        return findMatch((Iterator) left, (Iterator) right);
    }
    if (left instanceof Iterator) {
        return containsMatch((Iterator) left, right);
    }
    if (right instanceof Iterator) {
        return containsMatch((Iterator) right, left);
    }
    double ld = InfoSetUtil.doubleValue(left);
    if (Double.isNaN(ld)) {
        return false;
    }
    double rd = InfoSetUtil.doubleValue(right);
    if (Double.isNaN(rd)) {
        return false;
    }
    return evaluateCompare(ld == rd ? 0 : ld < rd ? -1 : 1);
}

public int getLength() {
    if (getBaseValue() == null) {
        return 0;
    }
    return ValueUtils.getLength(getBaseValue());
}

public static String getNamespaceURI(Node node) {
    if (node instanceof Document) {
        node = ((Document) node).getDocumentElement();
    }

    Element element = (Element) node;

    String uri = element.getNamespaceURI();
    if (uri == null) {
        String prefix = getPrefix(node);
        String qname = prefix == null ? "xmlns" : "xmlns:" + prefix;

        Node aNode = node;
        while (aNode != null) {
            if (aNode.getNodeType() == Node.ELEMENT_NODE) {
                Attr attr = ((Element) aNode).getAttributeNode(qname);
                if (attr != null) {
                    return attr.getValue();
                }
            }
            aNode = aNode.getParentNode();
        }
        return null;
    }
    return uri;
}

