public boolean isFeasible(final double[] x) {
    if (boundaries == null) {
        return true;
    }


    for (int i = 0; i < x.length; i++) {
        if (x[i] < boundaries[i][0]) {
            return false;
        }
        if (x[i] > boundaries[i][1]) {
            return false;
        }
    }
    return true;
}

private void checkParameters() {
    final double[] init = getStartPoint();
    final double[] lB = getLowerBound();
    final double[] uB = getUpperBound();

    // Checks whether there is at least one finite bound value.
    boolean hasFiniteBounds = false;
    for (int i = 0; i < lB.length; i++) {
        if (!Double.isInfinite(lB[i]) &&
            !Double.isInfinite(uB[i])) {
            hasFiniteBounds = true;
            break;
        }
    }
    // Checks whether there is at least one infinite bound value.
    boolean hasInfiniteBounds = false;
    if (hasFiniteBounds) {
        for (int i = 0; i < lB.length; i++) {
            if (Double.isInfinite(lB[i]) ||
                Double.isInfinite(uB[i])) {
                hasInfiniteBounds = true;
                break;
            }
        }

        if (hasInfiniteBounds) {
            // If there is at least one finite bound, none can be infinite,
            // because mixed cases are not supported by the current code.
            throw new MathUnsupportedOperationException();
        } else {
            // Convert API to internal handling of boundaries.
            boundaries = new double[2][];
            boundaries[0] = lB;
            boundaries[1] = uB;

            // Abort early if the normalization will overflow (cf. "encode" method).
        }
    } else {
        // Convert API to internal handling of boundaries.
        boundaries = null;
    }

    if (inputSigma != null) {
        if (inputSigma.length != init.length) {
            throw new DimensionMismatchException(inputSigma.length, init.length);
        }
        for (int i = 0; i < init.length; i++) {
            if (inputSigma[i] < 0) {
                throw new NotPositiveException(inputSigma[i]);
            }
            if (boundaries != null) {
                if (inputSigma[i] > boundaries[1][i] - boundaries[0][i]) {
                    throw new OutOfRangeException(inputSigma[i], 0, boundaries[1][i] - boundaries[0][i]);
                }
            }
        }
    }
}

/**
 * Update of the evolution paths ps and pc.
 *
 * @param zmean Weighted row matrix of the gaussian random numbers generating
 * the current offspring.
 * @param xold xmean matrix of the previous generation.
 * @return hsig flag indicating a small correction.
 */
private boolean updateEvolutionPaths(RealMatrix zmean, RealMatrix xold) {
    ps = ps.scalarMultiply(1. - cs).add(
            B.multiply(zmean).scalarMultiply(
                    Math.sqrt(cs * (2. - cs) * mueff)));
    normps = ps.getFrobeniusNorm();
    boolean hsig = normps /
        Math.sqrt(1. - Math.pow(1. - cs, 2. * iterations)) /
            chiN < 1.4 + 2. / (dimension + 1.);
    pc = pc.scalarMultiply(1. - cc);
    if (hsig) {
        pc = pc.add(xmean.subtract(xold).scalarMultiply(
                Math.sqrt(cc * (2. - cc) * mueff) / sigma));
    }
    return hsig;
}

/**
 * Update of the covariance matrix C for diagonalOnly > 0
 *
 * @param hsig Flag indicating a small correction.
 * @param bestArz Fitness-sorted matrix of the gaussian random values of the
 * current offspring.
 * @param xold xmean matrix of the previous generation.
 */
private void updateCovarianceDiagonalOnly(boolean hsig,
                                          final RealMatrix bestArz,
                                          final RealMatrix xold) {
    // minor correction if hsig==false
    double oldFac = hsig ? 0 : ccov1Sep * cc * (2. - cc);
    oldFac += 1. - ccov1Sep - ccovmuSep;
    diagC = diagC.scalarMultiply(oldFac) // regard old matrix
            // plus rank one update
            .add(square(pc).scalarMultiply(ccov1Sep))
            // plus rank mu update
            .add((times(diagC, square(bestArz).multiply(weights)))
                    .scalarMultiply(ccovmuSep));
    diagD = sqrt(diagC); // replaces eig(C)
    if (diagonalOnly > 1 && iterations > diagonalOnly) {
        // full covariance matrix from now on
        diagonalOnly = 0;
        B = eye(dimension, dimension);
        BD = diag(diagD);
        C = diag(diagC);
    }
}

/**
 * Update of the covariance matrix C.
 *
 * @param hsig Flag indicating a small correction.
 * @param bestArx Fitness-sorted matrix of the argument vectors producing the
 * current offspring.
 * @param arz Unsorted matrix containing the gaussian random values of the
 * current offspring.
 * @param arindex Indices indicating the fitness-order of the current offspring.
 * @param xold xmean matrix of the previous generation.
 */
private void updateCovariance(boolean hsig, final RealMatrix bestArx,
        final RealMatrix arz, final int[] arindex, final RealMatrix xold) {
    double negccov = 0;
    if (ccov1 + ccovmu > 0) {
        RealMatrix arpos = bestArx.subtract(repmat(xold, 1, mu))
                .scalarMultiply(1. / sigma); // mu difference vectors
        RealMatrix roneu = pc.multiply(pc.transpose())
                .scalarMultiply(ccov1); // rank one update
        // minor correction if hsig==false
        double oldFac = hsig ? 0 : ccov1 * cc * (2. - cc);
        oldFac += 1. - ccov1 - ccovmu;
        if (isActiveCMA) {
            // Adapt covariance matrix C active CMA
            negccov = (1. - ccovmu) * 0.25 * mueff /
            (Math.pow(dimension + 2., 1.5) + 2. * mueff);
            double negminresidualvariance = 0.66;
            // keep at least 0.66 in all directions, small popsize are most
            // critical
            double negalphaold = 0.5; // where to make up for the variance
                                      // loss,
                                      // prepare vectors, compute negative updating matrix Cneg
            int[] arReverseIndex = reverse(arindex);
            RealMatrix arzneg
                = selectColumns(arz, MathArrays.copyOf(arReverseIndex, mu));
            RealMatrix arnorms = sqrt(sumRows(square(arzneg)));
            int[] idxnorms = sortedIndices(arnorms.getRow(0));
            RealMatrix arnormsSorted = selectColumns(arnorms, idxnorms);
            int[] idxReverse = reverse(idxnorms);
            RealMatrix arnormsReverse = selectColumns(arnorms, idxReverse);
            arnorms = divide(arnormsReverse, arnormsSorted);
            int[] idxInv = inverse(idxnorms);
            RealMatrix arnormsInv = selectColumns(arnorms, idxInv);
            // check and set learning rate negccov
            double negcovMax = (1. - negminresidualvariance) /
                    square(arnormsInv).multiply(weights).getEntry(0, 0);
            if (negccov > negcovMax) {
                negccov = negcovMax;
            }
            arzneg = times(arzneg, repmat(arnormsInv, dimension, 1));
            RealMatrix artmp = BD.multiply(arzneg);
            RealMatrix Cneg = artmp.multiply(diag(weights)).multiply(
                    artmp.transpose());
            oldFac += negalphaold * negccov;
            C = C.scalarMultiply(oldFac)
                    // regard old matrix
                    .add(roneu)
                    // plus rank one update
                    .add(arpos.scalarMultiply(
                            // plus rank mu update
                            ccovmu + (1. - negalphaold) * negccov)
                            .multiply(
                                    times(repmat(weights, 1, dimension),
                                            arpos.transpose())))
                    .subtract(Cneg.scalarMultiply(negccov));
        } else {
            // Adapt covariance matrix C - nonactive
            C = C.scalarMultiply(oldFac) // regard old matrix
                    .add(roneu)
                    // plus rank one update
                    .add(arpos.scalarMultiply(ccovmu) // plus rank mu update
                            .multiply(
                                    times(repmat(weights, 1, dimension),
                                            arpos.transpose())));
        }
    }
    updateBD(negccov);
}

/**
 * Update B and D from C.
 *
 * @param negccov Negative covariance factor.
 */
private void updateBD(double negccov) {
    if (ccov1 + ccovmu + negccov > 0 &&
            (iterations % 1. / (ccov1 + ccovmu + negccov) / dimension / 10.) < 1.) {
        // to achieve O(N^2)
        C = triu(C, 0).add(triu(C, 1).transpose());
        // enforce symmetry to prevent complex numbers
        EigenDecomposition eig = new EigenDecomposition(C);
        B = eig.getV(); // eigen decomposition, B==normalized eigenvectors
        D = eig.getD();
        diagD = diag(D);
        if (min(diagD) <= 0) {
            for (int i = 0; i < dimension; i++) {
                if (diagD.getEntry(i, 0) < 0) {
                    diagD.setEntry(i, 0, 0.);
                }
            }
            double tfac = max(diagD) / 1e14;
            C = C.add(eye(dimension, dimension).scalarMultiply(tfac));
            diagD = diagD.add(ones(dimension, 1).scalarMultiply(tfac));
        }
        if (max(diagD) > 1e14 * min(diagD)) {
            double tfac = max(diagD) / 1e14 - min(diagD);
            C = C.add(eye(dimension, dimension).scalarMultiply(tfac));
            diagD = diagD.add(ones(dimension, 1).scalarMultiply(tfac));
        }
        diagC = diag(C);
        diagD = sqrt(diagD); // D contains standard deviations now
        BD = times(B, repmat(diagD.transpose(), dimension, 1)); // O(n^2)
    }
}

/**
 * Pushes the current best fitness value in a history queue.
 *
 * @param vals History queue.
 * @param val Current best fitness value.
 */
private static void push(double[] vals, double val) {
    for (int i = vals.length-1; i > 0; i--) {
        vals[i] = vals[i-1];
    }
    vals[0] = val;
}

public class RectangularCholeskyDecomposition {

    /** Permutated Cholesky root of the symmetric positive semidefinite matrix. */
    private final RealMatrix root;

    /** Rank of the symmetric positive semidefinite matrix. */
    private int rank;

    /**
     * Decompose a symmetric positive semidefinite matrix.
     *
     * @param matrix Symmetric positive semidefinite matrix.
     * @param small Diagonal elements threshold under which  column are
     * considered to be dependent on previous ones and are discarded.
     * @exception NonPositiveDefiniteMatrixException if the matrix is not
     * positive semidefinite.
     */
    public RectangularCholeskyDecomposition(RealMatrix matrix, double small)
        throws NonPositiveDefiniteMatrixException {

        final int order = matrix.getRowDimension();
        final double[][] c = matrix.getData();
        final double[][] b = new double[order][order];

        int[] swap  = new int[order];
        int[] index = new int[order];
        for (int i = 0; i < order; ++i) {
            index[i] = i;
        }

        int r = 0;
        for (boolean loop = true; loop;) {

            // find maximal diagonal element
            swap[r] = r;
            for (int i = r + 1; i < order; ++i) {
                int ii  = index[i];
                int isi = index[swap[i]];
                if (c[ii][ii] > c[isi][isi]) {
                    swap[r] = i;
                }
            }


            // swap elements
            if (swap[r] != r) {
                int tmp = index[r];
                index[r] = index[swap[r]];
                index[swap[r]] = tmp;
            }

            // check diagonal element
            int ir = index[r];
            if (c[ir][ir] < small) {

                if (r == 0) {
                    throw new NonPositiveDefiniteMatrixException(c[ir][ir], ir, small);
                }

                // check remaining diagonal elements
                for (int i = r; i < order; ++i) {
                    if (c[index[i]][index[i]] < -small) {
                        // there is at least one sufficiently negative diagonal element,
                        // the symmetric positive semidefinite matrix is wrong
                        throw new NonPositiveDefiniteMatrixException(c[index[i]][index[i]], i, small);
                    }
                }

                // all remaining diagonal elements are close to zero, we consider we have
                // found the rank of the symmetric positive semidefinite matrix
                ++r;
                loop = false;

            } else {

                // transform the matrix
                final double sqrt = FastMath.sqrt(c[ir][ir]);
                b[r][r] = sqrt;
                final double inverse  = 1 / sqrt;
                for (int i = r + 1; i < order; ++i) {
                    final int ii = index[i];
                    final double e = inverse * c[ii][ir];
                    b[i][r] = e;
                    c[ii][ii] -= e * e;
                    for (int j = r + 1; j < i; ++j) {
                        final int ij = index[j];
                        final double f = c[ii][ij] - e * b[j][r];
                        c[ii][ij] = f;
                        c[ij][ii] = f;
                    }
                }

                // prepare next iteration
                loop = ++r < order;
            }
        }

        // build the root matrix
        rank = r;
        root = MatrixUtils.createRealMatrix(order, r);
        for (int i = 0; i < order; ++i) {
            for (int j = 0; j < r; ++j) {
                root.setEntry(index[i], j, b[i][j]);
            }
        }

    }

    /** Get the root of the covariance matrix.
     * The root is the rectangular matrix <code>B</code> such that
     * the covariance matrix is equal to <code>B.B<sup>T</sup></code>
     * @return root of the square matrix
     * @see #getRank()
     */
    public RealMatrix getRootMatrix() {
        return root;
    }

protected UnivariatePointValuePair doOptimize() {
    final boolean isMinim = getGoalType() == GoalType.MINIMIZE;
    final double lo = getMin();
    final double mid = getStartValue();
    final double hi = getMax();

    // Optional additional convergence criteria.
    final ConvergenceChecker<UnivariatePointValuePair> checker
        = getConvergenceChecker();

    double a;
    double b;
    if (lo < hi) {
        a = lo;
        b = hi;
    } else {
        a = hi;
        b = lo;
    }

    double x = mid;
    double v = x;
    double w = x;
    double d = 0;
    double e = 0;
    double fx = computeObjectiveValue(x);
    if (!isMinim) {
        fx = -fx;
    }
    double fv = fx;
    double fw = fx;

    UnivariatePointValuePair previous = null;
    UnivariatePointValuePair current
        = new UnivariatePointValuePair(x, isMinim ? fx : -fx);
    // Best point encountered so far (which is the initial guess).

    int iter = 0;
    while (true) {
        final double m = 0.5 * (a + b);
        final double tol1 = relativeThreshold * FastMath.abs(x) + absoluteThreshold;
        final double tol2 = 2 * tol1;

        // Default stopping criterion.
        final boolean stop = FastMath.abs(x - m) <= tol2 - 0.5 * (b - a);
        if (!stop) {
            double p = 0;
            double q = 0;
            double r = 0;
            double u = 0;

            if (FastMath.abs(e) > tol1) { // Fit parabola.
                r = (x - w) * (fx - fv);
                q = (x - v) * (fx - fw);
                p = (x - v) * q - (x - w) * r;
                q = 2 * (q - r);

                if (q > 0) {
                    p = -p;
                } else {
                    q = -q;
                }

                r = e;
                e = d;

                if (p > q * (a - x) &&
                    p < q * (b - x) &&
                    FastMath.abs(p) < FastMath.abs(0.5 * q * r)) {
                    // Parabolic interpolation step.
                    d = p / q;
                    u = x + d;

                    // f must not be evaluated too close to a or b.
                    if (u - a < tol2 || b - u < tol2) {
                        if (x <= m) {
                            d = tol1;
                        } else {
                            d = -tol1;
                        }
                    }
                } else {
                    // Golden section step.
                    if (x < m) {
                        e = b - x;
                    } else {
                        e = a - x;
                    }
                    d = GOLDEN_SECTION * e;
                }
            } else {
                // Golden section step.
                if (x < m) {
                    e = b - x;
                } else {
                    e = a - x;
                }
                d = GOLDEN_SECTION * e;
            }

            // Update by at least "tol1".
            if (FastMath.abs(d) < tol1) {
                if (d >= 0) {
                    u = x + tol1;
                } else {
                    u = x - tol1;
                }
            } else {
                u = x + d;
            }

            double fu = computeObjectiveValue(u);
            if (!isMinim) {
                fu = -fu;
            }

            // User-defined convergence checker.
            previous = current;
            current = new UnivariatePointValuePair(u, isMinim ? fu : -fu);

            if (checker != null) {
                if (checker.converged(iter, previous, current)) {
                    return best(current, previous, isMinim);
                }
            }

            // Update a, b, v, w and x.
            if (fu <= fx) {
                if (u < x) {
                    b = x;
                } else {
                    a = x;
                }
                v = w;
                fv = fw;
                w = x;
                fw = fx;
                x = u;
                fx = fu;
            } else {
                if (u < x) {
                    a = u;
                } else {
                    b = u;
                }
                if (fu <= fw ||
                    Precision.equals(w, x)) {
                    v = w;
                    fv = fw;
                    w = u;
                    fw = fu;
                } else if (fu <= fv ||
                           Precision.equals(v, x) ||
                           Precision.equals(v, w)) {
                    v = u;
                    fv = fu;
                }
            }
        } else { // Default termination (Brent's criterion).
            return
                        best(current,
                             previous,
                        isMinim);
        }
        ++iter;
    }
}

