public Rotation(Vector3D u1, Vector3D u2, Vector3D v1, Vector3D v2) {

// norms computation
double u1u1 = u1.getNormSq();
double u2u2 = u2.getNormSq();
double v1v1 = v1.getNormSq();
double v2v2 = v2.getNormSq();
if ((u1u1 == 0) || (u2u2 == 0) || (v1v1 == 0) || (v2v2 == 0)) {
  throw MathRuntimeException.createIllegalArgumentException(LocalizedFormats.ZERO_NORM_FOR_ROTATION_DEFINING_VECTOR);
}

// normalize v1 in order to have (v1'|v1') = (u1|u1)
v1 = new Vector3D(FastMath.sqrt(u1u1 / v1v1), v1);

// adjust v2 in order to have (u1|u2) = (v1'|v2') and (v2'|v2') = (u2|u2)
double u1u2   = u1.dotProduct(u2);
double v1v2   = v1.dotProduct(v2);
double coeffU = u1u2 / u1u1;
double coeffV = v1v2 / u1u1;
double beta   = FastMath.sqrt((u2u2 - u1u2 * coeffU) / (v2v2 - v1v2 * coeffV));
double alpha  = coeffU - beta * coeffV;
v2 = new Vector3D(alpha, v1, beta, v2);

// preliminary computation
Vector3D uRef  = u1;
Vector3D vRef  = v1;
Vector3D v1Su1 = v1.subtract(u1);
Vector3D v2Su2 = v2.subtract(u2);
Vector3D k     = v1Su1.crossProduct(v2Su2);
Vector3D u3    = u1.crossProduct(u2);
double c       = k.dotProduct(u3);
if (c == 0) {
  // the (q1, q2, q3) vector is close to the (u1, u2) plane
  // we try other vectors
  Vector3D v3 = Vector3D.crossProduct(v1, v2);
  Vector3D v3Su3 = v3.subtract(u3);
  k = v1Su1.crossProduct(v3Su3);
  Vector3D u2Prime = u1.crossProduct(u3);
  c = k.dotProduct(u2Prime);

  if (c == 0) {
    // the (q1, q2, q3) vector is also close to the (u1, u3) plane,
    // it is almost aligned with u1: we try (u2, u3) and (v2, v3)
    k = v2Su2.crossProduct(v3Su3);
    c = k.dotProduct(u2.crossProduct(u3));

    if (c == 0) {
      // the (q1, q2, q3) vector is aligned with everything
      // this is really the identity rotation
      q0 = 1.0;
      q1 = 0.0;
      q2 = 0.0;
      q3 = 0.0;
      return;
    }

    // we will have to use u2 and v2 to compute the scalar part
    uRef = u2;
    vRef = v2;

  }

}

// compute the vectorial part
c = FastMath.sqrt(c);
double inv = 1.0 / (c + c);
q1 = inv * k.getX();
q2 = inv * k.getY();
q3 = inv * k.getZ();

// compute the scalar part
 k = new Vector3D(uRef.getY() * q3 - uRef.getZ() * q2,
                  uRef.getZ() * q1 - uRef.getX() * q3,
                  uRef.getX() * q2 - uRef.getY() * q1);
q0 = vRef.dotProduct(k) / (2 * k.getNormSq());

}

public double abs() {
    if (isNaN) {
        return Double.NaN;
    }

    if (isInfinite()) {
        return Double.POSITIVE_INFINITY;
    }

    if (FastMath.abs(real) < FastMath.abs(imaginary)) {
        if (imaginary == 0.0) {
            return FastMath.abs(real);
        }
        double q = real / imaginary;
        return FastMath.abs(imaginary) * FastMath.sqrt(1 + q * q);
    } else {
        if (real == 0.0) {
            return FastMath.abs(imaginary);
        }
        double q = imaginary / real;
        return FastMath.abs(real) * FastMath.sqrt(1 + q * q);
    }
}

public Complex add(Complex rhs)
    throws NullArgumentException {
    MathUtils.checkNotNull(rhs);
    return createComplex(real + rhs.getReal(),
        imaginary + rhs.getImaginary());
}

public Complex conjugate() {
    if (isNaN) {
        return NaN;
    }
    return createComplex(real, -imaginary);
}

public Complex divide(Complex rhs)
    throws NullArgumentException {
    MathUtils.checkNotNull(rhs);
    if (isNaN || rhs.isNaN) {
        return NaN;
    }

    double c = rhs.getReal();
    double d = rhs.getImaginary();
    if (c == 0.0 && d == 0.0) {
        return NaN;
    }

    if (rhs.isInfinite() && !isInfinite()) {
        return ZERO;
    }

    if (FastMath.abs(c) < FastMath.abs(d)) {
        double q = c / d;
        double denominator = c * q + d;
        return createComplex((real * q + imaginary) / denominator,
            (imaginary * q - real) / denominator);
    } else {
        double q = d / c;
        double denominator = d * q + c;
        return createComplex((imaginary * q + real) / denominator,
            (imaginary - real * q) / denominator);
        }
    }

public boolean equals(Object other) {
    if (this == other) {
        return true;
    }
    if (other instanceof Complex){
        Complex rhs = (Complex)other;
        if (rhs.isNaN) {
            return isNaN;
        } else {
            return (real == rhs.real) && (imaginary == rhs.imaginary);
        }
    }
    return false;
}

public int hashCode() {
    if (isNaN) {
        return 7;
    }
    return 37 * (17 * MathUtils.hash(imaginary) +
        MathUtils.hash(real));
}

public Complex multiply(Complex rhs)
    throws NullArgumentException {
    MathUtils.checkNotNull(rhs);
    if (isNaN || rhs.isNaN) {
        return NaN;
    }
    if (Double.isInfinite(real) || Double.isInfinite(imaginary) ||
        Double.isInfinite(rhs.real)|| Double.isInfinite(rhs.imaginary)) {
        // we don't use Complex.isInfinite() to avoid testing for NaN again
        return INF;
    }
    return createComplex(real * rhs.real - imaginary * rhs.imaginary,
            real * rhs.imaginary + imaginary * rhs.real);
}

public Complex multiply(double rhs) {
    if (isNaN || Double.isNaN(rhs)) {
        return NaN;
    }
    if (Double.isInfinite(real) || Double.isInfinite(imaginary) ||
        Double.isInfinite(rhs)) {
        // we don't use Complex.isInfinite() to avoid testing for NaN again
        return INF;
    }
    return createComplex(real * rhs, imaginary * rhs);
}

public Complex negate() {
    if (isNaN) {
        return NaN;
    }

    return createComplex(-real, -imaginary);
}

public Complex subtract(Complex rhs)
    throws NullArgumentException {
    MathUtils.checkNotNull(rhs);
    if (isNaN || rhs.isNaN) {
        return NaN;
    }

    return createComplex(real - rhs.getReal(),
        imaginary - rhs.getImaginary());
}

public Complex acos() {
    if (isNaN) {
        return NaN;
    }

    return this.add(this.sqrt1z().multiply(Complex.I)).log()
          .multiply(Complex.I.negate());
}

public Complex asin() {
    if (isNaN) {
        return NaN;
    }

    return sqrt1z().add(this.multiply(Complex.I)).log()
          .multiply(Complex.I.negate());
}

public Complex atan() {
    if (isNaN) {
        return NaN;
    }

    return this.add(Complex.I).divide(Complex.I.subtract(this)).log()
        .multiply(Complex.I.divide(createComplex(2.0, 0.0)));
}

public Complex cos() {
    if (isNaN) {
        return NaN;
    }

    return createComplex(FastMath.cos(real) * MathUtils.cosh(imaginary),
        -FastMath.sin(real) * MathUtils.sinh(imaginary));
}

public Complex cosh() {
    if (isNaN) {
        return NaN;
    }

    return createComplex(MathUtils.cosh(real) * FastMath.cos(imaginary),
        MathUtils.sinh(real) * FastMath.sin(imaginary));
}

public Complex exp() {
    if (isNaN) {
        return NaN;
    }

    double expReal = FastMath.exp(real);
    return createComplex(expReal *  FastMath.cos(imaginary), expReal * FastMath.sin(imaginary));
}

public Complex log() {
    if (isNaN) {
        return NaN;
    }

    return createComplex(FastMath.log(abs()),
        FastMath.atan2(imaginary, real));
}

public Complex pow(Complex x)
    throws NullArgumentException {
    MathUtils.checkNotNull(x);
    return this.log().multiply(x).exp();
}

public Complex sin() {
    if (isNaN) {
        return NaN;
    }

    return createComplex(FastMath.sin(real) * MathUtils.cosh(imaginary),
        FastMath.cos(real) * MathUtils.sinh(imaginary));
}

public Complex sinh() {
    if (isNaN) {
        return NaN;
    }

    return createComplex(MathUtils.sinh(real) * FastMath.cos(imaginary),
        MathUtils.cosh(real) * FastMath.sin(imaginary));
}

public Complex sqrt() {
    if (isNaN) {
        return NaN;
    }

    if (real == 0.0 && imaginary == 0.0) {
        return createComplex(0.0, 0.0);
    }

    double t = FastMath.sqrt((FastMath.abs(real) + abs()) / 2.0);
    if (real >= 0.0) {
        return createComplex(t, imaginary / (2.0 * t));
    } else {
        return createComplex(FastMath.abs(imaginary) / (2.0 * t),
            MathUtils.indicator(imaginary) * t);
        }
    }

public Complex tan() {
    if (isNaN) {
        return NaN;
    }

    double real2 = 2.0 * real;
    double imaginary2 = 2.0 * imaginary;
    double d = FastMath.cos(real2) + MathUtils.cosh(imaginary2);

    return createComplex(FastMath.sin(real2) / d, MathUtils.sinh(imaginary2) / d);
}

protected Dfp(final DfpField field, double x) {

    // initialize as if 0
    mant = new int[field.getRadixDigits()];
    sign = 1;
    exp = 0;
    nans = FINITE;
    this.field = field;

    long bits = Double.doubleToLongBits(x);
    long mantissa = bits & 0x000fffffffffffffL;
    int exponent = (int) ((bits & 0x7ff0000000000000L) >> 52) - 1023;

    if (exponent == -1023) {
        // Zero or sub-normal
        if (x == 0) {
            // make sure 0 has the right sign
            return;
        }

        exponent++;

        // Normalize the subnormal number
        while ( (mantissa & 0x0010000000000000L) == 0) {
            exponent--;
            mantissa <<= 1;
        }
        mantissa &= 0x000fffffffffffffL;
    }

    if (exponent == 1024) {
        // infinity or NAN
        if (x != x) {
            sign = (byte) 1;
            nans = QNAN;
        } else if (x < 0) {
            sign = (byte) -1;
            nans = INFINITE;
        } else {
            sign = (byte) 1;
            nans = INFINITE;
        }
        return;
    }

    Dfp xdfp = new Dfp(field, mantissa);
    xdfp = xdfp.divide(new Dfp(field, 4503599627370496l)).add(field.getOne());  // Divide by 2^52, then add one
    xdfp = xdfp.multiply(DfpMath.pow(field.getTwo(), exponent));

    if ((bits & 0x8000000000000000L) != 0) {
        xdfp = xdfp.negate();
    }

    System.arraycopy(xdfp.mant, 0, mant, 0, mant.length);
    sign = xdfp.sign;
    exp  = xdfp.exp;
    nans = xdfp.nans;

}

public double toDouble() {

    if (isInfinite()) {
        if (lessThan(getZero())) {
            return Double.NEGATIVE_INFINITY;
        } else {
            return Double.POSITIVE_INFINITY;
        }
    }

    if (isNaN()) {
        return Double.NaN;
    }

    Dfp y = this;
    boolean negate = false;
    if (lessThan(getZero())) {
        y = negate();
        negate = true;
    }

    /* Find the exponent, first estimate by integer log10, then adjust.
     Should be faster than doing a natural logarithm.  */
    int exponent = (int)(y.log10() * 3.32);
    if (exponent < 0) {
        exponent--;
    }

    Dfp tempDfp = DfpMath.pow(getTwo(), exponent);
    while (tempDfp.lessThan(y) || tempDfp.equals(y)) {
        tempDfp = tempDfp.multiply(2);
        exponent++;
    }
    exponent--;

    /* We have the exponent, now work on the mantissa */

    y = y.divide(DfpMath.pow(getTwo(), exponent));
    if (exponent > -1023) {
        y = y.subtract(getOne());
    }

    if (exponent < -1074) {
        return 0;
    }

    if (exponent > 1023) {
        return negate ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY;
    }


    y = y.multiply(newInstance(4503599627370496l)).rint();
    String str = y.toString();
    str = str.substring(0, str.length()-1);
    long mantissa = Long.parseLong(str);

    if (mantissa == 4503599627370496L) {
        // Handle special case where we round up to next power of two
        mantissa = 0;
        exponent++;
    }

    /* Its going to be subnormal, so make adjustments */
    if (exponent <= -1023) {
        exponent--;
    }

    while (exponent < -1023) {
        exponent++;
        mantissa >>>= 1;
    }

    long bits = mantissa | ((exponent + 1023L) << 52);
    double x = Double.longBitsToDouble(bits);

    if (negate) {
        x = -x;
    }

    return x;

}

public static Vector3D crossProduct(final Vector3D v1, final Vector3D v2) {
    double rho = (v1.x * v2.x + v1.y * v2.y + v1.z * v2.z) / v2.norm();
    Vector3D v3 = new Vector3D(v1.x - rho * v2.x, v1.y - rho * v2.y, v1.z - rho * v2.z);
    return new Vector3D(v3.y * v2.z - v3.z * v2.y, v3.z * v2.x - v3.x * v2.z, v3.x * v2.y - v3.y * v2.x);
}

    chooseInitialCenters(final Collection<T> points, final int k, final Random random) {

    final List<T> pointSet = new ArrayList<T>(points);
    final List<Cluster<T>> resultSet = new ArrayList<Cluster<T>>();

    // Choose one center uniformly at random from among the data points.
    final T firstPoint = pointSet.remove(random.nextInt(pointSet.size()));
    resultSet.add(new Cluster<T>(firstPoint));

    final double[] dx2 = new double[pointSet.size()];
    while (resultSet.size() < k) {
        // For each data point x, compute D(x), the distance between x and
        // the nearest center that has already been chosen.
        double sum = 0;
        for (int i = 0; i < pointSet.size(); i++) {
            final T p = pointSet.get(i);
            final Cluster<T> nearest = getNearestCluster(resultSet, p);
            final double d = p.distanceFrom(nearest.getCenter());
            sum += d * d;
            dx2[i] = sum;
        }

        // Add one new data point as a center. Each point x is chosen with
        // probability proportional to D(x)2
        final double r = random.nextDouble() * sum;
        for (int i = 0 ; i < dx2.length; i++) {
            if (dx2[i] >= r) {
                final T p = pointSet.remove(i);
                resultSet.add(new Cluster<T>(p));
                break;
            }
        }
    }

    return resultSet;

}

