public static int gcd(final int p, final int q) {
    int u = p;
    int v = q;
    if ((u == 0) || (v == 0)) {
        return Math.abs(u) + Math.abs(v);
    }
    // keep u and v negative, as negative integers range down to
    // -2^31, while positive numbers can only be as large as 2^31-1
    // (i.e. we can't necessarily negate a negative number without
    // overflow)
    /* assert u!=0 && v!=0; */
    if (u > 0) {
        u = -u;
    } // make u negative
    if (v > 0) {
        v = -v;
    } // make v negative
    // B1. [Find power of 2]
    int k = 0;
    while ((u & 1) == 0 && (v & 1) == 0 && k < 31) { // while u and v are
                                                        // both even...
        u /= 2;
        v /= 2;
        k++; // cast out twos.
    }
    if (k == 31) {
        throw MathRuntimeException.createArithmeticException(
                "overflow: gcd({0}, {1}) is 2^31",
                new Object[] { p, q });
    }
    // B2. Initialize: u and v have been divided by 2^k and at least
    // one is odd.
    int t = ((u & 1) == 1) ? v : -(u / 2)/* B3 */;
    // t negative: u was odd, v may be even (t replaces v)
    // t positive: u was even, v is odd (t replaces u)
    do {
        /* assert u<0 && v<0; */
        // B4/B3: cast out twos from t.
        while ((t & 1) == 0) { // while t is even..
            t /= 2; // cast out twos
        }
        // B5 [reset max(u,v)]
        if (t > 0) {
            u = -t;
        } else {
            v = t;
        }
        // B6/B3. at this point both u and v should be odd.
        t = (v - u) / 2;
        // |u| larger: t positive (replace u)
        // |v| larger: t negative (replace v)
    } while (t != 0);
    return -u * (1 << k); // gcd is u*2^k
}

public static int lcm(int a, int b) {
    if (a == 0 || b == 0) {
        return 0;
    }
    int lcm = Math.abs(mulAndCheck(a / gcd(a, b), b));
    return lcm;
}

protected void updateJacobian() {
    incrementJacobianEvaluationsCounter();
    Arrays.fill(jacobian, 0);
    for (int i = 0, index = 0; i < rows; i++) {
        WeightedMeasurement wm = measurements[i];
        double factor = -Math.sqrt(wm.getWeight());
        for (int j = 0; j < cols; ++j) {
            jacobian[index++] = factor * wm.getPartial(parameters[j]);
        }
    }
}

protected void updateResidualsAndCost()
throws EstimationException {

    if (++costEvaluations > maxCostEval) {
        throw new EstimationException("maximal number of evaluations exceeded ({0})",
                                      new Object[] { new Integer(maxCostEval) });
    }

    cost = 0;
    for (int i = 0, index = 0; i < rows; i++, index += cols) {
        WeightedMeasurement wm = measurements[i];
        double residual = wm.getResidual();
        residuals[i] = Math.sqrt(wm.getWeight()) * residual;
        cost += wm.getWeight() * residual * residual;
    }
    cost = Math.sqrt(cost);

}

public double getRMS(EstimationProblem problem) {
    WeightedMeasurement[] wm = problem.getMeasurements();
    double criterion = 0;
    for (int i = 0; i < wm.length; ++i) {
        double residual = wm[i].getResidual();
        criterion += wm[i].getWeight() * residual * residual;
    }
    return Math.sqrt(criterion / wm.length);
}

public double getChiSquare(EstimationProblem problem) {
    WeightedMeasurement[] wm = problem.getMeasurements();
    double chiSquare = 0;
    for (int i = 0; i < wm.length; ++i) {
        double residual = wm[i].getResidual();
        chiSquare += residual * residual / wm[i].getWeight();
    }
    return chiSquare;
}

public double[][] getCovariances(EstimationProblem problem)
  throws EstimationException {

    // set up the jacobian
    updateJacobian();

    // compute transpose(J).J, avoiding building big intermediate matrices
    final int rows = problem.getMeasurements().length;
    final int cols = problem.getAllParameters().length;
    final int max  = cols * rows;
    double[][] jTj = new double[cols][cols];
    for (int i = 0; i < cols; ++i) {
        for (int j = i; j < cols; ++j) {
            double sum = 0;
            for (int k = 0; k < max; k += cols) {
                sum += jacobian[k + i] * jacobian[k + j];
            }
            jTj[i][j] = sum;
            jTj[j][i] = sum;
        }
    }

    try {
        // compute the covariances matrix
        return new RealMatrixImpl(jTj).inverse().getData();
    } catch (InvalidMatrixException ime) {
        throw new EstimationException("unable to compute covariances: singular problem",
                                      new Object[0]);
    }

}

public double[] guessParametersErrors(EstimationProblem problem)
  throws EstimationException {
    int m = problem.getMeasurements().length;
    int p = problem.getAllParameters().length;
    if (m <= p) {
        throw new EstimationException("no degrees of freedom ({0} measurements, {1} parameters)",
                                      new Object[] { new Integer(m), new Integer(p)});
    }
    double[] errors = new double[problem.getAllParameters().length];
    final double c = Math.sqrt(getChiSquare(problem) / (m - p));
    double[][] covar = getCovariances(problem);
    for (int i = 0; i < errors.length; ++i) {
        errors[i] = Math.sqrt(covar[i][i]) * c;
    }
    return errors;
}

protected void initializeEstimate(EstimationProblem problem) {

    // reset counters
    costEvaluations     = 0;
    jacobianEvaluations = 0;

    // retrieve the equations and the parameters
    measurements = problem.getMeasurements();
    parameters   = problem.getUnboundParameters();

    // arrays shared with the other private methods
    rows      = measurements.length;
    cols      = parameters.length;
    jacobian  = new double[rows * cols];
    residuals = new double[rows];

    cost = Double.POSITIVE_INFINITY;

}

public Complex parse(String source, ParsePosition pos) {
    int initialIndex = pos.getIndex();

    // parse whitespace
    parseAndIgnoreWhitespace(source, pos);

    // parse real
    Number re = parseNumber(source, getRealFormat(), pos);
    if (re == null) {
        // invalid real number
        // set index back to initial, error index should already be set
        // character examined.
        pos.setIndex(initialIndex);
        return null;
    }

    // parse sign
    int startIndex = pos.getIndex();
    char c = parseNextCharacter(source, pos);
    int sign = 0;
    switch (c) {
    case 0 :
        // no sign
        // return real only complex number
        return new Complex(re.doubleValue(), 0.0);
    case '-' :
        sign = -1;
        break;
    case '+' :
        sign = 1;
        break;
    default :
        // invalid sign
        // set index back to initial, error index should be the last
        // character examined.
        pos.setIndex(initialIndex);
        pos.setErrorIndex(startIndex);
        return null;
    }

    // parse whitespace
    parseAndIgnoreWhitespace(source, pos);

    // parse imaginary
    Number im = parseNumber(source, getRealFormat(), pos);
    if (im == null) {
        // invalid imaginary number
        // set index back to initial, error index should already be set
        // character examined.
        pos.setIndex(initialIndex);
        return null;
    }

    // parse imaginary character
    int n = getImaginaryCharacter().length();
    startIndex = pos.getIndex();
    int endIndex = startIndex + n;
    if (
        source.substring(startIndex, endIndex).compareTo(
        getImaginaryCharacter()) != 0) {
        // set index back to initial, error index should be the start index
        // character examined.
        pos.setIndex(initialIndex);
        pos.setErrorIndex(startIndex);
        return null;
    }

    // parse end
    parseAndIgnoreWhitespace(source, pos);
    if (pos.getIndex() != source.length()) {
        // unexpected character
        pos.setIndex(initialIndex);
        pos.setErrorIndex(pos.getIndex());
        return null;
    }

    return new Complex(sign * re.doubleValue(), im.doubleValue());
}

/**
 * {@inheritDoc}
 * <p><strong>Note: </strong>This implementation rescales the 
 * <code>expected</code> array if necessary to ensure that the sum of the
 * expected and observed counts are equal.</p>
 * 
 * @param observed array of observed frequency counts
 * @param expected array of expected frequency counts
 * @return chi-square test statistic
 * @throws IllegalArgumentException if preconditions are not met
 * or length is less than 2
 */
public double chiSquare(double[] expected, long[] observed)
    throws IllegalArgumentException {
    if ((expected.length < 2) || (expected.length != observed.length)) {
        throw new IllegalArgumentException(
                "observed, expected array lengths incorrect");
    }
    if (!isPositive(expected) || !isNonNegative(observed)) {
        throw new IllegalArgumentException(
            "observed counts must be non-negative and expected counts must be postive");
    }
    double sumSq = 0.0d;
    double dev = 0.0d;
    for (int i = 0; i < observed.length; i++) {
            dev = ((double) observed[i] - expected[i]);
            sumSq += dev * dev / expected[i];
    }
    return sumSq;
}

/**
 * {@inheritDoc}
 * <p><strong>Note: </strong>This implementation rescales the 
 * <code>expected</code> array if necessary to ensure that the sum of the
 * expected and observed counts are equal.</p>
 * 
 * @param observed array of observed frequency counts
 * @param expected array of exptected frequency counts
 * @return p-value
 * @throws IllegalArgumentException if preconditions are not met
 * @throws MathException if an error occurs computing the p-value
 */
public double chiSquareTest(double[] expected, long[] observed)
    throws IllegalArgumentException, MathException {
    distribution.setDegreesOfFreedom(expected.length - 1.0);
    return 1.0 - distribution.cumulativeProbability(
        chiSquare(expected, observed));
}

/**
 * {@inheritDoc}
 * <p><strong>Note: </strong>This implementation rescales the 
 * <code>expected</code> array if necessary to ensure that the sum of the
 * expected and observed counts are equal.</p>
 * 
 * @param observed array of observed frequency counts
 * @param expected array of exptected frequency counts
 * @param alpha significance level of the test
 * @return true iff null hypothesis can be rejected with confidence
 * 1 - alpha
 * @throws IllegalArgumentException if preconditions are not met
 * @throws MathException if an error occurs performing the test
 */
public boolean chiSquareTest(double[] expected, long[] observed, 
        double alpha) throws IllegalArgumentException, MathException {
    if ((alpha <= 0) || (alpha > 0.5)) {
        throw new IllegalArgumentException(
                "bad significance level: " + alpha);
    }
    return (chiSquareTest(expected, observed) < alpha);
}

/**
 * @param counts array representation of 2-way table
 * @return chi-square test statistic
 * @throws IllegalArgumentException if preconditions are not met
 */
public double chiSquare(long[][] counts) throws IllegalArgumentException {

    checkArray(counts);
    int nRows = counts.length;
    int nCols = counts[0].length;

    // compute row, column and total sums
    double[] rowSum = new double[nRows];
    double[] colSum = new double[nCols];
    double total = 0.0d;
    for (int row = 0; row < nRows; row++) {
        for (int col = 0; col < nCols; col++) {
            rowSum[row] += (double) counts[row][col];
            colSum[col] += (double) counts[row][col];
            total += (double) counts[row][col];
        }
    }

    // compute expected counts and chi-square
    double sumSq = 0.0d;
    double expected = 0.0d;
    for (int row = 0; row < nRows; row++) {
        for (int col = 0; col < nCols; col++) {
            expected = (rowSum[row] * colSum[col]) / total;
            sumSq += (((double) counts[row][col] - expected) * 
                    ((double) counts[row][col] - expected)) / expected; 
        }
    } 
    return sumSq;
}

/**
 * @param counts array representation of 2-way table
 * @return p-value
 * @throws IllegalArgumentException if preconditions are not met
 * @throws MathException if an error occurs computing the p-value
 */
public double chiSquareTest(long[][] counts)
throws IllegalArgumentException, MathException {
    checkArray(counts);
    double df = ((double) counts.length -1) * ((double) counts[0].length - 1);
    distribution.setDegreesOfFreedom(df);
    return 1 - distribution.cumulativeProbability(chiSquare(counts));
}

/**
 * @param counts array representation of 2-way table
 * @param alpha significance level of the test
 * @return true iff null hypothesis can be rejected with confidence
 * 1 - alpha
 * @throws IllegalArgumentException if preconditions are not met
 * @throws MathException if an error occurs performing the test
 */
public boolean chiSquareTest(long[][] counts, double alpha)
throws IllegalArgumentException, MathException {
    if ((alpha <= 0) || (alpha > 0.5)) {
        throw new IllegalArgumentException("bad significance level: " + alpha);
    }
    return (chiSquareTest(counts) < alpha);
}

/**
 * @param observed1 array of observed frequency counts of the first data set
 * @param observed2 array of observed frequency counts of the second data set
 * @return chi-square test statistic
 * @throws IllegalArgumentException if preconditions are not met
 */
public double chiSquareDataSetsComparison(long[] observed1, long[] observed2)
    throws IllegalArgumentException {

    // Make sure lengths are same
    if ((observed1.length < 2) || (observed1.length != observed2.length)) {
        throw new IllegalArgumentException(
                "observed1, observed2 array lengths incorrect");
    }
    // Ensure non-negative counts
    if (!isNonNegative(observed1) || !isNonNegative(observed2)) {
        throw new IllegalArgumentException(
            "observed counts must be non-negative");
    }
    // Compute and compare count sums
    long countSum1 = 0;
    long countSum2 = 0;
    boolean unequalCounts = false;
    double weight = 0.0;
    for (int i = 0; i < observed1.length; i++) {
        countSum1 += observed1[i];
        countSum2 += observed2[i];   
    }
    // Ensure neither sample is uniformly 0
    if (countSum1 * countSum2 == 0) {
        throw new IllegalArgumentException(
         "observed counts cannot all be 0"); 
    }
    // Compare and compute weight only if different
    unequalCounts = (countSum1 != countSum2);
    if (unequalCounts) {
        weight = Math.sqrt((double) countSum1 / (double) countSum2);
    }
    // Compute ChiSquare statistic
    double sumSq = 0.0d;
    double dev = 0.0d;
    double obs1 = 0.0d;
    double obs2 = 0.0d;
    for (int i = 0; i < observed1.length; i++) {
        if (observed1[i] == 0 && observed2[i] == 0) {
            throw new IllegalArgumentException(
                    "observed counts must not both be zero");
        } else {
            obs1 = (double) observed1[i];
            obs2 = (double) observed2[i];
            if (unequalCounts) { // apply weights
                dev = obs1/weight - obs2 * weight;
            } else {
                dev = obs1 - obs2;
            }
            sumSq += (dev * dev) / (obs1 + obs2);
        }
    }
    return sumSq;
}

public double cumulativeProbability(double x) throws MathException {
    if (Double.isNaN(x)) {
        return Double.NaN;
    }
    if (x < getDomainLowerBound(0.5)) {
        return 0.0;
    }
    if (x > getDomainUpperBound(0.5)) {
        return 1.0;
    }
    return 0.5 * (1.0 + Erf.erf((x - mean) /
            (standardDeviation * Math.sqrt(2.0))));
}

public double inverseCumulativeProbability(final double p) 
throws MathException {
    if (p == 0) {
        return Double.NEGATIVE_INFINITY;
    }
    if (p == 1) {
        return Double.POSITIVE_INFINITY;
    }
    if (p < 0 || p > 1) {
        throw new IllegalArgumentException(
            "p must be between 0 and 1.");
    }
    return super.inverseCumulativeProbability(p);
}

