private final String iID;

/**
 * Constructor.
 * 
 * @param id  the id to use
 * @throws IllegalArgumentException if the id is null
 */
protected DateTimeZone(String id) {
    if (id == null) {
        throw new IllegalArgumentException("Id must not be null");
    }
    iID = id;
}

/**
 * Gets the ID of this datetime zone.
 * 
 * @return the ID of this datetime zone
 */
@ToString
public final String getID() {
    return iID;
}

/**
 * By default, when DateTimeZones are serialized, only a "stub" object
 * referring to the id is written out. When the stub is read in, it
 * replaces itself with a DateTimeZone object.
 * @return a stub object to go in the stream
 */
protected Object writeReplace() throws ObjectStreamException {
    return new Stub(iID);
}

/**
 * Used to serialize DateTimeZones by id.
 */
private static final class Stub implements Serializable {
    /** Serialization lock. */
    private static final long serialVersionUID = -6471952376487863581L;
    /** The ID of the zone. */
    private transient String iID;

    /**
     * Constructor.
     * @param id  the id of the zone
     */
    Stub(String id) {
        iID = id;
    }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.writeUTF(iID);
    }

    private void readObject(ObjectInputStream in) throws IOException {
        iID = in.readUTF();
    }

    private Object readResolve() throws ObjectStreamException {
        return forID(iID);
    }
}

public long computeMillis(boolean resetFields, String text) {
    SavedField[] savedFields = iSavedFields;
    int count = iSavedFieldsCount;
    if (iSavedFieldsShared) {
        iSavedFields = savedFields = (SavedField[])iSavedFields.clone();
        iSavedFieldsShared = false;
    }
    sort(savedFields, count);
    if (count > 0) {
        // alter base year for parsing if first field is month or day
        DurationField months = DurationFieldType.months().getField(iChrono);
        DurationField days = DurationFieldType.days().getField(iChrono);
        DurationField first = savedFields[0].iField.getDurationField();
        if (compareReverse(first, months) >= 0 && compareReverse(first, days) <= 0) {
            saveField(DateTimeFieldType.year(), iDefaultYear);
            return computeMillis(resetFields, text);
        }
    }

    long millis = iMillis;
    try {
        for (int i = 0; i < count; i++) {
            millis = savedFields[i].set(millis, resetFields);
        }
    } catch (IllegalFieldValueException e) {
        if (text != null) {
            e.prependMessage("Cannot parse \"" + text + '"');
        }
        throw e;
    }

    if (iZone == null) {
        millis -= iOffset;
    } else {
        int offset = iZone.getOffsetFromLocal(millis);
        millis -= offset;
        if (offset != iZone.getOffset(millis)) {
            String message =
                "Illegal instant due to time zone offset transition (" + iZone + ')';
            if (text != null) {
                message = "Cannot parse \"" + text + "\": " + message;
            }
            throw new IllegalArgumentException(message);
        }
    }

    return millis;
}

public int getOffsetFromLocal(long instantLocal) {
    // get the offset at instantLocal (first estimate)
    final int offsetLocal = getOffset(instantLocal);
    // adjust instantLocal using the estimate and recalc the offset
    final long instantAdjusted = instantLocal - offsetLocal;
    final int offsetAdjusted = getOffset(instantAdjusted);
    // if the offsets differ, we must be near a DST boundary
    if (offsetLocal != offsetAdjusted) {
        // we need to ensure that time is always after the DST gap
        // this happens naturally for positive offsets, but not for negative
        if ((offsetLocal - offsetAdjusted) < 0) {
            // if we just return offsetAdjusted then the time is pushed
            // back before the transition, whereas it should be
            // on or after the transition
            long nextLocal = nextTransition(instantAdjusted);
            long nextAdjusted = nextTransition(instantLocal - offsetAdjusted);
            if (nextLocal != nextAdjusted) {
                return offsetLocal;
            }
        }
    }
    return offsetAdjusted;
}

